#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 10.0 // Amperes
#define LOG_FILE "current_log.txt"
#define SENSOR_PRESENT_LOW 0x00 // All zeros
#define SENSOR_PRESENT_HIGH 0xFF // All ones

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_read_adc(int fd, int channel);
float adc_to_current(int adc_value);
int log_current(float current);
int control_fan(int gpio, int state);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_per_word_val = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_val) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    int speed_val = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_val) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion (assuming 3.3V reference)
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * 3.3; // 0-1023 to 0-3.3V
    float current = voltage / 3.3; // Assuming 3.3V reference
    return current;
}

// Log current reading function
int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Fan control function
int control_fan(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        perror("Error writing to GPIO");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Check for sensor presence
        if (adc_value == SENSOR_PRESENT_LOW || adc_value == SENSOR_PRESENT_HIGH) {
            fprintf(stderr, "Sensor not present (all zeros or all ones)\n");
            log_current(-1.0); // Log sensor absence
        } else {
            // Convert ADC value to current
            float current = adc_to_current(adc_value);

            // Log current reading
            if (log_current(current) != 0) {
                fprintf(stderr, "Error logging current reading\n");
            }

            // Control fan
            if (current > CURRENT_THRESHOLD) {
                if (control_fan(FAN_GPIO, 1) != 0) {
                    fprintf(stderr, "Error turning fan ON\n");
                }
            } else {
                if (control_fan(FAN_GPIO, 0) != 0) {
                    fprintf(stderr, "Error turning fan OFF\n");
                }
            }
        }

        sleep(1); // Sample every second
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_fan(FAN_GPIO, 0); // Turn off fan
    gpioTerminate(); // Terminate pigpio

    fprintf(stderr, "Exiting.\n");
    return 0;
}

