int log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Fan control function
int control_fan(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        perror("Error writing to GPIO");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Check for sensor presence
        if (adc_value == SENSOR_PRESENT_LOW || adc_value == SENSOR_PRESENT_HIGH) {
            fprintf(stderr, "Sensor not present (all zeros or all ones)\n");
            log_current(-1.0); // Log sensor absence
        } else {
            // Convert ADC value to current
            float current = adc_to_current(adc_value);

            // Log current reading
            if (log_current(current) != 0) {
                fprintf(stderr, "Error logging current reading\n");
            }

            // Control fan
            if (current > CURRENT_THRESHOLD) {
                if (control_fan(FAN_GPIO, 1) != 0) {
                    fprintf(stderr, "Error turning fan ON\n");
                }
            } else {
                if (control_fan(FAN_GPIO, 0) != 0) {
                    fprintf(stderr, "Error turning fan OFF\n");
                }
            }
        }

        sleep(1); // Sample every second
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_fan(FAN_GPIO, 0); // Turn off fan
    gpioTerminate(); // Terminate pigpio

    fprintf(stderr, "Exiting.\n");
    return 0;
}

