#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define REF_VOLTAGE 4.096
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float co_ppm;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float adc_to_resistance(int16_t raw_value);
float resistance_to_ppm(float resistance);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read from ADS1115
int read_ads1115(int16_t *raw_value) {
    char config[3];

    // Configure for single-shot mode, AIN0, 4.096V, 128 SPS
    config[0] = CONFIG_REG;
    config[1] = 0x40; // Single-shot mode
    config[2] = 0x83; // AIN0, 4.096V, 128 SPS

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion register
    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register\n");
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    *raw_value = *raw_value >> 8; // ADS1115 returns MSB first

    return 0;
}

// Function to convert ADC value to resistance
float adc_to_resistance(int16_t raw_value) {
    float voltage = (float)raw_value / 32768.0 * REF_VOLTAGE;
    float resistance = 10000.0 * (1.0 / voltage - 1.0); // Example resistance calculation
    return resistance;
}

// Function to convert resistance to ppm (CO)
float resistance_to_ppm(float resistance) {
    // Calibration curve: ppm = a * exp(b * log(r))
    // Example: a = 100, b = 0.5
    float ppm = 100.0 * exp(0.5 * log(resistance));
    return ppm;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f ppm\n", timestamp, data.co_ppm);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int16_t raw_value;
    float resistance, co_ppm;
    sensor_data_t sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_ads1115(&raw_value) == 0) {
            // Convert ADC value to resistance
            resistance = adc_to_resistance(raw_value);

            // Convert resistance to ppm
            co_ppm = resistance_to_ppm(resistance);

            // Get current timestamp
            sensor_data.timestamp = time(NULL);
            sensor_data.co_ppm = co_ppm;

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

