#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CS_PIN 8
#define MCP3008_CLK_PIN 11
#define MCP3008_MISO_PIN 9
#define MCP3008_MOSI_PIN 10

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 parameters
#define MCP3008_CHANNEL 0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int flame_sensor_pin;
    int mcp3008_cs_pin;
    int mcp3008_clk_pin;
    int mcp3008_miso_pin;
    int mcp3008_mosi_pin;
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
} config_t;

// Function prototypes
int initialize_gpio(config_t *config);
int initialize_spi(config_t *config);
int read_flame_sensor(int pin);
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_present, float temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio(config_t *config) {
    if (gpioSetMode(config->flame_sensor_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting flame sensor pin mode.\n");
        return -1;
    }
    if (gpioSetMode(config->mcp3008_cs_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MCP3008 CS pin mode.\n");
        return -1;
    }
    if (gpioSetMode(config->mcp3008_clk_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MCP3008 CLK pin mode.\n");
        return -1;
    }
    if (gpioSetMode(config->mcp3008_miso_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting MCP3008 MISO pin mode.\n");
        return -1;
    }
    if (gpioSetMode(config->mcp3008_mosi_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting MCP3008 MOSI pin mode.\n");
        return -1;
    }

    return 0;
}

// Function to initialize SPI
int initialize_spi(config_t *config) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read the flame sensor
int read_flame_sensor(int pin) {
    return gpioRead(pin);
}

// Function to read the MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS_PIN, 0); // Select MCP3008
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS_PIN, 1); // Deselect MCP3008

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // You'll need to calibrate this based on your specific sensor and environment
    float temperature = (float)adc_value * 0.1; // Example conversion
    return temperature;
}

// Function to log data to a CSV file
int log_data(int flame_present, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%.2f\n", timestamp, flame_present, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    config_t config = {
        .flame_sensor_pin = FLAME_SENSOR_PIN,
        .mcp3008_cs_pin = MCP3008_CS_PIN,
        .mcp3008_clk_pin = MCP3008_CLK_PIN,
        .mcp3008_miso_pin = MCP3008_MISO_PIN,
        .mcp3008_mosi_pin = MCP3008_MOSI_PIN,
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_channel = MCP3008_CHANNEL
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO pins
    if (initialize_gpio(&config) != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(&config) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("flame_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read flame sensor
        int flame_present = read_flame_sensor(config.flame_sensor_pin);

        // Read MCP3008 ADC
        int adc_value = read_mcp3008(config.mcp3008_channel);

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        log_data(flame_present, temperature);

        // Print data to console
        printf("Flame: %d, Temperature: %.2f\n", flame_present, temperature);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

