#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 27
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define RMS threshold
#define RMS_THRESHOLD 0.5

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define audio window parameters
#define AUDIO_WINDOW_MS 100
#define AUDIO_WINDOW_SAMPLES 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold audio data
typedef struct {
    int16_t mic1_samples[AUDIO_WINDOW_SAMPLES];
    int16_t mic2_samples[AUDIO_WINDOW_SAMPLES];
    int window_index;
} AudioData;

AudioData audio_data = {{0}, {0}, 0};

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
double calculate_rms(int16_t *samples, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn LED off initially

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    gpioWrite(SPI_CE0, 0); // Select the MCP3008
    spiXfer(spi_handle, spi_data, rx_buffer, 3);
    gpioWrite(SPI_CE0, 1); // Deselect the MCP3008

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS
double calculate_rms(int16_t *samples, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)samples[i] * samples[i];
    }
    return sqrt(sum_of_squares / num_samples);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
