#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define CURRENT_THRESHOLD 50.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float current_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int init_ads1115();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(float current);
float calculate_average();
void control_led(float average_current);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize ADS1115
int init_ads1115() {
    // Configure ADS1115 for single-ended channel A0, 4.096V range, 128 SPS, single conversion mode
    uint16_t config = 0x4003; //0b0100000000000011

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw value from ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Convert raw value to current (Amps)
float convert_to_current(int16_t raw_value) {
    // Assuming a 12-bit ADC and a 4.096V reference voltage
    float full_scale_voltage = 4.096;
    float current = (float)raw_value / 32768.0 * full_scale_voltage; // 2^15 - 1
    return current;
}

// Add current reading to circular buffer
void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate average of current readings in the buffer
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += current_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control LED based on average current
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(current);
            control_led(calculate_average());
            printf("Current: %.2f A\n", current);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

