#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_WTIME           0x03
#define TCS34725_AILTL           0x04
#define TCS34725_AILTH           0x05
#define TCS34725_AIHTL           0x06
#define TCS34725_AIHTH           0x07
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A
#define TCS34725_POWERON         0x01

// Global variables
static int i2c_handle;
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;
static int i2c_retries = 3;

// Structure to hold sensor data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, sensor_data_t *data);
int log_data(const char *filename, sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the TCS34725 sensor
int initialize_sensor(int i2c_handle) {
    int status;
    uint8_t id;

    // Check the ID register
    status = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (status < 0) {
        fprintf(stderr, "Error reading ID register: %s\n", strerror(errno));
        return -1;
    }
    id = (uint8_t)status;

    if (id != 0x44) {
        fprintf(stderr, "Incorrect ID register value: 0x%02X\n", id);
        return -1;
    }

    // Enable the sensor
    status = i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_POWERON);
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Set integration time (ATIME) - 101ms
    status = i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB); // 101ms
    if (status < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    // Set wait time (WTIME) - 15ms
    status = i2cWriteByteData(i2c_handle, TCS34725_WTIME, 0xCF); // 15ms
    if (status < 0) {
        fprintf(stderr, "Error writing to WTIME register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
int read_sensor_data(int i2c_handle, sensor_data_t *data) {
    int status;
    uint8_t clear_low, clear_high, red_low, red_high, green_low, green_high, blue_low, blue_high;
    uint16_t clear_raw, red_raw, green_raw, blue_raw;

    // Read clear data
    status = i2cReadByteData(i2c_handle, TCS34725_CDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %s\n", strerror(errno));
        return -1;
    }
    clear_low = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, TCS34725_CDATA + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading clear data: %s\n", strerror(errno));
        return -1;
    }
    clear_high = (uint8_t)status;
    clear_raw = (clear_high << 8) | clear_low;

    // Read red data
    status = i2cReadByteData(i2c_handle, TCS34725_RDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }
    red_low = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, TCS34725_RDATA + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }
    red_high = (uint8_t)status;
    red_raw = (red_high << 8) | red_low;

    // Read green data
    status = i2cReadByteData(i2c_handle, TCS34725_GDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return -1;
    }
    green_low = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, TCS34725_GDATA + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return -1;
    }
    green_high = (uint8_t)status;
    green_raw = (green_high << 8) | green_low;

    // Read blue data
    status = i2cReadByteData(i2c_handle, TCS34725_BDATA);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return -1;
    }
    blue_low = (uint8_t)status;

    status = i2cReadByteData(i2c_handle, TCS34725_BDATA + 1);
    if (status < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return -1;
