// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];
    int count;

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    for (int i = 0; i < 3; i++) {
        count = 0;
        while (count < 100) { // Retry loop
            if (spiXfer(spi_handle, tx_buffer + i, rx_buffer + i, 3) == 0) {
                break;
            }
            count++;
            gpioDelay(1000); // 1 ms delay
        }
        if (count >= 100) {
            fprintf(stderr, "SPI read failed after multiple retries (channel %d)\n", channel);
            return -1; // Indicate error
        }
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

