#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define PRESSURE_MIN 0.0  // kPa
#define PRESSURE_MAX 100.0 // kPa
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int sample_rate_hz;
} config_t;

// Function prototypes
int initialize_i2c(config_t *config);
int configure_ads1115(int i2c_handle);
int read_pressure(int i2c_handle, float *pressure);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int initialize_i2c(config_t *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(config->i2c_bus, config->ads1115_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure ADS1115 for single-ended AIN0, 16-bit, continuous conversion mode
int configure_ads1115(int i2c_handle) {
    // Configuration register value: 0x4003 (Single-ended AIN0, 16-bit, Continuous, Disable comparator)
    uint16_t config_value = 0x4003;

    // Write the configuration value to the configuration register
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    buf[2] = config_value & 0xFF;        // LSB

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read pressure data from ADS1115
int read_pressure(int i2c_handle, float *pressure) {
    // Read the conversion register (0x00)
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
