    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (data[0] << 8) | data[1];

    // Convert raw value to pressure (kPa)
    *pressure = (float)raw_value * 0.125; // 0.125 V/kPa

    return 0;
}

