        .i2c_bus = I2C_BUS,
        .ads1115_address = ADS1115_ADDR,
        .sample_rate_hz = SAMPLE_RATE_HZ
    };

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c(&config) != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    float pressure;

    // Main loop
    while (!terminate) {
        // Read pressure
        if (read_pressure(i2c_handle, &pressure) == 0) {
            // Validate pressure
            if (validate_pressure(pressure) == 0) {
                // Log pressure
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        gpioDelay(SAMPLE_PERIOD_US); // Delay for 1ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

