#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3208_CHANNEL 0 // Humidity sensor connected to channel 0
#define HUMIDITY_THRESHOLD 80.0
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 5000
#define EMAIL_RECIPIENT "recipient@example.com" // Replace with your email
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
int socket_desc;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
void send_email_alert(float humidity);
void send_udp_alert(float humidity);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3208_channel;
    float humidity_threshold;
    char server_ip[20];
    int server_port;
    char email_recipient[50];
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3208_CHANNEL,
    HUMIDITY_THRESHOLD,
    SERVER_IP,
    SERVER_PORT,
    EMAIL_RECIPIENT
};

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet formula
    float humidity = (adc_value / 1023.0) * 100.0;
    return humidity;
}

// Function to send email alert using ssmtp
void send_email_alert(float humidity) {
    char command[200];
    snprintf(command, sizeof(command), "echo \"Humidity exceeded threshold: %.2f%%\" | ssmtp -t %s", humidity, config.email_recipient);
    int result = system(command);
    if (result == -1) {
        fprintf(stderr, "Error: Failed to send email alert\n");
    }
}

// Function to send UDP alert
void send_udp_alert(float humidity) {
    char message[50];
    snprintf(message, sizeof(message), "Humidity exceeded threshold: %.2f%%", humidity);
    if (sendto(socket_desc, message, strlen(message), 0, (struct sockaddr *)&config.server_ip, sizeof(config.server_ip)) < 0) {
        fprintf(stderr, "Error: Failed to send UDP alert\n");
    }
}

// Function to log data to file
void log_data(float humidity, float temperature) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (socket_desc >= 0) {
        close(socket_desc);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Create UDP socket
    socket_desc = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_desc < 0) {
        fprintf(stderr, "Error: Socket creation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure server address
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(config.server_port);
    if (inet_pton(AF_INET, config.server_ip, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid server IP address\n");
        close(socket_desc);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3208(config.mcp3208_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity
        float humidity = calculate_humidity(adc_value);

        // Get temperature (replace with actual temperature reading if needed)
        float temperature = 25.0 + (adc_value / 1023.0) * 25.0; // Example temperature calculation

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold
        if (humidity > config.humidity_threshold) {
            printf("Humidity threshold exceeded! Sending alert.\n");
            send_email_alert(humidity);
            send_udp_alert(humidity);
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here due to signal handler)
    spiClose(spi_handle);
    close(socket_desc);
    gpioTerminate();
    return 0;
}

