#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define HR_REG 0x24 // Example register address for HR
#define SPO2_REG 0x26 // Example register address for SpO2
#define SAMPLE_INTERVAL_MS 1000
#define LOG_FILE "biometric_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int ir_raw;
    int red_raw;
    int hr_raw;
    int spo2_raw;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si1172 sensor
int initialize_sensor() {
    // Add initialization code here based on the Si1172 datasheet
    // This is a placeholder, replace with actual initialization sequence
    // Example: Writing to configuration registers
    if (i2cWriteByteData(i2c_handle, 0x01, 0x00) < 0) {
        fprintf(stderr, "Error writing to configuration register 0x01\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) {
        fprintf(stderr, "Error writing to configuration register 0x02\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Reads raw data from the Si1172 sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int ir_raw, red_raw, hr_raw, spo2_raw;
    int result;

    // Read IR raw data
    ir_raw = i2cReadWordData(i2c_handle, 0x24); // Example register address
    if (ir_raw < 0) {
        fprintf(stderr, "Error reading IR data: %d\n", ir_raw);
        data.error_flag = 2; // Sensor absent/uninitialized
        return data;
    }

    // Read RED raw data
    red_raw = i2cReadWordData(i2c_handle, 0x26); // Example register address
    if (red_raw < 0) {
        fprintf(stderr, "Error reading RED data: %d\n", red_raw);
        data.error_flag = 2; // Sensor absent/uninitialized
        return data;
    }

    // Read HR raw data (replace with actual register address)
    hr_raw = i2cReadWordData(i2c_handle, HR_REG); // Example register address
    if (hr_raw < 0) {
        fprintf(stderr, "Error reading HR data: %d\n", hr_raw);
        data.error_flag = 1; // Read error
        return data;
    }

    // Read SpO2 raw data (replace with actual register address)
    spo2_raw = i2cReadWordData(i2c_handle, SPO2_REG); // Example register address
    if (spo2_raw < 0) {
        fprintf(stderr, "Error reading SpO2 data: %d\n", spo2_raw);
        data.error_flag = 1; // Read error
        return data;
    }

    data.ir_raw = ir_raw;
    data.red_raw = red_raw;
    data.hr_raw = hr_raw;
    data.spo2_raw = spo2_raw;
    data.error_flag = 0; // OK

    return data;
}

// Logs the sensor data to a CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[256];

    // Get current timestamp
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Format the log entry
    snprintf(log_entry, sizeof(log_entry), "%s,%d,%d,%d,%d\n",
             timestamp, data.hr_raw, data.spo2_raw, data.error_flag);

    // Flush the log file
    fflush(log_file);

    // Write the log entry to the file
    if (fprintf(log_file, "%s", log_entry) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row to the log file
    fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t data = read_sensor_data();

        // Log the data
        if (data.error_flag == 0) {
            if (log_data(data) < 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, logging error flag\n");
            if (log_data(data) < 0) {
                fprintf(stderr, "Error logging error flag\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Close the I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close the log file
    fclose(log_file);

    return 0;
}

