#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define FLOW_SENSOR_MIN_FLOW 0.0 // L/min
#define FLOW_SENSOR_MAX_FLOW 5.0 // L/min
#define ADC_MIN 0
#define ADC_MAX 1023
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float flow_min;
    float flow_max;
    char *log_file_name;
} Config;

// Function prototypes
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
float adc_to_flow_rate(int adc_value);
int validate_flow_rate(float flow_rate);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi(int channel, int speed) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float adc_to_flow_rate(int adc_value) {
    if (adc_value < ADC_MIN || adc_value > ADC_MAX) {
        return -1.0; // Sensor out of range
    }

    // Linear conversion (example, adjust based on sensor datasheet)
    float flow_rate = (float)(adc_value - ADC_MIN) / (ADC_MAX - ADC_MIN) * (FLOW_SENSOR_MAX_FLOW - FLOW_SENSOR_MIN_FLOW) + FLOW_SENSOR_MIN_FLOW;
    return flow_rate;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_SENSOR_MIN_FLOW || flow_rate > FLOW_SENSOR_MAX_FLOW) {
        fprintf(stderr, "Error: Flow rate out of range: %.2f L/min\n", flow_rate);
        return -1;
    }
    return 0;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", (long int)time(NULL) % 1000000); // Microsecond precision

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_handle = initialize_spi(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Try again
        }

        // Convert to flow rate
        float flow_rate = adc_to_flow_rate(adc_value);
        if (flow_rate < 0) {
            fprintf(stderr, "Error converting ADC to flow rate\n");
            continue; // Try again
        }

        // Validate flow rate
        if (validate_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Error: Invalid flow rate\n");
            continue; // Try again
        }

        // Log flow rate
        log_flow_rate(flow_rate);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

