#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// ICP-10125 I2C address
#define ICP10125_ADDR 0x68

// ICP-10125 register addresses
#define ICP10125_MEASURE_HIGH_PRECISION 0x03
#define ICP10125_RESULT_PRESSURE_MSB 0x00
#define ICP10125_RESULT_PRESSURE_LSB 0x01
#define ICP10125_RESULT_TEMPERATURE_MSB 0x02
#define ICP10125_RESULT_TEMPERATURE_LSB 0x03
#define ICP10125_RESULT_CRC_MSB 0x04
#define ICP10125_RESULT_CRC_LSB 0x05

// Calibration parameters (replace with your sensor's values)
#define P_SENS 100.0  // Pressure sensitivity
#define T_SENS 100.0  // Temperature sensitivity
#define P_OFFSET 0.0  // Pressure offset
#define T_OFFSET 0.0  // Temperature offset

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold raw sensor data
typedef struct {
    int16_t pressure_raw;
    int16_t temperature_raw;
    uint8_t crc_raw;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(sensor_data_t *data);
double convert_temperature(int16_t raw_temp);
double convert_pressure(int16_t raw_pressure);
int log_data(double temperature, double pressure);
void display_data(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ICP10125_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Trigger a high-precision measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, ICP10125_MEASURE_HIGH_PRECISION, 0x03);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data from the ICP-10125
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_RESULT_PRESSURE_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    data->pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature_raw = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->crc_raw = buffer[4];

    return 0;
}

// Convert raw temperature to degrees Celsius
double convert_temperature(int16_t raw_temp) {
    // Implement the temperature conversion formula from the datasheet
    // This is a placeholder; replace with the actual formula
    return (double)raw_temp * 0.01; // Example conversion
}

// Convert raw pressure to Pascals
double convert_pressure(int16_t raw_pressure) {
    // Implement the pressure conversion formula from the datasheet
    // This is a placeholder; replace with the actual formula
    return (double)raw_pressure * 10.0; // Example conversion
}

// Log data to a CSV file
int log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Display data to the console
void display_data(double temperature, double pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data;
        if (trigger_measurement() < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }
        gpioDelay(10000); // Wait for conversion (10ms)

        if (read_sensor_data(&sensor_data) < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        double temperature = convert_temperature(sensor_data.temperature_raw);
        double pressure = convert_pressure(sensor_data.pressure_raw);

        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Retrying in 5 seconds.\n");
        }

        display_data(temperature, pressure);

        sleep(5); // Sample every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

