int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_RESULT_PRESSURE_MSB, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    data->pressure_raw = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature_raw = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->crc_raw = buffer[4];

    return 0;
}

// Convert raw temperature to degrees Celsius
double convert_temperature(int16_t raw_temp) {
    // Implement the temperature conversion formula from the datasheet
    // This is a placeholder; replace with the actual formula
    return (double)raw_temp * 0.01; // Example conversion
}

// Convert raw pressure to Pascals
double convert_pressure(int16_t raw_pressure) {
    // Implement the pressure conversion formula from the datasheet
    // This is a placeholder; replace with the actual formula
    return (double)raw_pressure * 10.0; // Example conversion
}

// Log data to a CSV file
int log_data(double temperature, double pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Display data to the console
void display_data(double temperature, double pressure) {
    printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temperature, pressure);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data;
        if (trigger_measurement() < 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }
        gpioDelay(10000); // Wait for conversion (10ms)

        if (read_sensor_data(&sensor_data) < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        double temperature = convert_temperature(sensor_data.temperature_raw);
        double pressure = convert_pressure(sensor_data.pressure_raw);

        if (log_data(temperature, pressure) < 0) {
            fprintf(stderr, "Failed to log data. Retrying in 5 seconds.\n");
        }

        display_data(temperature, pressure);

        sleep(5); // Sample every 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

