#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CS 8
#define NUM_CHANNELS 2
#define SAMPLE_RATE 10000 // 10 kHz
#define GAIN_MULTIPLIER 1.0 // Default gain

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration parameters
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_cs;
    int num_channels;
    int sample_rate;
    float gain_multiplier;
} Config;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int speed, int cs_pin);
int read_mcp3008(int channel, int spi_handle);
void apply_noise_cancellation(int *input1, int *input2, int gain_multiplier);
void print_csv(int *output1, int *output2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi(int channel, int speed, int cs_pin) {
    int handle = spiOpen(channel, speed, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    gpioSetMode(cs_pin, PI_OUTPUT);
    gpioWrite(cs_pin, 1); // Deactivate CS
    return handle;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel, int spi_handle) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(MCP3008_CS, 0); // Activate CS
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(MCP3008_CS, 1); // Deactivate CS

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Apply noise cancellation
void apply_noise_cancellation(int *input1, int *input2, float gain_multiplier) {
    // Simple average of the two inputs
    int average = (input1[0] + input1[1]) / 2.0;
    average += (input2[0] + input2[1]) / 2.0;

    // Apply gain multiplier
    int output = (int)(average * gain_multiplier);

    // Clamp the output to the range of the input
    if (output < 0) output = 0;
    if (output > 255) output = 255;

    *input1 = input1[0]; // Reuse the first input for the next sample
    *input2 = input2[0];
}

// Print CSV output
void print_csv(int *output1, int *output2) {
    printf("Sample,Channel1,Channel2\n");
    for (int i = 0; i < 1000; ++i) {
        printf("%d,%d,%d\n", i, *output1, *output2);
        *output1 = *output2;
        *output2 = (int)((*output1 + *output2) / 2.0); // Simple moving average
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_cs = MCP3008_CS,
        .num_channels = NUM_CHANNELS,
        .sample_rate = SAMPLE_RATE,
        .gain_multiplier = GAIN_MULTIPLIER
    };

    // Parse command-line arguments
    if (argc > 1) {
        config.gain_multiplier = atof(argv[1]);
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(config.spi_channel, config.spi_speed, config.mcp3008_cs);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Allocate memory for audio samples
    int *input1 = malloc(2 * sizeof(int));
    int *input2 = malloc(2 * sizeof(int));
    int *output1 = malloc(2 * sizeof(int));
    int *output2 = malloc(2 * sizeof(int));

    if (!input1 || !input2 || !output1 || !output2) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read audio samples from both microphones
        int adc_value1 = read_mcp3008(0, spi_handle);
        int adc_value2 = read_mcp3008(1, spi_handle);

        if (adc_value1 < 0 || adc_value2 < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            break;
        }

        // Apply noise cancellation
        apply_noise_cancellation(input1, input2, config.gain_multiplier);

        // Print CSV output
        print_csv(output1, output2);

        // Delay to achieve desired sample rate
        gpioDelay(1000000 / config.sample_rate); // Delay in microseconds
    }

    // Clean up resources
    free(input1);
    free(input2);
    free(output1);
    free(output2);
    cleanup();

    return 0;
}

