#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LOG_FILE "moisture_log.txt"
#define SAMPLE_INTERVAL_SEC 60

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
int log_data(float moisture_percentage);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    char *log_file;
    int sample_interval;
} config_t;

// Initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    // Assuming ADC range is 0-1023, corresponding to 0-100% moisture
    return 100.0 - ((float)adc_value / 1023.0) * 100.0;
}

// Log data to file
int log_data(float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to moisture percentage
        float moisture_percentage = convert_to_moisture_percentage(adc_value);

        // Log data
        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

