    return adc_value;
}

// Function to calculate water level percentage
float calculate_percentage(int adc_value) {
    // Assuming 0 ADC value is 0% and 1023 ADC value is 100%
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

