// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500kHz
#define MCP3008_CHANNEL 0
#define MOISTURE_THRESHOLD 30.0
#define LOGGING_INTERVAL 60 // seconds
#define EMAIL_RECIPIENT "recipient@example.com"
#define CONFIG_FILE "msmtp.conf"

// Global variables
int spi_handle;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void send_email_alert(float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float min_calibration_value;
    float max_calibration_value;
    float moisture_threshold;
    int logging_interval;
    char *recipient_email;
    char *msmtp_config_file;
} Config;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d): %s\n", result, strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Assuming min_calibration_value = 0, max_calibration_value = 1023
    float moisture_percentage = 100.0 - ((float)(adc_value - 1023) / (float)(1023 - 1023)) * 100.0; // Inverted for moisture
    if (moisture_percentage < 0.0) moisture_percentage = 0.0;
    if (moisture_percentage > 100.0) moisture_percentage = 100.0;
    return moisture_percentage;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to send email alert using msmtp
void send_email_alert(float moisture_percentage) {
    char command[256];
    snprintf(command, sizeof(command), "msmtp -t < %s", CONFIG_FILE);

    FILE *fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to execute msmtp command: %s\n", strerror(errno));
        return;
    }

