        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config;

    // Default values
    config.spi_channel = SPI_CHANNEL;
    config.spi_speed = SPI_SPEED;
    config.mcp3008_channel = MCP3008_CHANNEL;
    config.min_calibration_value = 0.0;
    config.max_calibration_value = 1023.0;
    config.moisture_threshold = MOISTURE_THRESHOLD;
    config.logging_interval = LOGGING_INTERVAL;
    config.recipient_email = EMAIL_RECIPIENT;
    config.msmtp_config_file = CONFIG_FILE;

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "c:s:m:n:t:i:f:")) != -1) {
        switch (opt) {
            case 'c':
                config.spi_channel = atoi(optarg);
                break;
            case 's':
                config.spi_speed = atoi(optarg);
                break;
            case 'm':
                config.mcp3008_channel = atoi(optarg);
                break;
            case 'n':
                config.min_calibration_value = atof(optarg);
                break;
            case 't':
                config.max_calibration_value = atof(optarg);
                break;
            case 'i':
                config.logging_interval = atoi(optarg);
                break;
            case 'f':
                config.msmtp_config_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-s spi_speed] [-m mcp3008_channel] [-n min_calibration_value] [-t max_calibration_value] [-i logging_interval] [-f msmtp_config_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code = %d): %s\n", spi_handle, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("plant_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialisation failed (error code = %d): %s\n", spi_handle, strerror(errno));
                // Consider exiting if SPI re-initialization consistently fails
            }
            sleep(1); // Wait before retrying
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value);
        log_data(moisture_percentage);

        if (moisture_percentage < config.moisture_threshold) {
            send_email_alert(moisture_percentage);
        }

        sleep(config.logging_interval);
    }

    return 0;
}

