// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0     // MCP3008 channel connected to MLX90823
#define VREF 3.3          // Reference voltage
#define MIN_ADC_VALUE 0   // Minimum ADC value (0V)
#define MAX_ADC_VALUE 1023 // Maximum ADC value (3.3V)
#define MIN_PRESSURE 0.0   // Minimum pressure (Pascals)
#define MAX_PRESSURE 1000.0 // Maximum pressure (Pascals)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float vref;
    float min_adc;
    float max_adc;
    float min_pressure;
    float max_pressure;
} config_t;

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Convert voltage to pressure (linear approximation)
float voltage_to_pressure(float voltage) {
    return (voltage - VREF) / (VREF - MIN_VREF) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
}

// Get current timestamp in ISO 8601 format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Log data to console
void log_data(float pressure) {
    char timestamp[21];
    get_timestamp(timestamp);
    printf("%s Pressure: %.2f Pa\n", timestamp, pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
