#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// SPI device file
#define SPI_DEVICE "/dev/spidev0.0"

// SPI mode
#define SPI_MODE SPI_MODE_0

// SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 channel
#define MCP3008_CHANNEL 0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int fd, int channel)
{
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct the SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) & 0xFF; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to calculate the moisture percentage
float calculate_moisture_percentage(int adc_value)
{
    // Assuming a linear relationship between ADC value and moisture percentage
    // Adjust the formula based on your sensor's characteristics
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture_percentage;
}

int main()
{
    int spi_fd;
    int adc_value;
    float moisture_percentage;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Open the SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return 1;
    }

    // Configure the SPI device
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return 1;
    }

    uint8_t bits_per_word = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed hz");
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the ADC value
        adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate the moisture percentage
        moisture_percentage = calculate_moisture_percentage(adc_value);

        // Get the current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log the data to the console
        printf("%s - Moisture: %.2f%%\n", timestamp, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the SPI device
    close(spi_fd);

    return 0;
}

