        int adc_value2 = read_mcp3008(SENSOR2_CHANNEL);
        int adc_value3 = read_mcp3008(SENSOR3_CHANNEL);
        int adc_value4 = read_mcp3008(SENSOR4_CHANNEL);

        // Check for errors during ADC read
        if (adc_value1 == -1 || adc_value2 == -1 || adc_value3 == -1 || adc_value4 == -1) {
            fprintf(stderr, "Error: Failed to read ADC value from one or more sensors\n");
        } else {
            // Convert ADC values to voltages
            sensor1_data.voltage = convert_to_voltage(adc_value1);
            sensor2_data.voltage = convert_to_voltage(adc_value2);
            sensor3_data.voltage = convert_to_voltage(adc_value3);
            sensor4_data.voltage = convert_to_voltage(adc_value4);

            // Log data to file
            log_data(sensor1_data);
            log_data(sensor2_data);
            log_data(sensor3_data);
            log_data(sensor4_data);
        }

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Clean up resources before exiting
    printf("Closing resources...\n");
    fclose(data_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

