#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define GPIO_REED 27
#define THRESHOLD 500  // Calibration threshold
#define RELAY_DURATION 3000 // 3 seconds in milliseconds
#define LOG_FILE "/var/log/door_events.log"

// Global variables
int i2c_fd;
int running = 1;

// Function prototypes
int init_i2c();
int read_distance();
int read_reed_sensor();
void control_relay(int state);
void log_event(const char *event);
void signal_handler(int signal);

// Calibration phase
int calibrate_sensor() {
    int baseline_sum = 0;
    for (int i = 0; i < 10; i++) {
        // Read ADC value
        int adc_value = read_distance();
        if (adc_value < 0) {
            return -1; // Indicate calibration failure
        }
        // Store the ADC value in the baseline sum
        baseline_sum += adc_value;
        gpioDelay(50); // 50ms delay
    }
    // Calculate the average baseline reading
    int baseline = baseline_sum / 10;
    printf("Baseline reading: %d\n", baseline);
    return baseline;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as input
    gpioSetMode(GPIO_REED, PI_INPUT);
    gpioSetPullUpDown(GPIO_REED, PI_PUD_UP); // Enable pull-up resistor

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Calibrate the sensor
    int baseline = calibrate_sensor();
    if (baseline < 0) {
        fprintf(stderr, "Sensor calibration failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Failed to read distance\n");
            gpioDelay(200); // Wait 200ms before retrying
            continue;
        }

        // Check if distance is below threshold
        if (distance < baseline) {
            printf("Distance below threshold\n");
            control_relay(1); // Energize relay
            gpioDelay(RELAY_DURATION);
            control_relay(0); // De-energize relay
            log_event("Door opened");
        } else {
            log_event("Door not opened");
        }

        gpioDelay(200); // Wait 200ms
    }

    // Cleanup
    i2cClose(i2c_fd);
    gpioTerminate();
    printf("Program terminated gracefully\n");
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Configure ADS1115 (Single-ended A0, 4.096V, Continuous conversion, 128 SPS)
    uint16_t config_value = 0x4003; //0b0100000000000011
    uint8_t buffer[3];
    buffer[0] = ADS1115_REG_CONFIG;
    buffer[1] = (config_value >> 8) & 0xFF;
    buffer[2] = config_value & 0xFF;

    if (write(i2c_fd, buffer, 3) != 3) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read distance from ADS1115
int read_distance() {
    uint8_t buffer[2];
    uint16_t raw_value;
    int adc_value;

    // Read the conversion register
    buffer[0] = ADS1115_REG_CONVERT;
    if (write(i2c_fd, buffer, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(i2c_fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    raw_value = (buffer[0] << 8) | buffer[1];

    // Convert raw value to distance (example formula, adjust as needed)
    adc_value = (int)raw_value; // Assuming raw value is already in ADC units
    // Apply calibration curve here if needed
    return adc_value;
}

// Read reed sensor
int read_reed_sensor() {
    return gpioRead(GPIO_REED);
}

// Control relay
void control_relay(int state) {
    gpioWrite(GPIO_REED, state);
}

// Log event
void log_event(const char *event) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received, cleaning up...\n");
    running = 0;
    control_relay(0); // De-energize relay
    i2cClose(i2c_fd);
    gpioTerminate();
    exit(0);
}

