#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for chip select
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CPOL 0
#define SPI_CPHA 0

// Define CSV filename
#define CSV_FILENAME "soil_moisture_log.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
} SensorData;

// Function prototypes
int spi_open(int channel, int speed, int mode, int cpol, int cpha);
int spi_read_adc(int channel);
int spi_close(int handle);
int csv_write_header(const char *filename);
int csv_write_data(FILE *fp, const char *filename, int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
void cleanup();

// Function to open the SPI device
int spi_open(int channel, int speed, int mode, int cpol, int cpha) {
    int handle = spiOpen(channel, speed, mode, cpol, cpha);
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read from the MCP3008 ADC
int spi_read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Select the MCP3008
    gpioWrite(CS0_PIN, 0); // Assuming CS0 is active low
    gpioWrite(CS1_PIN, 0); // Assuming CS1 is active low
    gpioWrite(CS2_PIN, 0); // Assuming CS2 is active low
    gpioDelay(1); // Small delay after CS goes low

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        gpioWrite(CS0_PIN, 1); // Deselect the MCP3008
        gpioWrite(CS1_PIN, 1); // Deselect the MCP3008
        gpioWrite(CS2_PIN, 1); // Deselect the MCP3008
        return -1;
    }

    // Deselect the MCP3008
    gpioWrite(CS0_PIN, 1); // Deselect the MCP3008
    gpioWrite(CS1_PIN, 1); // Deselect the MCP3008
    gpioWrite(CS2_PIN, 1); // Deselect the MCP3008
    gpioDelay(1); // Small delay after CS goes high

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to close the SPI device
int spi_close(int handle) {
    int result = spiClose(handle);
    if (result != 0) {
        fprintf(stderr, "Error closing SPI device: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to write the CSV header
int csv_write_header(const char *filename) {
    fp = fopen(filename, "r");
    if (fp == NULL) {
        fp = fopen(filename, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening CSV file for writing header: %s\n", filename);
            return -1;
        }
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3\n");
        fclose(fp);
        return 0;
    }
    fclose(fp);
    return 0;
}

// Function to write data to the CSV file
int csv_write_data(FILE *fp, const char *filename, int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spi_close(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(CS0_PIN, PI_OUTPUT);
    gpioSetMode(CS1_PIN, PI_OUTPUT);
    gpioSetMode(CS2_PIN, PI_OUTPUT);

    // Set CS pins high initially (deselected)
    gpioWrite(CS0_PIN, 1);
    gpioWrite(CS1_PIN, 1);
    gpioWrite(CS2_PIN, 1);

    // Open SPI device
    spi_handle = spi_open(SPI_CHANNEL, SPI_SPEED, SPI_MODE, SPI_CPOL, SPI_CPHA);
    if (spi_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Write CSV header
    if (csv_write_header(CSV_FILENAME) != 0) {
        spi_close(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor values
        int sensor1 = spi_read_adc(0);
        int sensor2 = spi_read_adc(1);
        int sensor3 = spi_read_adc(2);

        // Write data to CSV file
        if (sensor1 != -1 && sensor2 != -1 && sensor3 != -1) {
            if (csv_write_data(fp, CSV_FILENAME, sensor1, sensor2, sensor3) != 0) {
                fprintf(stderr, "Error writing data to CSV file. Skipping.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

