#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30.0
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
int threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;
int sleep_interval = DEFAULT_SLEEP_INTERVAL;
int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_level(int adc_value);
void control_pump(int state, int duration);
void log_data(float moisture_level, int pump_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int count = 0;
    while (count < 3) {
        char tx_buf[3];
        char rx_buf[3];

        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
        tx_buf[2] = 0x00;

        if (spiXfer(spi_handle, tx_buf, rx_buf, 3) == 3) {
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read error, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            count++;
        }
    }
    fprintf(stderr, "Failed to read SPI after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to calculate moisture level percentage
float calculate_moisture_level(int adc_value) {
    if (adc_value < 0) return -1.0; // Indicate error
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to control the water pump
void control_pump(int state, int duration) {
    gpioWrite(PUMP_GPIO, state); // HIGH to activate, LOW to deactivate
    log_data(0.0, state); // Log the pump state
    gpioDelay(duration * 1000); // Delay for the specified duration
    gpioWrite(PUMP_GPIO, LOW); // Ensure pump is off after duration
}

// Function to log data to file
void log_data(float moisture_level, int pump_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Moisture: %.2f%%, Pump: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            moisture_level, pump_state == 1 ? "ON" : "OFF");

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System\n");
    printf("Threshold: %.2f%%, Duration: %d seconds, Sleep: %d seconds\n", threshold, duration, sleep_interval);

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_level = calculate_moisture_level(adc_value);
            if (moisture_level >= 0) {
                printf("Moisture Level: %.2f%%\n", moisture_level);

                if (moisture_level < threshold) {
                    printf("Moisture level below threshold. Activating pump.\n");
                    control_pump(1, duration);
                } else {
                    printf("Moisture level above threshold. Pump deactivated.\n");
                }
            } else {
                fprintf(stderr, "Error reading ADC value. Skipping irrigation cycle.\n");
            }
        } else {
            fprintf(stderr, "Error reading ADC value. Skipping irrigation cycle.\n");
        }

        gpioDelay(sleep_interval * 1000); // Sleep for the specified interval
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(PUMP_GPIO, LOW); // Ensure pump is off
    gpioTerminate();

    return 0;
}

