#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48
#define PCF8591_REG_CONTROL 0x40
#define PCF8591_REG_DATA0 0x40

int i2c_fd = -1;

void signal_handler(int sig);
int setup_i2c(void);
int read_pcf8591_channel(int fd, int channel);

void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
        if (i2c_fd != -1) {
            close(i2c_fd);
        }
        exit(0);
    }
}

int setup_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

int read_pcf8591_channel(int fd, int channel) {
    uint8_t control_byte = 0x40 | (channel << 4);
    uint8_t data[2];

    // Write control byte to PCF8591
    if (write(fd, &control_byte, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Read 2 bytes from PCF8591
    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine the two bytes to get the 8-bit ADC value
    return (data[0] << 4) | (data[1] >> 4);
}

int main(void) {
    signal(SIGINT, signal_handler);

    if (setup_i2c() != 0) {
        return 1;
    }

    printf("PCF8591 ADC monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        int adc_value = read_pcf8591_channel(i2c_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            usleep(100000); // 100ms delay
            continue;
        }

        printf("AIN0: %d\n", adc_value);
        usleep(100000); // 100ms delay
    }

    return 0;
}

