#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define THRESHOLD_GAUSS 500.0
#define VOLTAGE_RANGE 3.3
#define GAUSS_PER_VOLT 0.003333333333333333
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int init_gpio();
int init_ads1115();
int read_adc(int channel);
float convert_to_gauss(int adc_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_rolling_average(CircularBuffer *cb);
void check_threshold(float average_gauss);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO mode");
        return -1;
    }
    gpioWrite(GPIO_PIN, 0); // Initialize to LOW
    return 0;
}

// Initialize ADS1115
int init_ads1115() {
    // Configure ADS1115 for single-ended AIN0, 4.096V range, 128 SPS, single conversion
    uint16_t config = 0x4003; //0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to ADS1115 configuration register");
        return -1;
    }
    return 0;
}

// Read ADC value from ADS1115
int read_adc(int channel) {
    if (channel != 0 && channel != 1) {
        syslog(LOG_ERR, "Invalid ADC channel: %d", channel);
        return -1;
    }

    char reg[1];
    char data[2];

    reg[0] = ADS1115_CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, reg, 1) != 0) {
        syslog(LOG_ERR, "Failed to set ADC conversion register address");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADC data");
        return -1;
    }

    int16_t adc_value = (data[0] << 8) | data[1];
    return adc_value;
}

// Convert ADC value to magnetic field strength (Gauss)
float convert_to_gauss(int adc_value) {
    float voltage = (float)adc_value * VOLTAGE_RANGE / 32768.0; // Assuming 12-bit ADC
    float gauss = voltage * GAUSS_PER_VOLT;
    return gauss;
}

// Add value to circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate rolling average
float calculate_rolling_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Check threshold and trigger shutdown
void check_threshold(float average_gauss) {
    if (average_gauss > THRESHOLD_GAUSS) {
        syslog(LOG_WARNING, "Threshold exceeded: Average Gauss = %.2f", average_gauss);
        gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
        syslog(LOG_INFO, "Motor shutdown triggered");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

int main() {
    // Initialize syslog
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize ADS1115
    if (init_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize circular buffer
    CircularBuffer cb = {{0.0}, 0, 0};

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            syslog(LOG_WARNING, "Failed to read ADC value, skipping sample");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        // Convert to Gauss
        float gauss = convert_to_gauss(adc_value);

        // Add to buffer
        add_to_buffer(&cb, gauss);

        // Calculate rolling average
        float average_gauss = calculate_rolling_average(&cb);

        // Check threshold
        check_threshold(average_gauss);

        // Delay for 1 Hz sampling rate
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

