#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 18
#define MOISTURE_THRESHOLD 300
#define WATERING_DURATION 10 // seconds
#define LOG_FILE "watering_events.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int control_pump(int gpio_pin, int state, int duration_seconds);
int log_event(int moisture_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel. Channel must be between 0 and 7.\n");
        return -1; // Indicate an error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed. pigpio error code: %d\n", result);
        return -1; // Indicate an error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the water pump
int control_pump(int gpio_pin, int state, int duration_seconds) {
    if (gpio_pin < 0 || gpio_pin > 31) {
        fprintf(stderr, "Error: Invalid GPIO pin number. Pin must be between 0 and 31.\n");
        return -1; // Indicate an error
    }

    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO pin %d. pigpio error code: %d\n", gpio_pin, gpioWrite(gpio_pin, state));
        return -1; // Indicate an error
    }

    gpioDelay(duration_seconds * 1000000); // Delay in microseconds

    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to write to GPIO pin %d. pigpio error code: %d\n", gpio_pin, gpioWrite(gpio_pin, 0));
        return -1; // Indicate an error
    }

    return 0; // Indicate success
}

// Function to log watering events
int log_event(int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Indicate an error
    }

    fprintf(log_file, "%s, Moisture Level: %d\n", timestamp, moisture_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0; // Indicate success
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);

    // Turn off the pump
    control_pump(PUMP_GPIO, 0, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed. pigpio error code: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin for pump as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring and watering system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read moisture level from channel 0
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "Error: Failed to read moisture level. Retrying in 60 seconds.\n");
            sleep(60);
            continue; // Retry
        }

        printf("Moisture level: %d\n", moisture_level);

        // Check if moisture level is below threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating water pump.\n");
            if (control_pump(PUMP_GPIO, 1, WATERING_DURATION) == 0) {
                log_event(moisture_level);
                printf("Watering event logged.\n");
            } else {
                fprintf(stderr, "Error: Failed to activate water pump.\n");
            }
        }

        // Wait for 60 seconds
        sleep(60);
    }

    // Cleanup (should not reach here if signal handler is working)
    control_pump(PUMP_GPIO, 0, 0);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

