#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1024

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int set_pwm(int gpio, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008): %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to set PWM duty cycle
int set_pwm(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    // Set PWM duty cycle
    gpioPWM(gpio, duty_cycle);

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM GPIO
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value from MCP3008
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Set PWM duty cycle based on ADC value
        int duty_cycle = (int)(((float)adc_value / 1023.0) * PWM_RANGE);

        // Set PWM duty cycle
        if (set_pwm(PWM_GPIO, duty_cycle) != 0) {
            fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        }

        // Print ADC value and PWM duty cycle
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, duty_cycle);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Stop PWM output and release resources before exiting
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

