#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_LED 17
#define BLINK_DURATION_MS 1000
#define DEFAULT_THRESHOLD 100.0

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int16_t *raw_value);
double convert_to_gauss(int16_t raw_value);
void blink_led(int duration_ms);
void signal_handler(int signal);
void cleanup();

// Structure for ADS1115 configuration
typedef struct {
    int16_t config_value;
} ads1115_config_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    ads1115_config_t config = {0};

    // Set config register value for single-ended AIN0, gain 4.096V, single conversion, disable comparator
    config.config_value = 0x4403; //0b0100010000000011;

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config.config_value);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read ADS1115 conversion
int read_ads1115(int16_t *raw_value) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, CONVERSION_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading conversion data: %d\n", result);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    // Assuming 4.096V full scale range and 12-bit resolution
    double voltage = (double)raw_value * 4.096 / 32768.0; // Convert to voltage
    double gauss = (voltage / 4.096) * 100.0; // Convert to Gauss
    return gauss;
}

// Function to blink LED
void blink_led(int duration_ms) {
    gpioWrite(GPIO_LED, 1); // Turn LED on
    gpioDelay(duration_ms / 2000); // Wait for half the duration
    gpioWrite(GPIO_LED, 0); // Turn LED off
    gpioDelay(duration_ms / 2000); // Wait for the other half
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using threshold: %.2f Gauss\n", threshold);
    } else {
        printf("Using default threshold: %.2f Gauss\n", threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_value;
    double gauss_value;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to Gauss
            gauss_value = convert_to_gauss(raw_value);

            // Print magnetic field strength
            printf("Gauss: %.2f\n", gauss_value);

            // Check if threshold is exceeded
            if (gauss_value > threshold) {
                blink_led(BLINK_DURATION_MS);
            }
        } else {
            fprintf(stderr, "Error reading ADC value\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

