// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel
#define MCP3008_CHANNEL 0

// Define VDD and VREF
#define VDD 3.3
#define VREF 3.3

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully.\n");
        if (spi_fd != -1) {
            close(spi_fd);
        }
        exit(0);
    }
}

// Function to initialize the SPI device
int init_spi(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "Error sending SPI message: %s\n", strerror(errno));
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VDD;
}

// Function to print the raw ADC value and voltage
void print_data(int adc_value, float voltage) {
    printf("Raw ADC Value: %d, Voltage: %.2f V\n", adc_value, voltage);
}

int main(void) {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the SPI device
    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read the ADC value from channel 0
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
