            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10ms
            continue;
        }

        // Control motors based on noise level
        if (noise_level > config.noise_threshold) {
            control_motor(config.motor_gpio17, 1); // Turn on motor 1
            control_motor(config.motor_gpio27, 1); // Turn on motor 2
        } else {
            control_motor(config.motor_gpio17, 0); // Turn off motor 1
            control_motor(config.motor_gpio27, 0); // Turn off motor 2
        }

