#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_CE 0
#define BH1750_ADDR 0x23
#define I2C_BUS 1
#define CSV_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL_SEC 5
#define I2C_RETRY_COUNT 3

// Global variables
int spi_handle;
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int read_bh1750(float *light_level);
int log_data(time_t timestamp, int sound_level, float light_level, int error_code);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate error
    }

    // Extract 10-bit ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to read from BH1750 sensor
int read_bh1750(float *light_level) {
    unsigned char buf[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // High Resolution Mode
    buf[1] = 0x00; // Don't care

    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
        if (result == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error: I2C write failed (retry %d): %d\n", i + 1, result);
            gpioDelay(1000); // Wait 1ms before retry
        }
    }
    if (result != 0) {
        return -1; // Indicate error
    }

    gpioDelay(180000); // Wait 180ms for measurement

    // Read 2 bytes of light level data
    result = i2cReadDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C read failed (light level): %d\n", result);
        return -1; // Indicate error
    }

    // Combine bytes to form light level (see BH1750 datasheet)
    *light_level = (float)((buf[0] << 8) | buf[1]) / 1.2;
    return 0; // Success
}

// Function to log data to CSV file
int log_data(time_t timestamp, int sound_level, float light_level, int error_code) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%.2f,%d\n", timestamp_str, sound_level, light_level, error_code);
    fflush(csv_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, 1000000, 0); // SPI0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        time_t current_time = time(NULL);
        int sound_level = -1;
        float light_level = -1.0f;
        int error_code = 0;

        // Read sound level from MCP3008
        sound_level = read_mcp3008(0); // Read from channel 0
        if (sound_level < 0) {
            error_code = 1; // MCP3008 read error
        }

        // Read light level from BH1750
        if (read_bh1750(&light_level) == 0) {
            error_code = 0; // BH1750 read error
        } else {
            error_code = 2; // BH1750 read error
        }

        // Log data to CSV file
        log_data(current_time, sound_level, light_level, error_code);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    fclose(csv_file);
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

