// Sensor channels
const int sensor_channels[NUM_SENSORS] = {0, 1, 2};

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture(int adc_value);
void control_pump(float moisture_level);
void log_data(int sensor_id, float moisture_level);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture(int adc_value) {
    // Assuming 0V = 0% moisture, 3.3V = 100% moisture
    // Linear relationship: moisture = (adc_value / 1023.0) * 100.0
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to control the water pump
void control_pump(float moisture_level) {
    if (moisture_level < MOISTURE_THRESHOLD) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump ON
        printf("Moisture level: %.2f%% - Turning pump ON\n", moisture_level);
    } else {
        gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
        printf("Moisture level: %.2f%% - Turning pump OFF\n", moisture_level);
    }
}

