    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is initially off

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring System\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = -1; // Initialize to an invalid value
            int retries = 3;
            int read_success = 0;

            while (retries > 0 && adc_value == -1) {
                adc_value = read_mcp3008(sensor_channels[i]);
                if (adc_value == -1) {
                    fprintf(stderr, "Failed to read sensor %d, retrying...\n", i);
                    gpioDelay(100); // Wait before retrying
                    retries--;
                } else {
                    read_success = 1;
                }
            }

            if (read_success == 0) {
                fprintf(stderr, "Failed to read sensor %d after multiple retries.\n", i);
                continue; // Skip to the next sensor
            }

            float moisture_level = convert_to_moisture(adc_value);
            control_pump(moisture_level);
            log_data(i, moisture_level);
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(PUMP_GPIO, 0); // Turn pump OFF
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

