        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            // Attempt to re-initialize SPI
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "Error: SPI re-initialization failed\n");
                // Consider exiting if SPI re-initialization fails repeatedly
            }
            continue; // Skip to the next iteration
        }

        // Convert ADC value to CO2 concentration
        float co2_ppm = adc_to_co2(adc_value);

        // Control the fan
        control_fan(co2_ppm);

        // Get the current fan state
        int fan_state = gpioRead(FAN_GPIO);

        // Log the data
        log_data(co2_ppm, fan_state);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

