        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int sample1 = read_mcp3008(0);
        int sample2 = read_mcp3008(1);
        int sample3 = read_mcp3008(2);

        if (sample1 == -1 || sample2 == -1 || sample3 == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping this iteration.\n");
            gpioDelay(config.sample_interval * 1000000); // Delay in microseconds
            continue;
        }

        float average_moisture = calculate_average(sample1, sample2, sample3);
        int valve_position = set_valve_position(average_moisture);

        if (log_data(sample1, sample2, sample3, average_moisture, valve_position) != 0) {
            fprintf(stderr, "Error logging data. \n");
        }

        gpioDelay(config.sample_interval * 1000000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

