        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float calculate_average(int sample1, int sample2, int sample3) {
    return (float)(sample1 + sample2 + sample3) / 3.0;
}

int set_valve_position(float average_moisture) {
    int duty_cycle = (int)((average_moisture / 100.0) * 100.0); // Scale to 0-100
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(config.valve_gpio, duty_cycle);
    return duty_cycle;
}

int log_data(int sample1, int sample2, int sample3, float average, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d, %d, %d, %.2f, %d\n", timestamp, sample1, sample2, sample3, average, valve_position);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }
}

void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(config.valve_gpio, 0); // Turn off valve
    gpioTerminate();
}

