#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MOISTURE_THRESHOLD 30.0
#define MAX_RETRIES 5
#define RETRY_DELAY_BASE 1 // seconds
#define MAX_RETRY_DELAY 60 // seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    float moisture_threshold;
    int max_retries;
    int retry_delay_base;
    int max_retry_delay;
} config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;
    int retries = 0;

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    while (retries < MAX_RETRIES) {
        if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) == 0) {
            // Extract ADC value from response
            adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI communication failed. Retrying in %d seconds...\n", RETRY_DELAY_BASE * (1 << retries));
            gpioDelay(RETRY_DELAY_BASE * (1 << retries) * 1000000); // Delay in microseconds
            retries++;
            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. SPI communication failed.\n");
                return -1; // Indicate failure
            }
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries.\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
