#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <math.h>

// Configuration file path
#define CONFIG_FILE "theremin_config.txt"

// Default values
#define DEFAULT_DISTANCE_THRESHOLD 500 // mm
#define DEFAULT_LDR_THRESHOLD 500      // ADC value
#define DEFAULT_FREQUENCY_MIN 200
#define DEFAULT_FREQUENCY_MAX 2000
#define DEFAULT_VOLUME_MIN 500
#define DEFAULT_VOLUME_MAX 1500

// GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// PWM frequency
#define PWM_FREQUENCY 440

// Global variables
static volatile int running = 1;
static int distance_threshold = DEFAULT_DISTANCE_THRESHOLD;
static int ldr_threshold = DEFAULT_LDR_THRESHOLD;
static int frequency_min = DEFAULT_FREQUENCY_MIN;
static int frequency_max = DEFAULT_FREQUENCY_MAX;
static int volume_min = DEFAULT_VOLUME_MIN;
static int volume_max = DEFAULT_VOLUME_MAX;

// Calibration data
static int last_distance = 0;
static int last_ldr_value = 0;

// Function prototypes
int read_config();
int read_ldr(int spi_fd);
float get_distance();
int map_distance_to_frequency(float distance);
int map_ldr_to_volume(int ldr_value);
void set_pwm_frequency(int frequency);
void set_pwm_volume(int volume);
void signal_handler(int signal);
void cleanup();

// Function to read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s. Using default values.\n", CONFIG_FILE);
        return -1; // Use default values
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "distance_threshold") == 0) {
            distance_threshold = atoi(value);
        } else if (strcmp(key, "ldr_threshold") == 0) {
            ldr_threshold = atoi(value);
        } else if (strcmp(key, "frequency_min") == 0) {
            frequency_min = atoi(value);
        } else if (strcmp(key, "frequency_max") == 0) {
            frequency_max = atoi(value);
        } else if (strcmp(key, "volume_min") == 0) {
            volume_min = atoi(value);
        } else if (strcmp(key, "volume_max") == 0) {
            volume_max = atoi(value);
        }
    }

    fclose(fp);
    return 0;
}

// Function to read LDR value from MCP3008
int read_ldr(int spi_fd) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended mode (1), channel 0 (000), dummy bit (1)
    tx_buf[0] = 0x01;
    tx_buf[1] = 0x80;
    tx_buf[2] = 0x00;

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transaction failed\n");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to get distance from HC-SR04 sensor
float get_distance() {
    gpioWrite(TRIG_PIN, 0); // Ensure TRIG is low
    gpioDelay(2);            // Wait 2 us

    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10);          // Send 10 us pulse
    gpioWrite(TRIG_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate error
    }
    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < 10000) {
        count++;
        gpioDelay(1); // Check every 1 us
    }
    if (count >= 10000) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate error
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in mm (speed of sound: 343 m/s)
    float distance = (float)diff * 343.0 / 20000.0; // Divide by 2 because of the round trip

    return distance;
}

// Function to map distance to frequency
int map_distance_to_frequency(float distance) {
    if (distance < 0) return 0; // Handle invalid distance

    // Clamp distance to the defined range
    if (distance < distance_threshold) {
        distance = distance_threshold;
    }

    // Map distance to frequency range
    int frequency = frequency_min + (int)(((float)(distance - distance_threshold) / (float)(distance_threshold - 0)) * (frequency_max - frequency_min));

    return frequency;
}

// Function to map LDR value to volume
int map_ldr_to_volume(int ldr_value) {
    if (ldr_value < 0) return 0; // Handle invalid LDR value

    // Clamp LDR value to the defined range
    if (ldr_value < ldr_threshold) {
        ldr_value = ldr_threshold;
    }

    // Map LDR value to volume range
    int volume = volume_min + (int)(((float)(ldr_value - ldr_threshold) / (float)(ldr_threshold - 0)) * (volume_max - volume_min));

    return volume;
}

// Function to set PWM frequency
void set_pwm_frequency(int frequency) {
    gpioSetPWMfrequency(PWM_PIN, frequency);
}

// Function to set PWM volume
void set_pwm_volume(int volume) {
    gpioPWM(PWM_PIN, volume);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioPWM(PWM_PIN, 0); // Stop PWM
    gpioTerminate();     // Terminate pigpio
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device %s\n", SPI_DEVICE);
        cleanup();
        return 1;
    }

    // Configure SPI
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = NULL;
    tr.rx_buf = NULL;
    tr.len = 0;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Warning: Using default configuration values.\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        float distance = get_distance();
        int ldr_value = read_ldr(spi_fd);

        // Error handling for sensor readings
        if (distance < 0 || ldr_value < 0) {
            fprintf(stderr, "Error: Invalid sensor reading. Using last valid values.\n");
            last_distance = distance;
            last_ldr_value = ldr_value;
            gpioDelay(100); // Small delay to avoid flooding the console
            continue;
        }

        // Map sensor values to audio parameters
        int frequency = map_distance_to_frequency(distance);
        int volume = map_ldr_to_volume(ldr_value);

        // Set PWM parameters
        set_pwm_frequency(frequency);
        set_pwm_volume(volume);

        // Update last valid values
        last_distance = distance;
        last_ldr_value = ldr_value;

        gpioDelay(50); // Small delay to avoid flooding the console
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

