#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Define GPIO pins for motor control
#define MOTOR1_ENABLE 18
#define MOTOR2_ENABLE 24
#define MOTOR1_DIRECTION 23
#define MOTOR2_DIRECTION 25

// Define GPIO pin for potentiometer 1
#define POT1_PIN 12

// Define GPIO pin for potentiometer 2
#define POT2_PIN 13

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define SPI mode
#define SPI_MODE 0

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 100

// Define speed limits
#define MIN_SPEED 0
#define MAX_SPEED 100

// Define acceleration/deceleration time
#define ACCELERATION_TIME 2
#define DECCELERATION_TIME 2

// Define reversal time
#define REVERSAL_TIME 5

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_to_speed(int adc_value);
void set_motor_speed(int motor_number, int speed);
void reverse_motors();
void cleanup();
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_mcp3008(int channel) {
    unsigned char buffer[3];
    int adc_value = 0;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    buffer[2] = 0x00; // Don't care

    wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3);

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    return adc_value;
}

// Function to map ADC value to speed
int map_to_speed(int adc_value) {
    // Linear mapping from 0-1023 to 0-100
    return (int)(((float)adc_value / 1023.0) * MAX_SPEED);
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_number, int speed) {
    int enable_pin, direction_pin;

    if (motor_number == 1) {
        enable_pin = MOTOR1_ENABLE;
        direction_pin = MOTOR1_DIRECTION;
    } else if (motor_number == 2) {
        enable_pin = MOTOR2_ENABLE;
        direction_pin = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor_number);
        return;
    }

    if (speed < 0 || speed > MAX_SPEED) {
        fprintf(stderr, "Invalid speed: %d\n", speed);
        return;
    }

    if (speed > 0) {
        gpioPWM(enable_pin, speed);
    } else if (speed < 0) {
        gpioPWM(enable_pin, -speed); // Negative speed means reverse
    }

    if (speed > 0) {
        gpioWrite(direction_pin, 1); // Forward
    } else if (speed < 0) {
        gpioWrite(direction_pin, 0); // Reverse
    }
}

// Function to reverse the direction of both motors
void reverse_motors() {
    set_motor_speed(1, -100); // Reverse Motor 1
    set_motor_speed(2, 100);  // Reverse Motor 2
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(MOTOR1_ENABLE, 0);
    gpioWrite(MOTOR2_ENABLE, 0);
    gpioWrite(MOTOR1_DIRECTION, 0);
    gpioWrite(MOTOR2_DIRECTION, 0);
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);
    gpioTerminate();
    exit(0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPi initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle == -1) {
        fprintf(stderr, "SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        // Map ADC values to speeds
        int speed1 = map_to_speed(pot1_value);
        int speed2 = map_to_speed(pot2_value);

        // Set motor speeds
        set_motor_speed(1, speed1);
        set_motor_speed(2, speed2);

        // Accelerate and decelerate
        if (speed1 > 0) {
            set_motor_speed(1, 0);
            gpioDelay(ACCELERATION_TIME * 1000); // Delay in microseconds
            set_motor_speed(1, speed1);
            gpioDelay(DECCELERATION_TIME * 1000);
        }

        if (speed2 > 0) {
            set_motor_speed(2, 0);
            gpioDelay(ACCELERATION_TIME * 1000); // Delay in microseconds
            set_motor_speed(2, speed2);
            gpioDelay(DECCELERATION_TIME * 1000);
        }

        // Reverse motors
        reverse_motors();

        // Pause for 5 seconds
        gpioDelay(REVERSAL_TIME * 1000); // Delay in microseconds

