#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define CS_PIN 8
#define LED_PIN 17

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration parameters
#define CALIBRATION_TIME 5 // seconds
#define DEBOUNCE_DELAY 10 // milliseconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
float calibrate_noise_level();
int read_sound_level();
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Structure to hold calibration data
typedef struct {
    float baseline;
    float noise_level;
} CalibrationData;

CalibrationData calibration_data;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(CS_PIN, 1); // Ensure CS is initially high
    gpioWrite(LED_PIN, 0); // Ensure LED is initially off

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, spi_data, spi_data, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((spi_data[1] & 0x03) << 8) + spi_data[2];
    return adc_value;
}

// Function to calibrate the noise level
float calibrate_noise_level() {
    float sum = 0.0;
    int num_samples = 0;
    time_t start_time = time(NULL);

    printf("Calibrating noise level for %d seconds...\n", CALIBRATION_TIME);
    while (time(NULL) - start_time < CALIBRATION_TIME) {
        int adc_value = read_sound_level();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading sound level during calibration\n");
            return -1.0; // Indicate calibration failure
        }
        sum += adc_value;
        num_samples++;
        gpioDelay(1000); // 1 ms delay
    }

    if (num_samples > 0) {
        calibration_data.baseline = sum / num_samples;
        printf("Calibration complete. Baseline: %.2f\n", calibration_data.baseline);
        return calibration_data.baseline;
    } else {
        fprintf(stderr, "Calibration failed: no valid samples collected\n");
        return -1.0; // Indicate calibration failure
    }
}

// Function to read the sound level
int read_sound_level() {
    int adc_value = read_mcp3008(0);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading sound level\n");
        return -1;
    }
    return adc_value;
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Calibrate the noise level
    if (calibrate_noise_level() < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int sound_level = read_sound_level();
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Debounce the sound level
        gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

        // Compare to the calibrated baseline
        float sound_level_float = (float)sound_level; // Cast to float for comparison
        if (sound_level_float > calibration_data.baseline) {
            control_led(1); // Turn on LED
        } else {
            control_led(0); // Turn off LED
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

