#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CE0 8         // GPIO8 (CE0)
#define GPIO_MOSI 10        // GPIO10 (MOSI)
#define GPIO_MISO 9         // GPIO9 (MISO)
#define GPIO_SCLK 11        // GPIO11 (SCLK)
#define LOG_FILE "audio_log.txt"
#define SAMPLE_RATE 1000 // 1 kHz
#define SAMPLE_INTERVAL_MS 1 // 1 ms

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold GPIO configuration
typedef struct {
    int gpio;
    int fd;
} gpio_config_t;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int gpio_export(int gpio);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_set_value(int gpio, int value);
int gpio_get_value(int gpio);
int read_adc(int channel);
void log_data(long long timestamp_ns, int raw_adc_value);
void signal_handler(int sig);

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_value = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_value = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_value) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_value = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_value) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// GPIO export function
int gpio_export(int gpio) {
    char buffer[3];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/export");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        perror("Error writing to /sys/class/gpio/export");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int gpio) {
    char buffer[3];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, len) != len) {
        perror("Error writing to /sys/class/gpio/unexport");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Error writing to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set value function
int gpio_set_value(int gpio, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) != 1) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO get value function
int gpio_get_value(int gpio) {
    char path[64];
    int fd;
    char value_str[3];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("Error reading from GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Read ADC function
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Log data function
void log_data(long long timestamp_ns, int raw_adc_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%lld|%d\n", timestamp_ns, raw_adc_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

int main() {
    // Initialize GPIO pins
    gpio_config_t gpio_configs[] = {
        {GPIO_CE0, gpio_export(GPIO_CE0)},
        {GPIO_MOSI, gpio_export(GPIO_MOSI)},
        {GPIO_MISO, gpio_export(GPIO_MISO)},
        {GPIO_SCLK, gpio_export(GPIO_SCLK)}
    };
    int num_gpio_configs = sizeof(gpio_configs) / sizeof(gpio_configs[0]);

    for (int i = 0; i < num_gpio_configs; i++) {
        if (gpio_configs[i].gpio != -1) {
            if (gpio_configs[i].fd == -1) {
                if (gpio_configs[i].gpio != GPIO_CE0 && gpio_configs[i].gpio != GPIO_MOSI &&
                    gpio_configs[i].gpio != GPIO_MISO && gpio_configs[i].gpio != GPIO_SCLK) {
                    fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_configs[i].gpio);
                    continue;
                }
                if (gpio_configs[i].gpio == GPIO_CE0) {
                    if (gpio_set_direction(gpio_configs[i].gpio, "out") != 0) {
                        fprintf(stderr, "Failed to set CE0 direction.\n");
                    }
                } else {
                    if (gpio_set_direction(gpio_configs[i].gpio, "in") != 0) {
                        fprintf(stderr, "Failed to set CE%d direction.\n", gpio_configs[i].gpio);
                    }
                }
            } else {
                if (gpio_set_value(gpio_configs[i].gpio, 1) != 0) {
                    fprintf(stderr, "Failed to set GPIO%d value.\n", gpio_configs[i].gpio);
                }
            }
        }
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        // Unexport GPIO pins before exiting
        for (int i = 0; i < num_gpio_configs; i++) {
            if (gpio_configs[i].gpio != -1) {
                gpio_unexport(gpio_configs[i].gpio);
            }
        }
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        // Unexport GPIO pins before exiting
        for (int i = 0; i < num_gpio_configs; i++) {
            if (gpio_configs[i].gpio != -1) {
                gpio_unexport(gpio_configs[i].gpio);
            }
        }
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec ts;
    int adc_value;
    long long timestamp_ns;

    while (!terminate) {
        // Read ADC value
        adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed.\n");
            break;
        }

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == -1) {
            perror("clock_gettime");
            break;
        }
        timestamp_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;

        // Log data
        log_data(timestamp_ns, adc_value);

        // Sleep for 1 ms
        nanosleep(&ts, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Unexport GPIO pins
    for (int i = 0; i < num_gpio_configs; i++) {
        if (gpio_configs[i].gpio != -1) {
            gpio_unexport(gpio_configs[i].gpio);
        }
    }

    return 0;
}

