#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CS 8
#define ADC_CHANNEL_X 0
#define ADC_CHANNEL_Y 1
#define ADC_CHANNEL_Z 2
#define VREF 3.3f
#define G_PER_VOLT 9.81f
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float P;
} KalmanFilterState;

// Kalman filter parameters
float Q = 0.01f; // Process noise covariance
float R = 0.1f;  // Measurement noise covariance

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float convert_to_voltage(int adc_value);
float convert_to_acceleration_g(float voltage);
void kalman_filter(KalmanFilterState *state, float measurement);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(MCP3008_CS, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(MCP3008_CS, 1); // Deselect the MCP3008

    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

// Convert voltage to acceleration in g
float convert_to_acceleration_g(float voltage) {
    return (voltage - VREF) / G_PER_VOLT;
}

// Kalman filter update step
void kalman_filter(KalmanFilterState *state, float measurement) {
    // Prediction step
    state->x = state->x + 0.1f; // Simple prediction (adjust as needed)
    state->P = state->P + 0.1f; // Simple prediction (adjust as needed)

    // Update step
    float K = state->P / (state->P + R);
    state->x = state->x + K * (measurement - state->x);
    state->P = (1 - K) * state->P;
}

// Print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure MCP3008_CS as output
    gpioSetMode(MCP3008_CS, PI_OUTPUT);
    gpioWrite(MCP3008_CS, 1); // Deselect MCP3008 initially

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_x = read_adc(ADC_CHANNEL_X);
        int adc_y = read_adc(ADC_CHANNEL_Y);
        int adc_z = read_adc(ADC_CHANNEL_Z);

        if (adc_x < 0 || adc_y < 0 || adc_z < 0) {
            fprintf(stderr, "Error reading ADC values\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC values to voltage
        float voltage_x = convert_to_voltage(adc_x);
        float voltage_y = convert_to_voltage(adc_y);
        float voltage_z = convert_to_voltage(adc_z);

        // Convert voltage to acceleration in g
        float acceleration_x = convert_to_acceleration_g(voltage_x);
        float acceleration_y = convert_to_acceleration_g(voltage_y);
        float acceleration_z = convert_to_acceleration_g(voltage_z);

        // Kalman filter
        KalmanFilterState kalman_state;
        kalman_state.x = 0.0f;
        kalman_state.P = 1.0f;

        kalman_filter(&kalman_state, acceleration_x);
        kalman_filter(&kalman_state, acceleration_y);
        kalman_filter(&kalman_state, acceleration_z);

        // Print acceleration values
        print_acceleration(acceleration_x, acceleration_y, acceleration_z);

        // Delay for 10ms (10Hz sampling rate)
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

