        int sensor3_state = read_sensor(SENSOR3_PIN);

        // Check for errors during sensor reading
        if (sensor1_state == -1 || sensor2_state == -1 || sensor3_state == -1) {
            fprintf(stderr, "Error reading sensor data. Skipping logging iteration.\n");
            gpioDelay(100); // Wait 100ms before the next iteration
            continue;
        }

        // Convert the digital states to magnetic field strengths
        float sensor1_mT = convert_to_magnetic_field(sensor1_state);
        float sensor2_mT = convert_to_magnetic_field(sensor2_state);
        float sensor3_mT = convert_to_magnetic_field(sensor3_state);

