// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "watering.log"

// Global variables
int spi_handle;
FILE *log_file;

// Function prototypes
int read_moisture_sensor(int spi_handle);
void control_pump(int gpio_pin, int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read moisture sensor data from MCP3008
int read_moisture_sensor(int spi_handle) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // MCP3008 command to read channel 0 (single-ended)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = 0x80; // Single-ended, channel 0
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_event("Error: SPI transfer failed");
        return -1; // Indicate error
    }

    // Extract ADC value from the response
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to control the water pump
void control_pump(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    char message[100];
    sprintf(message, "Pump set to %s", (state == 1) ? "ON" : "OFF");
    log_event(message);
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Program terminated by signal");
    control_pump(PUMP_GPIO, 0); // Turn off the pump
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    int moisture_level;
    int pump_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (1) {
        moisture_level = read_moisture_sensor(spi_handle);

        if (moisture_level < 0) {
            log_event("Error reading moisture sensor, continuing...");
            gpioDelay(60000); // Wait 60 seconds before retrying
            continue;
        }

        char message[100];
        sprintf(message, "Moisture level: %d", moisture_level);
        log_event(message);

        if (moisture_level < MOISTURE_THRESHOLD && pump_state == 0) {
            control_pump(PUMP_GPIO, 1); // Turn pump ON
            pump_state = 1;
        } else if (moisture_level >= MOISTURE_THRESHOLD && pump_state == 1) {
            control_pump(PUMP_GPIO, 0); // Turn pump OFF
            pump_state = 0;
        }

        gpioDelay(60000); // Wait 60 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

