    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (read_mcp3008): %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to write CSV header
int write_csv_header(FILE *file) {
    if (fputs(CSV_FILENAME, file) == EOF) {
        fprintf(stderr, "Error: Failed to write CSV filename to file.\n");
        return -1;
    }
    fputs(",Channel0,Channel1,Channel2\n", file);
    return 0;
}

// Function to write CSV data
int write_csv_data(FILE *file, int channel0, int channel1, int channel2) {
    if (fputs(CSV_FILENAME, file) == EOF) {
        fprintf(stderr, "Error: Failed to write CSV filename to file.\n");
        return -1;
    }
    fprintf(file, "%d,%d,%d\n", channel0, channel1, channel2);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Closing CSV file and terminating pigpio.\n");
        terminate = 1;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file for writing.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    if (fseek(csv_file, 0, SEEK_END) == 0) {
        if (write_csv_header(csv_file) != 0) {
            fclose(csv_file);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        int channel0_value = read_mcp3008(MCP3008_CHANNEL_0);
        int channel1_value = read_mcp3008(MCP3008_CHANNEL_1);
        int channel2_value = read_mcp3008(MCP3008_CHANNEL_2);

        if (channel0_value == -1 || channel1_value == -1 || channel2_value == -1) {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying in 1 second.\n");
            sleep(1);
            continue; // Retry the loop
        }

        // Write data to CSV file
        if (write_csv_data(csv_file, channel0_value, channel1_value, channel2_value) != 0) {
            fprintf(stderr, "Error: Failed to write data to CSV file.\n");
        }

        // Sleep for 1 second
        sleep(1);
    }

    // Close CSV file
    if (fseek(csv_file, 0, SEEK_END) == 0) {
        if (write_csv_header(csv_file) != 0) {
            fprintf(stderr, "Error: Failed to write CSV header after closing file.\n");
        }
        fclose(csv_file);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

