#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_RECONNECT_DELAY 1  // seconds
#define MQTT_RECONNECT_MAX 60  // seconds
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold MQTT client state
typedef struct {
    int sock;
    int client_id;
    int reconnection_delay;
    int reconnection_max;
    int last_reconnection_delay;
} mqtt_client_state_t;

// Function prototypes
int mqtt_connect(mqtt_client_state_t *state);
int mqtt_subscribe(mqtt_client_state_t *state);
int mqtt_receive_message(mqtt_client_state_t *state, char *buffer, int max_length);
int mqtt_parse_json(const char *json_string, int *led_state);
int mqtt_handle_message(const char *message);
void mqtt_disconnect(mqtt_client_state_t *state);
void signal_handler(int signal);
void cleanup(mqtt_client_state_t *state);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, exiting gracefully...\n");
}

// MQTT connection function
int mqtt_connect(mqtt_client_state_t *state) {
    int rc;
    char connect_payload[100];
    int retry_delay = MQTT_RECONNECT_DELAY;

    while (state->last_reconnection_delay == 0 && program_running) {
        snprintf(connect_payload, sizeof(connect_payload), "topic=\"%s\" qos=0", MQTT_TOPIC);
        rc = mqtt_simple_connect(state, connect_payload, retry_delay);
        if (rc != 0) {
            fprintf(stderr, "Error connecting to MQTT broker: %d. Retrying in %d seconds.\n", rc, retry_delay);
            sleep(retry_delay);
            retry_delay *= 2;
            if (retry_delay > MAX_RECONNECT_DELAY) {
                retry_delay = MAX_RECONNECT_DELAY;
            }
        } else {
            state->last_reconnection_delay = retry_delay;
            break; // Connection successful, exit retry loop
        }
    }

    if (!program_running) {
        return -1; // Exit if signal received during connection attempt
    }

    return 0;
}

// MQTT subscribe function
int mqtt_subscribe(mqtt_client_state_t *state) {
    int rc;
    char subscribe_payload[100];

    snprintf(subscribe_payload, sizeof(subscribe_payload), "topic=\"%s\" qos=0", MQTT_TOPIC);
    rc = mqtt_simple_subscribe(state, subscribe_payload, 0);
    if (rc != 0) {
        fprintf(stderr, "Error subscribing to topic: %s. Error code: %d\n", MQTT_TOPIC, rc);
        return -1;
    }
    return 0;
}

// MQTT receive message function
int mqtt_receive_message(mqtt_client_state_t *state, char *buffer, int max_length) {
    int rc;
    int bytes_received = 0;

    while (program_running) {
        rc = mqtt_receive(state, buffer + bytes_received, max_length - bytes_received);
        if (rc > 0) {
            bytes_received += rc;
            if (bytes_received >= max_length) {
                break;
            }
        } else if (rc < 0) {
            fprintf(stderr, "Error receiving message: %d. Reconnecting...\n", rc);
            mqtt_disconnect(state);
            if (mqtt_connect(state) != 0) {
                fprintf(stderr, "Failed to reconnect to MQTT broker.\n");
                return -1;
            }
        } else {
            // No message received, sleep for a short interval
            gpioDelay(10000); // 10ms
        }
    }

    return 0;
}

// MQTT handle message function
int mqtt_handle_message(const char *message) {
    int led_state;
    int rc;

    rc = mqtt_parse_json(message, &led_state);
    if (rc != 0) {
        fprintf(stderr, "Error parsing JSON: %s\n", message);
        return -1;
    }

    if (led_state == 1) {
        gpioWrite(GPIO_PIN, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_PIN, 0); // Turn LED off
    }

    return 0;
}

// MQTT disconnect function
void mqtt_disconnect(mqtt_client_state_t *state) {
    if (state->sock >= 0) {
        close(state->sock);
        state->sock = -1;
    }
}

// JSON parsing function (using jansson)
int mqtt_parse_json(const char *json_string, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(json_string, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    json_t *led_value = json_object_get(root, "led_state");
    if (!json_is_boolean(led_value)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean\n");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_value);
    json_decref(root);
    return 0;
}

// Cleanup function
void cleanup(mqtt_client_state_t *state) {
    if (state->sock >= 0) {
        mqtt_disconnect(state);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    mqtt_client_state_t mqtt_state;
    char buffer[256];
    int rc;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn LED off initially

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT client state
    mqtt_state.client_id = MQTT_CLIENT_ID;
    mqtt_state.reconnection_delay = MQTT_RECONNECT_DELAY;
    mqtt_state.reconnection_max = MQTT_RECONNECT_MAX;
    mqtt_state.sock = -1;

    // MQTT connection
    if (mqtt_connect(&mqtt_state) != 0) {
        fprintf(stderr, "MQTT connection failed. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // MQTT subscription
    if (mqtt_subscribe(&mqtt_state) != 0) {
        fprintf(stderr, "MQTT subscription failed. Exiting.\n");
        mqtt_disconnect(&mqtt_state);
        gpioTerminate();
        return 1;
    }

    printf("MQTT connected and subscribed. Listening for messages...\n");

    // Main loop
    while (program_running) {
        rc = mqtt_receive_message(&mqtt_state, buffer, sizeof(buffer));
        if (rc > 0) {
            mqtt_handle_message(buffer);
        } else if (rc < 0) {
            fprintf(stderr, "Error receiving message, exiting.\n");
            break;
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup and exit
    mqtt_disconnect(&mqtt_state);
    cleanup(&mqtt_state);

    return 0;
}

