#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int sound_level;
    int alarm_duration = 1; // seconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        sound_level = gpioRead(SOUND_SENSOR_PIN);

        if (sound_level == 0) { // Sound detected (LOW signal)
            printf("Sound detected!\n");
            gpioWrite(ALARM_LED_PIN, 1); // Turn on alarm LED
            gpioDelay(alarm_duration * 1000000); // Delay for 1 second
            gpioWrite(ALARM_LED_PIN, 0); // Turn off alarm LED
        }

        gpioDelay(100000); // 100ms delay
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

