#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define EVENT_FILE "/tmp/vibration_event"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_line;
    FILE *log_file;
    char timestamp[20];
    time_t rawtime;
    struct tm *timeinfo;
    int vibration_detected;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO line
    gpio_line = gpioOpen(GPIO_PIN, PI_INPUT, 0);
    if (gpio_line < 0) {
        fprintf(stderr, "Failed to open GPIO %d\n", GPIO_PIN);
        gpioTerminate();
        return 1;
    }

    // Request event for falling edge
    if (gpioSetAlertFuncEx(gpio_line, FALLING_EDGE, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to request event for GPIO %d\n", GPIO_PIN);
        gpioSetAlertFunc(gpio_line, PI_ALERT_DISABLE);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioSetAlertFunc(gpio_line, PI_ALERT_DISABLE);
        gpioTerminate();
        return 1;
    }

    printf("Vibration monitor started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Wait for event
        if (gpioRead(gpio_line) == 0) { // Assuming active low
            vibration_detected = 1;
        } else {
            vibration_detected = 0;
        }

        if (vibration_detected) {
            // Read event
            FILE *event_file = fopen(EVENT_FILE, "w");
            if (event_file == NULL) {
                perror("Failed to open event file");
                gpioSetAlertFunc(gpio_line, PI_ALERT_DISABLE);
                gpioTerminate();
                fclose(log_file);
                return 1;
            }

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(event_file, "%s - Vibration detected!\n", timestamp);
            fclose(event_file);

            // Log to file and stdout
            printf("%s - Vibration detected!\n", timestamp);

            // Shutdown the system
            system("sudo shutdown -h now");
            break; // Exit the loop after shutdown
        }

