    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    int adc_value;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_bh1750(&lux) == 0 && read_mcp3008(0) != -1) {
            // Log the data
            log_data(lux, adc_value);
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

