// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
int initialize_gpio();
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to activate and deactivate relays
    while (program_running) {
        activate_relay(1);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(1);
        gpioDelay(1000); // Wait for 1 second

        activate_relay(2);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(2);
        gpioDelay(1000); // Wait for 1 second

        activate_relay(3);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(3);
        gpioDelay(1000); // Wait for 1 second

        activate_relay(4);
        gpioDelay(1000); // Wait for 1 second
        deactivate_relay(4);
        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

