// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_ENABLE_PIN 27
#define PWM_RANGE 255
#define LOG_FILE "rain_log.txt"

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_handle;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
int log_rain_level(int level);
void control_motor(int direction);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to log rain level to file
int log_rain_level(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the DC motor
void control_motor(int direction) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_FORWARD_PIN, 1);
        gpioWrite(MOTOR_REVERSE_PIN, 0);
        gpioPWM(MOTOR_ENABLE_PIN, 128); // 50% duty cycle
    } else if (direction == 0) { // Reverse
        gpioWrite(MOTOR_FORWARD_PIN, 0);
        gpioWrite(MOTOR_REVERSE_PIN, 1);
        gpioPWM(MOTOR_ENABLE_PIN, 128); // 50% duty cycle
    } else {
        fprintf(stderr, "Error: Invalid motor direction: %d\n", direction);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motor and exiting...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code = %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes for motor control
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_REVERSE_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_ENABLE_PIN, PI_OUTPUT);

    // Set PWM range for motor enable pin
    gpioSetPWMrange(MOTOR_ENABLE_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read rain sensor value
        int rain_level = read_mcp3008(0);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor value\n");
            // Log the error to the log file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, ERROR: Failed to read rain sensor value\n", timestamp);
            fflush(log_file);
        } else {
            // Log rain level
            log_rain_level(rain_level);

            // Control motor based on rain level
            if (rain_level > RAIN_THRESHOLD) {
                control_motor(1); // Forward
            } else {
                control_motor(0); // Reverse
            }
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(0); // Stop the motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

