#include <pigpio.h>

// Define GPIO pins
#define CLOCK_PIN 26
#define DATA_PIN 27
#define LED_PIN 16

// Define constants
#define NUM_SAMPLES 100
#define DEBOUNCE_DELAY_MS 50
#define LED_ON_MS 500

// Global variables
volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int *samples, int num_samples);
void control_led(int state);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int led_state;
} ProgramState;

ProgramState state = {0}; // Initialize LED state to off

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (running) {
        // Read ADC value
        int adc_value = read_adc();

        // Check for errors during ADC read
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC. Retrying.\n");
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Store ADC value in circular buffer
        samples[0] = adc_value; // Initialize with the first sample

        // Detect clap
        if (detect_clap(samples, NUM_SAMPLES)) {
            // Turn on LED
            control_led(1);

            // Wait for debounce
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to us

            // Turn off LED
            control_led(0);

            // Print timestamped message
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - Clap detected!\n", timestamp);
        }

        // Delay before next sample
        gpioDelay(10000); // 10ms delay
    }

    // Clean up GPIO on exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set clock pin as input
    gpioSetMode(CLOCK_PIN, PI_INPUT);
    // Set data pin as input
    gpioSetMode(DATA_PIN, PI_INPUT);
    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read ADC value using bit-banging
int read_adc() {
    int sum = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        // Clock high
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability
        // Read data pin
        sum += gpioRead(DATA_PIN);
        // Clock low
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1); // Small delay for clock stability
    }
    return sum;
}

// Detect clap event
int detect_clap(int *samples, int num_samples) {
    // Simple threshold-based clap detection
    if (samples[0] > 500) { // Adjust threshold as needed
        return 1;
    } else {
        return 0;
    }
}

// Control LED state
void control_led(int state) {
    state_t current_state = state.led_state;
    state.led_state = state.led_state ? 0 : 1; // Toggle LED state
    gpioWrite(LED_PIN, current_state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated.\n");
    exit(0);
}

