#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "distance_log.txt"

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int distance;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Feeder Monitoring System started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the GPIO pin
        distance = gpioRead(GPIO_PIN);

        // Get current time
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the data
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately

        // Check distance and print status
        if (distance == 0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Clean up
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

