#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3 // Reference voltage
#define SENSOR_SENSITIVITY 0.001 // 100 mV/A
#define SENSOR_ZERO_FIELD_OUTPUT 2.5 // V
#define LOG_FILE "magnetic_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    char spi_device[20];
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int adc_channel;
    float vref;
    float sensor_sensitivity;
    float sensor_zero_field_output;
    char log_file[20];
    int sample_interval_ms;
} Config;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_adc(int fd, int channel);
float convert_to_magnetic_field(int adc_value, float vref, float sensor_sensitivity, float sensor_zero_field_output);
int log_data(FILE *fp, float magnetic_field);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_value = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_value = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_value) == -1) {
        perror("Error setting bits per word");
        close(fd);
