#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <stdbool.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 5.0 // Reference voltage
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
FILE *log_file = NULL;

// Structure for configuration
typedef struct {
    char spi_device[20];
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int adc_channel;
    float vref;
    char log_file[20];
    int sample_interval_ms;
} Config;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_adc(int fd, int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void signal_handler(int sig);
void cleanup(int fd, FILE *fp);

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_value = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_per_word_value = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_value) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    int speed_value = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_value) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error performing SPI transfer");
        return -1;
    }

    return 0;
}

// ADC read function
int read_adc(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error reading ADC channel %d\n", channel);
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    float current = (adc_value / 1023.0) * VREF;
    return current;
}

// Logging function
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s XX.XXA\n", timestamp);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Cleanup function
void cleanup(int fd, FILE *fp) {
    if (fd != -1) {
        close(fd);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Configuration
    Config config = {
        .spi_device = SPI_DEVICE,
        .spi_mode = SPI_MODE,
        .spi_bits_per_word = SPI_BITS_PER_WORD,
        .spi_speed = SPI_SPEED,
        .adc_channel = ADC_CHANNEL,
        .vref = VREF,
        .log_file = LOG_FILE,
        .sample_interval_ms = SAMPLE_INTERVAL_MS
    };

    // Signal handling
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(config.spi_device, config.spi_mode, config.spi_bits_per_word, config.spi_speed);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup(spi_fd, NULL);
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(spi_fd, config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping sample.\n");
            usleep(config.sample_interval_ms * 1000); // Sleep for the sample interval
            continue;
        }

        // Voltage check
        float voltage = (adc_value / 1023.0) * config.vref;
        if (voltage < 0.0 || voltage > config.vref) {
            fprintf(stderr, "Voltage out of range: %.2fV. Skipping sample.\n", voltage);
            usleep(config.sample_interval_ms * 1000); // Sleep for the sample interval
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);

        usleep(config.sample_interval_ms * 1000); // Sleep for the sample interval
    }

    // Cleanup and exit
    cleanup(spi_fd, log_file);
    return 0;
}

