#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Debounce interval in milliseconds
#define DEBOUNCE_INTERVAL 2

// Global variable to store the last sensor reading for each sensor
int last_sensor1_value = 1; // Initialize to 1 (no object present)
int last_sensor2_value = 1; // Initialize to 1 (no object present)

// Function prototypes
int read_sensor(int gpio_pin);
int debounce(int gpio_pin, int *last_value);
int get_majority_value(int sensor1_value, int sensor2_value);
void log_sensor_state(int sensor1_value, int sensor2_value);
void check_alert_condition(int sensor1_value, int sensor2_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to implement the debounce routine
int debounce(int gpio_pin, int *last_value) {
    int i;
    for (i = 0; i < 5; i++) {
        int value = read_sensor(gpio_pin);
        if (value != *last_value) {
            *last_value = value;
            gpioDelay(DEBOUNCE_INTERVAL * 1000); // Delay for 2ms
        }
    }
    return *last_value;
}

// Function to determine the majority value
int get_majority_value(int sensor1_value, int sensor2_value) {
    return (sensor1_value && sensor2_value) ? 0 : 1;
}

// Function to log the sensor state
void log_sensor_state(int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (sensor1_value == 0) {
        printf("%s: Sensor 1 - Object Present\n", timestamp);
    } else {
        printf("%s: Sensor 1 - No Object\n", timestamp);
    }

    if (sensor2_value == 0) {
        printf("%s: Sensor 2 - Object Present\n", timestamp);
    } else {
        printf("%s: Sensor 2 - No Object\n", timestamp);
    }
}

// Function to check for the alert condition
void check_alert_condition(int sensor1_value, int sensor2_value) {
    if (sensor1_value == 0 && sensor2_value == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values with debouncing
        int sensor1_value = debounce(SENSOR1_PIN, &last_sensor1_value);
        int sensor2_value = debounce(SENSOR2_PIN, &last_sensor2_value);

        // Determine the majority value
        int majority_value = get_majority_value(sensor1_value, sensor2_value);

        // Log the sensor state
        log_sensor_state(sensor1_value, sensor2_value);

        // Check for the alert condition
        check_alert_condition(sensor1_value, sensor2_value);

        // Update the last sensor readings
        last_sensor1_value = sensor1_value;
        last_sensor2_value = sensor2_value;

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

