    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);
    return 0;
}

int read_pir_sensor() {
    return gpioRead(PIR_GPIO);
}

int debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // pigpioDelay takes microseconds
    return 0;
}

int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[100];
    char command[200];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --quality 85", filename);

    int status = system(command);
    if (status == -1) {
        syslog(LOG_ERR, "Failed to execute libcamera-still: %s", strerror(errno));
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
        return -1;
    }

    syslog(LOG_INFO, "Image captured: %s", filename);
    return 0;
}

int main() {
    openlog("pir_camera", LOG_PID | LOG_CONS, LOG_USER);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Program started");

    while (program_running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            syslog(LOG_INFO, "Motion detected");
            if (capture_image() != 0) {
                syslog(LOG_ERR, "Failed to capture image");
            }
        }

        debounce_delay();
    }

    gpioTerminate();
    syslog(LOG_INFO, "Program stopped");
    closelog();
    return 0;
}

