#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#define NUM_BUFFERS 1
#define BUFFER_SIZE 1024

// Structure to hold camera configuration
typedef struct {
    char *device_path;
    int fd;
    void **buffers;
    size_t buffer_size;
    int buffer_count;
    int buffer_index;
    int streaming;
} camera_config_t;

// Global configuration
camera_config_t config;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    streaming = 0; // Stop streaming
    if (config.fd != -1) {
        close(config.fd);
    }
    if (config.buffers != NULL) {
        for (int i = 0; i < config.buffer_count; i++) {
            munmap(config.buffers[i], config.buffer_size);
        }
        free(config.buffers);
    }
    exit(0);
}

// Function to initialize the camera
int init_camera(camera_config_t *config, const char *device_path) {
    config->device_path = strdup(device_path);
    if (config->device_path == NULL) {
        perror("strdup");
        return -1;
    }

    config->fd = open(device_path, O_RDWR | O_NONBLOCK, 0);
    if (config->fd == -1) {
        perror("open");
        return -1;
    }

    config.buffer_size = BUFFER_SIZE;
    config.buffer_count = NUM_BUFFERS;
    config.buffers = calloc(config.buffer_count, sizeof(void *));
    if (config.buffers == NULL) {
        perror("calloc");
        close(config.fd);
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(config->fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_path);
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device_path);
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY; // Set desired format
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(config->fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = config.buffer_count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(config->fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("VIDIOC_REQBUFS");
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    if (req.count < config.buffer_count) {
        fprintf(stderr, "Error: %s does not support buffer allocation\n", device_path);
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    for (config.buffer_index = 0; config.buffer_index < config.buffer_count; config.buffer_index++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = config.buffer_index;

        if (ioctl(config->fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF");
            close(config.fd);
            free(config.device_path);
            return -1;
        }

        config.buffer_size = buf.length;
        config.buffers[config.buffer_index] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, config.fd, buf.m.offset);
        if (config.buffers[config.buffer_index] == MAP_FAILED) {
            perror("mmap");
            close(config.fd);
            free(config.device_path);
            return -1;
        }
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(config->fd, VIDIOC_STREAMON, &type) == -1) {
        perror("VIDIOC_STREAMON");
        close(config.fd);
        free(config.device_path);
        return -1;
    }

    config.streaming = 1;
    return 0;
}

// Function to dequeue a frame
int dequeue_frame(camera_config_t *config) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(config->fd, VIDIOC_DQBUF, &buf) == -1) {
        if (errno == EAGAIN) {
            // Timeout occurred, return 0 to indicate no data
            return 0;
        } else {
            perror("VIDIOC_DQBUF");
            return -1;
        }
    }

    // Copy the frame data to the buffer
    memcpy(config->buffers[config->buffer_index], &buf, sizeof(buf));

    // Advance to the next frame
    config->buffer_index = (config->buffer_index + 1) % config.buffer_count;

    // Requeue the buffer
    if (ioctl(config->fd, VIDIOC_QBUF, &buf) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    return 1; // Indicate that a frame was dequeued
}

// Function to save a frame as a PGM file
int save_frame(camera_config_t *config, int index) {
    FILE *fp = fopen("image_0001.pgm", "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", 640, 480); // Image width and height, max pixel value
    fseek(fp, 0, SEEK_END); // Move to the end of the file to overwrite
    fseek(fp, 0, SEEK_SET); // Move back to the beginning of the file

    // Read the frame data from the buffer
    char *frame_data = (char *)config->buffers[config->buffer_index];
    size_t frame_size = config.buffer_size;
    char *end_ptr;

    // Copy the frame data to the file
    end_ptr = frame_data + frame_size;
    while (frame_data < end_ptr) {
        fwrite(frame_data, 1, end_ptr - frame_data, fp);
        frame_data = end_ptr;
        end_ptr = frame_data + frame_size;
    }

    fclose(fp);
    printf("Saved image_%03d.pgm\n", index);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    const char *device_path = "/dev/video0";

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                device_path = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-d device_path]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize the camera
    if (init_camera(&config, device_path) != 0) {
        fprintf(stderr, "Failed to initialize camera\n");
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (streaming) {
        if (dequeue_frame(&config) == 0) {
            if (save_frame(&config, config.buffer_index) != 0) {
                fprintf(stderr, "Failed to save frame\n");
            }
        } else if (errno == EAGAIN) {
            // Timeout occurred, sleep for a short period
            struct timespec ts;
            ts.tv_sec = 2; // 2 seconds
            ts.tv_nsec = 0;
            nanosleep(&ts, NULL);
        } else {
            fprintf(stderr, "Error dequeueing frame: %s\n", strerror(errno));
        }
    }

    // Clean up resources
    close(config.fd);
    free(config.device_path);
    free(config.buffers);

    return EXIT_SUCCESS;
}

