#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <time.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_WIDTH 640
#define FRAME_HEIGHT 480
#define FRAME_BUFFER_SIZE (FRAME_WIDTH * FRAME_HEIGHT * 3) // MJPEG
#define LOG_FILE "frame_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int fd = -1;
FILE *log_file = NULL;

// Structure to hold video buffer information
typedef struct {
    void *start;
    size_t length;
} buffer_t;

// Function prototypes
int open_device(const char *device_name);
int configure_device(int fd);
buffer_t *mmap_buffer(int fd, size_t length);
int unmap_buffer(buffer_t *buffer);
int read_frame(buffer_t *buffer, unsigned char *frame_data, size_t frame_size);
void log_timestamp(FILE *log_file);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to configure the video device
int configure_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = FRAME_WIDTH;
    fmt.fmt.pix.height = FRAME_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to map the video buffer to memory
buffer_t *mmap_buffer(int fd, size_t length) {
    buffer_t *buffer = (buffer_t *)mmap(NULL, length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return NULL;
    }
    buffer->length = length;
    return buffer;
}

// Function to unmap the video buffer from memory
int unmap_buffer(buffer_t *buffer) {
    if (buffer == NULL) return 0;
    if (munmap(buffer->start, buffer->length) == -1) {
        perror("Error unmapping buffer");
        return -1;
    }
    return 0;
}

// Function to read a frame from the video buffer
int read_frame(buffer_t *buffer, unsigned char *frame_data, size_t frame_size) {
    if (buffer == NULL || frame_data == NULL || frame_size == 0) return -1;

    ssize_t bytes_read = read(fd, frame_data, frame_size);
    if (bytes_read == -1) {
        perror("Error reading frame");
        return -1;
    }

    return (int)bytes_read;
}

// Function to log the timestamp to a file
void log_timestamp(FILE *log_file) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%s.%06ld", timeinfo);
    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure the data is written to the file immediately
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return 1;
    }

    // Configure the device
    if (configure_device(fd) == -1) {
        close(fd);
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(fd);
        return 1;
    }

    // Main loop
    unsigned char frame_data[FRAME_BUFFER_SIZE];
    while (program_running) {
