#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define NUM_BUFFERS 4
#define FRAME_SIZE (NUM_BUFFERS * 2) // YUYV * 2 bytes per pixel
#define MAX_PACKET_SIZE 65000
#define I2C_DEVICE "/dev/i2c-1"

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Structure to hold I2C device information
typedef struct {
    int fd;
    int address;
} i2c_device_t;

// Global variables
static int camera_fd = -1;
static int i2c_fd = -1;
static int udp_socket = -1;
static int num_fragments = 0;
static int frame_index = 0;
static int target_ip[16] = {0};
static int target_port = 0;
static int running = 1;
static buffer_t *buffers = NULL;
static i2c_device_t *i2c_devices = NULL;
static int num_i2c_devices = 0;

// Function prototypes
int open_camera(const char *device_name);
int configure_camera(int fd);
int capture_frame(int fd, unsigned char *frame_data, size_t frame_size);
int fragment_frame(unsigned char *frame_data, size_t frame_size, unsigned char *fragments[], int *num_fragments);
int send_udp_packet(unsigned char *packet, int packet_size, const char *ip_address, int port);
void signal_handler(int sig);
int i2c_read_device(int fd, unsigned char *data, int count);
int i2c_write_device(int fd, unsigned char *data, int count);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, stopping...\n", sig);
        running = 0;
    }
}

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR);
    if (fd < 0) {
        perror("Error opening camera device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", device_name);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure the camera
int configure_camera(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting camera format");
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("Out of memory");
        return -1;
    }

    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to capture a frame from the camera
int capture_frame(int fd, unsigned char *frame_data, size_t frame_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    struct v4l2_buffer rbuf;
    memset(&rbuf, 0, sizeof(rbuf));
    rbuf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    rbuf.memory = V4L2_MEMORY_MMAP;
    rbuf.index = 0;

    if (ioctl(fd, VIDIOC_DQBUF, &rbuf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (frame_size != rbuf.bytesused) {
        fprintf(stderr, "Error: Frame size mismatch\n");
        return -1;
    }

    memcpy(frame_data, buffers[rbuf.index].start, frame_size);
    return 0;
}

// Function to fragment a frame into smaller packets
int fragment_frame(unsigned char *frame_data, size_t frame_size, unsigned char *fragments[], int *num_fragments) {
    size_t frame_offset = 0;
    size_t fragment_size = 0;
    size_t remaining_frame_size = frame_size;

    *num_fragments = 0;
    while (remaining_frame_size > 0) {
        fragment_size = (remaining_frame_size > MAX_PACKET_SIZE) ? MAX_PACKET_SIZE : remaining_frame_size;
        memcpy(fragments[*num_fragments], frame_data + frame_offset, fragment_size);
        frame_offset += fragment_size;
        *num_fragments++;
        remaining_frame_size -= fragment_size;
    }

    return 0;
}

// Function to send a UDP packet
int send_udp_packet(unsigned char *packet, int packet_size, const char *ip_address, int port) {
    struct sockaddr_in servaddr;
    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(udp_socket, packet, packet_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

// Function to read from an I2C device
int i2c_read_device(int fd, unsigned char *data, int count) {
    if (count > 1) {
        fprintf(stderr, "Error: I2C read only supports reading a single byte at a time\n");
        return -1;
    }

    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to write to an I2C device
int i2c_write_device(int fd, unsigned char *data, int count) {
    if (count > 1) {
        fprintf(stderr, "Error: I2C write only supports writing a single byte at a time\n");
        return -1;
    }

    if (write(fd, data, count) != count) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            target_ip[0] = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            target_port = atoi(argv[i + 1]);
            i++;
        } else if (i2c_devices == NULL) {
            i2c_devices = calloc(1, sizeof(i2c_device_t));
            if (!i2c_devices) {
                perror("Out of memory");
                return 1;
            }
            num_i2c_devices = 0;
        } else {
            fprintf(stderr, "Usage: %s [-i <ip_address>] [-p <port>] [-d <i2c_device_address>] [-d <i2c_device_address>] [-d <i2c_device_address>]\n", argv[0]);
            return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    camera_fd = open_camera("/dev/video0");
    if (camera_fd < 0) {
        return 1;
    }

    // Configure the camera
    if (configure_camera(camera_fd) < 0) {
        close(camera_fd);
        return 1;
    }

    // Open the UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error opening UDP socket");
        close(camera_fd);
        return 1;
    }

    // Main loop
    unsigned char frame_data[FRAME_SIZE];
    unsigned char *fragments[NUM_BUFFERS];
    int packet_size;
    unsigned char header[40]; // Adjust size as needed

    while (running) {
        // Capture a frame
        if (capture_frame(camera_fd, frame_data, FRAME_SIZE) < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }

        // Fragment the frame
        if (fragment_frame(frame_data, FRAME_SIZE, fragments, &num_fragments) < 0) {
            fprintf(stderr, "Error fragmenting frame\n");
            break;
        }

        // Send UDP packets
        for (int i = 0; i < num_fragments; i++) {
            packet_size = sizeof(header) + num_fragments * 2; // Header + fragment size
            memcpy(header, &frame_index, sizeof(frame_index));
            memcpy(header + sizeof(frame_index), &i, sizeof(i));
            memcpy(header + sizeof(frame_index) + sizeof(i), &num_fragments, sizeof(num_fragments));
            memcpy(header + sizeof(frame_index) + sizeof(i) + sizeof(num_fragments), &packet_size, sizeof(packet_size));

            if (send_udp_packet(header, packet_size, target_ip, target_port) < 0) {
                fprintf(stderr, "Error sending UDP packet %d\n", i);
                break;
            }
        }

        frame_index++;
        if (frame_index >= num_fragments) {
            frame_index = 0;
        }

        // Read I2C data (example: read from device 0x28)
        if (i2c_devices != NULL && num_i2c_devices > 0) {
            if (i2c_read_device(i2c_devices[0].fd, (unsigned char *)target_ip, 1) < 0) {
                fprintf(stderr, "Error reading from I2C device 0x28\n");
            }
        }

        // Sleep for a short period
        usleep(10000); // 10ms
    }

    // Clean up
    printf("Cleaning up...\n");
    if (buffers) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
    }
    if (i2c_devices) {
        for (int i = 0; i < num_i2c_devices; i++) {
            close(i2c_devices[i].fd);
        }
        free(i2c_devices);
    }
    if (udp_socket > 0) {
        close(udp_socket);
    }
    close(camera_fd);

    printf("Exiting.\n");
    return 0;
}

