    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(port);
    if (inet_pton(AF_INET, ip_address, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(udp_socket, packet, packet_size, 0, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

// Function to read from an I2C device
int i2c_read_device(int fd, unsigned char *data, int count) {
    if (count > 1) {
        fprintf(stderr, "Error: I2C read only supports reading a single byte at a time\n");
        return -1;
    }

    if (read(fd, data, count) != count) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Function to write to an I2C device
int i2c_write_device(int fd, unsigned char *data, int count) {
    if (count > 1) {
        fprintf(stderr, "Error: I2C write only supports writing a single byte at a time\n");
        return -1;
    }

    if (write(fd, data, count) != count) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

