    // Parse command-line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-i") == 0 && i + 1 < argc) {
            target_ip[0] = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-p") == 0 && i + 1 < argc) {
            target_port = atoi(argv[i + 1]);
            i++;
        } else if (i2c_devices == NULL) {
            i2c_devices = calloc(1, sizeof(i2c_device_t));
            if (!i2c_devices) {
                perror("Out of memory");
                return 1;
            }
            num_i2c_devices = 0;
        } else {
            fprintf(stderr, "Usage: %s [-i <ip_address>] [-p <port>] [-d <i2c_device_address>] [-d <i2c_device_address>] [-d <i2c_device_address>]\n", argv[0]);
            return 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    camera_fd = open_camera("/dev/video0");
    if (camera_fd < 0) {
        return 1;
    }

    // Configure the camera
    if (configure_camera(camera_fd) < 0) {
        close(camera_fd);
        return 1;
    }

    // Open the UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error opening UDP socket");
        close(camera_fd);
        return 1;
    }

    // Main loop
    unsigned char frame_data[FRAME_SIZE];
    unsigned char *fragments[NUM_BUFFERS];
    int packet_size;
    unsigned char header[40]; // Adjust size as needed

    while (running) {
        // Capture a frame
        if (capture_frame(camera_fd, frame_data, FRAME_SIZE) < 0) {
            fprintf(stderr, "Error capturing frame\n");
            break;
        }

        // Fragment the frame
        if (fragment_frame(frame_data, FRAME_SIZE, fragments, &num_fragments) < 0) {
            fprintf(stderr, "Error fragmenting frame\n");
            break;
        }

        // Send UDP packets
        for (int i = 0; i < num_fragments; i++) {
            packet_size = sizeof(header) + num_fragments * 2; // Header + fragment size
            memcpy(header, &frame_index, sizeof(frame_index));
            memcpy(header + sizeof(frame_index), &i, sizeof(i));
            memcpy(header + sizeof(frame_index) + sizeof(i), &num_fragments, sizeof(num_fragments));
            memcpy(header + sizeof(frame_index) + sizeof(i) + sizeof(num_fragments), &packet_size, sizeof(packet_size));

            if (send_udp_packet(header, packet_size, target_ip, target_port) < 0) {
                fprintf(stderr, "Error sending UDP packet %d\n", i);
                break;
            }
        }

        frame_index++;
        if (frame_index >= num_fragments) {
            frame_index = 0;
        }

        // Read I2C data (example: read from device 0x28)
        if (i2c_devices != NULL && num_i2c_devices > 0) {
            if (i2c_read_device(i2c_devices[0].fd, (unsigned char *)target_ip, 1) < 0) {
                fprintf(stderr, "Error reading from I2C device 0x28\n");
            }
        }

        // Sleep for a short period
        usleep(10000); // 10ms
    }

    // Clean up
    printf("Cleaning up...\n");
    if (buffers) {
        for (int i = 0; i < NUM_BUFFERS; i++) {
            munmap(buffers[i].start, buffers[i].length);
        }
        free(buffers);
    }
    if (i2c_devices) {
        for (int i = 0; i < num_i2c_devices; i++) {
            close(i2c_devices[i].fd);
        }
        free(i2c_devices);
    }
    if (udp_socket > 0) {
        close(udp_socket);
    }
    close(camera_fd);

    printf("Exiting.\n");
    return 0;
}

