#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 144
#define IMAGE_FORMAT V4L2_PIX_FMT_MJPEG
#define IMAGE_FIELD V4L2_FIELD_NONE

// Global variables for signal handling
volatile sig_atomic_t stop_flag = 0;

// Structure to hold camera buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Signal handler function
void signal_handler(int sig)
{
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, stopping streaming...\n", sig);
        stop_flag = 1;
    }
}

// Function to check if a capability is supported
int capability_supported(int fd, int capability)
{
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP failed");
        return 0;
    }
    return (cap.capabilities & capability);
}

// Function to open the camera device
int open_camera(const char *device_name)
{
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Failed to open camera device");
        return -1;
    }
    return fd;
}

// Function to query the camera capabilities
int query_camera_capabilities(int fd)
{
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_G_CAPS, &cap) == -1) {
        perror("VIDIOC_G_CAPS failed");
        return -1;
    }

    if (!capability_supported(fd, V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!capability_supported(fd, V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming\n", DEVICE_NAME);
        return -1;
    }

    return 0;
}

// Function to set the camera format
int set_camera_format(int fd, int width, int height, int field, int pixel_format)
{
    struct v4l2_format fmt;

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = field;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, struct v4l2_requestbuffers *buffers, int n_buffers)
{
    if (ioctl(fd, VIDIOC_REQBUFS, buffers) == -1) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("VIDIOC_QUERYBUF failed");
            return -1;
        }

        struct v4l2_buffer *actual_buf = malloc(sizeof(struct v4l2_buffer));
        if (actual_buf == NULL) {
            perror("Failed to allocate buffer structure");
            return -1;
        }

        memcpy(actual_buf, &buf, sizeof(struct v4l2_buffer));

        if (ioctl(fd, VIDIOC_QBUF, actual_buf) == -1) {
            perror("VIDIOC_QBUF failed");
            free(actual_buf);
            return -1;
        }

        if (ioctl(fd, VIDIOC_STREAMON, fd) == -1) {
            perror("VIDIOC_STREAMON failed");
            free(actual_buf);
            return -1;
        }
    }

    return 0;
}

// Function to dequeue a frame
int dequeue_frame(int fd, struct v4l2_buffer *buffer)
{
    if (ioctl(fd, VIDIOC_DQBUF, buffer) == -1) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    return 0;
}

// Function to write the frame to a file
int write_frame_to_file(const char *filename, const void *frame_data, size_t frame_size)
{
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(frame_data, 1, frame_size, fp);
    if (bytes_written != frame_size) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, frame_size);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unmap buffers
int unmap_buffers(int fd, struct v4l2_buffer *buffers, int n_buffers)
{
    for (int i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("VIDIOC_QBUF failed");
            return -1;
        }
    }

    return 0;
}

// Function to free buffer arrays
void free_buffers(struct v4l2_buffer *buffers, int n_buffers)
{
    for (int i = 0; i < n_buffers; ++i) {
        if (buffers[i].start != NULL) {
            free(buffers[i].start);
        }
    }
}

// Function to close the camera device
int close_camera(int fd)
{
    if (ioctl(fd, VIDIOC_STREAMOFF, fd) == -1) {
        perror("VIDIOC_STREAMOFF failed");
        return -1;
    }

    if (close(fd) == -1) {
        perror("Failed to close device");
        return -1;
    }

    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT,   signal_handler);
    signal(SIGTERM,  signal_handler);

    // Open the camera device
    int fd = open_camera(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Query camera capabilities
    if (query_camera_capabilities(fd) == -1) {
        close_camera(fd);
        return EXIT_FAILURE;
    }

    // Set the camera format
    if (set_camera_format(fd, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_FIELD, IMAGE_FORMAT) == -1) {
        close_camera(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    struct v4l2_buffer buffers[1];
    buffers[0].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffers[0].memory = V4L2_MEMORY_MMAP;
    buffers[0].index = 0;

    if (request_buffers(fd, buffers, 1) == -1) {
        close_camera(fd);
        return EXIT_FAILURE;
    }

    // Allocate buffer data
    buffer_t *buffers_to_write = malloc(sizeof(buffer_t) * 1);
    if (buffers_to_write == NULL) {
        perror("Failed to allocate memory for buffers");
        close_camera(fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 1; ++i) {
        buffers_to_write[i].start = NULL;
        buffers_to_write[i].length = 0;
    }

    // Dequeue a frame
    struct v4l2_buffer buffer;
    memset(&buffer, 0, sizeof(struct v4l2_buffer));
    buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer.memory = V4L2_MEMORY_MMAP;
    buffer.index = 0;

    if (dequeue_frame(fd, &buffer) == -1) {
        close_camera(fd);
        free(buffers_to_write);
        return EXIT_FAILURE;
    }

    // Write the frame to a file
    char *frame_data = buffer.data;
    size_t frame_size = buffer.bytesused;

    if (write_frame_to_file("image.jpg", frame_data, frame_size) == -1) {
        close_camera(fd);
        free(buffers_to_write);
        return EXIT_FAILURE;
    }

    printf("Frame written to image.jpg\n");

    // Unmap buffers
    if (unmap_buffers(fd, buffers, 1) == -1) {
        close_camera(fd);
        free(buffers_to_write);
        return EXIT_FAILURE;
    }

    // Free buffer arrays
    free_buffers(buffers, 1);
    free(buffers_to_write);

    // Close the camera device
    if (close_camera(fd) == -1) {
        return EXIT_FAILURE;
    }

    printf("Camera streaming stopped.\n");

    return EXIT_SUCCESS;
}

