#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

// PWM frequency (Hz)
#define PWM_FREQUENCY 50

// PWM period (microseconds)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// PWM duty cycle range (0-1000)
#define PWM_DUTY_CYCLE_MAX 1000

// Servo mid-position (duty cycle)
#define SERVO_MID_POSITION 75

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the pan servo position
void set_pan_servo(int duty_cycle) {
