#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <jpeglib.h>
#include <math.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_FORMAT "YUYV"
#define JPEG_QUALITY 75

// Global variables for cleanup
static int fd = -1;
static struct v4l2_buffer buf;
static unsigned char *buffers[2];
static unsigned long buffer_size = 0;
static FILE *jpeg_file = NULL;
static FILE *error_log_file = NULL;

// Function prototypes
int open_camera(const char *device_name);
int request_buffers(int fd, struct v4l2_requestbuffers *req);
int queue_buffers(int fd, struct v4l2_buffer *buf, int n);
int start_streaming(int fd);
int stop_streaming(int fd);
int dequeue_buffer(int fd, struct v4l2_buffer *buf);
int unqueue_buffer(int fd, struct v4l2_buffer *buf);
int read_frame(int fd, unsigned char *frame);
int convert_yuyv_to_rgb24(unsigned char *yuyv_frame, unsigned char *rgb24_frame, int width, int height);
int apply_blur(unsigned char *rgb24_frame, int width, int height, int kernel_size);
int encode_jpeg(unsigned char *rgb24_frame, int width, int height, int quality, char *filename);
void log_error(const char *message);
void signal_handler(int sig);

// Structure to hold camera configuration
typedef struct {
    const char *device_name;
    int image_width;
    int image_height;
    const char *image_format;
} camera_config_t;

// Function to open the camera device
int open_camera(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening camera device");
        return -1;
    }

    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying camera capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device_name);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device_name);
        close(fd);
        return -1;
    }

    return fd;
}

// Function to request buffers from the camera
int request_buffers(int fd, struct v4l2_requestbuffers *req) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    for (int i = 0; i < req->count; i++) {
        struct v4l2_buffer *buffer = &req->buffers[i];
        memset(buffer, 0, sizeof(struct v4l2_buffer));
        buffer->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffer->memory = V4L2_MEMORY_MMAP;
        buffer->index = i;
    }

    return 0;
}

// Function to queue buffers
int queue_buffers(int fd, struct v4l2_buffer *buf) {
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }
    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting streaming");
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping streaming");
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("Error dequeueing buffer");
        return -1;
    }
    return 0;
}

// Function to unqueue a buffer
int unqueue_buffer(int fd, struct v4l2_buffer *buf) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_QBUF, buf) == -1) {
        perror("Error unqueuing buffer");
        return -1;
    }
    return 0;
}

// Function to read a frame from the camera
int read_frame(int fd, unsigned char *frame) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    memcpy(frame, buffers[buf.index], buf.bytesused);
    return 0;
}

// Function to convert YUYV to RGB24
int convert_yuyv_to_rgb24(unsigned char *yuyv_frame, unsigned char *rgb24_frame, int width, int height) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int yuyv_index = y * width + x;
            int u = yuyv_frame[yuyv_index * 2 + 0];
            int v = yuyv_frame[yuyv_index * 2 + 1];
            int r = yuyv_index * 2 + 2;
            int g = yuyv_index * 2 + 3;
            int b = yuyv_index * 2 + 4;

            float y = (float)yuyv_index * 2 + 0;
            float u = (float)yuyv_index * 2 + 1;

            float r_new = y + (u - y) * 1.37071;
            float g_new = y - (u - y) * 0.69864;
            float b_new = y + (u - y) * 2.11456;

            if (r_new < 0) r_new = 0;
            if (r_new > 255) r_new = 255;
            if (g_new < 0) g_new = 0;
            if (g_new > 255) g_new = 255;
            if (b_new < 0) b_new = 0;
            if (b_new > 255) b_new = 255;

            rgb24_frame[rgb24_index++] = (unsigned char)r_new;
            rgb24_frame[rgb24_index++] = (unsigned char)g_new;
            rgb24_frame[rgb24_index++] = (unsigned char)b_new;
        }
    }
    return 0;
}

// Function to apply a blur filter
int apply_blur(unsigned char *rgb24_frame, int width, int height, int kernel_size) {
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int sum_r = 0;
            int sum_g = 0;
            int sum_b = 0;
            for (int i = -kernel_size; i <= kernel_size; i++) {
                for (int j = -kernel_size; j <= kernel_size; j++) {
                    int x_offset = x + i;
                    int y_offset = y + j;
                    if (x_offset >= 0 && x_offset < width && y_offset >= 0 && y_offset < height) {
                        sum_r += rgb24_frame[y_offset * width * 3 + x_offset * 3 + 0];
                        sum_g += rgb24_frame[y_offset * width * 3 + x_offset * 3 + 1];
                        sum_b += rgb24_frame[y_offset * width * 3 + x_offset * 3 + 2];
                    }
                }
            }
            int r = sum_r / (2 * kernel_size + 1);
            int g = sum_g / (2 * kernel_size + 1);
            int b = sum_b / (2 * kernel_size + 1);
            rgb24_frame[y * width * 3 + x * 3 + 0] = r;
            rgb24_frame[y * width * 3 + x * 3 + 1] = g;
            rgb24_frame[y * width * 3 + x * 3 + 2] = b;
        }
    }
    return 0;
}

// Function to encode a frame as JPEG
int encode_jpeg(unsigned char *rgb24_frame, int width, int height, int quality, char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening output JPEG file: %s\n", filename);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = width;
    cinfo.image_height = height;
    cinfo.input_components = 3; // RGB24
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, quality, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = width * 3; // RGB24
    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &rgb24_frame[cinfo.next_scanline * row_stride];
        (void) jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(error_log_file, "[%s] ERROR: %s\n", timestamp, message);
    fflush(error_log_file);
}

// Signal handler for SIGINT
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, cleaning up...\n");
        log_error("Received SIGINT, cleaning up...");

        // Stop streaming
        stop_streaming(fd);

        // Unqueue buffers
        unqueue_buffer(fd, &buf);

        // Unmap buffers
        if (buffers[0] != NULL) {
            munmap(buffers[0], buffer_size);
        }
        if (buffers[1] != NULL) {
            munmap(buffers[1], buffer_size);
        }

        // Close file descriptor
        close(fd);

        // Close error log file
        if (error_log_file != NULL) {
            fclose(error_log_file);
        }

        exit(0);
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open error log file
    error_log_file = fopen("error.log", "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        return 1;
    }

    // Open camera device
    fd = open_camera(DEVICE_NAME);
    if (fd == -1) {
        log_error("Failed to open camera device");
        fclose(error_log_file);
        return 1;
    }

    // Request buffers
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    if (request_buffers(fd, &buf) == -1) {
        log_error("Failed to request buffers");
        close(fd);
        fclose(error_log_file);
        return 1;
    }

    // Allocate buffers
    buffers[0] = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffers[0] == MAP_FAILED) {
        log_error("Failed to mmap buffer 1");
        close(fd);
        fclose(error_log_file);
        return 1;
    }

    buffers[1] = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset + buf.length);
    if (buffers[1] == MAP_FAILED) {
        log_error("Failed to mmap buffer 2");
        close(fd);
        munmap(buffers[0], buffer_size);
        fclose(error_log_file);
        return 1;
    }

    buffer_size = buf.length;

    // Convert YUYV to RGB24
    unsigned char *yuyv_frame = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 2);
    if (yuyv_frame == NULL) {
        log_error("Failed to allocate YUYV frame");
        munmap(buffers[0], buffer_size);
        munmap(buffers[1], buffer_size);
        close(fd);
        fclose(error_log_file);
        return 1;
    }

    unsigned char *rgb24_frame = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (rgb24_frame == NULL) {
        log_error("Failed to allocate RGB24 frame");
        free(yuyv_frame);
        munmap(buffers[0], buffer_size);
        munmap(buffers[1], buffer_size);
        close(fd);
        fclose(error_log_file);
        return 1;
    }

    for (int i = 0; i < IMAGE_HEIGHT; i++) {
        for (int j = 0; j < IMAGE_WIDTH; j++) {
            yuyv_frame[i * IMAGE_WIDTH * 2 + j * 2] = yuyv_frame[i * IMAGE_WIDTH * 2 + j * 2 + 1];
        }
    }

    convert_yuyv_to_rgb24(yuyv_frame, rgb24_frame, IMAGE_WIDTH, IMAGE_HEIGHT);

    // Apply blur filter
    apply_blur(rgb24_frame, IMAGE_WIDTH, IMAGE_HEIGHT, 5);

    // Encode as JPEG
    char filename[50];
    snprintf(filename, sizeof(filename), "capture_%s.jpg", ctime(&time(NULL)));
    if (encode_jpeg(rgb24_frame, IMAGE_WIDTH, IMAGE_HEIGHT, JPEG_QUALITY, filename) == -1) {
        log_error("Failed to encode JPEG");
    }

    // Read frame
    unsigned char *frame = (unsigned char *)malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (frame == NULL) {
        log_error("Failed to allocate frame buffer");
        free(rgb24_frame);
        free(yuyv_frame);
        munmap(buffers[0], buffer_size);
        munmap(buffers[1], buffer_size);
        close(fd);
        fclose(error_log_file);
        return 1;
    }

    if (read_frame(fd, frame) == -1) {
        log_error("Failed to read frame");
    }

    // Free allocated memory
    free(rgb24_frame);
    free(yuyv_frame);
    free(frame);

    // Unmap buffers
    munmap(buffers[0], buffer_size);
    munmap(buffers[1], buffer_size);

    // Close file descriptor
    close(fd);

    // Close error log file
    fclose(error_log_file);

    return 0;
}

