#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <errno.h>
#include <stdint.h>

#define DEVICE_NODE "/dev/video0"
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x29
#define I2C_DEVICE_NAME "i2c-1"

// Structure to hold camera capabilities
typedef struct {
    int supported_resolutions[4]; // Example: max 4 resolutions
    int supported_frame_rates[4];  // Example: max 4 frame rates
    int autofocus_supported;
} camera_capabilities_t;

// Function to enumerate supported resolutions
int enumerate_resolutions(int fd, int supported_resolutions[], int max_resolutions) {
    struct v4l2_res_list_hdr header;
    struct v4l2_res_list_pixel_format pixel_format;
    struct v4l2_res_list_pixel_format_e pixel_format_enum;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_format fmt;
    int i;

    if (ioctl(fd, VIDIOC_G_RES, &header) < 0) {
        perror("VIDIOC_G_RES");
        return -1;
    }

    if (header.type != V4L2_BUF_TYPE_VIDEO_CAPTURE) {
        fprintf(stderr, "Not a video capture device\n");
        return -1;
    }

    if (header.n_formats < 1) {
        fprintf(stderr, "No formats supported\n");
        return -1;
    }

    for (i = 0; i < header.n_formats; i++) {
        if (ioctl(fd, VIDIOC_QUERYFMT, &fmt) < 0) {
            perror("VIDIOC_QUERYFMT");
            return -1;
        }

        if (ioctl(fd, VIDIOC_CROPPINGFMT, &fmt) < 0) {
            perror("VIDIOC_CROPPINGFMT");
            return -1;
        }

        if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
            perror("VIDIOC_S_FMT");
            return -1;
        }

        if (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) < 0) {
            perror("VIDIOC_ENUM_FMT");
            return -1;
        }

        if (ioctl(fd, V4L2_FMT_TYPE_VIDEO_CAPTURE, &pixel_format) < 0) {
            perror("VIDIOC_FMT_TYPE");
            return -1;
        }

        if (ioctl(fd, V4L2_FMT_TYPE_VIDEO_CAPTURE, &pixel_format_enum) < 0) {
            perror("VIDIOC_FMT_TYPE");
            return -1;
        }

        if (pixel_format_enum.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
            if (pixel_format_enum.fmt.pix.width > 0 && pixel_format_enum.fmt.pix.height > 0) {
                if (pixel_format_enum.fmt.pix.width <= max_resolutions && pixel_format_enum.fmt.pix.height <= max_resolutions) {
                    supported_resolutions[pixel_format_enum.fmt.pix.width * 8 + pixel_format_enum.fmt.pix.height * 2] = 1;
                }
            }
        }
    }

    return 0;
}

// Function to enumerate supported frame rates
int enumerate_frame_rates(int fd, int supported_frame_rates[], int max_frame_rates) {
    struct v4l2_res_list_hdr header;
    struct v4l2_res_list_pixel_format pixel_format;
    struct v4l2_res_list_pixel_format_e pixel_format_enum;
    struct v4l2_fmtdesc fmtdesc;
    struct v4l2_format fmt;
    int i;

    if (ioctl(fd, VIDIOC_G_FMT, &fmt) < 0) {
        perror("VIDIOC_G_FMT");
        return -1;
    }

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        return -1;
    }

    if (ioctl(fd, VIDIOC_ENUM_FMT, &fmtdesc) < 0) {
        perror("VIDIOC_ENUM_FMT");
        return -1;
    }

    if (ioctl(fd, V4L2_FMT_TYPE_VIDEO_CAPTURE, &pixel_format) < 0) {
        perror("VIDIOC_FMT_TYPE");
        return -1;
    }

    if (ioctl(fd, V4L2_FMT_TYPE_VIDEO_CAPTURE, &pixel_format_enum) < 0) {
        perror("VIDIOC_FMT_TYPE");
        return -1;
    }

    if (pixel_format_enum.type == V4L2_BUF_TYPE_VIDEO_CAPTURE) {
        if (pixel_format_enum.fmt.pix.width > 0 && pixel_format_enum.fmt.pix.height > 0) {
            if (pixel_format_enum.fmt.pix.width <= max_frame_rates && pixel_format_enum.fmt.pix.height <= max_frame_rates) {
                supported_frame_rates[pixel_format_enum.fmt.pix.width * 8 + pixel_format_enum.fmt.pix.height * 2] = 1;
            }
        }
    }

    return 0;
}

// Function to query autofocus control
int query_autofocus_control(int fd) {
    struct v4l2_ctrl_elem_s buf;
    struct v4l2_ctrl_val_s val;
    int i;

    if (ioctl(fd, VIDIOC_G_CTRL, &buf) < 0) {
        perror("VIDIOC_G_CTRL");
        return -1;
    }

    if (ioctl(fd, VIDIOC_S_CTRL, &buf) < 0) {
        perror("VIDIOC_S_CTRL");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCTRL, &buf) < 0) {
        perror("VIDIOC_QUERYCTRL");
        return -1;
    }

    if (buf.disp_out == V4L2_DISP_OUT_AUTO) {
        return 1; // Autofocus supported
    } else {
        return 0; // Autofocus not supported
    }
}

// Function to print camera capabilities
void print_camera_capabilities(int fd, camera_capabilities_t capabilities) {
    printf("Resolutions: ");
    for (int i = 0; i < 4; i++) {
        if (capabilities.supported_resolutions[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");

    printf("Frame Rates: ");
    for (int i = 0; i < 4; i++) {
        if (capabilities.supported_frame_rates[i]) {
            printf("%d ", i);
        }
    }
    printf("\n");

    printf("Autofocus: %s\n", capabilities.autofocus_supported ? "Supported" : "Not Supported");
}

int main() {
    int fd;
    camera_capabilities_t capabilities;

    // Open the device node
    fd = open(DEVICE_NODE, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device node");
        return 1;
    }

    // Enumerate supported resolutions
    if (enumerate_resolutions(fd, capabilities.supported_resolutions, 4) < 0) {
        fprintf(stderr, "Failed to enumerate resolutions\n");
        close(fd);
        return 1;
    }

    // Enumerate supported frame rates
    if (enumerate_frame_rates(fd, capabilities.supported_frame_rates, 4) < 0) {
        fprintf(stderr, "Failed to enumerate frame rates\n");
        close(fd);
        return 1;
    }

    // Query autofocus control
    if (query_autofocus_control(fd) < 0) {
        fprintf(stderr, "Failed to query autofocus control\n");
    }

    // Print camera capabilities
    print_camera_capabilities(fd, capabilities);

    // Close the device node
    close(fd);

    return 0;
}

