#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5

// Define GPIO pins for buttons
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define center position pulse width (microseconds)
#define CENTER_POSITION 1500

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define PWM range (microseconds)
#define PWM_RANGE 2000

// Global variable to store the current pulse width for each servo
int pan_pulse_width = CENTER_POSITION;
int tilt_pulse_width = CENTER_POSITION;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int pin, int pulse_width);
void handle_button_press(int button_pin);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold servo pin assignments
typedef struct {
    int pan_pin;
    int tilt_pin;
} ServoPins;

// Structure to hold button pin assignments
typedef struct {
    int up_pin;
    int down_pin;
    int left_pin;
    int right_pin;
} ButtonPins;

ServoPins servo_pins = {PAN_SERVO_PIN, TILT_SERVO_PIN};
ButtonPins button_pins = {UP_BUTTON_PIN, DOWN_BUTTON_PIN, LEFT_BUTTON_PIN, RIGHT_BUTTON_PIN};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error: Failed to initialize pigpio library.\n");
        return 1;
    }

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(servo_pins.pan_pin, PWM_FREQUENCY);
    gpioSetPWMfrequency(servo_pins.tilt_pin, PWM_FREQUENCY);

    // Set PWM range for both servos
    gpioSetPWMrange(servo_pins.pan_pin, PWM_RANGE);
    gpioSetPWMrange(servo_pins.tilt_pin, PWM_RANGE);

    // Set initial pulse widths for both servos
    set_servo_pulse_width(servo_pins.pan_pin, pan_pulse_width);
    set_servo_pulse_width(servo_pins.tilt_pin, tilt_pulse_width);

    // Main loop
    while (1) {
        // Check for button presses
        handle_button_press(button_pins.up_pin);
        handle_button_press(button_pins.down_pin);
        handle_button_press(button_pins.left_pin);
        handle_button_press(button_pins.right_pin);

        // Delay to prevent excessive CPU usage
        gpioDelay(10000); // 10ms
    }

    return 0;
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }
    return 0;
}

// Function to set the pulse width for a servo
void set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < 1000) {
        pulse_width = 1000;
    } else if (pulse_width > 2000) {
        pulse_width = 2000;
    }

    gpioPWM(pin, pulse_width);
}

// Function to handle button presses
void handle_button_press(int button_pin) {
    int new_pulse_width;

    if (button_pin == button_pins.up_pin) {
        new_pulse_width = pan_pulse_width - 10;
        if (new_pulse_width < 1000) {
            new_pulse_width = 1000;
        }
        pan_pulse_width = new_pulse_width;
    } else if (button_pin == button_pins.down_pin) {
        new_pulse_width = pan_pulse_width + 10;
        if (new_pulse_width > 2000) {
            new_pulse_width = 2000;
        }
        pan_pulse_width = new_pulse_width;
    } else if (button_pin == button_pins.left_pin) {
        new_pulse_width = tilt_pulse_width - 10;
        if (new_pulse_width < 1000) {
            new_pulse_width = 1000;
        }
        tilt_pulse_width = new_pulse_width;
    } else if (button_pin == button_pins.right_pin) {
        new_pulse_width = tilt_pulse_width + 10;
        if (new_pulse_width > 2000) {
            new_pulse_width = 2000;
        }
        tilt_pulse_width = new_pulse_width;
    }
}

// Function to clean up GPIO resources
void cleanup_gpio() {
    gpioPWM(servo_pins.pan_pin, 0); // Stop PWM
    gpioPWM(servo_pins.tilt_pin, 0); // Stop PWM
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

