#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2 // seconds
#define HTTP_PORT 8080
#define HTTP_IP "127.0.0.1" // Default IP address
#define HTTP_PORT_DEFAULT 8080

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int http_socket = -1;

// Structure to hold configuration data
typedef struct {
    char *ip_address;
    int port;
} Config;

// Function prototypes
int initialize_gpio(int pin);
int read_pir_sensor(int pin);
int capture_jpeg(const char *filename);
int create_directory(const char *directory);
int get_iso8601_timestamp(char *timestamp);
json_t *create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin);
int send_http_request(const char *url, const char *payload);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO pin
int initialize_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_INPUT);
    gpioSetPullUpDown(pin, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the PIR sensor value
int read_pir_sensor(int pin) {
    return gpioRead(pin);
}

// Function to capture a JPEG image using raspistill
int capture_jpeg(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -q 85", filename);
    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Error capturing JPEG: raspistill returned %d\n", status);
        return -1;
    }
    return 0;
}

// Function to create a directory if it doesn't exist
int create_directory(const char *directory) {
    if (mkdir(directory, 0777) == -1) {
        if (errno == EEXIST) {
            // Directory already exists, no error
            return 0;
        } else {
            fprintf(stderr, "Error creating directory: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to get the current timestamp in ISO 8601 format with microseconds
int get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    if (strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }
    return 0;
}

// Function to create a JSON payload
json_t *create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    json_t *root = json_object();
    json_t *filename_json = json_string(filename);
    json_t *timestamp_json = json_string(timestamp);
    json_t *motion_status_json = json_integer(motion_status);
    json_t *gpio_pin_json = json_integer(gpio_pin);

    json_object_set_new(root, "filename", filename_json);
    json_object_set_new(root, "timestamp", timestamp_json);
    json_object_set_new(root, "motion_status", motion_status_json);
    json_object_set_new(root, "gpio_pin", gpio_pin_json);

    return root;
}

// Function to send an HTTP POST request
int send_http_request(const char *url, const char *payload) {
    struct sockaddr_in server_addr;
    char buffer[1024];
    int client_socket, server_socket;
    socklen_t server_len = sizeof(server_addr);

    // Create socket
    client_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (client_socket == -1) {
        perror("Error creating socket");
        return -1;
    }

    // Prepare the sockaddr_in structure
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(HTTP_PORT);
    if (inet_pton(AF_INET, HTTP_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(client_socket);
        return -1;
    }

    // Connect to server
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        close(client_socket);
        return -1;
    }

    if (connect(server_socket, (struct sockaddr *)&server_addr, server_len) < 0) {
        perror("Error connecting to server");
        close(client_socket);
        close(server_socket);
        return -1;
    }

    // Prepare the HTTP POST request
    snprintf(buffer, sizeof(buffer), "POST /upload HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", HTTP_IP, strlen(payload), payload);

    // Send the request
    if (send(client_socket, buffer, strlen(buffer), 0) < 0) {
        perror("Error sending request");
        close(client_socket);
        close(server_socket);
        return -1;
    }

    // Receive the response (optional, for error checking)
    char response[1024];
    memset(response, 0, sizeof(response));
    ssize_t bytes_received = recv(client_socket, response, sizeof(response) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving response");
    } else {
        response[bytes_received] = '\0';
        printf("HTTP Response: %s\n", response);
    }

    // Close the socket
    close(client_socket);
    close(server_socket);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

// Cleanup function
void cleanup() {
    if (http_socket != -1) {
        close(http_socket);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    Config config;
    config.ip_address = HTTP_IP;
    config.port = HTTP_PORT;

    // Parse command-line arguments
    if (argc > 1) {
        config.ip_address = argv[1];
    }
    if (argc > 2) {
        config.port = atoi(argv[2]);
    }

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) != 0) {
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int motion_detected = 0;
        time_t last_motion_time = 0;

        // Read PIR sensor
        int sensor_value = read_pir_sensor(GPIO_PIN);

        if (sensor_value == 1) {
            motion_detected = 1;
            last_motion_time = time(NULL);
        }

        // Debounce
        if (motion_detected) {
            time_t current_time = time(NULL);
            if (difftime(current_time, last_motion_time) >= DEBOUNCE_TIME) {
                // Create directory if it doesn't exist
                if (create_directory("motion_captures") != 0) {
                    fprintf(stderr, "Error creating motion_captures directory\n");
                }

                // Generate filename
                char filename[32];
                get_iso8601_timestamp(filename);
                snprintf(filename, sizeof(filename), "motion_captures/%s.jpg", filename);

                // Capture JPEG image
                if (capture_jpeg(filename) != 0) {
                    fprintf(stderr, "Error capturing JPEG image\n");
                } else {
                    // Create JSON payload
                    json_t *payload = create_json_payload(filename, NULL, motion_detected, GPIO_PIN);

                    // Send HTTP request
                    if (send_http_request(config.ip_address, payload->valuestr) != 0) {
                        fprintf(stderr, "Error sending HTTP request\n");
                    }

                    json_decref(payload);
                }

                last_motion_time = current_time;
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

