#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/stat.h>
#include <errno.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define CAPTURE_COMMAND "libcamera-jpeg -o /home/pi/images/motion_capture.jpg -w 640 -h 480 -q 85 -t 2000 -nopreview"
#define LOG_FILE "/home/pi/motion_capture.log"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "[%s] %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to capture an image
int capture_image() {
    char command[256];
    snprintf(command, sizeof(command), "%s", CAPTURE_COMMAND);

    int status = system(command);
    if (status == -1) {
        log_message("Error: Failed to execute capture command.");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        log_message("Error: Image capture failed with non-zero exit status.");
        return -1;
    }

    return 0;
}

// Function to get the current timestamp
void get_timestamp(char *timestamp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    strftime(timestamp, 20, "%Y%m%d_%H%M%S", t);
}

// Function to log errors
void log_error(const char *message) {
    char timestamp[30];
    get_timestamp(timestamp);
    log_message(message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as input with edge-falling detection
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message("Motion detection started.");

    // Main loop
    while (running) {
        // Debounce the sensor
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to us

        // Check for falling edge
        if (gpioRead(GPIO_PIN) == 0) {
            log_message("Motion detected!");

            // Capture image
            if (capture_image() == 0) {
                char timestamp[20];
                get_timestamp(timestamp);
                char filename[50];
                snprintf(filename, sizeof(filename), "/home/pi/images/%s_motion.jpg", timestamp);

                // Create the image directory if it doesn't exist
                struct stat st = {0};
                if (stat(filename, &st) == -1) {
                    if (mkdir(filename, 0777) == -1) {
                        log_message("Error: Failed to create image directory.");
                    }
                }

                // Log the image capture success
                log_message("Image captured successfully.");
            } else {
                log_message("Error: Image capture failed.");
            }

            // Debounce the sensor after capture
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to us
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Clean up
    log_message("Cleaning up and exiting...");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

