#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the pan servo angle
void set_pan_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Pan angle out of range (0-180 degrees).\n");
        return;
    }

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set PWM frequency and pulse width
    gpioPWM(PAN_SERVO_PIN, pulse_width / 1000); // pigpio uses 0-1000 for duty cycle

    printf("Pan angle set to: %d degrees\n", angle);
}

// Function to set the tilt servo angle
void set_tilt_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Tilt angle out of range (0-180 degrees).\n");
        return;
    }

    // Calculate pulse width based on angle
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    // Set PWM frequency and pulse width
    gpioPWM(TILT_SERVO_PIN, pulse_width / 1000); // pigpio uses 0-1000 for duty cycle

    printf("Tilt angle set to: %d degrees\n", angle);
}

// Function to handle arrow keys
void handle_arrow_keys(int key) {
    switch (key) {
        case 37: // Left arrow
            set_pan_angle(-5);
            break;
        case 38: // Up arrow
            set_pan_angle(5);
            break;
        case 40: // Right arrow
            set_pan_angle(5);
            break;
        case 39: // Down arrow
            set_pan_angle(-5);
            break;
        case 1073: // Page Up
            set_tilt_angle(-5);
            break;
        case 1074: // Page Down
            set_tilt_angle(5);
            break;
        case 1075: // Home
            set_pan_angle(90);
            set_tilt_angle(90);
            break;
        case 1076: // End
            set_pan_angle(180);
            set_tilt_angle(180);
            break;
        default:
            fprintf(stderr, "Error: Invalid key pressed (arrow key or 'q').\n");
            break;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(PAN_SERVO_PIN, 255);
    gpioSetPWMrange(TILT_SERVO_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Servo control program started. Press 'q' to exit.\n");

    // Main loop
    while (program_running) {
        // Read input from stdin
        int key = getchar();

        // Handle arrow keys
        handle_arrow_keys(key);

        // Check for 'q' character
        if (key == 12) {
            printf("Exiting...\n");
            break;
        }

        // Delay
        gpioDelay(100000); // 100ms
    }

    // Set servos to neutral position before exiting
    set_pan_angle(90);
    set_tilt_angle(90);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

