// Global Variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_cpu_temp();
int read_cpu_usage();
int oled_init();
void oled_clear();
void oled_print(int x, int y, char *text);
void oled_display_text(int x, int y, char *text);
void signal_handler(int signal);
void log_error(const char *message);

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    int temp = -1;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        log_error("Failed to open CPU temperature file.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer);
    }

    fclose(fp);
    return temp;
}

// Function to read CPU usage from /proc/stat
int read_cpu_usage() {
    FILE *fp;
    char line[256];
    char *token;
    int usage = 0;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        log_error("Failed to open CPU usage file.");
        return -1;
    }

    // Read the first line (CPU usage)
    if (fgets(line, sizeof(line), fp) == NULL) {
        log_error("Failed to read CPU usage from /proc/stat.");
        fclose(fp);
        return -1;
    }

    token = strtok(line, " ");
    if (token != NULL) {
        usage = atoi(token);
    }

    fclose(fp);
    return usage;
}

// Function to initialize the OLED display
int oled_init() {
    // Initialization sequence (SSD1306)
    unsigned char init_commands[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100Hz)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset
        0x40,       // Start line
        0x8D, 0x14, // Charge pump setting
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap
        0xC8,       // COM output scan direction
        0xDA, 0x12, // COM pins hardware configuration
        0x81, 0xCF, // Contrast control
        0xD9, 0xF1, // Precharge period
        0xDB, 0x40, // VCOM deselect level
        0xA4,       // Entire display ON/OFF
        0xA6,       // Normal/Inverse display
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_commands); i++) {
        if (i2cWriteByteData(i2c_handle, init_commands[i], 0) < 0) {
            log_error("Failed to write initialization command to OLED.");
            return -1;
        }
    }

    return 0;
}

// Function to clear the OLED display
void oled_clear() {
    unsigned char clear_command = 0x40; // Command to clear the display
    if (i2cWriteByteData(i2c_handle, 0x00, clear_command) < 0) {
        log_error("Failed to clear OLED display.");
    }
}

// Function to print text on the OLED display
void oled_print(int x, int y, char *text) {
    // Simple character printing (bitmap font)
    for (int i = 0; text[i] != '\0'; i++) {
        // Check if the character is in the font
        if (text[i] >= ' ' && text[i] <= '~') {
            for (int j = 0; j < 5; j++) {
                // Send the pixel data for each pixel in the character
                if (i2cWriteByteData(i2c_handle, x + j, font[text[i]][j]) < 0) {
                    log_error("Failed to write pixel data to OLED.");
                }
            }
        } else {
            // Send a space character to pad the line
            for (int j = 0; j < 5; j++) {
                if (i2cWriteByteData(i2c_handle, x + j, 0x00) < 0) {
                    log_error("Failed to write space pixel data to OLED.");
                }
            }
        }
    }
}

// Function to display text on the OLED display
void oled_display_text(int x, int y, char *text) {
    oled_clear();
    oled_print(x, y, text);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OLED_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    if (oled_init() < 0) {
        fprintf(stderr, "OLED initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read CPU temperature and usage
        int cpu_temp = read_cpu_temp();
        int cpu_usage = read_cpu_usage();

        // Display temperature and usage on OLED
        char temp_str[10];
        char usage_str[10];

        if (cpu_temp != -1) {
            snprintf(temp_str, sizeof(temp_str), "Temp: %d°C", cpu_temp);
        } else {
            snprintf(temp_str, sizeof(temp_str), "Temp: ERROR");
        }

        if (cpu_usage != -1) {
            snprintf(usage_str, sizeof(usage_str), "Usage: %d%%", cpu_usage);
        } else {
            snprintf(usage_str, sizeof(usage_str), "Usage: ERROR");
        }

        // Display temperature and usage on OLED
        oled_display_text(0, 0, temp_str);
        oled_display_text(0, 16, usage_str);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

