#include <math.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define LCD_ADDRESS 0x27 // Example address, check your LCD
#define SAMPLE_WINDOW_MS 500
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_RETRY_COUNT 3

// Global variables
volatile int pulse_count = 0;
volatile int running = 1;
int spi_fd;
int i2c_fd;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick);
int read_mcp3008(int channel);
float calculate_wind_speed(int pulses);
char* calculate_wind_direction(int adc_value);
void lcd_init();
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *message);
void lcd_byte(int bits, int mode);
void lcd_string(const char *s);
void signal_handler(int sig);

// Anemometer interrupt handler
void pulse_counter(int gpio, int level, uint32_t tick)
{
    if (level == RISING_EDGE)
    {
        pulse_count++;
    }
}

// MCP3008 ADC reading function
int read_mcp3008(int channel)
{
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0)
    {
        fprintf(stderr, "Error: SPI transaction failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Wind speed calculation function
float calculate_wind_speed(int pulses)
{
    return (float)pulses * 60.0 / (SAMPLE_WINDOW_MS / 1000.0); // m/s
}

// Wind direction calculation function
