    if (adc_value == 1023) return "S"; // Sensor error
    if (adc_value < 0) return "E"; // Sensor error
    if (adc_value > 1022) return "W"; // Sensor error

    float angle = (float)adc_value / 1023.0 * 360.0;
    if (angle < 0) angle += 360; // Normalize to 0-360 degrees

    if (angle < 45) return "N";
    if (angle < 95) return "NE";
    if (angle < 135) return "E";
    if (angle < 185) return "SE";
    if (angle < 225) return "S";
    if (angle < 275) return "SW";
    if (angle < 315) return "W";
    if (angle < 360) return "NW";

    return "Invalid";
}

// LCD initialization function
void lcd_init()
{
    uint8_t init_seq[] = {0x03, 0x03, 0x03, 0x02, 0x08, 0x08, 0x14, 0x24, 0x42, 0x82, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    for (int i = 0; i < sizeof(init_seq); i++)
    {
        char buf[2];
        buf[0] = 0x06; // Function set
        buf[1] = init_seq[i];
        usleep(1000); // Delay

        buf[0] = 0x06; // Function set
        buf[1] = 0x08; // 4-bit mode
        usleep(1000);

        buf[0] = 0x06; // Function set
        buf[1] = 0x10; // 4-bit mode, 2 lines
        usleep(1000);

        buf[0] = 0x06; // Function set
        buf[1] = 0x07; // Display on, cursor off, blink off
        usleep(1000);

        buf[0] = 0x06; // Function set
        buf[1] = 0x01; // Display off, cursor off, blink off
        usleep(1000);
    }
}

// LCD clear function
void lcd_clear()
{
    uint8_t clear_seq[] = {0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40};
    for (int i = 0; i < sizeof(clear_seq); i++)
    {
        char buf[2];
        buf[0] = 0x06; // Function set
        buf[1] = clear_seq[i];
        usleep(1000); // Delay
    }
}

// LCD set cursor function
void lcd_set_cursor(int row, int col)
{
    uint8_t set_cursor_seq[4];
    set_cursor_seq[0] = 0x06; // Function set
    set_cursor_seq[1] = (row << 4) | 0x08; // Set lower nibble of column address
    set_cursor_seq[2] = (col & 0x07); // Set lower nibble of page address
    set_cursor_seq[3] = 0x06; // Function set
    for (int i = 0; i < sizeof(set_cursor_seq); i++)
    {
        usleep(1000);
        char buf[2];
        buf[0] = set_cursor_seq[i];
        buf[1] = 0x00; // Data byte
        usleep(1000);
    }
}

// LCD print function
void lcd_print(const char *message)
{
    uint8_t print_seq[4];
    print_seq[0] = 0x06; // Function set
    print_seq[1] = 0x06; // Function set
    print_seq[2] = 0x06; // Function set
    print_seq[3] = 0x00; // Data byte

    for (int i = 0; message[i] != '\0'; i++)
    {
        char c = message[i];
        char buf[2];
        buf[0] = 0x06; // Function set
        buf[1] = c;
        usleep(1000);
        usleep(1000); // Delay for each character
        buf[0] = 0x06; // Function set
        buf[1] = 0x00; // Data byte
        usleep(1000);
    }
}

// LCD byte function
void lcd_byte(int bits, int mode)
{
    uint8_t byte_seq[4];
    byte_seq[0] = 0x06; // Function set
    byte_seq[1] = (mode << 4) | 0x08; // Set lower nibble of column address
    byte_seq[2] = 0x00; // Data byte
    byte_seq[3] = 0x06; // Function set

    for (int i = 0; i < sizeof(byte_seq); i++)
    {
        usleep(1000);
        char buf[2];
        buf[0] = byte_seq[i];
        buf[1] = 0x00; // Data byte
        usleep(1000);
    }

    if (mode == 0x08) // 4-bit mode
    {
        for (int i = 0; i < 8; i++)
        {
            char buf[2];
            buf[0] = 0x06; // Function set
            buf[1] = (bits >> (7 - i)) & 0x01;
            usleep(1000);
            usleep(1000);
            lcd_byte(bits & 0x01, mode);
        }
    } else
    {
        for (int i = 0; i < 8; i++)
        {
            char buf[2];
            buf[0] = 0x06; // Function set
            buf[1] = (bits >> (7 - i)) & 0x01;
            usleep(1000);
            usleep(1000);
            lcd_byte(bits & 0x01, mode);
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("Caught signal %d, exiting gracefully...\n", sig);
    running = 0;
}

int main()
{
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0)
    {
        fprintf(stderr, "Error: Could not open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0)
    {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0)
    {
        fprintf(stderr, "Error: Could not open I2C device %s: %s\n", I2C_DEVICE, strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Initialize LCD
    lcd_init();
    lcd_clear();

    // Set up interrupt handler for anemometer
    if (ioctl(ANEMOMETER_GPIO, SI_EVENT_SET_ISR, &pulse_counter) < 0)
    {
        fprintf(stderr, "Error: Could not set anemometer interrupt handler: %s\n", strerror(errno));
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (running)
    {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0)
        {
            fprintf(stderr, "Error: Could not read ADC value, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Calculate wind direction
        char *direction = calculate_wind_direction(adc_value);

        // Calculate wind speed
        float speed = calculate_wind_speed(pulse_count);

        // Update LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print("Speed: ");
        lcd_string(speed);
        lcd_set_cursor(1, 0);
        lcd_print("Dir: ");
        lcd_string(direction);

        // Print to console
        printf("Speed: %.2f m/s, Dir: %s\n", speed, direction);

        // Reset pulse count
        pulse_count = 0;

        // Wait for 500ms
        usleep(500000);
    }

    // Cleanup
    close(spi_fd);
    close(i2c_fd);

    return 0;
}

