#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for rows
#define ROW1 17
#define ROW2 18
#define ROW3 27
#define ROW4 22
#define ROW5 23
#define ROW6 24
#define ROW7 25
#define ROW8 4

// Define GPIO pins for columns
#define COL1 5
#define COL2 6
#define COL3 12
#define COL4 13
#define COL5 19
#define COL6 16
#define COL7 26
#define COL8 20

// Define the delay between rows (in microseconds)
#define ROW_DELAY 800

// Define the number of rows to display
#define NUM_ROWS 8

// Define the number of columns to display
#define NUM_COLS 8

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set row pins as output
    gpioSetMode(ROW1, PI_OUTPUT);
    gpioSetMode(ROW2, PI_OUTPUT);
    gpioSetMode(ROW3, PI_OUTPUT);
    gpioSetMode(ROW4, PI_OUTPUT);
    gpioSetMode(ROW5, PI_OUTPUT);
    gpioSetMode(ROW6, PI_OUTPUT);
    gpioSetMode(ROW7, PI_OUTPUT);
    gpioSetMode(ROW8, PI_OUTPUT);

    // Set column pins as output
    gpioSetMode(COL1, PI_OUTPUT);
    gpioSetMode(COL2, PI_OUTPUT);
    gpioSetMode(COL3, PI_OUTPUT);
    gpioSetMode(COL4, PI_OUTPUT);
    gpioSetMode(COL5, PI_OUTPUT);
    gpioSetMode(COL6, PI_OUTPUT);
    gpioSetMode(COL7, PI_OUTPUT);
    gpioSetMode(COL8, PI_OUTPUT);

    return 0;
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(ROW1, 0);
        gpioWrite(ROW2, 0);
        gpioWrite(ROW3, 0);
        gpioWrite(ROW4, 0);
        gpioWrite(ROW5, 0);
        gpioWrite(ROW6, 0);
        gpioWrite(ROW7, 0);
        gpioWrite(ROW8, 0);

        for (int j = 0; j < NUM_COLS; j++) {
            gpioWrite(COL1, 1);
            gpioWrite(COL2, 1);
            gpioWrite(COL3, 1);
            gpioWrite(COL4, 1);
            gpioWrite(COL5, 1);
            gpioWrite(COL6, 1);
            gpioWrite(COL7, 1);
            gpioWrite(COL8, 1);
        }
        gpioDelay(1000); // Short delay to allow the LEDs to turn off
    }
}

// Function to display a wave-like pattern
void display_wave() {
    for (int i = 0; i < NUM_ROWS; i++) {
        // Set row pins HIGH
        gpioWrite(ROW1, (i == 0) ? 1 : 0);
        gpioWrite(ROW2, (i == 1) ? 1 : 0);
        gpioWrite(ROW3, (i == 2) ? 1 : 0);
        gpioWrite(ROW4, (i == 3) ? 1 : 0);
        gpioWrite(ROW5, (i == 4) ? 1 : 0);
        gpioWrite(ROW6, (i == 5) ? 1 : 0);
        gpioWrite(ROW7, (i == 6) ? 1 : 0);
        gpioWrite(ROW8, (i == 7) ? 1 : 0);

        // Set column pins LOW
        for (int j = 0; j < NUM_COLS; j++) {
            gpioWrite(COL1, (j == 0) ? 0 : 1);
            gpioWrite(COL2, (j == 1) ? 0 : 1);
            gpioWrite(COL3, (j == 2) ? 0 : 1);
            gpioWrite(COL4, (j == 3) ? 0 : 1);
            gpioWrite(COL5, (j == 4) ? 0 : 1);
            gpioWrite(COL6, (j == 5) ? 0 : 1);
            gpioWrite(COL7, (j == 6) ? 0 : 1);
            gpioWrite(COL8, (j == 7) ? 0 : 1);
        }
        gpioDelay(ROW_DELAY);
    }
}

// Function to display a horizontal wave
void display_horizontal_wave() {
    for (int i = 0; i < NUM_ROWS; i++) {
        // Set row pins HIGH
        gpioWrite(ROW1, (i == 0) ? 1 : 0);
        gpioWrite(ROW2, (i == 1) ? 1 : 0);
        gpioWrite(ROW3, (i == 2) ? 1 : 0);
        gpioWrite(ROW4, (i == 3) ? 1 : 0);
        gpioWrite(ROW5, (i == 4) ? 1 : 0);
        gpioWrite(ROW6, (i == 5) ? 1 : 0);
        gpioWrite(ROW7, (i == 6) ? 1 : 0);
        gpioWrite(ROW8, (i == 7) ? 1 : 0);

        // Set column pins LOW
        for (int j = 0; j < NUM_COLS; j++) {
            gpioWrite(COL1, 0);
            gpioWrite(COL2, 0);
            gpioWrite(COL3, 0);
            gpioWrite(COL4, 0);
            gpioWrite(COL5, 0);
            gpioWrite(COL6, 0);
            gpioWrite(COL7, 0);
            gpioWrite(COL8, 0);
        }
        gpioDelay(ROW_DELAY);
    }
}

// Function to display a vertical wave
void display_vertical_wave() {
    for (int i = 0; i < NUM_ROWS; i++) {
        // Set row pins HIGH
        gpioWrite(ROW1, (i == 0) ? 1 : 0);
        gpioWrite(ROW2, (i == 1) ? 1 : 0);
        gpioWrite(ROW3, (i == 2) ? 1 : 0);
        gpioWrite(ROW4, (i == 3) ? 1 : 0);
        gpioWrite(ROW5, (i == 4) ? 1 : 0);
        gpioWrite(ROW6, (i == 5) ? 1 : 0);
        gpioWrite(ROW7, (i == 6) ? 1 : 0);
        gpioWrite(ROW8, (i == 7) ? 1 : 0);

        // Set column pins HIGH
        for (int j = 0; j < NUM_COLS; j++) {
            gpioWrite(COL1, 1);
            gpioWrite(COL2, 1);
            gpioWrite(COL3, 1);
            gpioWrite(COL4, 1);
            gpioWrite(COL5, 1);
            gpioWrite(COL6, 1);
            gpioWrite(COL7, 1);
            gpioWrite(COL8, 1);
        }
        gpioDelay(ROW_DELAY);
    }
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("LED Matrix Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        clear_matrix();
        display_wave();

        // Simulate horizontal wave
        display_horizontal_wave();

        // Simulate vertical wave
        display_vertical_wave();
    }

    // Clear the matrix before exiting
    clear_matrix();

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");

    return 0;
}

