const int num_cols = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set row pins as output
    for (int i = 0; i < num_rows; i++) {
        gpioSetMode(row_pins[i], PI_OUTPUT);
        gpioWrite(row_pins[i], 1); // Initialize all rows HIGH
    }

    // Set column pins as output
    for (int i = 0; i < num_cols; i++) {
        gpioSetMode(col_pins[i], PI_OUTPUT);
        gpioWrite(col_pins[i], 1); // Initialize all columns HIGH
    }

    return 0; // Indicate success
}

// Function to clear the LED matrix
void clear_matrix() {
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 0); // Set column HIGH
        gpioWrite(row_pins[0], 0); // Set all row pins LOW
    }
    gpioDelay(150); // Delay for 150ms
}

// Function to display a wave pattern
void display_wave() {
    for (int col = 0; col < num_cols; col++) {
        gpioWrite(col_pins[col], 0); // Set column HIGH
        gpioWrite(row_pins[0], 0); // Set all row pins LOW

        // Simulate the wave pattern by sequentially lighting up rows
        for (int row = 0; row < num_rows; row++) {
            gpioWrite(row_pins[row], 1); // Set row HIGH
            gpioDelay(50); // Delay for 50ms
            gpioWrite(row_pins[row], 0); // Set row LOW
        }
        gpioDelay(150); // Delay for 150ms
    }
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    printf("Cleaning up GPIO pins...\n");
    for (int i = 0; i < num_rows; i++) {
        gpioWrite(row_pins[i], 0); // Set all row pins LOW
    }
    for (int i = 0; i < num_cols; i++) {
        gpioWrite(col_pins[i], 1); // Set all column pins HIGH
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigint_handler);

    // Initialize GPIO pins
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("LED matrix wave animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        clear_matrix();
        display_wave();
    }

    // Cleanup GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

