#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// VL53L3CX I2C address
#define VL53L3CX_ADDR 0x29

// VL53L3CX register addresses (Example - refer to datasheet for complete list)
#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L3CX_REG_IDENTIFICATION_REVISION_ID 0x0110
#define VL53L3CX_REG_SYSRANGE_START 0x00
#define VL53L3CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L3CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int i2c_handle;
} sensor_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the VL53L3CX sensor
int init_vl53l3cx(int i2c_handle) {
    // Placeholder for the VL53L3CX initialization sequence
    // Replace with the actual initialization sequence from the datasheet
    // This example only sets the I2C bus and address.
    if (i2cWriteByteData(i2c_handle, 0x00, 0x29) < 0) {
        fprintf(stderr, "Error: Failed to set I2C bus and address.\n");
        return -1;
    }

    // Verify sensor model ID
    int model_id = i2cReadByteData(i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error: Failed to read model ID.\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    printf("VL53L3CX sensor initialized successfully.\n");
    return 0;
}

// Function to read distance measurements from the VL53L3CX sensor
int read_distance_data(int i2c_handle, int *distances, int max_targets) {
    // Placeholder for the VL53L3CX data reading sequence
    // Replace with the actual data reading sequence from the datasheet
    // This example reads 2 bytes per target.
    char buffer[2 * max_targets];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2 * max_targets);

    if (bytes_read < 0) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    // Convert the buffer to an array of distance values
    for (int i = 0; i < max_targets; i++) {
        distances[i] = (buffer[2 * i + 1] << 8) | buffer[2 * i];
    }

    return 0;
}

// Function to print the distance data with ISO 8601 timestamp
void print_distance_data(const int *distances, int max_targets) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s", timestamp);
    for (int i = 0; i < max_targets; i++) {
        printf(",%d", distances[i]);
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Sensor configuration
    sensor_config_t config = {
        .i2c_bus = 1,
        .i2c_address = VL53L3CX_ADDR,
        .i2c_handle = -1 // Initialize later
    };

    // Open I2C bus
    config.i2c_handle = i2cOpen(config.i2c_bus, config.i2c_address, 0);
    if (config.i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", config.i2c_handle);
        gpioTerminate();
        return 1;
    }
    i2c_handle = config.i2c_handle; // Store the handle for later use

    // Initialize the VL53L3CX sensor
    if (init_vl53l3cx(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    int distances[10]; // Assuming a maximum of 10 targets
    int num_targets;

    // Main loop
    while (!terminate) {
        // Read distance data
        if (read_distance_data(i2c_handle, distances, 10) == 0) {
            // Print the distance data
            print_distance_data(distances, 10);
        } else {
            fprintf(stderr, "Error: Failed to read distance data.\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

