#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the MLX75031 sensor
#define MLX75031_ADDR 0x4A

// Define the register address for the distance data (replace with actual register)
#define DISTANCE_REG 0x00

// Define the sampling interval in milliseconds
#define SAMPLE_INTERVAL_MS 100

// Define the log file name
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration (example)
typedef struct {
    int i2c_address;
    int i2c_bus;
    int i2c_handle;
    FILE *log_file;
} sensor_config_t;

// Function prototypes
int initialize_sensor(sensor_config_t *config);
int read_distance(sensor_config_t *config);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(sensor_config_t *config) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    config->i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (config->i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", config->i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify sensor initialization (replace with actual initialization sequence)
    // For example, read a register and check if it returns a valid value
    char init_data[1] = {0x00}; // Example initialization data
    int result = i2cWriteDevice(config->i2c_handle, init_data, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        i2cClose(config->i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance data from the sensor
int read_distance(sensor_config_t *config) {
    char buffer[2]; // Assuming 2 bytes for distance data
    int result = i2cReadDevice(config->i2c_handle, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return -1; // Indicate an error
    }

    // Convert the received bytes to a distance value (replace with actual conversion)
    int distance = (buffer[0] << 8) | buffer[1]; // Example conversion

    return distance;
}

// Function to log data to a file
int log_data(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d\n", timestamp, distance);
    fflush(fp); // Ensure data is written to the file immediately

    return 0;
}

int main() {
    sensor_config_t sensor_config;
    sensor_config.i2c_address = MLX75031_ADDR;
    sensor_config.i2c_bus = 1; // I2C bus 1
    sensor_config.i2c_handle = -1; // Initialize to -1
    sensor_config.log_file = NULL;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor(&sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        return 1;
    }

    // Open the log file
    sensor_config.log_file = fopen(LOG_FILE, "a");
    if (sensor_config.log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(sensor_config.i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(sensor_config.log_file, 0, SEEK_END);
    long file_size = ftell(sensor_config.log_file);
    if (file_size == 0) {
        fprintf(sensor_config.log_file, "Timestamp,Distance\n");
    }
    rewind(sensor_config.log_file);

    // Main loop
    while (program_running) {
        int distance = read_distance(&sensor_config);
        if (distance >= 0) {
            log_data(sensor_config.log_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance, logging -1\n");
            log_data(sensor_config.log_file, -1);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Close the log file
    fclose(sensor_config.log_file);

    // Close the I2C handle
    i2cClose(sensor_config.i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

