    if (sensor_config.log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(sensor_config.i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(sensor_config.log_file, 0, SEEK_END);
    long file_size = ftell(sensor_config.log_file);
    if (file_size == 0) {
        fprintf(sensor_config.log_file, "Timestamp,Distance\n");
    }
    rewind(sensor_config.log_file);

    // Main loop
    while (program_running) {
        int distance = read_distance(&sensor_config);
        if (distance >= 0) {
            log_data(sensor_config.log_file, distance);
        } else {
            fprintf(stderr, "Failed to read distance, logging -1\n");
            log_data(sensor_config.log_file, -1);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Close the log file
    fclose(sensor_config.log_file);

    // Close the I2C handle
    i2cClose(sensor_config.i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

