#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define LOG_FILE "biometric_log.txt"
#define SAMPLE_INTERVAL_MS 500

// Si1145 Registers
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x1E
#define REG_COMMAND 0x30
#define REG_HW_KEY 0x07

// Commands
#define HW_KEY_VAL 0x17
#define MEAS_RATE_VAL 0x00
#define PS_LED21_SELECT_VAL 0x03
#define PS_EN_ADC_VAL 0x01
#define ALS_EN_ADC_VAL 0x01
#define RESET_VAL 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_si1145();
int read_si1145(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function to initialize the Si1145 sensor
int init_si1145() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, RESET_VAL) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, REG_HW_KEY, HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE, MEAS_RATE_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, REG_PS_LED21_SELECT, PS_LED21_SELECT_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write PS_LED21_SELECT: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, REG_PS_EN_ADC, PS_LED21_SELECT_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write PS_EN_ADC: %s\n", strerror(errno));
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, REG_ALS_EN_ADC, ALS_EN_ADC_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write ALS_EN_ADC: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the Si1145 sensor
int read_si1145(int *proximity, int *ambient_light) {
    int als_low, als_high, ps_low, ps_high;

    als_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    if (als_low < 0) {
        fprintf(stderr, "Error: Failed to read ALS_VIS_DATA0: %s\n", strerror(errno));
        return -1;
    }

    als_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
    if (als_high < 0) {
        fprintf(stderr, "Error: Failed to read ALS_VIS_DATA1: %s\n", strerror(errno));
        return -1;
    }

    ps_low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    if (ps_low < 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA0: %s\n", strerror(errno));
        return -1;
    }

    ps_high = i2cReadByteData(i2c_handle, REG_PS1_DATA0 + 1);
    if (ps_high < 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA1: %s\n", strerror(errno));
        return -1;
    }

    *ambient_light = (als_high << 8) | als_low;
    *proximity = (ps_high << 8) | ps_low;

    return 0;
}

// Function to log the data to a file
void log_data(int proximity, int ambient_light) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the Si1145 sensor
    if (init_si1145() < 0) {
        fprintf(stderr, "Error: Si1145 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    int proximity, ambient_light;

    // Main loop
    while (!terminate) {
        if (read_si1145(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }
        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

