#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define LOG_FILE "proximity.log"

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int pigpio_init_result;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    int sensor_value;
    int led_state = 0; // 0 = off, 1 = on
    int last_sensor_value = 1; // Assume initially no object is detected

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value == 0 && last_sensor_value == 1) {
            // Object detected (sensor went LOW)
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log entry
            log_file = fopen(LOG_FILE, "a");
            if (log_file != NULL) {
                fprintf(log_file, "%s Object detected\n", timestamp);
                fclose(log_file);
            } else {
                perror("Error opening log file for writing");
            }

            // Blink LED
            gpioWrite(LED_PIN, 1);
            gpioDelay(100); // 100ms
            gpioWrite(LED_PIN, 0);

            last_sensor_value = sensor_value;
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

