#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 1000000      // 1 second timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm
#define WATERING_THRESHOLD 15.0 // cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    double distance;
    int valid;
} SensorData;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
SensorData validate_distance(double distance);
void log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick, end_tick, diff;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1 us
    }

    if (count >= TIMEOUT_US) {
        return 0; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return 0; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    return diff;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
