#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 1000000      // 1 second timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm
#define WATERING_THRESHOLD 15.0 // cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    double distance;
    int valid;
} SensorData;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long measure_pulse_width();
double calculate_distance(long pulse_width);
