// APDS9960 I2C address
#define APDS9960_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C
#define APDS9960_PDATAH 0x9D
#define APDS9960_PPULSE 0x9E
#define APDS9960_CONTROL2 0x9F

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_proximity();
int apds9960_read_rgb(uint16_t *r, uint16_t *g, uint16_t *b);
void log_data(uint16_t r, uint16_t g, uint16_t b, int proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// APDS9960 initialization function
int apds9960_init() {
    // Enable power and proximity sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set proximity pulse length (PPULSE)
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x1B) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set proximity gain (CONTROL2)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONTROL2 register\n");
        return -1;
    }

    return 0;
}

// APDS9960 read proximity function
int apds9960_read_proximity() {
    int proximity = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    return proximity;
}

// APDS9960 read RGB function
int apds9960_read_rgb(uint16_t *r, uint16_t *g, uint16_t *b) {
    uint8_t c_l, c_h, r_l, r_h, g_l, g_h, b_l, b_h;

    c_l = i2cReadByteData(i2c_handle, APDS9960_CDATAL);
    c_h = i2cReadByteData(i2c_handle, APDS9960_CDATAH);
    r_l = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
    r_h = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
    g_l = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
    g_h = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
    b_l = i2cReadByteData(i2c_handle, APDS9960_BDATAL);
    b_h = i2cReadByteData(i2c_handle, APDS9960_BDATAH);

    if (c_l < 0 || c_h < 0 || r_l < 0 || r_h < 0 || g_l < 0 || g_h < 0 || b_l < 0 || b_h < 0) {
        fprintf(stderr, "Error reading RGB data\n");
        return -1;
    }

    *r = (r_h << 8) | r_l;
    *g = (g_h << 8) | g_l;
    *b = (b_h << 8) | b_l;

    return 0;
}

// Log data to CSV file function
void log_data(uint16_t r, uint16_t g, uint16_t b, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%d\n", timestamp, r, g, b, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,R,G,B,Proximity\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int proximity = apds9960_read_proximity();
        if (proximity < 0) {
            fprintf(stderr, "Error reading proximity, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        uint16_t r, g, b;
        if (apds9960_read_rgb(&r, &g, &b) < 0) {
            fprintf(stderr, "Error reading RGB, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        log_data(r, g, b, proximity);

        gpioDelay(100); // Wait 100ms
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

