        return -1;
    }
    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

