                fprintf(stderr, "Error logging distance.\n");
            }
        } else {
            fprintf(stderr, "Error reading distance, skipping sample.\n");
        }

        // Wait before next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

