#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 20.0 // cm
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
void cleanup();
void signal_handler(int signal);
float read_distance();
void control_led(float distance);
void log_data(float distance);

// Structure to hold sensor data (optional)
typedef struct {
    float distance;
    time_t timestamp;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Read distance from ICU-20201 sensor
float read_distance() {
    char buf[2];
    int bytes_read;
    int16_t distance_raw;
    float distance_cm;

    bytes_read = i2cReadDevice(i2c_handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance: %d\n", bytes_read);
        return -1.0; // Indicate error
    }

    distance_raw = (buf[0] << 8) | buf[1];
    distance_cm = (float)distance_raw / 10.0; // Example conversion, adjust as needed

    return distance_cm;
}

// Control LED based on distance
void control_led(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Log data to file
void log_data(float distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    fprintf(log_file, "%s,%.2f\n", buf, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        i2cClose(i2c_handle);
        gpioWrite(LED_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Starting distance monitoring...\n");

    // Main loop
    while (!terminate) {
        float distance = read_distance();
        if (distance >= 0) {
            control_led(distance);
            log_data(distance);
        } else {
            fprintf(stderr, "Failed to read distance. Skipping LED control and logging.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

