        gpioDelay(50000); // 50ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn LED off
    fclose(log_file);
    gpioTerminate();

    return 0;
}

