#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESS 0x50
#define MEASUREMENT_COMMAND_SIZE 4
#define MEASUREMENT_RESPONSE_SIZE 15
#define INTRUSION_THRESHOLD 1000 // mm
#define SAMPLE_DELAY_MS 100
#define SAMPLE_PERIOD_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(unsigned char *response);
int verify_header(unsigned char *response);
int extract_distance(unsigned char *response);
int calculate_average_distance(int distance1, int distance2, int distance3, int distance4);
int log_intrusion_event(int distance);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SENSOR_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send measurement command
int send_measurement_command() {
    unsigned char command[MEASUREMENT_COMMAND_SIZE] = {0x01, 0x02, 0x03, 0x04};
    int result = i2cWriteDevice(i2c_handle, (char *)command, MEASUREMENT_COMMAND_SIZE);
    if (result != MEASUREMENT_COMMAND_SIZE) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(unsigned char *response) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)response, MEASUREMENT_RESPONSE_SIZE);
    if (bytes_read != MEASUREMENT_RESPONSE_SIZE) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to verify the header
int verify_header(unsigned char *response) {
    unsigned char header = response[0];
    if (header != 0xAB) {
        fprintf(stderr, "Error: Invalid header (expected 0xAB): 0x%02X\n", header);
        return -1;
    }
