// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x001E
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// I2C handle
int i2c_handle;

// Function prototypes
int vl53l0x_init();
int vl53l0x_read_distance();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
    }
}

// Function to initialize the VL53L0X sensor
int vl53l0x_init() {
    // Check if the sensor is present by reading the model ID register
    char model_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    if (model_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect model ID (0x%02X). Expected 0xEA.\n", model_id);
        return -1;
    }

    // Configure the sensor (example configuration - adjust as needed)
    // This is a simplified example and may need further tuning
    char config_data[] = {0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x0E, 0x0F};
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, config_data, sizeof(config_data)) != sizeof(config_data)) {
        fprintf(stderr, "Error writing configuration data: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L0X sensor
int vl53l0x_read_distance() {
    char data[2];
    int distance;

    // Read the distance from the sensor
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the VL53L0X sensor
    if (vl53l0x_init() != 0) {
        fprintf(stderr, "VL53L0X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read the distance from the sensor
        int distance = vl53l0x_read_distance();
        if (distance >= 0) {
            // Get the current timestamp
            time_t now = time(NULL);

            // Print the distance to stdout
            printf("%s Distance: %d mm\n", ctime(&now), distance);
        } else {
            fprintf(stderr, "Error reading distance, skipping iteration.\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

