#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the OPT3101 sensor
#define OPT3101_ADDR 0x64

// Define the register addresses for distance and ambient light
#define DISTANCE_REG 0x00
#define AMBIENT_LIGHT_REG 0x02

// Define the error value for distance measurement
#define DISTANCE_ERROR -1.0

// Global variable to store the I2C handle
int i2c_handle;

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the OPT3101 sensor
int read_opt3101_value(int handle, int reg) {
    int value = i2cReadWordData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1; // Indicate an error
    }
    return value;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C bus
    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and log sensor data
    while (1) {
        // Read the distance value from channel 0
        int distance = read_opt3101_value(i2c_handle, DISTANCE_REG);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance value\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Read the ambient light value
        int ambient_light = read_opt3101_value(i2c_handle, AMBIENT_LIGHT_REG);
        if (ambient_light < 0) {
            fprintf(stderr, "Error reading ambient light value\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                gpioTerminate();
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Log the sensor data to the console
        printf("Distance: %.2f mm, Ambient Light: %d\n", distance, ambient_light);

        // Wait for 500 milliseconds
        gpioDelay(500000); // Delay in microseconds
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

