#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // Timeout for echo pulse in microseconds (200ms)
#define MAX_DISTANCE 400         // Maximum measurable distance in cm
#define MIN_DISTANCE 2           // Minimum measurable distance in cm
#define MAX_PULSE_DURATION 38000 // Maximum valid pulse duration in microseconds (38ms)

// Global variable for graceful shutdown
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long long start_tick, end_tick, pulse_duration;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    // Wait for echo rising edge with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo rising edge timeout (0x%llX)\n", count);
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo falling edge with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo falling edge timeout (0x%llX)\n", count);
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    // Calculate pulse duration
    pulse_duration = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_duration * SPEED_OF_SOUND) / 2000000.0;

    // Validate distance
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Invalid distance reading: %.2f cm\n", distance);
        return -1.0; // Indicate error
    }

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float distance = measure_distance();

        if (distance >= 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the distance to the console
            printf("%s Distance: %.2f cm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Error: Failed to measure distance\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

