#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define TARGET_THRESHOLD 1.0
#define GPIO_LED 17
#define LOG_FILE "intrusion_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure to hold configuration parameters
typedef struct {
    char uart_device[20];
    int baud_rate;
    float target_threshold;
    int gpio_pin;
    char log_file_path[50];
} Config;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_magic_word(int fd, unsigned char magic_word[8]);
int read_range_profile(int fd, int *range_profile, int num_bins);
int detect_target(const int *range_profile, int num_bins, float threshold);
int log_intrusion(const char *timestamp, float distance);
int activate_alert(int gpio_pin, int duration_ms);
void signal_handler(int signal);
void cleanup();

// Function to initialize the UART interface
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the magic word from the UART
int read_magic_word(int fd, unsigned char magic_word[8]) {
    unsigned char buffer[8];
    ssize_t bytes_read = read(fd, buffer, 8);

    if (bytes_read != 8) {
        fprintf(stderr, "Error reading magic word: %zd bytes read\n", bytes_read);
        return -1;
    }

    memcpy(magic_word, buffer, 8);
    return 0;
}

// Function to read the range profile from the UART
int read_range_profile(int fd, int *range_profile, int num_bins) {
    unsigned char magic_word[8];
    if (read_magic_word(fd, magic_word) != 0) {
        fprintf(stderr, "Magic word read failed\n");
        return -1;
    }

    // Verify magic word (example: 0xDEADBEEF)
    if (magic_word[0] != 0xDEAD || magic_word[1] != 0xBEEF) {
        fprintf(stderr, "Invalid magic word\n");
        return -1;
    }

    // Read the range profile data
    ssize_t bytes_read = read(fd, range_profile, num_bins * 2); // Each bin is 2 bytes (16-bit)
    if (bytes_read != num_bins * 2) {
        fprintf(stderr, "Error reading range profile: %zd bytes read\n", bytes_read);
        return -1;
    }

    return 0;
}

// Function to detect a target within the specified threshold
int detect_target(const int *range_profile, int num_bins, float threshold) {
    for (int i = 0; i < num_bins; i++) {
        if (range_profile[i] < threshold) {
            return 1; // Target detected
        }
    }
    return 0; // No target detected
}

// Function to log the intrusion event to a file
int log_intrusion(const char *timestamp, float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to activate the alert (LED)
int activate_alert(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn LED off
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, exiting gracefully...\n");
}

// Cleanup function to release resources
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .target_threshold = TARGET_THRESHOLD,
        .gpio_pin = GPIO_LED,
        .log_file_path = LOG_FILE
    };

