#define SENSOR_PIN 17
#define BUZZER_PIN 18
#define LOG_FILE "obstacle_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the obstacle detection event to a file
void log_obstacle_detection(const char* timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s: Obstacle detected\n", timestamp);
    fclose(fp);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Set buzzer pin HIGH
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_PIN, 0); // Set buzzer pin LOW
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

