    gpioSetMode(SENSOR_PIN, PI_INPUT);
    // Set GPIO 18 as output for the buzzer
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read the sensor value
        int sensor_value = gpioRead(SENSOR_PIN);

        // Get the current timestamp
        char* timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping logging.\n");
            continue; // Skip logging if timestamp fails
        }

        // Log the obstacle detection event
        if (sensor_value == 0) { // Obstacle detected (active low)
            log_obstacle_detection(timestamp);
            activate_buzzer();
        } else {
            // Timestamp for obstacle removal
            char* timestamp_removal = get_iso8601_timestamp();
            if (timestamp_removal != NULL) {
                log_obstacle_detection(timestamp_removal);
                deactivate_buzzer();
            }
        }

        free(timestamp); // Free the allocated timestamp memory
        free(timestamp_removal); // Free the allocated timestamp memory for removal

        // Wait for 100 milliseconds
        gpioDelay(100); // pigpio's delay function
    }

    // Cleanup and exit
    deactivate_buzzer(); // Ensure buzzer is off
    gpioTerminate(); // Terminate pigpio

    printf("Program terminated.\n");
    return 0;
}

