// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x68 // Replace with the actual I2C address of the sensor
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define LOG_FILE "distance_log.txt"
#define ICU20201_REG_MEASURE 0x00 // Replace with the actual register address for measurement
#define ICU20201_REG_DISTANCE_MSB 0x01 // Replace with the actual register address for distance MSB
#define ICU20201_REG_DISTANCE_LSB 0x02 // Replace with the actual register address for distance LSB

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_distance(float *distance);
int log_data(float distance);
int check_threshold(float distance);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    gpioWrite(GPIO_PIN, 0); // Initially low
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;

    // Trigger measurement (replace with the correct register and value)
    result = i2cWriteByteData(i2c_handle, ICU20201_REG_MEASURE, 0x01); // Example: Trigger measurement
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // 10ms delay

    // Read distance data (replace with the correct registers)
    result = i2cReadI2CBlockData(i2c_handle, ICU20201_REG_DISTANCE_MSB, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine MSB and LSB to get the distance
    int16_t raw_distance = (buf[0] << 8) | buf[1];

    // Convert raw distance to centimeters (replace with the correct conversion formula)
    *distance = (float)raw_distance * 0.1; // Example conversion

    return 0;
}

// Log data to file
int log_data(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

