int check_threshold(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1); // Assert GPIO
        printf("Distance below threshold: %.2f cm\n", distance);
    } else {
        gpioWrite(GPIO_PIN, 0); // De-assert GPIO
    }
    return 0;
}

