    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float distance;

    printf("Starting distance measurement...\n");

    while (!terminate) {
        if (read_distance(&distance) == 0) {
            log_data(distance);
            check_threshold(distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }
        gpioDelay(100); // 100ms delay
    }

