// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x29
#define DISTANCE_REG 0x00 // Example register address
#define LED_GPIO 18
#define BLINK_FREQUENCY_MAX 1000 // Maximum blink frequency (Hz)
#define BLINK_FREQUENCY_MIN 10   // Minimum blink frequency (Hz)
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    int blink_frequency;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_distance(int *distance);
int calculate_blink_frequency(int distance);
void control_led(int blink_frequency);
void log_data(int distance, int blink_frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_distance(int *distance) {
    char buf[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2) == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculate blink frequency based on distance
int calculate_blink_frequency(int distance) {
    // Implement a mapping from distance to blink frequency
    // This is a simple linear mapping, but you can use a more complex function
    // based on your sensor's characteristics and desired behavior.
    int frequency = BLINK_FREQUENCY_MIN + (int)(((float)distance / 100.0) * (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN)); // Example: 100cm to 10Hz
    if (frequency < BLINK_FREQUENCY_MIN) frequency = BLINK_FREQUENCY_MIN;
    if (frequency > BLINK_FREQUENCY_MAX) frequency = BLINK_FREQUENCY_MAX;
    return frequency;
}

// Control the LED blinking
void control_led(int blink_frequency) {
    // Calculate the delay for each half-cycle of the blink
    int delay_us = 500000 / blink_frequency; // Delay in microseconds
    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(delay_us);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioDelay(delay_us);
}

// Log the data
void log_data(int distance, int blink_frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %d mm, Blink Frequency: %d Hz\n", timestamp, distance, blink_frequency);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    int distance;
    int blink_frequency;

    // Main loop
    while (!terminate) {
        if (read_distance(&distance) == 0) {
            blink_frequency = calculate_blink_frequency(distance);
            control_led(blink_frequency);
            log_data(distance, blink_frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying in 100ms.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

