                }
                sensor1_data.last_state = sensor1_data.current_state;
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(sensor2_data.gpio_pin);
        if (sensor2_value >= 0) {
            sensor2_data.current_state = sensor2_value;
