} ProgramState;

ProgramState state = {0, NULL, 1};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    state.running = 0; // Stop the main loop

    if (state.i2c_fd != -1) {
        i2cClose(state.i2c_fd);
    }

    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    gpioTerminate();
    exit(0);
}

// Function to open the I2C device
int open_i2c_device() {
    int fd = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", fd);
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %d\n", errno);
        return -1;
    }
    return 0;
}

// Function to read a register with timeout
int read_register_with_timeout(int fd, unsigned char reg, unsigned char *data, int timeout_ms) {
    int retries = 0;
    int delay_ms = 10; // Initial delay

    while (retries < 3) {
        if (i2cWriteByte(fd, reg) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", errno);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        if (i2cReadByte(fd) < 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", errno);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }

        *data = i2cReadByte(fd);
        if (*data >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, errno);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
        }
    }

    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to write a register with timeout
int write_register_with_timeout(int fd, unsigned char reg, unsigned char data, int timeout_ms) {
    int retries = 0;
    int delay_ms = 10; // Initial delay

    while (retries < 3) {
        if (i2cWriteByteData(fd, reg, data) < 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", errno);
            retries++;
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            continue;
        }
        return 0; // Success
    }

    fprintf(stderr, "Failed to write register 0x%02X after multiple retries.\n", reg);
    return -1; // Failure
}

// Function to read the distance from the sensor
int read_distance(int fd, int *distance_mm) {
    unsigned char status;
    unsigned char distance_data[2];

    // Poll MEAS_STATUS register with timeout
    if (read_register_with_timeout(fd, MEAS_STATUS_REG, &status, TIMEOUT_MS) != 0) {
        fprintf(stderr, "Error reading MEAS_STATUS register.\n");
        return -1;
    }

    // Check if the sensor is ready
    if (status & 0x01) {
        // Read distance data
        if (read_register_with_timeout(fd, DISTANCE_REG, distance_data, TIMEOUT_MS) != 0) {
            fprintf(stderr, "Error reading distance data.\n");
            return -1;
        }

        // Combine the two bytes to form the distance in millimeters
        *distance_mm = (distance_data[0] << 8) | distance_data[1];

        // Validate the distance
        if (*distance_mm < 0 || *distance_mm > 10000) {
            fprintf(stderr, "Invalid distance reading: %d\n", *distance_mm);
            return -1;
        }

        return 0; // Success
    } else {
        fprintf(stderr, "Sensor not ready.\n");
        return -1; // Not ready
    }
}

// Function to log the data to a CSV file
int log_data(FILE *fp, time_t timestamp, int distance_mm) {
    struct tm *timeinfo;
    char timestamp_str[30];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp_str, distance_mm) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open_i2c_device();
    if (i2c_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Set the I2C slave address
    if (set_i2c_slave_address(i2c_fd, CH101_ADDR) != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    state.log_file = fopen("distance_log.csv", "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (state.running) {
        int distance_mm;
        time_t current_time = time(NULL);

        if (read_distance(i2c_fd, &distance_mm) == 0) {
            if (distance_mm >= 0 && distance_mm <= DISTANCE_THRESHOLD) {
                if (log_data(state.log_file, current_time, distance_mm) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Distance out of range: %d mm\n", distance_mm);
            }
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Clean up
    i2cClose(i2c_fd);
    fclose(state.log_file);
    gpioTerminate();

    return 0;
}

