#define VL53L5CX_ADDR 0x29

// VL53L5CX register addresses (example, adjust based on datasheet)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00C0
#define VL53L5CX_REG_IDENTIFICATION_REVISION_ID 0x00C2
#define VL53L5CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_MS 0x001E
#define VL53L5CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_MS 0x001F
#define VL53L5CX_REG_SYSTEM_SEQUENCE_CONFIG 0x0020
#define VL53L5CX_REG_START_STOP_CONTROL 0x0080
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L5CX_REG_RESULT_SPAD_NB_DETECTED 0x008A
#define VL53L5CX_REG_RESULT_SIGNAL_RATE 0x008F
#define VL53L5CX_REG_RESULT_AMBIENT_RATE 0x0090
#define VL53L5CX_REG_RESULT_DISTANCE 0x0096

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nExiting program...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int fd) {
    // Example initialization sequence (adjust based on datasheet)
    uint8_t model_id, revision_id;
    uint8_t status;

    // Check sensor ID
    if (i2c_smbus_read_byte_data(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID) < 0) {
        perror("Error reading model ID");
        return -1;
    }
    model_id = i2c_smbus_read_byte_data(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        perror("Error reading model ID");
        return -1;
    }

    if (i2c_smbus_read_byte_data(fd, VL53L5CX_REG_IDENTIFICATION_REVISION_ID) < 0) {
        perror("Error reading revision ID");
        return -1;
    }
    revision_id = i2c_smbus_read_byte_data(fd, VL53L5CX_REG_IDENTIFICATION_REVISION_ID);
    if (revision_id < 0) {
        perror("Error reading revision ID");
        return -1;
    }

    // Configure sensor (example settings)
    if (i2c_smbus_write_byte_data(fd, VL53L5CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_MS, 0x04) < 0) {
        perror("Error writing pre-range config timeout");
        return -1;
    }
    if (i2c_smbus_write_byte_data(fd, VL53L5CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_MS, 0x04) < 0) {
        perror("Error writing final range config timeout");
        return -1;
    }

    // Start continuous ranging
    if (i2c_smbus_write_byte_data(fd, VL53L5CX_REG_START_STOP_CONTROL, 0x01) < 0) {
        perror("Error starting continuous ranging");
        return -1;
    }

    // Verify sensor is ready (check status register)
    status = i2c_smbus_read_byte_data(fd, VL53L5CX_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        perror("Error reading status register");
        return -1;
    }

    if (status != 0) {
        fprintf(stderr, "Sensor not ready (status = 0x%02X)\n", status);
        return -1;
    }

    printf("VL53L5CX sensor initialized successfully.\n");
    return 0;
}

// Function to read distance data from the VL53L5CX sensor
int read_distance_data(int fd, uint16_t *distances) {
    uint8_t buffer[2];
    int i;

    // Read distance data for each zone
    for (i = 0; i < 64; i++) {
        if (i2c_smbus_read_byte_data(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2)) < 0) {
            perror("Error reading distance data");
            return -1;
        }
        buffer[0] = i2c_smbus_read_byte_data(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2));
        buffer[1] = i2c_smbus_read_byte_data(fd, VL53L5CX_REG_RESULT_DISTANCE + (i * 2) + 1);
        distances[i] = (uint16_t)((buffer[0] << 8) | buffer[1]);
    }

    return 0;
}

int main() {
    int i;
    uint16_t distances[64];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Specify the address of the slave device
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the VL53L5CX sensor
    if (init_vl53l5cx(i2c_fd) < 0) {
        fprintf(stderr, "VL53L5CX initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance data
        if (read_distance_data(i2c_fd, distances) < 0) {
            fprintf(stderr, "Failed to read distance data.\n");
        } else {
            // Log the distance data
            for (i = 0; i < 64; i++) {
                printf("Zone %d: %d mm\n", i, distances[i]);
            }
        }

        // Wait for 500ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000; // 500ms
        nanosleep(&ts, NULL);
    }

    // Close I2C device (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

