#include <string.h>

// Define the I2C address of the MLX75030 sensor
#define MLX75030_ADDR 0x4A

// Define the register address for distance data (replace with actual register)
#define DISTANCE_REG 0x00

// Define the number of retries for I2C operations
#define MAX_RETRIES 3

// Define the delay between I2C retries (in milliseconds)
#define RETRY_DELAY_MS 10

// Global variable to store the I2C handle
int i2c_handle = -1;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle, uint8_t *data);
void log_distance(uint8_t distance);
void signal_handler(int signal);

// Structure to hold configuration parameters
typedef struct {
    int i2c_bus;
    int i2c_address;
    int logging_interval_ms;
} config_t;

// Function to initialize the I2C bus
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read distance data from the sensor
int read_distance(int handle, uint8_t *data) {
    int result;
    for (int i = 0; i < MAX_RETRIES; ++i) {
        result = i2cReadI2CBlockData(handle, DISTANCE_REG, (char *)data, 2); // Read 2 bytes
        if (result == 2) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log the distance measurement with a timestamp
void log_distance(uint8_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %u mm\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Define the configuration parameters
    config_t config = {
        .i2c_bus = 1,
        .i2c_address = MLX75030_ADDR,
        .logging_interval_ms = 100
    };

    // Initialize the I2C bus
    i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log distance measurements
    uint8_t distance_data[2];
    while (1) {
        if (read_distance(i2c_handle, distance_data) == 0) {
            // Convert the raw data to a distance value (replace with actual conversion)
            uint8_t distance = (distance_data[0] << 8) | distance_data[1];

            // Log the distance measurement
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        gpioDelay(config.logging_interval_ms * 1000); // Delay in microseconds
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate proper resource cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

