int read_distance();
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (adjust based on datasheet)
    char init_data[] = {0x00, 0x01}; // Example register and value
    int result = i2cWriteDevice(i2c_handle, init_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X: %d\n", result);
        return -1;
    }

    // Configure for continuous ranging mode (example)
    init_data[0] = VL53L1X_REG_RANGING_MODE;
    init_data[1] = 0x04; // Example value for continuous mode
    result = i2cWriteDevice(i2c_handle, init_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X (continuous mode): %d\n", result);
        return -1;
    }

    // Verify sensor ID (example)
    char sensor_id;
    result = i2cReadDevice(i2c_handle, &sensor_id, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", result);
        return -1;
    }

    if (sensor_id != 0xEA) { // Expected value for VL53L1X
        fprintf(stderr, "Incorrect sensor ID: 0x%02x\n", sensor_id);
        return -1;
    }

    printf("VL53L1X initialized successfully.\n");
    return 0;
}

