int read_distance() {
    char cmd[1];
    char data[2];
    int distance;

    // Read range status
    cmd[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X (range status): %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading range status: %d\n", result);
        return -1;
    }

    // Read distance (example)
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to VL53L1X (distance): %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading distance: %d\n", result);
        return -1;
    }

    distance = (data[0] << 8) | data[1];

    return distance;
}

