        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            control_buzzer(distance);
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(500); // 500ms delay
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

