    if (status != 0) {
        fprintf(stderr, "Error starting measurement: %d\n", status);
        return -1;
    }

    // Wait for measurement to complete (adjust timeout as needed)
    gpioDelay(10000); // 10ms

    // Read the distance
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    status = i2cWriteDevice(i2c_handle, cmd, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to read distance: %d\n", status);
