        cleanup();
        return 1;
    }

    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = 100;
    attr.mq_curmsgs = 0;

    if (bind(message_queue_socket, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error binding socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (listen(message_queue_socket, 1) < 0) {
        fprintf(stderr, "Error listening on socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance
        int distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
