#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 1000000      // 1 second timeout
#define BUZZER_THRESHOLD 30.0   // cm
#define BUZZER_ACTIVE_THRESHOLD 30.0 // cm
#define BUZZER_INACTIVE_THRESHOLD 30.0 // cm

// Global variables
volatile unsigned int start_tick, end_tick, echo_time;
volatile int buzzer_active = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int buzzer_active;
    int distance;
} sensor_data_t;

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;
        echo_time = end_tick - start_tick;
    }
}

