#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD 200 // mm
#define OPEN_GPIO 23
#define CLOSE_GPIO 24
#define PWM_FREQUENCY 50
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);
void v2_callback(int gpio, int level, uint32_t tick, void *user_data);

// VL53L1X register addresses (Example - adjust as needed)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Software reset
    char buf[2];
    buf[0] = VL53L1X_REG_SYSRANGE_START;
    buf[1] = 0x01; // Reset command
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_event("VL53L1X: I2C write error during reset");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Check sensor ID
    char id;
    if (i2cReadDevice(i2c_handle, &id, 1) != 0) {
        log_event("VL53L1X: I2C read error during sensor ID check");
        return -1;
    }
    if (id != 0xEE) {
        log_event("VL53L1X: Incorrect sensor ID");
        return -1;
    }

    // Start ranging
    buf[0] = VL53L1X_REG_SYSRANGE_START;
    buf[1] = 0x01; // Start ranging command
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_event("VL53L1X: I2C write error during ranging start");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    char cmd[1];
    char data[2];
    int distance;

    // Read range status
    cmd[0] = VL53L1X_REG_RESULT_RANGE_STATUS;
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        log_event("VL53L1X: I2C write error during range status read");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 1) != 0) {
        log_event("VL53L1X: I2C read error during range status read");
        return -1;
    }

    // Read distance
    cmd[0] = VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0;
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
        log_event("VL53L1X: I2C write error during distance read");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, data, 2) != 0) {
        log_event("VL53L1X: I2C read error during distance read");
        return -1;
    }

    distance = (data[0] << 8) | data[1];
    return distance;
}

// Function to open the gate
void open_gate() {
    gpioWrite(OPEN_GPIO, 1); // Set GPIO HIGH
    gpioDelay(5000000);      // Wait 5 seconds
    gpioWrite(OPEN_GPIO, 0); // Set GPIO LOW
    log_event("Gate opened");
}

// Function to close the gate
void close_gate() {
    gpioWrite(CLOSE_GPIO, 1); // Set GPIO HIGH
    gpioDelay(5000000);      // Wait 5 seconds
    gpioWrite(CLOSE_GPIO, 0); // Set GPIO LOW
    log_event("Gate closed");
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

// Callback function for remote control commands
void v2_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge (command received)
        int distance = read_distance();
        if (distance > 0) {
            if (distance < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        } else {
            log_event("VL53L1X: I2C read error during distance read in callback");
        }
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("I2C initialisation failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_event("VL53L1X initialisation failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(OPEN_GPIO, PI_OUTPUT);
    gpioSetMode(CLOSE_GPIO, PI_OUTPUT);
    gpioSetMode(OPEN_GPIO, PI_OUTPUT); // Set open GPIO as output
    gpioSetMode(CLOSE_GPIO, PI_OUTPUT); // Set close GPIO as output

    // Set PWM frequency
    gpioSetPWMfrequency(OPEN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(CLOSE_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(OPEN_GPIO, 2000); // Adjust range as needed
    gpioSetPWMrange(CLOSE_GPIO, 2000); // Adjust range as needed

    // Set PWM duty cycle (0 for off, 1000 for 50%)
    gpioPWM(OPEN_GPIO, 0);
    gpioPWM(CLOSE_GPIO, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up callback for remote control commands
    gpioSetAlertFuncEx(OPEN_GPIO, v2_callback, NULL);
    gpioSetAlertFuncEx(CLOSE_GPIO, v2_callback, NULL);

    log_event("Gate control system started");

    // Main loop
    while (program_running) {
        gpioDelay(1000000); // Check every second
    }

    // Cleanup
    log_event("Cleaning up...");
    gpioWrite(OPEN_GPIO, 0);
    gpioWrite(CLOSE_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

