#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_THRESHOLD 60000 // microseconds
#define MIN_DISTANCE 100.0     // microseconds
#define MAX_DISTANCE 30000.0  // microseconds
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile unsigned int echo_tick = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_pulse_duration(unsigned int rising_tick, unsigned int falling_tick);
double calculate_distance(double pulse_duration);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger a 10 µs pulse on the TRIG pin
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 µs pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 0) { // Falling edge
        echo_tick = tick;
    }
}

// Function to calculate pulse duration in microseconds
double calculate_pulse_duration(unsigned int rising_tick, unsigned int falling_tick) {
    return falling_tick - rising_tick;
}

// Function to calculate distance in centimeters
double calculate_distance(double pulse_duration) {
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Convert microseconds to seconds
}

// Function to log distance to file and stdout
void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    // Log to file
    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written immediately
    }

    // Log to stdout
    printf("%s,%.2f\n", timestamp, distance);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt callback for ECHO pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for a short period before the next measurement
        gpioDelay(200); // 200 ms delay

        // Check for valid echo within 60 ms
        if (echo_tick > 0 && echo_tick < TIMEOUT_THRESHOLD) {
            double pulse_duration = calculate_pulse_duration(echo_tick, echo_tick);
            double distance = calculate_distance(pulse_duration);

            // Validate distance
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Warning: Invalid distance measurement: %.2f\n", distance);
            }
        } else {
            fprintf(stderr, "Warning: Timeout or no object detected.\n");
        }
    }

