int init_vl53l1x(int i2c_handle);
int read_distance(int i2c_handle);
void control_gate(int gpio_open, int gpio_close, int distance);
void log_event(const char *event_type, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize VL53L1X sensor
int init_vl53l1x(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x001D, 0x01) < 0) {
        fprintf(stderr, "Error: VL53L1X reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Example configuration (adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, 0x001E, 0x00) < 0) {
        fprintf(stderr, "Error: VL53L1X configuration failed\n");
        return -1;
    }

    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    printf("VL53L1X sensor initialized successfully\n");
    return 0;
}

// Read distance from VL53L1X sensor
int read_distance(int i2c_handle) {
    int distance = -1; // Default to error value
    int retries = 3;

    while (retries > 0) {
        distance = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance >= 0) {
            break;
        } else {
            fprintf(stderr, "Error: Failed to read distance, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (distance < 0) {
        fprintf(stderr, "Error: Failed to read distance after multiple retries\n");
        return -1;
    }

    return distance;
}

// Control the gate based on distance
void control_gate(int gpio_open, int gpio_close, int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(gpio_open, 1); // Open
        gpioWrite(gpio_close, 0);
    } else {
        gpioWrite(gpio_open, 0); // Close
        gpioWrite(gpio_close, 1);
    }
}

// Log events to file
void log_event(const char *event_type, int distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %s, Distance: %d mm\n", timestamp, event_type, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Open log file
    log_file = fopen(TAMPER_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance(i2c_handle);
        if (distance >= 0) {
            control_gate(GPIO_OPEN, GPIO_CLOSE, distance);
            log_event("Open", distance);
        } else {
            log_event("Error", -1); // Log error
        }
        gpioDelay(500000); // 500ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_OPEN, 0);
    gpioWrite(GPIO_CLOSE, 1);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated gracefully\n");
    return 0;
}

