    buf[1] = 0x01; // Value to write for reset

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to perform soft reset.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

