    char buf[2];
    buf[0] = 0x01; // Register address for start measurement
    buf[1] = 0x00; // Value to write for start measurement

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to start measurement.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
