void motor_forward(int motor_forward_pin, int motor_backward_pin) {
    gpioWrite(motor_forward_pin, 1);
    gpioWrite(motor_backward_pin, 0);
    printf("Motor: Forward\n");
}

void motor_backward(int motor_forward_pin, int motor_backward_pin) {
    gpioWrite(motor_forward_pin, 0);
    gpioWrite(motor_backward_pin, 1);
    printf("Motor: Backward\n");
}

void motor_stop(int motor_forward_pin, int motor_backward_pin) {
    gpioWrite(motor_forward_pin, 0);
    gpioWrite(motor_backward_pin, 0);
    printf("Motor: Stopped\n");
}

// Distance callback function
void distance_callback(int gpio, int level, uint32_t tick) {
    static int distance = 0;
    static int distance_read_count = 0;
    static uint32_t last_tick = 0;
    int distance_value;

    if (level == 1) { // Rising edge
        distance_value = vl53l1x_read_distance(i2c_handle, &distance);
        if (distance_value >= 0) {
            distance_read_count++;
            if (distance_read_count >= 10) { // Average over 10 readings
                distance = (distance_read_count > 0) ? distance : 1000; // Default to 1000 if no valid readings
            }
        } else {
            distance = 1000; // Set to a default value if read fails
        }
        distance_read_count = 0; // Reset counter for the next rising edge
    }
}

