    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // VL53L1X Initialization (Soft Reset)
    if (vl53l1x_soft_reset(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed (soft reset).\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // VL53L1X Configuration (Example - adjust based on datasheet)
    char buf[2];
    buf[0] = 0x00; // Register address for config
    buf[1] = 0x01; // Value to write for config

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error: Failed to write config register.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioDelay(10000); // 10ms delay

    // Start measurement
    if (vl53l1x_start_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X start measurement failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_FORWARD_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_BACKWARD_PIN, PI_OUTPUT);
    gpioSetMode(RISING_EDGE_PIN, PI_INPUT);
