    signal(SIGTERM, signal_handler);

    // Set up interrupt on rising edge
    gpioSetISRFuncEx(RISING_EDGE_PIN, RISING_EDGE, 0, distance_callback, NULL);

    int distance;
    int motor_state = 0; // 0 = stopped, 1 = forward, -1 = backward

    // Main loop
    while (program_running) {
        // Read distance
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
