            // Control motor based on distance
            if (distance < DISTANCE_THRESHOLD_LOW) {
                motor_forward(MOTOR_FORWARD_PIN, MOTOR_BACKWARD_PIN);
                motor_state = 1;
            } else if (distance > DISTANCE_THRESHOLD_HIGH) {
                motor_backward(MOTOR_FORWARD_PIN, MOTOR_BACKWARD_PIN);
                motor_state = -1;
            } else {
                motor_stop(MOTOR_FORWARD_PIN, MOTOR_BACKWARD_PIN);
                motor_state = 0;
            }

            // Log distance and motor state
            time_t rawtime;
