            time(&rawtime);
            timeinfo = localtime(&rawtime);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s - Distance: %d mm, Motor: %s\n", timestamp, distance, (motor_state == 1) ? "Forward" : (motor_state == -1) ? "Backward" : "Stopped");
        } else {
            fprintf(stderr, "Error: Failed to read distance.\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works)
    motor_stop(MOTOR_FORWARD_PIN, MOTOR_BACKWARD_PIN);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

