#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000

volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    double distance;
    time_t timestamp;
} SensorData;

// Function to handle SIGINT signal
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Ensure trigger is low initially
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); // 1ms

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5); // 5µs
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10µs
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measure_pulse_width() {
    long start_tick, end_tick, diff;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Check every 1us
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        return -1; // Timeout
    }

    end_tick = gpioTick();

    diff = end_tick - start_tick;
    if (diff < 0) {
        diff += 0xFFFFFFFF; // Handle tick rollover
    }

    return diff;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 1000000.0 to convert us to s and divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    FILE *fp = fopen("distance_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    fprintf(fp, "%s,%.2f\n", buf, distance);
    fclose(fp);
}

// Function to check if the distance is within the valid range
int is_valid_distance(double distance) {
    return (distance >= 2.0 && distance <= 400.0);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            double distance = calculate_distance(pulse_width);
            if (is_valid_distance(distance)) {
                log_distance(distance);
            } else {
                FILE *fp = fopen("distance_log.txt", "a");
                if (fp != NULL) {
                    time_t now = time(NULL);
                    struct tm *tstruct = localtime(&now);
                    char buf[80];
                    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
                    fprintf(fp, "%s,Invalid distance\n", buf);
                    fclose(fp);
                }
            }
        } else {
            FILE *fp = fopen("distance_log.txt", "a");
            if (fp != NULL) {
                time_t now = time(NULL);
                struct tm *tstruct = localtime(&now);
                char buf[80];
                strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
                fprintf(fp, "%s,Timeout\n", buf);
                fclose(fp);
            }
        }

        gpioDelay(1000); // 1 second delay
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

