#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 1.0      // cm
#define MAX_DISTANCE 4.0      // cm
#define MIN_PULSE_WIDTH 58.0  // us
#define MAX_PULSE_WIDTH 25000.0 // us
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
void trigger_sensor(int gpio);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Interrupt callback function
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;
    static int echo_valid = 0;

    if (level == 1) {
        start_tick = tick;
        echo_valid = 0; // Reset echo_valid flag
    } else if (level == 0) {
        end_tick = tick;
        echo_valid = 1; // Set echo_valid flag
    }

    if (start_tick != 0 && end_tick != 0 && echo_valid) {
        uint32_t pulse_width = end_tick - start_tick;
        if (pulse_width > 0) {
            float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2

            // Validate pulse width
            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                sensor_data_t data;
                data.distance = distance;
                data.timestamp = time(NULL);
                log_data(data);
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            }
        } else {
            fprintf(stderr, "Invalid pulse width: %u us\n", pulse_width);
        }

        start_tick = 0;
        end_tick = 0;
        echo_valid = 0; // Reset echo_valid flag
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor(int gpio) {
    gpioWrite(gpio, 1); // Set TRIG high
    gpioDelay(10);      // Wait 10 us
    gpioWrite(gpio, 0); // Set TRIG low
}

// Function to log data to a file
void log_data(sensor_data_t data) {
    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.2f\n", data.timestamp, data.distance);
        fflush(log_file); // Flush the buffer to ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up interrupt callback for ECHO pin
    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for ECHO pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor(TRIG_PIN);
        gpioDelay(50000); // Wait 50 ms
    }

    // Disable interrupt callback
    gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

