    char revision_id;

    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read model ID");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id, 1) != 1) {
        syslog(LOG_ERR, "Failed to read revision ID");
        return -1;
    }

    if (model_id != 0xEACC) {
        syslog(LOG_ERR, "Incorrect model ID: 0x%02X", model_id);
        return -1;
    }

    // Enable ranging (example, adjust based on datasheet)
