        syslog(LOG_ERR, "Failed to read distance");
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];

    // Verify status
    int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (status < 0) {
        syslog(LOG_ERR, "Failed to read status");
        return -1;
    }

    return distance;
}

