        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_data(distance, 0); // Log successful read
        } else {
            log_data(-1, -1); // Log error
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(XSHUT_PIN, 0); // Disable sensor
    gpioTerminate();
    closelog();

    return 0;
}

