#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define MOVING_AVG_SIZE 5
#define MAX_DISTANCE 400.0
#define MIN_DISTANCE 2.0

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float distance;
    int pulse_width;
    int new_pulse;
} sensor_data_t;

// Function prototypes
void trigger_sensor(int trigger_pin);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_distance(int pulse_width);
int set_servo_angle(int servo_pin, int angle);
int log_data(float distance, int angle);
void signal_handler(int signal);
int initialize_gpio();
int initialize_logging();
void cleanup();

// Function to trigger the ultrasonic sensor
void trigger_sensor(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(trigger_pin, 0);
}

// Interrupt callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static int echo_received = 0;
    int pulse_width;

    if (level == 1) {
        start_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0) {
        if (start_tick != 0) {
            pulse_width = tick - start_tick;
            if (pulse_width > 0) {
                echo_received = 1; // Set echo_received flag
            }
            start_tick = 0; // Reset start_tick
        }
    }
}

// Function to calculate distance from pulse width
float calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate error
    }
    float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // in cm
    return distance;
}

// Function to set the servo angle
int set_servo_angle(int servo_pin, int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle. Must be between 0 and 180 degrees.\n");
        return -1;
    }

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * SERVO_RANGE);
    gpioServo(servo_pin, pulse_width);
    return 0;
}

// Function to log data to CSV file
int log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
        fflush(log_file); // Flush the buffer to ensure data is written to the file
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    return 0;
}

// Function to initialize logging
int initialize_logging() {
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        return -1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Angle (degrees)\n");
    }

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioServo(SERVO_PIN, 0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging() != 0) {
        cleanup();
        return 1;
    }

    // Set up interrupt callback for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Main loop
    while (program_running) {
        // Trigger the sensor
        trigger_sensor(TRIGGER_PIN);

        // Wait for a short period
        gpioDelay(50); // 50 ms delay

        // Read sensor data
        int pulse_width = 0;
        int new_pulse = 0;
        sensor_data_t sensor_data;

        // Read pulse width from the callback
        if (gpioRead(ECHO_PIN) == 1) {
            pulse_width = gpioTick() - start_tick; // Corrected pulse_width calculation
        }

        // Calculate distance
        sensor_data.distance = calculate_distance(pulse_width);
        sensor_data.pulse_width = pulse_width;
        sensor_data.new_pulse = 1; // Set new_pulse flag

        // Set servo angle based on distance
        if (sensor_data.distance > 0 && sensor_data.distance < MAX_DISTANCE && sensor_data.distance > MIN_DISTANCE) {
            int angle = (int)(((sensor_data.distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 180.0);
            if (angle < 0) angle = 0;
            if (angle > 180) angle = 180;
            if (set_servo_angle(SERVO_PIN, angle) != 0) {
                fprintf(stderr, "Error: Failed to set servo angle.\n");
            }
        } else {
            // Log -1.0 and 90 degrees if distance is invalid
            if (sensor_data.distance < 0) {
                sensor_data.distance = -1.0;
            }
            if (set_servo_angle(SERVO_PIN, 90) != 0) {
                fprintf(stderr, "Error: Failed to set servo angle to 90 degrees.\n");
            }
        }

        // Log data
        if (log_data(sensor_data.distance, sensor_data.new_pulse) != 0) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        // Wait before next measurement
        gpioDelay(50); // 50 ms delay
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

