#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define RANGE_THRESHOLD 200 // mm

// VL53L1X Register Addresses (Example - Refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR 0x0010
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN 0x0014
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer
int distance_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (Refer to VL53L1X datasheet)
    // This is a simplified example and may need adjustments based on your specific needs.
    // Always refer to the official datasheet for the complete initialization sequence.

    // Check sensor ID
    char model_id;
    char revision_id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id, 1) < 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Set signal rate checking
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_PRE_RANGE_CONFIG_MIN_SNR, 0x04) < 0) {
        fprintf(stderr, "Error writing pre-range config min SNR\n");
        return -1;
    }

    // Configure cross-talk compensation
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN, 0x01) < 0) {
        fprintf(stderr, "Error writing final range config min count rate RTT\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x04) < 0) {
        fprintf(stderr, "Error writing system sequence config\n");
        return -1;
    }

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    // Start a new measurement
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    // Wait for measurement to be ready (polling the status register)
    int timeout_count = 0;
    while (1) {
        int status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
        if (status < 0) {
            fprintf(stderr, "Error reading range status\n");
            return -1;
        }
        if (status & 0x01) { // Bit 0 indicates measurement ready
            break;
        }
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) {
            fprintf(stderr, "Timeout waiting for measurement\n");
            return -1;
        }
    }

    // Read the distance
    char distance_data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance_data, 2) < 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    int distance = (distance_data[0] << 8) | distance_data[1];
    return distance;
}

// Control the warning LED
void control_led(int on) {
    gpioWrite(GPIO_LED, on);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            // Store distance in circular buffer
            distance_buffer[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Check if distance is below threshold
            if (distance < RANGE_THRESHOLD) {
                control_led(1); // Turn on LED
            } else {
                control_led(0); // Turn off LED
            }

            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(50); // Wait 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

