#include <stdbool.h>

// Constants
#define I2C_BUS 1
#define SI1102_ADDR_DEFAULT 0x60
#define GPIO_PIN 27
#define PROXIMITY_THRESHOLD 1000
#define LOG_FILE "proximity.log"
#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_ALS_VIS_DATA0 0x10
#define SI1102_REG_ALS_VIS_DATA1 0x11
#define SI1102_REG_PS1_DATA0 0x18
#define SI1102_REG_PS1_DATA1 0x19
#define SI1102_REG_COMMAND 0x30
#define SI1102_REG_HW_KEY 0x07
#define SI1102_REG_MEAS_RATE0 0x08
#define SI1102_REG_MEAS_RATE1 0x09
#define SI1102_REG_ALS_RATE 0x0A
#define SI1102_REG_PS_RATE 0x0B
#define SI1102_REG_PS_LED21_SELECT 0x13
#define SI1102_REG_PS_ADC_GAIN 0x1E
#define SI1102_REG_PS_LED_DUTY 0x1F
#define SI1102_REG_PS_MEAS_CONFIG 0x01
#define SI1102_REG_ALS_MEAS_CONFIG 0x02

// Global variables
int i2c_handle;
int i2c_address = SI1102_ADDR_DEFAULT;
bool running = true;

// Function prototypes
int initialize_i2c(int bus, int address);
int initialize_sensor(int i2c_handle);
int configure_sensor(int i2c_handle);
int read_proximity(int i2c_handle);
void log_data(int proximity, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c(int bus, int address) {
    int handle = i2cOpen(bus, address, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1102_REG_COMMAND, 0x00) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1102_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Error writing HW_KEY\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_MEAS_RATE0, 0x01) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE0\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error writing MEAS_RATE1\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_ALS_RATE, 0x01) < 0) {
        fprintf(stderr, "Error writing ALS_RATE\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_PS_RATE, 0x01) < 0) {
        fprintf(stderr, "Error writing PS_RATE\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_PS_LED21_SELECT, 0x03) < 0) {
        fprintf(stderr, "Error writing PS_LED21_SELECT\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_PS_ADC_GAIN, 0x03) < 0) {
        fprintf(stderr, "Error writing PS_ADC_GAIN\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_PS_LED_DUTY, 0x7F) < 0) {
        fprintf(stderr, "Error writing PS_LED_DUTY\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_PS_MEAS_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error writing PS_MEAS_CONFIG\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1102_REG_ALS_MEAS_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Error writing ALS_MEAS_CONFIG\n");
        return -1;
    }

    return 0;
}

// Function to configure the sensor
int configure_sensor(int i2c_handle) {
    // Enable proximity sensor
    if (i2cWriteByteData(i2c_handle, SI1102_REG_COMMAND, 0x02) < 0) {
        fprintf(stderr, "Error enabling proximity sensor\n");
        return -1;
    }

    return 0;
}

// Function to read proximity data
int read_proximity(int i2c_handle) {
    int proximity_low, proximity_high;

    proximity_low = i2cReadByteData(i2c_handle, SI1102_REG_PS1_DATA0);
    if (proximity_low < 0) {
        fprintf(stderr, "Error reading proximity low byte\n");
        return -1;
    }

    proximity_high = i2cReadByteData(i2c_handle, SI1102_REG_PS1_DATA1);
    if (proximity_high < 0) {
        fprintf(stderr, "Error reading proximity high byte\n");
        return -1;
    }

    return (proximity_high << 8) | proximity_low;
}

// Function to log data to file
void log_data(int proximity, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %d, %s\n", timestamp, proximity, status);
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused

    int proximity = read_proximity(i2c_handle);
    if (proximity >= 0) {
        log_data(proximity, "SAFE");
    } else {
        log_data(0, "ALERT");
    }
}

// Signal handler function
void signal_handler(int signal) {
    (void)signal; // unused
    running = false;
    printf("Caught signal, exiting...\n");
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                break;
            case 't':
                PROXIMITY_THRESHOLD = strtol(optarg, NULL, 10);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, i2c_address);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for interrupt
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Threshold: %d, I2C Address: 0x%02X\n", PROXIMITY_THRESHOLD, i2c_address);

    // Main loop
    while (running) {
        sleep(1);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

