    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    int start_tick = gpioTick();
    int end_tick = start_tick;
    int timeout_count = 0;

    // Wait for echo to go high
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < 10000) {
        timeout_count++;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout_count >= 10000) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < 10000) {
