#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define GPIO pin for chip select
#define CS_PIN 8

// Define distance range
#define MIN_DISTANCE 200
#define MAX_DISTANCE 5000

// Define log file name
#define LOG_FILE "distance_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_distance(int *distance);
int validate_distance(int distance);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    char tx_buf[2] = {0x00, 0x00}; // Example: Send dummy data for reading
    char rx_buf[2];

    gpioWrite(CS_PIN, 0); // Assert chip select
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    gpioWrite(CS_PIN, 1); // Deassert chip select

    if (result != 2) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Convert received data to distance (example conversion)
    *distance = (rx_buf[0] << 8) | rx_buf[1]; // Example: Combine two bytes

    // Validate distance
    if (!validate_distance(*distance)) {
        fprintf(stderr, "Invalid distance reading: %d\n", *distance);
        return -1;
    }

    return 0;
}

// Validate distance reading
int validate_distance(int distance) {
    return (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE);
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    struct tm *timeinfo;
    char timestamp[20];

    timeinfo = localtime(&data.timestamp);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, data.distance);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deassert chip select initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (mm)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int distance;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Get current timestamp
            time(&sensor_data.timestamp);

            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Delay
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

