int write_register(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
uint16_t read_proximity(int fd);
void log_data(FILE *fp, uint16_t als_visible, uint16_t proximity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t als_visible;
    uint16_t proximity;
} sensor_data_t;

// Initialize I2C
int init_i2c(int bus, int addr) {
    int fd = i2cOpen(bus, addr, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", fd);
        return -1;
    }
    return fd;
}

// Read a register
int read_register(int fd, uint8_t reg) {
    int value = i2cReadByteData(fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Write a register
int write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read ALS Visible data
uint16_t read_als_visible(int fd) {
    int data0 = read_register(fd, ALS_VIS_DATA0);
    int data1 = read_register(fd, ALS_VIS_DATA1);

    if (data0 < 0 || data1 < 0) {
        return 0; // Return 0 on error
    }

    return (uint16_t)((data1 << 8) | data0);
}

// Read Proximity data
uint16_t read_proximity(int fd) {
    int data0 = read_register(fd, PROX_DATA0);
    int data1 = read_register(fd, PROX_DATA1);
    int data2 = read_register(fd, PROX_DATA2);
    int data3 = read_register(fd, PROX_DATA3);

    if (data0 < 0 || data1 < 0 || data2 < 0 || data3 < 0) {
        return 0; // Return 0 on error
    }

    return (uint16_t)((data3 << 16) | (data2 << 8) | data1);
}

