#define SI1120_ADDR 0x60

// Si1120 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24
#define REG_RESET 0x01

// Reset value
#define RESET_VALUE 0x01

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to initialize the Si1120 sensor
int init_si1120()
{
    int result;
    int retries = 3;

    // Reset the sensor
    while (retries > 0)
    {
        result = i2cWriteByteData(i2c_handle, REG_RESET, RESET_VALUE);
        if (result >= 0)
        {
            break;
        }
        else
        {
            fprintf(stderr, "Error resetting Si1120: %d. Retrying...\n", result);
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    if (retries == 0)
    {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }

    gpioDelay(10000); // Wait for reset to complete

    // Verify part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0)
    {
        fprintf(stderr, "Error reading part ID: %d\n", part_id);
        return -1;
    }

    if (part_id != 0x20) // Expected part ID for Si1120
    {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }

    return 0;
}

// Function to read ALS and proximity data
int read_als_prox(uint16_t *als, uint16_t *prox)
{
    int result;
    int retries = 3;

    while (retries > 0)
    {
        // Read ALS data
        int als_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
        if (als_low < 0)
        {
            fprintf(stderr, "Error reading ALS data (low byte): %d. Retrying...\n", als_low);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        int als_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
        if (als_high < 0)
        {
            fprintf(stderr, "Error reading ALS data (high byte): %d. Retrying...\n", als_high);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Read proximity data
        int prox_low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
        if (prox_low < 0)
        {
            fprintf(stderr, "Error reading proximity data (low byte): %d. Retrying...\n", prox_low);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        int prox_high = i2cReadByteData(i2c_handle, REG_PS1_DATA0 + 1);
        if (prox_high < 0)
        {
            fprintf(stderr, "Error reading proximity data (high byte): %d. Retrying...\n", prox_high);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Combine bytes into 16-bit values
        *als = (uint16_t)((als_high << 8) | als_low);
        *prox = (uint16_t)((prox_high << 8) | prox_low);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read ALS and proximity data after multiple retries.\n");
    return -1; // Failure
}

