#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define MEASUREMENT_RATE_REG 0x08
#define PART_ID_REG 0x00
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;

// Function prototypes
int init_i2c();
int read_register(int reg, unsigned char *data, int len);
int write_register(int reg, unsigned char *data, int len);
int read_part_id();
int configure_sensor();
int read_sensor_data(int *lux, int *proximity);
void log_data(int lux, int proximity);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    int measurement_rate;
    int part_id;
} sensor_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read data from a register
int read_register(int reg, unsigned char *data, int len) {
    int result = i2cReadI2CBlockData(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write data to a register
int write_register(int reg, unsigned char *data, int len) {
    int result = i2cWriteI2CBlockData(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the part ID register
int read_part_id() {
    unsigned char data[2];
    if (read_register(PART_ID_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read part ID.\n");
        return -1;
    }
    return (data[1] << 8) | data[0];
}

// Function to configure the sensor
int configure_sensor() {
    unsigned char config_data[2];
    config_data[0] = 0x07; // Example configuration value
    config_data[1] = 0x00; // Example configuration value

    if (write_register(MEASUREMENT_RATE_REG, config_data, 2) != 0) {
        fprintf(stderr, "Failed to configure sensor.\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *lux, int *proximity) {
    unsigned char data[4];
    if (read_register(0x24, data, 4) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    *lux = (data[1] << 8) | data[0];
    *proximity = (data[3] << 8) | data[2];

    return 0;
}

// Function to log data to a file
void log_data(int lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_fp, "%s,%d,%d\n", timestamp, lux, proximity);
    fflush(log_fp); // Ensure data is written to disk immediately
    printf("%s,%d,%d\n", timestamp, lux, proximity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read part ID
    int part_id = read_part_id();
    if (part_id == -1) {
        fprintf(stderr, "Failed to read part ID, exiting.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("Part ID: 0x%04X\n", part_id);

    // Configure sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Failed to configure sensor, exiting.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    int lux, proximity;
    while (1) {
        if (read_sensor_data(&lux, &proximity) == 0) {
            log_data(lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_fd);
    fclose(log_fp);
    gpioTerminate();
    return 0;
}

