        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read data from a register
int read_register(int reg, unsigned char *data, int len) {
    int result = i2cReadI2CBlockData(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to write data to a register
int write_register(int reg, unsigned char *data, int len) {
    int result = i2cWriteI2CBlockData(i2c_fd, reg, (char *)data, len);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the part ID register
int read_part_id() {
    unsigned char data[2];
    if (read_register(PART_ID_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read part ID.\n");
        return -1;
    }
    return (data[1] << 8) | data[0];
}

// Function to configure the sensor
int configure_sensor() {
    unsigned char config_data[2];
    config_data[0] = 0x07; // Example configuration value
    config_data[1] = 0x00; // Example configuration value

    if (write_register(MEASUREMENT_RATE_REG, config_data, 2) != 0) {
        fprintf(stderr, "Failed to configure sensor.\n");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int *lux, int *proximity) {
    unsigned char data[4];
    if (read_register(0x24, data, 4) != 0) {
        fprintf(stderr, "Failed to read sensor data.\n");
        return -1;
    }

    *lux = (data[1] << 8) | data[0];
    *proximity = (data[3] << 8) | data[2];

    return 0;
}

// Function to log data to a file
void log_data(int lux, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_fp, "%s,%d,%d\n", timestamp, lux, proximity);
    fflush(log_fp); // Ensure data is written to disk immediately
    printf("%s,%d,%d\n", timestamp, lux, proximity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read part ID
    int part_id = read_part_id();
    if (part_id == -1) {
        fprintf(stderr, "Failed to read part ID, exiting.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("Part ID: 0x%04X\n", part_id);

