#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_THRESHOLD 20.0 // cm
#define BUZZER_DURATION 1000000 // µs (1 ms)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
void buzzer_control(int state);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 µs trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_valid = 0; // Reset valid flag
    } else if (level == 0) {
        echo_end_tick = tick;
        echo_valid = 1; // Set valid flag
    }
}

// Function to control the buzzer
void buzzer_control(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    buzzer_control(0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    running = 0;
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register interrupt handler for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor and buzzer control program running...\n");

    // Main loop
    while (running) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for a short period
        gpioDelay(50000); // 50 ms

        // Check if echo was valid
        if (echo_valid) {
            // Calculate pulse width
            int pulse_width = echo_end_tick - echo_start_tick;

            // Calculate distance
            float distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // in cm

            // Print distance
            printf("Distance: %.2f cm\n", distance);

            // Control buzzer
            if (distance < DISTANCE_THRESHOLD) {
                buzzer_control(1); // Turn on buzzer
                gpioDelay(BUZZER_DURATION);
                buzzer_control(0); // Turn off buzzer
            }
        } else {
            printf("Invalid echo signal\n");
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    buzzer_control(0);
    gpioTerminate();
    return 0;
}

