}

// Initializes the VL53L1X sensor
int init_vl53l1x() {
    // Check model ID
    int model_id = i2cReadWordData(i2c_handle, VL53L1X_REG_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Incorrect model ID: 0x%04X\n", model_id);
        return -1;
    }

    // Set timing budget
    int timing_budget = 80; // Example value, adjust as needed
    if (i2cWriteWordData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, timing_budget) < 0) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_MODE, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

