    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            // Calculate servo angle based on distance
            int servo_angle = 0;
            if (distance > 250) {
                servo_angle = 1500; // Open gate
            } else if (distance < 200) {
                servo_angle = 500; // Close gate
            } else {
                // Smooth transition
                int angle_diff = 500 - servo_angle;
                servo_angle += angle_diff * (250 - distance) / 500; // Map distance to angle
                if (servo_angle < 500) servo_angle = 500;
                if (servo_angle > 1500) servo_angle = 1500;
            }

            set_servo_angle(servo_angle);
            log_event("Gate opened/closed");
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // Delay 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

