#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000        // 50ms timeout
#define SERVO_MIN_US 500         // 0°
#define SERVO_MAX_US 2500        // 180°
#define MIN_DISTANCE 2.0        // cm
#define MAX_DISTANCE 400.0      // cm

// Global variables
volatile int pulse_start = 0;
volatile int pulse_end = 0;
volatile int valid_pulse = 0;

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
float calculateDistance(uint32_t pulse_width);
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    setServoAngle(0); // Stop the servo
    gpioTerminate();   // Terminate pigpio
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
        valid_pulse = 0; // Reset valid_pulse flag
    } else if (level == 0) {
        pulse_end = tick;
        valid_pulse = 1; // Set valid_pulse flag
    }
}

// Function to calculate distance from pulse width
float calculateDistance(uint32_t pulse_width) {
    if (!valid_pulse) {
        return -1.0; // Indicate timeout
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return 0; // 0°
    } else if (distance > MAX_DISTANCE) {
        return 180; // 180°
    } else {
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * (SERVO_MAX_US - SERVO_MIN_US) + SERVO_MIN_US);
    }
}

// Function to set servo angle
void setServoAngle(int angle) {
    gpioServo(SERVO_PIN, angle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Main loop
    while (1) {
        triggerSensor();

        if (pulse_start > 0 && pulse_end > pulse_start) {
            uint32_t pulse_width = pulse_end - pulse_start;
            float distance = calculateDistance(pulse_width);

            int angle = mapDistanceToAngle(distance);

            printf("Distance: %.2f cm, Angle: %d\n", distance, angle);

            setServoAngle(angle);
        } else {
            printf("Timeout or invalid pulse\n");
        }

        gpioDelay(100); // 100ms delay
    }

    return 0;
}

