    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configures the Si7005 sensor
int configure_sensor() {
    // Set to measure temperature and humidity, 1 Hz
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Reads temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[4];

    // Read temperature
    if (i2cWriteByte(i2c_handle, TEMP_REG) < 0) {
        fprintf(stderr, "Failed to write to TEMP register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    int raw_temp = (buffer[0] << 8) | buffer[1];
    data->temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Read humidity
    if (i2cWriteByte(i2c_handle, HUMID_REG) < 0) {
        fprintf(stderr, "Failed to write to HUMID register\n");
        return -1;
    }
    if (i2cReadDevice(i2c_handle, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }
    int raw_humidity = (buffer[0] << 8) | buffer[1];
    data->humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Logs the temperature and humidity data to the console
void log_data(sensor_data_t data) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() < 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }
        sleep(2);
    }

    // Close I2C and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

