#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43
#define WHO_AM_I     0x75

// I2C handle
int i2c_handle;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a 14-byte data block from the MPU-6050
int read_mpu6050_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z, int16_t *temperature)
{
    char buffer[14];
    int result = i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buffer, 14);

    if (result < 0) {
        fprintf(stderr, "Error reading 14 bytes from MPU-6050: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for accelerometer and gyroscope values
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x  = (int16_t)((buffer[6] << 8) | buffer[7]);
    *gyro_y  = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_z  = (int16_t)((buffer[10] << 8) | buffer[11]);
    *temperature = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

