{
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i < 0) {
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x41\n", who_am_i);
