    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (verify_who_am_i(i2c_handle) != 0) {
        fprintf(stderr, "MPU-6050 not found. Verify sensor is connected and enabled.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU-6050
    if (write_register(i2c_handle, PWR_MGMT_1, 0x00) != 0) {
        fprintf(stderr, "Error waking up MPU-6050\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, temperature;
    while (1) {
        if (read_mpu6050_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z, &temperature) == 0) {
            printf("Accel: %d, %d, %d, Gyro: %d, %d, %d, Temp: %d\n",
                   accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, temperature);
        } else {
            fprintf(stderr, "Error reading MPU-6050 data\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // The following lines will never be reached in normal execution
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

