        return -1;
    }
    unsigned int raw_ambient = (buf[1] << 8) | buf[0];
    *ambient_temp = (float)raw_ambient * 0.02 - 273.15;

    // Read object temperature
    result = i2cReadI2CBlockData(i2c_handle, OBJECT_TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading object temperature: %d\n", result);
        return -1;
    }
    unsigned int raw_object = (buf[1] << 8) | buf[0];
    *object_temp = (float)raw_object * 0.02 - 273.15;

    return 0;
}

// Function to log temperature data to a file
int log_temperature(float ambient_temp, float object_temp) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fclose(log_file);

    return 0;
}

int main() {
    float ambient_temp, object_temp;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_temperature(i2c_handle, &ambient_temp, &object_temp) == 0) {
            if (log_temperature(ambient_temp, object_temp) != 0) {
