#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// GPIO pins for SDA and SCL
#define SDA_PIN 2
#define SCL_PIN 3

// CRC-8-Maxim polynomial
#define CRC8_POLY 0x31

// Measurement command (high repeatability)
#define MEASURE_HIGH_REPEATABILITY 0xFD

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_fd, float *temperature, float *humidity) {
    uint8_t cmd[1] = {MEASURE_HIGH_REPEATABILITY};
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_fd, cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 10ms)
    gpioDelay(10000); // 10ms

    // Read 6 bytes of data
    if (i2cReadDevice(i2c_fd, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data to temperature and humidity
    uint16_t temperature_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    *temperature = -45.0 + 175.0 * (float)temperature_raw / 65535.0;
    *humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to file
void log_data(FILE *log_file, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sht40_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sht40(i2c_fd, &temperature, &humidity) == 0) {
            log_data(log_file, temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

