int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t buf[2];
    int result;
    int retries = 0;

    // Read temperature
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            // Success
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            data->temperature = (175.72 * raw_temp / 65536.0) - 46.85;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (temperature), retry %d: %s\n", retries + 1, strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    // If all retries failed, return error
    fprintf(stderr, "Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

    // Read humidity
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, (char *)buf, 2);
        if (result == 2) {
            // Success
            uint16_t raw_humidity = (buf[0] << 8) | buf[1];
            data->humidity = (125.0 * raw_humidity / 65536.0) - 6;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (humidity), retry %d: %s\n", retries + 1, strerror(errno));
            gpioDelay(1000); // Wait 1ms before retrying
            retries++;
        }
    }

    // If all retries failed, return error
    fprintf(stderr, "Failed to read humidity after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

