        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

