#include <sys/ioctl.h>
#include <fcntl.h>

// Define the I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDRESS 0x25

// Define the continuous measurement command
#define SDP800_TRIGGER_COMMAND_MSB 0x36
#define SDP800_TRIGGER_COMMAND_LSB 0x15

// Define the data file
#define DATA_FILE "airflow_data.txt"

// Define the log file
#define LOG_FILE "airflow_data.log"

// Define the number of bytes to read (pressure, temperature, scale factor)
#define NUM_BYTES 9

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize the I2C bus
int i2c_init(int i2c_bus) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_I2C_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to send the continuous measurement command
int sdp800_trigger_command(int i2c_fd) {
    uint8_t command[2] = {SDP800_TRIGGER_COMMAND_MSB, SDP800_TRIGGER_COMMAND_LSB};
    if (write(i2c_fd, command, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int sdp800_read_data(int i2c_fd, uint8_t *data) {
    if (read(i2c_fd, data, NUM_BYTES) != NUM_BYTES) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// Function to validate the CRC-8 checksum
int validate_crc(uint8_t data[], int nbrOfBytes) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return (crc == 0);
}

// Function to convert raw pressure data to Pascals
float convert_pressure(uint8_t *raw_data) {
    int16_t raw_pressure = (raw_data[0] << 8) | raw_data[1];
    return (float)raw_pressure / 240.0;
}

// Function to convert raw temperature data to degrees Celsius
float convert_temperature(uint8_t *raw_data) {
    int16_t raw_temperature = (raw_data[3] << 8) | raw_data[4];
    return (float)raw_temperature / 200.0;
}

// Function to convert raw scale factor data to 1/4000
float convert_scale_factor(uint8_t *raw_data) {
    int16_t raw_scale_factor = (raw_data[6] << 8) | raw_data[7];
    return (float)raw_scale_factor / 4000.0;
}

// Function to log data to a file
int log_data(float pressure, float temperature, float scale_factor) {
    FILE *fp = fopen(DATA_FILE, "a");
    if (fp == NULL) {
        perror("Error opening data file");
        return -1;
    }

    // Write header row if the file is new
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Pressure (Pa),Temperature (C),Scale Factor\n");
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, pressure, temperature, scale_factor);
    fclose(fp);
    return 0;
}

int main() {
    int i2c_fd;
    uint8_t raw_data[NUM_BYTES];
    sensor_data_t sensor_data;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = i2c_init(1); // I2C bus 1
    if (i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    // Send the continuous measurement command
    if (sdp800_trigger_command(i2c_fd) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Wait for approximately 45ms
    usleep(50000); // 50ms

    // Read data from the sensor
    if (sdp800_read_data(i2c_fd, raw_data) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Validate CRC checksums
    if (!validate_crc(raw_data, 2) || !validate_crc(raw_data + 2, 2) || !validate_crc(raw_data + 4, 2)) {
        fprintf(stderr, "CRC validation failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Convert raw data to physical units
    sensor_data.pressure = convert_pressure(raw_data);
    sensor_data.temperature = convert_temperature(raw_data);
    sensor_data.scale_factor = convert_scale_factor(raw_data);

    // Log the data
    if (log_data(sensor_data.pressure, sensor_data.temperature, sensor_data.scale_factor) < 0) {
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    // Close the I2C bus
    close(i2c_fd);

    printf("Data logged successfully.\n");

    return EXIT_SUCCESS;
}

