        log_error("Failed to open I2C device");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to send the measurement command
int send_measurement_command() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        log_error("Failed to read sensor data");
        return -1;
    }
    return 0;
}

// Function to validate CRC checksum
int validate_crc(uint8_t *data, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }
    return (crc_calculated == crc);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + (175.0 * (float)raw_temp / 65535.0);
}

// Function to log temperature data
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to log errors
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    fprintf(error_file, "%s,%s\n", timestamp, message);
    fflush(error_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("enclosure_temp_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_file = fopen("error_log.txt", "a");
    if (error_file == NULL) {
        perror("Failed to open error log file");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[3];
    uint16_t raw_temp;
    float temperature;
    int retry;

    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (send_measurement_command() == 0) {
                gpioDelay(15); // Wait for conversion
                if (read_sensor_data(data) == 0) {
                    if (validate_crc(data, data[2]) == 0) {
                        raw_temp = (data[0] << 8) | data[1];
                        temperature = convert_temperature(raw_temp);
                        log_temperature(temperature);
                        break; // Exit retry loop on success
                    } else {
                        log_error("CRC validation failed");
                    }
                } else {
                    log_error("Failed to read sensor data (retry)");
                }
            } else {
                log_error("Failed to send measurement command (retry)");
            }
            retry++;
            gpioDelay(RETRY_DELAY_MS);
        }

        if (retry == RETRY_COUNT) {
            log_error("Failed to read sensor data after multiple retries");
        }

        gpioDelay(5000); // Sample every 5 seconds
    }

    // Close resources before exiting
    fclose(log_file);
    fclose(error_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

