#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure for sensor readings
typedef struct {
    time_t timestamp;
    float temperature;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_sensor(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(float temperature);
void print_buffer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the sensor
int read_sensor(float *temperature, float *humidity) {
    unsigned char cmd[1] = {0xE3}; // Measure temperature command
    unsigned char data[2];
    int result, i;

    for (i = 0; i < RETRY_COUNT; i++) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) == 0) {
            gpioDelay(25); // Wait for measurement (datasheet specifies 25ms)
            if (i2cReadDevice(i2c_handle, data, 2) == 2) {
                unsigned int raw_temperature = (data[0] << 8) | data[1];
                *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading temperature data: %d\n", i2c_handle);
            }
        } else {
            fprintf(stderr, "Error writing temperature command: %d\n", i2c_handle);
        }
        gpioDelay(10); // Small delay before retry
    }

    if (i == RETRY_COUNT) {
        fprintf(stderr, "Failed to read sensor after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Retry humidity reading
    for (i = 0; i < RETRY_COUNT; i++) {
        unsigned char cmd_humidity[1] = {0xE5}; // Measure humidity command
        if (i2cWriteDevice(i2c_handle, cmd_humidity, 1) == 0) {
