#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_READ_MEASUREMENT 0xec05

// CRC-8-ATM polynomial
#define POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_device(int bus, int addr);
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
int verify_crc(uint8_t data[], int data_len, uint8_t crc);
sensor_data_t process_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
int stop_periodic_measurement(int handle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Send command to SCD40
int send_command(int handle, uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], int data_len, uint8_t crc) {
    uint8_t polynomial = POLYNOMIAL;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Process raw data and extract CO2, temperature, and humidity
sensor_data_t process_data(uint8_t *data) {
    sensor_data_t sensor_data;
    sensor_data.co2 = (data[0] << 8) | data[1];
    sensor_data.temperature = (data[3] << 8) | data[4];
    sensor_data.humidity = (data[6] << 8) | data[7];
    return sensor_data;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);
    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement(int handle) {
    uint8_t stop_measurement_cmd[2] = {CMD_STOP_PERIODIC_MEASUREMENT >> 8, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(handle, (char *)stop_measurement_cmd, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send stop periodic measurement command: %d\n", result);
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    i2c_handle = open_i2c_device(1, SCD40_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for measurement to be ready
    uint8_t data_ready[2];
    int data_ready_flag = 0;
    int retry_count = 0;
    int max_retries = 10;
    int delay_ms = 10;

    while (!data_ready_flag && retry_count < max_retries) {
        if (read_data(i2c_handle, data_ready, 2) == 0) {
            if (verify_crc(data_ready, 2, 0xFF) == 0) {
                data_ready_flag = 1;
            }
        } else {
            fprintf(stderr, "Failed to read data ready flag, retrying...\n");
            gpioDelay(delay_ms * 1000); // Delay in microseconds
            delay_ms *= 2; // Exponential backoff
            retry_count++;
        }
    }

    if (!data_ready_flag) {
        fprintf(stderr, "Timeout waiting for data ready flag\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read and process data
    uint8_t data[9];
    if (read_data(i2c_handle, data, 9) != 0) {
        fprintf(stderr, "Failed to read measurement data\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data = process_data(data);

    // Log data
    log_data(sensor_data);

    // Stop periodic measurement
    if (stop_periodic_measurement(i2c_handle) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close resources
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

