// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

