int init_sensor() {
    // Send command to start periodic measurement (0x2190)
    char cmd[2] = {0x21, 0x90};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send start measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Read data from the SCD40 sensor
int read_sensor_data(sensor_data_t *data) {
    char cmd[2] = {0xE4, 0xB8}; // Command to read measurement
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send read measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

