    uint8_t crc_co2 = buffer[0];
    uint8_t crc_temp = buffer[2];
    uint8_t crc_humidity = buffer[4];

    if (calculate_crc8(buffer, 2) != crc_co2) {
        fprintf(stderr, "CO2 CRC check failed\n");
        return -1;
    }
    if (calculate_crc8(buffer + 3, 2) != crc_temp) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }
    if (calculate_crc8(buffer + 5, 2) != crc_humidity) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    data->co2 = (uint16_t)(buffer[0] << 8 | buffer[1]);
    data->temperature = -45 + 175 * ((float)((uint16_t)(buffer[3] << 8 | buffer[4])) / 65535.0);
    data->humidity = 100 * ((float)((uint16_t)(buffer[5] << 8 | buffer[6])) / 65535.0);

    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, sensor_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Print the contents of the circular buffer
void print_buffer(const circular_buffer_t *buffer) {
    printf("\n--- CO2 Sensor Readings ---\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("Entry %d: CO2=%d ppm, Temp=%.2f C, Humidity=%.2f %%\n",
               i + 1, buffer->data[index].co2, buffer->data[index].temperature, buffer->data[index].humidity);
