#include <unistd.h>

// Define GPIO pin for the sensor
#define SENSOR_PIN 4

// Define the log file name
#define LOG_FILE "temperature_log.txt"

// Define the timeout in microseconds
#define TIMEOUT_US 50000 // 50ms

// Define the valid temperature range
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0

// Global variables
static volatile unsigned long last_tick = 0;
static volatile int consecutive_failures = 0;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;

// Function prototypes
double calculate_temperature(unsigned long high_time, unsigned long low_time);
void log_temperature(double temperature);
void signal_handler(int signal);
int initialize_gpio();
void cleanup();

// Structure to hold timestamp data
typedef struct {
    long tv_sec;
    long tv_nsec;
} timestamp_t;

// Function to get current timestamp in ISO 8601 format
timestamp_t get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    timestamp_t timestamp;
    timestamp.tv_sec = ts.tv_sec;
    timestamp.tv_nsec = ts.tv_nsec;
    return timestamp;
}

// Function to calculate temperature in Celsius
double calculate_temperature(unsigned long high_time, unsigned long low_time) {
    if (low_time == 0) {
        fprintf(stderr, "Error: Division by zero in temperature calculation.\n");
        return -1000.0; // Indicate an error with a very low temperature
    }

    double temperature = (double)(high_time - low_time) / 1000.0; // Convert microseconds to seconds
    return temperature;
}

// Function to log temperature data to a file
void log_temperature(double temperature) {
    timestamp_t timestamp = get_timestamp();
    char timestamp_str[30];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%S%z", localtime(&timestamp.tv_sec));

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp_str, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    return 0;
}

// Function to perform cleanup operations
void cleanup() {
    if (pigpio_initialized) {
        gpioTerminate();
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        unsigned long high_time = 0, low_time = 0;
        int consecutive_failure = 0;

        // Wait for a rising edge
        while (gpioRead(SENSOR_PIN) == 0 && consecutive_failure < 3) {
            consecutive_failure++;
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (consecutive_failure >= 3) {
            fprintf(stderr, "Error: Timeout waiting for rising edge.\n");
            log_temperature(-999.0); // Log an error value
            consecutive_failure = 0; // Reset the counter to avoid further errors
            continue; // Skip to the next iteration
        }

        // Measure the high time
        while (gpioRead(SENSOR_PIN) == 1 && consecutive_failure < 3) {
            consecutive_failure++;
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (consecutive_failure >= 3) {
            fprintf(stderr, "Error: Timeout waiting for falling edge.\n");
            log_temperature(-999.0); // Log an error value
            consecutive_failure = 0; // Reset the counter to avoid further errors
            continue; // Skip to the next iteration
        }

        unsigned long high_time_us = gpioTick();
        while (gpioRead(SENSOR_PIN) == 0 && consecutive_failure < 3) {
            consecutive_failure++;
            gpioDelay(1); // Small delay to prevent busy-waiting
        }

        if (consecutive_failure >= 3) {
            fprintf(stderr, "Error: Timeout waiting for rising edge.\n");
            log_temperature(-999.0); // Log an error value
            consecutive_failure = 0; // Reset the counter to avoid further errors
            continue; // Skip to the next iteration
        }

        unsigned long low_time_us = gpioTick();

        // Calculate the temperature
        double temperature = calculate_temperature(high_time_us, low_time_us);

        if (temperature > -990.0) { // Check for valid temperature
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Error: Invalid temperature reading.\n");
            log_temperature(-999.0); // Log an error value
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    return 0;
}

