#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP810 I2C address
#define SDP810_ADDR 0x25

// I2C bus
#define I2C_BUS 1

// Measurement command (continuous mode, no averaging)
#define MEASURE_CMD 0x362F

// CRC-8-H2F polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t scale_factor;
    uint8_t crc;
} sensor_data_t;

// CRC-8-H2F calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    char buf[9];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 9);

    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", bytes_read);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    // Extract data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = buf[6];
    data->crc = buf[8];

    return 0;
}

