    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xe8, 0x99, 0xc8, 0xfb, 0xac, 0xfd, 0x8c, 0x9d
};

// Function prototypes
int read_sensor_data(int i2c_handle, uint8_t *data);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int log_data(FILE *log_file, float temperature, float humidity);
void signal_handler(int signal);
int reset_sensor(int i2c_handle);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Reset sensor
int reset_sensor(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0, 0x30) != 0) {
        fprintf(stderr, "Error resetting sensor: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete
    return 0;
}

// Read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result;
    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 3);
        if (result == 3) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d/%d): %d\n", i + 1, RETRY_COUNT, result);
            gpioDelay(RETRY_DELAY_MS);
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temp) {
    return ((175.72 * raw_temp) / 65536.0) - 46.85;
}

// Convert raw humidity to percentage
float convert_humidity(uint16_t raw_humidity) {
    return ((125.0 * raw_humidity) / 65536.0) - 6.0;
}

// Log data to CSV file
int log_data(FILE *log_file, float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Reset sensor
    if (reset_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Failed to reset sensor. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "timestamp,temperature_C,humidity_percent\n");
    fflush(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[3];
        if (read_sensor_data(i2c_handle, data) == 0) {
            uint16_t raw_temp = (data[0] << 8) | data[1];
            uint16_t raw_humidity = (data[2] << 8) | data[0];

            float temperature = convert_temperature(raw_temp);
            float humidity = convert_humidity(raw_humidity);

            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

