// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "environment.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8-Maxim polynomial
const uint8_t crc_table[] = {
    0x00, 0x31, 0x62, 0x53, 0xc4, 0xf5, 0xa6, 0x97, 0xe8, 0x99, 0xc8, 0xfb, 0xac, 0xfd, 0x8c, 0x9d,
