#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD_MSB 0x36
#define MEASURE_CMD_LSB 0x15
#define CONVERSION_TIME_MS 45
#define LOG_FILE "pressure_log.txt"
#define SLEEP_SECONDS 5

// CRC-8-H2F Polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t dp;
    int16_t temp;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP800 sensor
int read_sdp800(int i2c_handle, sensor_data_t *data) {
    char buf[9];
    int bytes_read;

    // Send measurement command
    if (i2cWriteByteData(i2c_handle, MEASURE_CMD_MSB, MEASURE_CMD_LSB) != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for conversion
    gpioDelay(CONVERSION_TIME_MS * 1000); // pigpioDelay takes microseconds

    // Read 9 bytes from the sensor
    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 9); // Read from any register, starting at address 0x00
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %s (read %d bytes)\n", strerror(errno), bytes_read);
        return -1;
    }

    // Validate CRC for differential pressure
    uint8_t crc_dp = crc8(buf, 2);
    if (crc_dp != buf[2]) {
        fprintf(stderr, "CRC error for differential pressure\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t crc_temp = crc8(buf + 3, 2);
    if (crc_temp != buf[5]) {
        fprintf(stderr, "CRC error for temperature\n");
        return -1;
    }

    // Populate sensor data
    data->dp = (int16_t)((buf[0] << 8) | buf[1]);
    data->temp = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

// Function to log data to a file
int log_data(FILE *log_file, sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to log file
    fprintf(log_file, "%s, Differential Pressure: %d Pa, Temperature: %d °C\n", timestamp, data.dp, data.temp);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp800(i2c_handle, &sensor_data) == 0) {
            // Log data
            log_data(log_file, sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_SECONDS * 1000000); // pigpioDelay takes microseconds
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

