#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/time.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5D, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Configure CTRL_REG1 (ODR = 100 Hz, enable BDU)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x84) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read pressure and temperature data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[5];
    int16_t press_raw, temp_raw;

    // Read pressure data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Failed to read pressure data\n");
        return -1;
    }
    press_raw = (int16_t)((buffer[2] << 8) | buffer[1]);

    // Read temperature data (2 bytes)
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }
    temp_raw = (int16_t)((buffer[1] << 8) | buffer[0]);

    // Convert raw data to hPa and °C (from datasheet)
    data->pressure = (float)press_raw / 4096.0;
    data->temperature = (float)temp_raw / 480.0 + 42.5;

    return 0;
}

// Log data to a file
int log_data(const sensor_data_t *data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Write data to the log file
    fprintf(fp, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, data->pressure, data->temperature);

    // Flush the file buffer
    fflush(fp);

    // Close the file
    fclose(fp);

    return 0;
}

int main() {
    sensor_data_t sensor_data;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

