#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP32 I2C address
#define SDP32_ADDR 0x21

// I2C bus
#define I2C_BUS 1

// Default sampling interval (milliseconds)
#define DEFAULT_INTERVAL 1000

// CRC-8-H2F polynomial
#define CRC8_POLY 0x31

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t scale_factor;
} sensor_data_t;

// Global variables
int i2c_handle;
int interval = DEFAULT_INTERVAL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sdp32(sensor_data_t *data);
int verify_crc(uint8_t data[], int len);
void print_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read data from SDP32 sensor
int read_sdp32(sensor_data_t *data) {
    char buf[9];
    int result;

    // Send read command (trigger measurement)
    result = i2cWriteByte(i2c_handle, 0x36); // Trigger measurement
    if (result != 0) {
        fprintf(stderr, "Failed to send read command: %d\n", result);
        return -1;
    }

    // Wait for measurement (adjust as needed based on sensor datasheet)
    gpioDelay(10); // 10 ms delay

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Extract data from buffer
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->scale_factor = (uint8_t)buf[6];

    return 0;
}

// Verify CRC-8 checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLY;
            else
                crc = (crc << 1);
        }
    }

    return (crc == 0);
}

// Print sensor data with timestamp
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n",
           timestamp, data.pressure, data.temperature, data.scale_factor);
}

int main(int argc, char *argv[]) {
    sensor_data_t sensor_data;

    // Parse command-line arguments
    if (argc > 1) {
        interval = atoi(argv[1]);
        if (interval <= 0) {
            fprintf(stderr, "Invalid interval. Using default value: %d ms\n", DEFAULT_INTERVAL);
            interval = DEFAULT_INTERVAL;
        }
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sdp32(&sensor_data) == 0) {
            // Verify CRC
            if (verify_crc((uint8_t[]){sensor_data.pressure, sensor_data.temperature, sensor_data.scale_factor}, 9)) {
                print_data(sensor_data);
            } else {
                fprintf(stderr, "CRC verification failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(interval); // Wait for the specified interval
    }

    // Clean up resources
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

