// Define the I2C bus and address
#define I2C_BUS 1
#define SDP810_ADDR 0x25

// Define the number of bytes to read
#define NUM_BYTES 9

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the CRC_INIT value
#define CRC_INIT 0xFF

// Global variable to store the I2C handle
int i2c_handle = -1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature)
{
    char buf[NUM_BYTES];
    int result;

    // Trigger measurement (no command needed for continuous mode)
    result = i2cWriteByte(i2c_handle, 0x00); // Trigger measurement
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for at least 45ms
    gpioDelay(50000); // 50ms

    // Read 9 bytes from the sensor
    result = i2cReadDevice(i2c_handle, buf, NUM_BYTES);
    if (result != NUM_BYTES) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Extract pressure and temperature from the buffer
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];

    // Convert raw values to physical units
    *pressure = (float)raw_pressure / 240.0; // Pa
    *temperature = (float)raw_temperature / 200.0; // °C

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(uint8_t data[], int nbrOfBytes)
{
    uint8_t crc = CRC_INIT;
    int i, j;

    for (i = 0; i < nbrOfBytes; i++)
    {
        crc ^= data[i];
        for (j = 0; j < 8; j++)
        {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return (crc == 0);
}

