    if (i2c_handle < 0)
    {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float pressure, temperature;
    while (1)
    {
        // Read data from the sensor
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0)
        {
            // Validate the CRC checksums
            if (validate_crc((uint8_t[]){pressure, pressure, pressure, pressure}, 4) &&
                validate_crc((uint8_t[]){temperature, temperature, temperature, temperature}, 4))
            {
                // Log the results to stdout
                printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
            } else {
                fprintf(stderr, "CRC check failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Close the I2C bus and terminate the pigpio library (this part will not be reached in the infinite loop)
    i2cClose(i2c_handle);
