#include <time.h>

// Constants
#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define TEMP_MEASURE_CMD 0xE3
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define READ_TIMEOUT_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int si7051_address;
    int read_interval_seconds;
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from Si7051
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = RETRY_COUNT;

    while (retries > 0) {
        result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing temperature command: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
            continue;
        }

        gpioDelay(READ_TIMEOUT_MS * 1000); // Wait for conversion (adjust as needed)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            uint16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading temperature data: %d\n", result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -1; // Failure
}

// Log temperature to console
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

