#define ICP10101_PRESS_LSB 0x01
#define ICP10101_PRESS_XLSB 0x02

// Calibration coefficients (example values, replace with actual values from sensor)
#define SENSITIVITY_TEMP 0.01  // Example sensitivity, check datasheet
#define OFFSET_TEMP 0.00       // Example offset, check datasheet
#define SENSITIVITY_PRESS 0.001 // Example sensitivity, check datasheet
#define OFFSET_PRESS 0.00      // Example offset, check datasheet

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int init_i2c();
int trigger_measurement();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(uint8_t *data);
char* format_output(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ICP10101_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, ICP10101_WHO_AM_I, &who_am_i, 1) != 1) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
