    uint8_t command = 0x07; // Trigger measurement command
    if (i2cWriteI2CBlockData(i2c_handle, ICP10101_MEASURE, &command, 1) != 1) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(7); // Wait 7ms
    return 0;
}

