    if (i2cReadI2CBlockData(i2c_handle, ICP10101_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }
    return 0;
}

// Process raw sensor data
sensor_data_t process_sensor_data(uint8_t *data) {
    sensor_data_t sensor_data;
    int32_t raw_pressure = (data[0] << 16) | (data[1] << 8) | data[2];
    int32_t raw_temperature = (data[3] << 16) | (data[4] << 8) | data[5];

    sensor_data.temperature = (float)raw_temperature * SENSITIVITY_TEMP + OFFSET_TEMP;
    sensor_data.pressure = (float)raw_pressure * SENSITIVITY_PRESS + OFFSET_PRESS;

    return sensor_data;
}

// Format output string
char* format_output(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char buffer[256]; // Static buffer to hold the formatted string
    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", t);

    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), "Temperature: %.2f C, Pressure: %.2f Pa", data.temperature, data.pressure);
    return buffer;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        sensor_data_t sensor_data;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Measurement trigger failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Sensor data read failed, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Process sensor data
        sensor_data = process_sensor_data(data);

        // Format output
        char* output = format_output(sensor_data);

        // Print output
        printf("%s\n", output);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    cleanup();

    return 0;
}

