        // Verify CRC
        if (!verify_crc((uint8_t){raw_pressure}, 2) || !verify_crc((uint8_t){raw_temperature}, 2)) {
            fprintf(stderr, "CRC verification failed, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert data
        float pressure = convert_pressure(raw_pressure);
