#include <pigpio.h>

#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define LOG_FILE "pressure_log.csv"

int i2c_handle;
FILE *log_file;

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

// Function to read pressure from the sensor
float read_pressure() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read pressure: %d\n", result);
        return -1.0;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert raw pressure to kPa (example conversion, adjust as needed)
    float pressure_kPa = (float)raw_pressure * 0.1; // Example scaling

    return pressure_kPa;
}

// Function to log the pressure to a file
int log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to check the pressure range
void check_pressure_range(float pressure) {
    if (pressure < 200.0 || pressure > 250.0) {
        fprintf(stderr, "Warning: Pressure out of range (%.2f kPa)\n", pressure);
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        float pressure = read_pressure();
        if (pressure >= 0) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Failed to log pressure\n");
            }
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    return 0;
}

