int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENT_PIN, PI_INPUT);
    gpioSetPullUpDown(SENT_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to read the SENT frame from the sensor
SENT_Frame read_sent_frame() {
    SENT_Frame frame;
    unsigned int pulse_width;
    int i;

    // Wait for the synchronization pulse (56 ticks)
    for (i = 0; i < 100; ++i) {
        if (gpioRead(SENT_PIN) == 0) {
            gpioDelay(1); // Small delay to avoid busy-waiting
        } else {
            fprintf(stderr, "Timeout waiting for synchronization pulse\n");
            frame.status = 0xFF; // Indicate error
            return frame;
        }
        if (i > 100) {
            fprintf(stderr, "Error: Timeout waiting for synchronization pulse\n");
            frame.status = 0xFF; // Indicate error
            return frame;
        }
    }

    // Read the status nibble (1st pulse)
    pulse_width = gpioTick() - SYNCHRONIZATION_PULSE;
    if (pulse_width < 0 || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid status nibble pulse width: %u\n", pulse_width);
        frame.status = 0xFF; // Indicate error
        return frame;
    }
    frame.status = (pulse_width > MIN_PULSE_WIDTH) ? 0x0F : 0x00; // Example status, adjust as needed

    // Read the data nibbles (2nd and 3rd pulses)
    for (i = 1; i <= DATA_NIBBLES; ++i) {
