        if (pulse_width < 0 || pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Invalid data nibble pulse width: %u\n", pulse_width);
            frame.status = 0xFF; // Indicate error
            return frame;
        }
        frame.data |= ((unsigned int)pulse_width << (i * 8));
    }

    // Read the checksum nibble (4th pulse)
    pulse_width = gpioTick() - SYNCHRONIZATION_PULSE;
    if (pulse_width < 0 || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid checksum nibble pulse width: %u\n", pulse_width);
        frame.status = 0xFF; // Indicate error
        return frame;
    }
    frame.checksum = (pulse_width > MIN_PULSE_WIDTH) ? 0x0F : 0x00; // Example checksum, adjust as needed

    return frame;
}

