    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        SENT_Frame frame = read_sent_frame();

        if (frame.status == 0xFF) {
            fprintf(stderr, "Error: Invalid SENT frame received\n");
        } else {
            double pressure = calculate_pressure(frame);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        }

        gpioDelay(100); // Delay between readings (100ms)
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

