#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for temperature data
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureData;

// Circular buffer
TemperatureData temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
float read_temperature();
void add_to_buffer(float temperature);
void flush_buffer_to_file();
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature from TMP117
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw data to temperature (see TMP117 datasheet)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 5; // Shift right by 5 bits
    float temperature = raw_temp * 0.0625;

    return temperature;
}

// Function to add temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    time_t now = time(NULL);
    temperature_buffer[buffer_index].timestamp = now;
    temperature_buffer[buffer_index].temperature = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to flush the circular buffer to a file
void flush_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing\n");
        return;
    }

    fwrite(temperature_buffer, sizeof(TemperatureData), BUFFER_SIZE, fp);
    fclose(fp);
    printf("Temperature data flushed to %s\n", LOG_FILE);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for read error
            add_to_buffer(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Flush the buffer to file before exiting
    flush_buffer_to_file();

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

