    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_rotation_speed(int *rotation_speed);
int read_temperature(int *temperature);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
