        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads the rotational speed from the sensor
int read_rotation_speed(int *rotation_speed) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, ROTATION_SPEED_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read rotation speed: %d\n", bytes_read);
        return -1;
    }

    *rotation_speed = (buf[0] << 8) | buf[1];
    return 0;
}

