    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", bytes_read);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    return 0;
}

