        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Rotation Speed (RPM),Temperature (C)\n");
    }
    rewind(log_file);

    int rotation_speed, temperature;
    sensor_data_t data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_rotation_speed(&rotation_speed) == 0 && read_temperature(&temperature) == 0) {
            // Data validation
            if (rotation_speed < 0 || rotation_speed > 10000) {
                fprintf(stderr, "Invalid rotation speed: %d\n", rotation_speed);
                data.rotation_speed = -999.0; // Indicate invalid data
            } else if (temperature < -40.0 || temperature > 85.0) {
                fprintf(stderr, "Invalid temperature: %d\n", temperature);
                data.temperature = -999.0; // Indicate invalid data
            } else {
                // Calculate RPM
                data.rotation_speed = (float)rotation_speed / 100.0; // Example conversion
                data.temperature = temperature / 10.0; // Example conversion

                // Log data
                log_data(data);
            }
        } else {
            // Data validation failure
            data.rotation_speed = -999.0;
            data.temperature = -999.0;
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpio uses microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

