// Define the I2C address of the Honeywell flow sensor
#define HAF_I2C_ADDR 0x28

// Define the log file name
#define LOG_FILE "flow_log.txt"

// Define the sampling interval (in seconds)
#define SAMPLE_INTERVAL 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C interface
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HAF_I2C_ADDR, 0); // Open I2C bus 1 with the sensor's address
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buffer[4];
    int bytes_read;
    int16_t flow_raw, temperature_raw;

    // Read 4 bytes from the sensor
    bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    // Combine the bytes to form the raw flow and temperature values
    flow_raw = (buffer[0] << 8) | buffer[1];
