#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for DHT11 sensors
#define DHT11_PIN_1 4
#define DHT11_PIN_2 17
#define DHT11_PIN_3 27

// Define constants for DHT11 communication
#define DHT11_START_BIT 0x03
#define DHT11_START_TIMEOUT 18000 // 18ms in microseconds
#define DHT11_RESPONSE_TIMEOUT 50000 // 50ms in microseconds
#define DHT11_DATA_BITS 40
#define DHT11_CHECKSUM_BIT 0
#define DHT11_CHECKSUM_VALUE 0xFF

// Global variables
FILE *log_file = NULL;
int running = 1;

// Structure to hold DHT11 data
typedef struct {
    int humidity_int;
    int humidity_dec;
    int temperature_int;
    int temperature_dec;
    int checksum;
} DHT11Data;

// Function prototypes
int init_gpio();
int start_dht11(int pin);
int read_dht11_data(int pin, DHT11Data *data);
int verify_checksum(DHT11Data data);
int log_data(DHT11Data data);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(DHT11_PIN_1, PI_OUTPUT);
    gpioSetMode(DHT11_PIN_2, PI_OUTPUT);
    gpioSetMode(DHT11_PIN_3, PI_OUTPUT);

    return 0;
}

// Function to start the DHT11 sensor
int start_dht11(int pin) {
    gpioWrite(pin, 0); // Pull the line low
    gpioDelay(DHT11_START_BIT); // Wait for 18ms
    gpioWrite(pin, 1); // Release the line
    gpioDelay(1); // Wait 1us
    return 0;
}

// Function to read data from the DHT11 sensor
int read_dht11_data(int pin, DHT11Data *data) {
    int i;
    int bit;
    int byte;

    // Start signal check
    if (!start_dht11(pin)) {
        fprintf(stderr, "DHT11 start signal timeout\n");
        return 1;
    }

    // Read data bits
    for (i = 0; i < DHT11_DATA_BITS; i++) {
        gpioSetMode(pin, PI_INPUT); // Set pin to input mode
        gpioDelay(1); // Small delay for the sensor to prepare the data

        // Measure the length of the high pulse
        int start_time = gpioTick();
        while (gpioRead(pin) == 0) {
            if (gpioTick() - start_time > DHT11_RESPONSE_TIMEOUT) {
                fprintf(stderr, "DHT11 response timeout\n");
                return 2;
            }
        }
        int high_time = gpioTick() - start_time;

        // Measure the length of the low pulse
        start_time = gpioTick();
        while (gpioRead(pin) == 1) {
            if (gpioTick() - start_time > DHT11_RESPONSE_TIMEOUT) {
                fprintf(stderr, "DHT11 response timeout\n");
                return 2;
            }
        }
        int low_time = gpioTick() - start_time;

        // Determine the bit value based on the pulse lengths
        if (high_time > low_time * 2) {
            bit = 1;
        } else {
            bit = 0;
        }

        // Store the bit in the data array
        data->data[i] = bit;
    }

    // Verify checksum
    if (verify_checksum(data)) {
        fprintf(stderr, "Checksum verification failed\n");
        return 3;
    }

    return 0;
}

// Function to verify the checksum
int verify_checksum(DHT11Data data) {
    int calculated_checksum = 0;
    for (int i = 0; i < DHT11_DATA_BITS - 1; i++) {
        calculated_checksum += data.data[i];
    }
    calculated_checksum += DHT11_CHECKSUM_BIT;

    if (calculated_checksum != DHT11_CHECKSUM_VALUE) {
        fprintf(stderr, "Checksum verification failed: calculated = %d, expected = %d\n", calculated_checksum, DHT11_CHECKSUM_VALUE);
        return 4;
    }

    return 0;
}

// Function to log data to a file
int log_data(DHT11Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, data.humidity_int, data.humidity_dec, data.temperature_int, data.temperature_dec);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release GPIO resources
void cleanup() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    DHT11Data data1, data2, data3;

    // Main loop
    while (running) {
        // Read data from DHT11 sensor 1
        if (read_dht11_data(DHT11_PIN_1, &data1) == 0) {
            log_data(data1);
        } else {
            fprintf(stderr, "Error reading DHT11 sensor 1\n");
        }

        // Read data from DHT11 sensor 2
        if (read_dht11_data(DHT11_PIN_2, &data2) == 0) {
            log_data(data2);
        } else {
            fprintf(stderr, "Error reading DHT11 sensor 2\n");
        }

        // Read data from DHT11 sensor 3
        if (read_dht11_data(DHT11_PIN_3, &data3) == 0) {
            log_data(data3);
        } else {
            fprintf(stderr, "Error reading DHT11 sensor 3\n");
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

