#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x2F
#define SAMPLE_INTERVAL_MS 1000
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8-H2F polynomial
uint8_t crc_table[256];

// Function prototypes
int init_i2c();
int read_sdp810(float *pressure, float *temperature);
int validate_crc(uint8_t data[], int len);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8-H2F calculation function
uint8_t crc8(const uint8_t *data, int len) {
    for (int i = 0; i < len; i++) {
        uint8_t crc = crc_table[data[i]];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
        crc_table[data[i]] = crc;
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from SDP810
int read_sdp810(float *pressure, float *temperature) {
    uint8_t cmd[2] = {MEASURE_CMD_1, MEASURE_CMD_2};
    uint8_t data[9];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (45ms)
    gpioDelay(45000); // 45ms

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for pressure data
    if (!validate_crc(data, 3)) {
        fprintf(stderr, "CRC error in pressure data\n");
        return -1;
    }

    // Validate CRC for temperature data
    if (!validate_crc(data + 3, 3)) {
        fprintf(stderr, "CRC error in temperature data\n");
        return -1;
    }

    // Convert raw data to pressure and temperature
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    *pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    *temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Validate CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = crc8(data, len - 1);
    for (int i = 0; i < len - 1; i++) {
        if (crc != data[i + 1]) {
            return 0; // CRC mismatch
        }
    }
    return 1; // CRC check passed
}

// Log data to file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    float pressure, temperature;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        result = read_sdp810(&pressure, &temperature);
        if (result == 0) {
            log_data(pressure, temperature);
            if (pressure > 5.0) {
                fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
            }
        } else {
            fprintf(stderr, "Error reading SDP810 sensor\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

