#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x43
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_HIGH 28.0
#define TEMP_LOW 27.0
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature(int i2c_handle);
void control_led(float temperature);
void log_temperature(float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from STTS2004 sensor
float read_temperature(int i2c_handle) {
    char buf[2];
    int result;
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            float temperature = (float)raw_temp / 16.0;
            return temperature;
        } else {
            // Error
            fprintf(stderr, "I2C read error: %s (errno: %d)\n", strerror(errno), errno);
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after multiple retries.\n");
    return -273.15; // Return absolute zero as error indicator
}

// Function to control the LED based on temperature
void control_led(float temperature) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > TEMP_HIGH && led_state == 0) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        led_state = 1;
    } else if (temperature < TEMP_LOW && led_state == 1) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
        led_state = 0;
    }
}

// Function to log the temperature with a timestamp
void log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Temperature: %.2f °C\n", timestamp, temperature);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s (errno: %d)\n", strerror(errno), errno);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature(i2c_handle);

        if (temperature != -273.15) {
            control_led(temperature);
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping logging.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

