#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C address of the SDP800-500Pa sensor
#define SDP800_I2C_ADDRESS 0x25

// Define the measurement command (continuous measurement without averaging)
#define MEASURE_COMMAND_MSB 0x36
#define MEASURE_COMMAND_LSB 0x15

// Define the number of bytes to read from the sensor
#define NUM_BYTES_TO_READ 9

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the scale factor
#define SCALE_FACTOR 120.0f

// Define the I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    float differential_pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
int validate_crc(uint8_t data[], int len);
sensor_data_t convert_data(uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(uint8_t *data) {
    char command[2] = {MEASURE_COMMAND_MSB, MEASURE_COMMAND_LSB};
    int bytes_written = i2cWriteDevice(i2c_handle, command, 2);
    if (bytes_written != 2) {
        fprintf(stderr, "Failed to write measurement command: %d\n", bytes_written);
        return -1;
    }

    gpioDelay(50); // Wait for at least 45ms

    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, NUM_BYTES_TO_READ);
    if (bytes_read != NUM_BYTES_TO_READ) {
        fprintf(stderr, "Failed to read data: %d\n", bytes_read);
        return -1;
    }

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

