    sensor_data_t sensor_data;
    int16_t differential_pressure_raw = (data[0] << 8) | data[1];
    int16_t temperature_raw = (data[3] << 8) | data[4];

    // Scale the raw values
    sensor_data.differential_pressure = (float)differential_pressure_raw / SCALE_FACTOR;
    sensor_data.temperature = (float)temperature_raw / SCALE_FACTOR;

    return sensor_data;
}

