        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t data[NUM_BYTES_TO_READ];

    // Main loop
    while (program_running) {
        // Read data from the sensor
        if (read_sensor_data(data) == 0) {
            // Validate the CRC checksums
            if (validate_crc(data, 2) && validate_crc(data + 2, 2)) {
                // Convert the raw data to differential pressure and temperature
                sensor_data_t sensor_data = convert_data(data);

                // Log the data to the file
                log_data(sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Close the I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

