#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS40_ADDR 0x44
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// CRC-8-ATM polynomial
#define POLYNOMIAL 0x31

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_sts40(float *temperature);
int verify_crc(unsigned char data[], int len);
int log_temperature(float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_fd = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read temperature from STS40 sensor
int read_sts40(float *temperature) {
    unsigned char data[3];
    int result;

    // Send trigger measurement command (High Precision Mode)
    result = i2cWriteByte(i2c_fd, 0x2D); // Trigger measurement
    if (result != 0) {
        fprintf(stderr, "Failed to send trigger measurement command: %d\n", result);
        return -1;
    }

    // Wait for 10ms
    gpioDelay(10000); // 10000 microseconds = 10 milliseconds

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_fd, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read 3 bytes of data: %d\n", result);
        return -1;
    }

    // Verify CRC
    if (verify_crc(data, 2) != 0) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data to temperature
    int16_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temperature / 65535.0);

    return 0;
}

// Function to verify CRC8 checksum
int verify_crc(unsigned char data[], int len) {
    unsigned char crc = 0xFF;
    unsigned char bit;

    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            bit = crc & 0x80;
            if (bit) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc = (crc << 1);
            }
        }
    }

    return (crc != 0);
}

// Function to log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    float temperature;
    sensor_data_t sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        if (read_sts40(&temperature) == 0) {
            sensor_data.temperature = temperature;
            sensor_data.timestamp = time(NULL);

            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    return 0;
}

