#define BUFFER_FILE_PATH "/var/log/scd40_data/scd40_buffer.csv"
#define SLEEP_DURATION_MS 1000

// CRC-8-ATM polynomial
#define POLYNOMIAL 0x31

// Global variables
static volatile int running = 1;
static int i2c_handle;
static pthread_t logging_thread;

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

