void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("I2C open failed");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to start periodic measurement
int start_periodic_measurement() {
    char cmd[2] = {(PERIODIC_MEASUREMENT_CMD >> 8) & 0xFF, PERIODIC_MEASUREMENT_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(float *co2, float *temperature, float *humidity) {
    unsigned char data[9];
    int result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // CRC validation
    if (!validate_crc(data, 9)) {
        log_error("CRC validation failed");
        return -1;
    }

    // Extract data
    *co2 = (float)((data[0] << 8) | data[1]);
    *temperature = (float)((data[3] << 8) | data[4]);
    *humidity = (float)((data[6] << 8) | data[7]);

    return 0;
}

// Function to validate CRC-8-ATM
int validate_crc(unsigned char *data, int data_len) {
    unsigned int crc = 0xFF;
    unsigned int polynomial = POLYNOMIAL;

    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
