#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SDP810 I2C address
#define SDP810_ADDR 0x25

// I2C bus
#define I2C_BUS 1

// CRC-8-Maxim polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
    float scale_factor;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, sensor_data_t *data) {
    uint8_t buffer[9];
    int result;

    // Trigger measurement (single shot mode)
    result = i2cWriteByte(i2c_handle, 0x24); // Trigger measurement command
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 45ms)
    gpioDelay(50000); // 50ms

    // Read 9 bytes from the sensor
    result = i2cReadDevice(i2c_handle, (char *)buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC for differential pressure
    uint8_t crc_dp = crc8(buffer, 2);
    if (crc_dp != buffer[2]) {
        fprintf(stderr, "CRC error for differential pressure\n");
        return -1;
    }

    // Validate CRC for temperature
    uint8_t crc_temp = crc8(buffer + 3, 2);
    if (crc_temp != buffer[5]) {
        fprintf(stderr, "CRC error for temperature\n");
        return -1;
    }

    // Validate CRC for scale factor
    uint8_t crc_scale = crc8(buffer + 6, 2);
    if (crc_scale != buffer[8]) {
        fprintf(stderr, "CRC error for scale factor\n");
        return -1;
    }

    // Convert raw data to physical units
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];
    int16_t raw_scale_factor = (buffer[6] << 8) | buffer[7];

    data->pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    data->temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet
    data->scale_factor = (float)raw_scale_factor / 200.0; // Scale factor from datasheet

    return 0;
}

// Function to log data to a file
int log_data(FILE *log_file, float pressure, float temperature, float scale_factor) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pressure, temperature, scale_factor);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sdp810_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        result = read_sdp810(i2c_handle, &sensor_data);
        if (result == 0) {
            // Log data
            log_data(log_file, sensor_data.pressure, sensor_data.temperature, sensor_data.scale_factor);
            printf("Pressure: %.2f Pa, Temperature: %.2f C, Scale Factor: %.2f\n", sensor_data.pressure, sensor_data.temperature, sensor_data.scale_factor);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

