#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 30.0
#define TEMP_THRESHOLD_OFF 28.0
#define LOG_FILE "temperature_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_mlx90614(float *ambient_temp, float *object_temp);
void log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature data from MLX90614
int read_mlx90614(float *ambient_temp, float *object_temp) {
    unsigned char buffer[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buffer, 6);
        if (result == 6) {
            // Convert raw data to temperatures (example formulas, adjust as needed)
            int ambient_raw = (buffer[0] << 8) | buffer[1];
            int object_raw = (buffer[3] << 8) | buffer[4];

            *ambient_temp = (float)ambient_raw * 0.02 - 273.15;
            *object_temp = (float)object_raw * 0.02 - 273.15;

            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read MLX90614 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Log temperature data to file
void log_temperature(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Ambient: %.2f C, Object: %.2f C\n", timestamp, ambient_temp, object_temp);
        fflush(log_file); // Ensure data is written to disk
    } else {
        fprintf(stderr, "Log file is not open\n");
    }
}

// Control the cooling fan
void control_fan(float object_temp) {
    static int fan_on = 0; // Track fan state

    if (object_temp > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan turned ON (Object Temp: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF (Object Temp: %.2f C)\n", object_temp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
    }

    float ambient_temp, object_temp;

    // Main loop
    while (!terminate) {
        if (read_mlx90614(&ambient_temp, &object_temp) == 0) {
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping logging\n");
        }

        gpioDelay(2000000); // Wait 2 seconds (2000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

