#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd, new_socket;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd > 0) {
        close(server_fd);
    }
    if (new_socket > 0) {
        close(new_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    unsigned char cmd[1] = {0xFD}; // High precision measurement command
    unsigned char buffer[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(10000); // Wait for measurement (at least 10ms)

        result = i2cReadDevice(i2c_handle, buffer, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C device (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
