    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0); // I2C bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the HDC2010 sensor
int configure_sensor() {
    // Configure for temperature and humidity mode, disable heater
    if (i2cWriteByteData(i2c_handle, CONFIGURATION_REGISTER, CONFIG_MODE_TEMP_HUMID | CONFIG_HEATER_DISABLE) < 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        return -1;
    }

    // Set measurement configuration (e.g., 14-bit resolution)
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, CONFIG_MEASUREMENT_CONFIG) < 0) {
        fprintf(stderr, "Failed to write to measurement config register\n");
        return -1;
    }

    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    int raw_temperature, raw_humidity;

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, CONFIG_MEASUREMENT_CONFIG) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // 10 ms delay

    // Read temperature data
    raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_MSB);
    if (raw_temperature < 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    // Read humidity data
    raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_MSB);
    if (raw_humidity < 0) {
        fprintf(stderr, "Failed to read humidity data\n");
        return -1;
    }

    // Process the raw data
    process_sensor_data(raw_temperature, raw_humidity, data);

    return 0;
}

// Process raw sensor data
void process_sensor_data(int raw_temperature, int raw_humidity, sensor_data_t *data) {
    // Convert raw data to temperature and humidity
    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;
}

// Print sensor data to the console
void print_sensor_data(sensor_data_t data) {
    printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            print_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

