#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// SDP800-500Pa I2C address
#define SDP800_ADDR 0x25

// I2C bus
#define I2C_BUS 1

// Measurement command (continuous mode, no averaging)
#define MEASURE_CMD_1 0x36
#define MEASURE_CMD_2 0x15

// CRC-8-H2F polynomial
#define POLYNOMIAL 0x31

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    uint8_t crc;
    int16_t temperature;
    uint8_t crc_temp;
} sensor_data_t;

// CRC-8-H2F calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read data from the SDP800 sensor
int read_sdp800(sensor_data_t *data) {
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteByteData(i2c_handle, MEASURE_CMD_1, MEASURE_CMD_2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 45ms)
    gpioDelay(50000); // 50ms

    // Read 6 bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC checksums
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }

    // Populate sensor data
    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->crc = buf[2];
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->crc_temp = buf[5];

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp800(&sensor_data) == 0) {
            // Log data to console
            printf("Pressure: %d Pa, Temperature: %d C\n", sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 500ms
        gpioDelay(500000);
    }

    // Clean up and exit
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

