#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define TARGET_TEMP_PROFILE_SIZE 10
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// PID variables
float integral = 0.0;
float previous_error = 0.0;

// Function prototypes
int spi_read_max6675(int spi_handle, float *temperature);
int spi_write_max6675(int spi_handle, int data);
int read_profile(const char *filename, float *profile);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_relay_duty_cycle(int duty_cycle);
void log_data(float temperature, float pid_output);
void signal_handler(int signal);

// Function to read temperature from MAX6675 via SPI
int spi_read_max6675(int spi_handle, float *temperature) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the bytes to form the 16-bit temperature value
    int16_t raw_temperature = (data[0] << 8) | data[1];

    // Check for fault bit (bit 15 of the first byte)
    if (raw_temperature & 0x8000) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -1; // Indicate fault
    }

    // Convert the raw temperature to Celsius (MAX6675 datasheet)
    *temperature = (float)raw_temperature / 4.0;

    return 0; // Indicate success
}

// Function to write data to MAX6675 via SPI
int spi_write_max6675(int spi_handle, int data) {
    unsigned char buffer[2];
    int result;

    buffer[0] = 0x40; // Command to write data
    buffer[1] = data;

    result = spiWrite(spi_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing SPI data: %d\n", result);
        return -1; // Indicate error
    }

    return 0; // Indicate success
}

// Function to read the target temperature profile from file
int read_profile(const char *filename, float *profile) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        return -1; // Indicate error
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading profile file: %s\n", filename);
        fclose(fp);
        return -1; // Indicate error
    }

    if (sscanf(line, "%f,%f,%f,%f,%f,%f,%f,%f,%f,%f", &profile[0], &profile[1], &profile[2], &profile[3], &profile[4], &profile[5], &profile[6], &profile[7], &profile[8], &profile[9]) != TARGET_TEMP_PROFILE_SIZE) {
        fprintf(stderr, "Error parsing profile file: %s\n", filename);
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return 0; // Indicate success
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;

    // Clamp the output to the range 0.0 to 1.0
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 1.0) {
        output = 1.0;
    }

    return output;
}

// Function to set the relay duty cycle
void set_relay_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 1.0) {
        duty_cycle = 1.0;
    }

    int pwm_range = 1000000; // Adjust as needed
    int pwm_value = (int)(duty_cycle * pwm_range);
    gpioPWM(RELAY_GPIO, pwm_value);
}

// Function to log data to file
void log_data(float temperature, float pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float temperature, pid_output;
    float profile[TARGET_TEMP_PROFILE_SIZE];
    int i;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetPWMrange(RELAY_GPIO, 1000000); // Set PWM range (adjust as needed)
    gpioSetPWMfrequency(RELAY_GPIO, 1000); // Set PWM frequency (adjust as needed)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Read target temperature profile
    if (read_profile(PROFILE_FILE, profile) != 0) {
        fprintf(stderr, "Failed to read profile, using default values.\n");
        // Set default profile values
        for (i = 0; i < TARGET_TEMP_PROFILE_SIZE; i++) {
            profile[i] = 25.0; // Default temperature
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature from MAX6675
        if (spi_read_max6675(spi_handle, &temperature) == 0) {
            // Calculate PID output
            pid_output = calculate_pid(profile[0], temperature, &integral, &previous_error);

            // Set relay duty cycle
            set_relay_duty_cycle((int)pid_output);

            // Log data
            log_data(temperature, pid_output);

            // Print PID output to console
            printf("Temperature: %.2f C, PID Output: %.2f\n", temperature, pid_output);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Clean up
    set_relay_duty_cycle(0.0); // Turn off relay
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

