#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>
#include <stdbool.h>

// Configuration
#define RELAY_PIN 17
#define PWM_PIN 18
#define TEMPERATURE_SENSOR_PIN 4
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000
#define LOG_FILE "greenhouse.log"
#define DEFAULT_SETPOINT 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define DEFAULT_SAMPLE_INTERVAL 5 // seconds

// Global variables
double setpoint = DEFAULT_SETPOINT;
double Kp = DEFAULT_KP;
double Ki = DEFAULT_KI;
double Kd = DEFAULT_KD;
int sample_interval = DEFAULT_SAMPLE_INTERVAL;
bool running = true;

// Function prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error);
void set_pwm(int duty_cycle);
void set_relay(int state);
void log_data(double average_temperature, double setpoint, double pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int validate_crc(unsigned char *data, int len);

// CRC-8 calculation
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from DS18B20 sensor
double read_temperature() {
    FILE *fp;
    char line[256];
    double temperature = -1000.0; // Initialize to an invalid value
    int fd = -1;

    // Open the w1-gpio device file
    fd = open("/sys/bus/w1/devices/28-000000000000/w1_slave", O_RDONLY);
    if (fd < 0) {
        perror("Error opening w1-gpio device");
        return temperature; // Return invalid value
    }

    // Read the file
    if (read(fd, line, sizeof(line) - 1) < 0) {
        perror("Error reading w1-gpio device");
        close(fd);
        return temperature; // Return invalid value
    }

    // Close the file
    close(fd);

    // Check for CRC error
    if (validate_crc(line, strlen(line) - 1) != 0) {
        fprintf(stderr, "CRC error detected\n");
        return temperature; // Return invalid value
    }

    // Extract temperature from the string
    char *temp_str = strstr(line, "t=");
    if (temp_str != NULL) {
        long temp_milli_celsius = strtol(temp_str + 2, NULL, 10);
        temperature = (double)temp_milli_celsius / 1000.0;
    } else {
        fprintf(stderr, "Temperature not found in w1-gpio data\n");
    }

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_PIN, duty_cycle);
}

// Function to set relay state
void set_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

// Function to log data to file
void log_data(double average_temperature, double setpoint, double pid_output, int pwm_duty_cycle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            average_temperature, setpoint, pid_output, pwm_duty_cycle);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:k:i:d:i:")) != -1) {
        switch (opt) {
            case 's':
                setpoint = atof(optarg);
                break;
            case 'k':
                Kp = atof(optarg);
                break;
            case 'i':
                Ki = atof(optarg);
                break;
            case 'd':
                Kd = atof(optarg);
                break;
            case 'i':
                sample_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s setpoint] [-k Kp] [-i Ki] [-d Kd] [-i sample_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set initial relay state to OFF
    set_relay(0);

    // Set initial PWM duty cycle to 0
    set_pwm(0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double average_temperature = 0.0;
        double integral = 0.0;
        double previous_error = 0.0;
        int pwm_duty_cycle = 0;

        // Read temperature and calculate PID output
        double temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            double pid_output = calculate_pid(setpoint, temperature, &integral, &previous_error);
            average_temperature = (temperature + 25.0) / 2.0; // Average temperature with setpoint
            pwm_duty_cycle = (int)(pid_output * 10000.0); // Scale PID output to PWM duty cycle
            if (pwm_duty_cycle < 0) pwm_duty_cycle = 0;
            if (pwm_duty_cycle > PWM_RANGE) pwm_duty_cycle = PWM_RANGE;
            set_pwm(pwm_duty_cycle);
            set_relay(1); // Turn on relay
            log_data(average_temperature, setpoint, pid_output, pwm_duty_cycle);
        } else {
            fprintf(stderr, "Invalid temperature reading, skipping PID calculation\n");
        }

        sleep(sample_interval);
    }

    // Cleanup
    set_relay(0); // Turn off relay
    set_pwm(0);  // Set PWM to 0
    gpioTerminate(); // Terminate pigpio
    fclose(fopen(LOG_FILE, "a")); // Close log file

    return 0;
}

