#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define DEHUMIDIFIER_GPIO 17
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_i2c();
int aht20_trigger_measurement();
int aht20_read_data(uint8_t *data);
float aht20_calculate_humidity(uint8_t *data);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint8_t status;
    uint8_t humidity;
} sensor_data_t;

// Function to initialize GPIO
int init_gpio() {
    if (gpioSetMode(DEHUMIDIFIER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode.\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to trigger a measurement on the AHT20 sensor
int aht20_trigger_measurement() {
    uint8_t trigger_cmd[3] = {0xAC, 0x33, 0x00};
    int result = i2cWriteDevice(i2c_handle, (char *)trigger_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(15000); // Wait 15ms
    return 0;
}

// Function to read data from the AHT20 sensor
int aht20_read_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate humidity from raw data
float aht20_calculate_humidity(uint8_t *data) {
    uint32_t raw_humidity = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    if (raw_humidity & (1 << 19)) {
        return -1.0; // Indicate error
    }
    return ((float)raw_humidity / 1048576.0) * 100.0;
}

// Function to control the dehumidifier relay
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(DEHUMIDIFIER_GPIO, 1); // Activate dehumidifier
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(DEHUMIDIFIER_GPIO, 0); // Deactivate dehumidifier
    }
}

// Function to log data with timestamp
void log_data(float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Deactivate dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int retries = 0;
        int result;

        // Retry reading data if the sensor is not present
        if (aht20_trigger_measurement() != 0) {
            fprintf(stderr, "AHT20 sensor not present.\n");
            log_data(-1.0); // Log error
            continue;
        }

        while (retries < MAX_RETRIES) {
            result = aht20_read_data(data);
            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read AHT20 data after %d retries.\n", MAX_RETRIES);
            log_data(-1.0); // Log error
            continue; // Skip to the next iteration
        }

        // Verify status byte
        if (data[0] != 0x08 || data[1] != 0x00 || data[2] != 0x00 || data[3] != 0x00 || data[4] != 0x00 || data[5] != 0x00) {
            fprintf(stderr, "Invalid status byte: 0x%02X\n", data[0]);
            log_data(-1.0); // Log error
            continue;
        }

        // Calculate humidity
        float humidity = aht20_calculate_humidity(data);

        // Control dehumidifier
        control_dehumidifier(humidity);

        // Log data
        log_data(humidity);

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

