    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(DEHUMIDIFIER_GPIO, 0); // Deactivate dehumidifier
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint8_t data[6];
        int retries = 0;
        int result;

        // Retry reading data if the sensor is not present
        if (aht20_trigger_measurement() != 0) {
            fprintf(stderr, "AHT20 sensor not present.\n");
            log_data(-1.0); // Log error
            continue;
        }

        while (retries < MAX_RETRIES) {
            result = aht20_read_data(data);
            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "I2C read failed, retry %d/%d\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read AHT20 data after %d retries.\n", MAX_RETRIES);
            log_data(-1.0); // Log error
            continue; // Skip to the next iteration
        }

        // Verify status byte
        if (data[0] != 0x08 || data[1] != 0x00 || data[2] != 0x00 || data[3] != 0x00 || data[4] != 0x00 || data[5] != 0x00) {
            fprintf(stderr, "Invalid status byte: 0x%02X\n", data[0]);
            log_data(-1.0); // Log error
            continue;
        }

        // Calculate humidity
        float humidity = aht20_calculate_humidity(data);

        // Control dehumidifier
        control_dehumidifier(humidity);

        // Log data
        log_data(humidity);

        // Wait for the next poll interval
        gpioDelay(POLL_INTERVAL_S * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

