// Configuration
#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define POST_URL "http://api.example.com/humidity"
#define POLL_INTERVAL 60 // seconds
#define MAX_RETRIES 3

// HTU21D Commands
#define TRIGGER_TEMP_MEASURE 0xE3
#define TRIGGER_HUMID_MEASURE 0xE5

// Global variables
int i2c_fd = -1;
bool running = true;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c(const char *bus, int addr);
int read_sensor_data(int fd, unsigned char *data);
float convert_humidity(unsigned int raw_humidity);
int post_data(const char *url, float temperature, float humidity);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %s", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor_data(int fd, unsigned char *data) {
    unsigned char command = TRIGGER_HUMID_MEASURE;
    if (write(fd, &command, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
        return -1;
    }

    usleep(100000); // Wait for measurement (100ms)

    if (read(fd, data, 3) != 3) {
        syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to convert raw humidity data to percentage
float convert_humidity(unsigned int raw_humidity) {
    float humidity = (float)raw_humidity / 65536.0 * 100.0;
    return humidity;
}

// Function to post data to the server
int post_data(const char *url, float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_data[256];

    // Format data as JSON
    snprintf(json_data, sizeof(json_data), "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        // Set Content-Type header
        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "Failed to initialize libcurl");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = false;
}

int main() {
    openlog("humidity_monitor", LOG_PID, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, HTU21D_ADDR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to initialize I2C, exiting");
        closelog();
        return 1;
    }

    unsigned char data[3];
    sensor_data_t sensor_data;
    int retries;

    while (running) {
        // Read sensor data
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(i2c_fd, data) == 0) {
                // Extract humidity data
                unsigned int raw_humidity = (data[0] << 8) | data[1];
                sensor_data.humidity = convert_humidity(raw_humidity);
                sensor_data.temperature = -46.85 + 175.72 * ((float)data[0] / 65536.0);

                // Post data to server
                if (post_data(POST_URL, sensor_data.temperature, sensor_data.humidity) == 0) {
                    syslog(LOG_INFO, "Data posted successfully: Temperature=%.2f, Humidity=%.2f", sensor_data.temperature, sensor_data.humidity);
                } else {
                    syslog(LOG_ERR, "Failed to post data, retrying...");
                }
                break; // Exit retry loop on success
            } else {
                syslog(LOG_ERR, "Failed to read sensor data, retrying...");
                retries++;
                usleep(1000000); // Wait 1 second before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            syslog(LOG_ERR, "Failed to read sensor data after %d retries, skipping this iteration.", MAX_RETRIES);
        }

        sleep(POLL_INTERVAL);
    }

    // Close I2C device
    if (i2c_fd != -1) {
        close(i2c_fd);
        syslog(LOG_INFO, "I2C device closed");
    }

    closelog();
    return 0;
}

