#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define BACKOFF_MS 10
#define LOG_FILE_NAME "sensor_data.csv"

// Global variables
static volatile int running = 1;
static int i2c_handle_tmp117 = -1;
static int i2c_handle_aht20 = -1;
static FILE *log_file = NULL;

// Function prototypes
int read_tmp117(float *temperature);
int read_aht20(float *humidity);
int read_pir();
void log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
int setup();
void cleanup();

// Function to read temperature from TMP117
int read_tmp117(float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle_tmp117, buf, 2);
        if (result == 2) {
            // Success
            int raw_temp = (buf[0] << 4) | (buf[1] >> 4);
            *temperature = (float)raw_temp * 0.0625;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (TMP117), retrying (%d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            gpioDelay(BACKOFF_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to read TMP117 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read humidity from AHT20
int read_aht20(float *humidity) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle_aht20, buf, 6);
        if (result == 6) {
            // Success
            int raw_humidity = (buf[1] << 12) | (buf[2] << 4) | (buf[3] >> 4);
            *humidity = (float)raw_humidity * 0.125;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (AHT20), retrying (%d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            gpioDelay(BACKOFF_MS * (1 << retries)); // Exponential backoff
            retries++;
        }
    }

    fprintf(stderr, "Failed to read AHT20 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read PIR sensor
int read_pir() {
    return gpioRead(PIR_GPIO);
}

// Function to log data to CSV file
void log_data(float temperature, float humidity, int motion_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Setup function to initialize pigpio and I2C
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C device for TMP117
    i2c_handle_tmp117 = i2cOpen(1, TMP117_ADDR, 0);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Failed to open I2C device for TMP117: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Open I2C device for AHT20
    i2c_handle_aht20 = i2cOpen(1, AHT20_ADDR, 0);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Failed to open I2C device for AHT20: %s\n", strerror(errno));
        i2cClose(i2c_handle_tmp117);
        gpioTerminate();
        return -1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle_tmp117);
        i2cClose(i2c_handle_aht20);
        gpioTerminate();
        return -1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    return 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close I2C devices
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (setup() != 0) {
        fprintf(stderr, "Setup failed, exiting.\n");
        return 1;
    }

    float temperature, humidity;
    int motion_detected;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_tmp117(&temperature) != 0) {
            fprintf(stderr, "Failed to read TMP117, using previous value or default.\n");
        }
        if (read_aht20(&humidity) != 0) {
            fprintf(stderr, "Failed to read AHT20, using previous value or default.\n");
        }
        motion_detected = read_pir();

        // Log data
        log_data(temperature, humidity, motion_detected);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

