#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common cathode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Global variable to store the last CPU load sample
static volatile unsigned long last_cpu_load = 0;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off the LED (set all channels to 255)
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();
    exit(0);
}

// Signal handler for SIGTERM (Terminate)
void sigterm_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Turn off the LED (set all channels to 255)
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);
    gpioTerminate();
    exit(0);
}

// Function to read CPU load from /proc/stat
unsigned long read_cpu_load() {
    FILE *fp;
    unsigned long load;
    char line[256];

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return 0; // Return 0 on error
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return 0; // Return 0 on error
    }

    if (sscanf(line, "cpu  %lu %lu %lu %lu %lu", &load, &load, &load, &load, &load) != 5) {
        fclose(fp);
        return 0; // Return 0 on error
    }

    fclose(fp);
    return load;
}

// Function to map CPU load to RGB color values
RGBColor map_cpu_load_to_color(unsigned long cpu_load) {
    RGBColor color;

    if (cpu_load <= 33) {
        color.red   = 0;
        color.green = 0;
        color.blue  = 255;
    } else if (cpu_load <= 66) {
        color.red   = 0;
        color.green = 255;
        color.blue  = 255;
    } else {
        color.red   = 255;
        color.green = 255;
        color.blue  = 0;
    }

    return color;
}

// Function to set the PWM duty cycle for each color channel
void set_pwm_duty_cycle(int red_pin, int green_pin, int blue_pin, int red_value, int green_value, int blue_value) {
    gpioPWM(red_pin, red_value);
    gpioPWM(green_pin, green_value);
    gpioPWM(blue_pin, blue_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Install signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop
    while (1) {
        // Read CPU load
        unsigned long current_cpu_load = read_cpu_load();

        // Calculate the change in CPU load
        unsigned long cpu_load_change = current_cpu_load - last_cpu_load;
        last_cpu_load = current_cpu_load;

        // Map CPU load to color
        RGBColor color = map_cpu_load_to_color(current_cpu_load);

        // Set PWM duty cycles
        set_pwm_duty_cycle(RED_PIN, GREEN_PIN, BLUE_PIN, color.red, color.green, color.blue);

        // Delay for 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

