#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_RESET 0xE0

// Calibration data registers
#define BMP280_REG_CALIB_00 0x88

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x4
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_NORMAL 3

// Global variables
int i2c_handle;
int udp_socket;

// Calibration data
unsigned short dig_T1;
short dig_T2;
short dig_T3;
unsigned short dig_P1;
short dig_P2;
short dig_P3;
short dig_P4;
short dig_P5;
short dig_P6;
short dig_P7;
short dig_P8;
short dig_P9;

// Function prototypes
int bmp280_init();
int bmp280_read_calibration_data();
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine);
char* format_json(double temperature, double pressure);
int send_udp_packet(const char* json_string);
void signal_handler(int signal);

// Structure to hold BMP280 data
typedef struct {
    double temperature;
    double pressure;
} bmp280_data_t;

// Function to read a single byte from the BMP280
int bmp280_read_byte(int reg, unsigned char *data)
{
    int result = i2cReadByteData(i2c_handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading byte from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *data = (unsigned char)result;
    return 0;
}

// Function to write a single byte to the BMP280
int bmp280_write_byte(int reg, unsigned char data)
{
    int result = i2cWriteByteData(i2c_handle, reg, data);
    if (result < 0) {
        fprintf(stderr, "Error writing byte 0x%02X to register 0x%02X: %s\n", data, reg, strerror(errno));
        return -1;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init() != 0) {
        fprintf(stderr, "BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int32_t raw_temperature, raw_pressure;
        double temperature, pressure;
        char* json_string;

        // Read raw temperature and pressure data
        if (bmp280_read_raw_data(&raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Error reading raw data\n");
            continue; // Try again
        }

        // Compensate temperature and pressure
        temperature = bmp280_compensate_temperature(raw_temperature);
        pressure = bmp280_compensate_pressure(raw_pressure, temperature);

        // Format data into JSON string
        json_string = format_json(temperature, pressure);

        // Send UDP packet
        if (send_udp_packet(json_string) != 0) {
            fprintf(stderr, "Error sending UDP packet\n");
        }

        // Free the JSON string
        free(json_string);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

// Initialize BMP280 sensor
int bmp280_init()
{
    // Reset the sensor
    if (bmp280_write_byte(BMP280_REG_RESET, 0xB6) != 0) {
        return -1;
    }
    gpioDelay(10); // Wait for the reset to complete

    // Set oversampling and mode
    if (bmp280_write_byte(BMP280_REG_CTRL_MEAS, (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL) != 0) {
        return -1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data() != 0) {
        return -1;
    }

    return 0;
}

// Read calibration data from the BMP280
int bmp280_read_calibration_data()
{
    unsigned char data[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char*)data, 26) != 26) {
        return -1;
    }

    dig_T1 = (data[1] << 8) | data[0];
    dig_T2 = (short)((data[3] << 8) | data[2]);
    dig_T3 = (short)((data[5] << 8) | data[4]);
    dig_P1 = (data[7] << 8) | data[6];
    dig_P2 = (short)((data[9] << 8) | data[8]);
    dig_P3 = (short)((data[11] << 8) | data[10]);
    dig_P4 = (short)((data[13] << 8) | data[12]);
    dig_P5 = (short)((data[15] << 8) | data[14]);
    dig_P6 = (short)((data[17] << 8) | data[16]);
    dig_P7 = (short)((data[19] << 8) | data[18]);
    dig_P8 = (short)((data[21] << 8) | data[20]);
    dig_P9 = (short)((data[23] << 8) | data[22]);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int bmp280_read_raw_data(int32_t *temperature, int32_t *pressure)
{
    unsigned char data[6];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char*)data, 6) != 6) {
        return -1;
    }

    *pressure = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    *temperature = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    return 0;
}

// Compensate temperature using BMP280 datasheet formula
double bmp280_compensate_temperature(int32_t raw_temperature)
{
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)dig_T1) / 1024.0) * ((double)dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)dig_T1) / 8192.0)) * ((double)dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using BMP280 datasheet formula
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine)
{
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)dig_P4) * 65536.0);
    var1 = (((double)dig_P3) * var1 * var1 / 524288.0 + ((double)dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)dig_P7)) / 16.0;
    return p;
}

// Format temperature and pressure data into a JSON string
char* format_json(double temperature, double pressure)
{
    char* json_string = (char*)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Send UDP packet
int send_udp_packet(const char* json_string)
{
    struct sockaddr_in server_addr;

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000);
    if (inet_pton(AF_INET, "192.168.1.100", &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address/ Address not supported\n");
        close(udp_socket);
        return -1;
    }

    // Send data
    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(udp_socket);
        return -1;
    }

    close(udp_socket);
    return 0;
}

// Signal handler
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close UDP socket
    close(udp_socket);

    exit(0);
}

