#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define FAN_GPIO 18
#define PWM_FREQUENCY 1000
#define DUTY_RANGE 255
#define BUFFER_SIZE 20

// MAX31855 Registers
#define MAX31855_TEMP_MSB 0x00
#define MAX31855_FAULT_BIT 0x01
#define MAX31855_FAULT_STATUS 0x00
#define MAX31855_FAULT_CODE 0x02
#define MAX31855_FAULT_STATUS_REG 0x01
#define MAX31855_FAULT_CODE_REG 0x00

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Circular Buffer Structure
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int spi_read_register(int reg, uint8_t *data, int len);
int spi_write_register(int reg, uint8_t *data, int len);
float read_temperature();
int calculate_duty_cycle(float temperature);
void update_fan_speed(int duty_cycle);
void log_data(time_t timestamp, float temperature, int duty_cycle);
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, len); // Pad with dummy data

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != (len + 1)) {
        fprintf(stderr, "SPI Read Error: %d\n", spi_handle);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Function
int spi_write_register(int reg, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    memset(tx_buf + 1, 0, len); // Pad with dummy data

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != (len + 1)) {
        fprintf(stderr, "SPI Write Error: %d\n", spi_handle);
        return -1;
    }

    memcpy(rx_buf, data, len);
    return 0;
}

// Temperature Reading Function
float read_temperature() {
    uint8_t data[4];
    int32_t raw_temp;
    float temperature;

    if (spi_read_register(MAX31855_TEMP_MSB, data, 4) != 0) {
        fprintf(stderr, "SPI Read Temperature Error\n");
        return -1000.0; // Indicate error
    }

    raw_temp = (data[0] << 16) | (data[1] << 8) | data[2];
    raw_temp >>= 2; // Remove fault bit

    if (raw_temp & 0x00000004) {
        fprintf(stderr, "MAX31855 Fault Detected\n");
        return -1000.0; // Indicate error
    }

    temperature = raw_temp * 0.25;
    return temperature;
}

// Duty Cycle Calculation Function
int calculate_duty_cycle(float temperature) {
    int duty_cycle;

    if (temperature < 25.0) {
        duty_cycle = 0;
    } else if (temperature >= 25.0 && temperature <= 40.0) {
        duty_cycle = (int)((temperature - 25.0) * 0.5);
    } else if (temperature >= 40.0 && temperature <= 60.0) {
        duty_cycle = (int)((temperature - 40.0) * 1.5);
    } else {
        duty_cycle = 255;
    }

    return duty_cycle;
}

// Fan Speed Control Function
void update_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Data Logging Function
void log_data(time_t timestamp, float temperature, int duty_cycle) {
    log_buffer[buffer_index].timestamp = timestamp;
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(FAN_GPIO, DUTY_RANGE);

    // Initialize fan speed to 0%
    update_fan_speed(0);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) {
            // Calculate duty cycle
            int duty_cycle = calculate_duty_cycle(temperature);

            // Update fan speed
            update_fan_speed(duty_cycle);

            // Get timestamp
            time_t now = time(NULL);

            // Log data
            log_data(now, temperature, duty_cycle);

            // Print data
            printf("Timestamp: %ld, Temperature: %.2f, Duty Cycle: %d\n", now, temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping update.\n");
        }

        // Wait 1 second
        sleep(1);
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print the full contents of the circular buffer
    printf("Circular Buffer Contents:\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&log_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("  %s, Temperature: %.2f, Duty Cycle: %d\n", timestamp_str, log_buffer[index].temperature, log_buffer[index].duty_cycle);
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

