#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_TEMP_MSB 0xFA
#define BME280_REG_PRESSURE_MSB 0xF7
#define BME280_REG_HUMIDITY_MSB 0xFD
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_CALIB_00 0x88

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

// Global variables
int i2c_handle;
FILE *log_file;
struct bme280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int bme280_init(int i2c_handle);
int bme280_read_calibration_data(int i2c_handle, struct bme280_calib_data *calib);
int bme280_read_data(int i2c_handle, float *temperature, float *humidity, float *pressure);
int bme280_verify_chip_id(int i2c_handle);
int bme280_log_data(float temperature, float humidity, float pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// BME280 initialization function
int bme280_init(int i2c_handle) {
    // Check chip ID
    if (bme280_verify_chip_id(i2c_handle) != 0) {
        fprintf(stderr, "Error: Invalid chip ID\n");
        return -1;
    }

    // Read calibration data
    if (bme280_read_calibration_data(i2c_handle, &calib) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to write humidity control register\n");
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and mode to normal
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write control measurement register\n");
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (i2cWriteByteData(i2c_handle, BME280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }

    return 0;
}

// BME280 read calibration data function
int bme280_read_calibration_data(int i2c_handle, struct bme280_calib_data *calib) {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)data, 26) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data block 1\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);
    calib->dig_H1 = data[25];

    uint8_t data_h[7];
    if (i2cReadI2CBlockData(i2c_handle, 0xE1, (char *)data_h, 7) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data block 2\n");
        return -1;
    }

    calib->dig_H2 = (int16_t)data_h[0] | ((int16_t)data_h[1] << 8);
    calib->dig_H3 = data_h[2];
    calib->dig_H4 = (int16_t)((data_h[3] << 4) | (data_h[4] & 0x0F));
    calib->dig_H5 = (int16_t)((data_h[5] << 4) | ((data_h[4] >> 4) & 0x0F));
    calib->dig_H6 = (int8_t)data_h[6];

    return 0;
}

// BME280 read data function
int bme280_read_data(int i2c_handle, float *temperature, float *humidity, float *pressure) {
    uint8_t data[8];
    int32_t raw_temp, raw_pressure, raw_humidity;

    if (i2cReadI2CBlockData(i2c_handle, BME280_REG_PRESSURE_MSB, (char *)data, 8) < 0) {
        fprintf(stderr, "Error: Failed to read data block\n");
        return -1;
    }

    raw_pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    raw_temp = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;
    raw_humidity = (int32_t)data[6] << 8 | (int32_t)data[7];

    // Temperature compensation
    double var1 = (raw_temp / 16384.0 - calib.dig_T1 / 1024.0) * calib.dig_T2;
    double var2 = ((raw_temp / 131072.0 - calib.dig_T1 / 8192.0) * (raw_temp / 131072.0 - calib.dig_T1 / 8192.0)) * calib.dig_T3;
    double t_fine = var1 + var2;
    *temperature = (t_fine / 5120.0);

    // Pressure compensation
    double var3 = (t_fine / 2.0) - 64000.0;
    double var4 = var3 * var3 * calib.dig_P6 / 32768.0;
    double var5 = var4 + var3 * calib.dig_P5 * 2.0;
    double var6 = (var5 / 4.0) + (calib.dig_P4 * 65536.0);
    double var7 = calib.dig_P3 * var3 * var3 / 524288.0;
    double var8 = calib.dig_P2 * var3 / 524288.0;
    double var9 = (1.0 + var7 + var8) * calib.dig_P1;
    *pressure = 1048576.0 - raw_pressure;
    *pressure = (*pressure - var6 / 4096.0) * 6250.0 / var9;
    var3 = calib.dig_P9 * (*pressure) * (*pressure) / 2147483648.0;
    var4 = (*pressure) * calib.dig_P8 / 32768.0;
    *pressure = *pressure + (var3 + var4 + calib.dig_P7) / 16.0;

    // Humidity compensation
    double var_H = (t_fine - 76800.0);
    var_H = (raw_humidity - (calib.dig_H4 * 64.0 + calib.dig_H5 / 16384.0 * var_H)) * (calib.dig_H2 / 65536.0 * (1.0 + calib.dig_H6 / 67108864.0 * var_H * (1.0 + calib.dig_H3 / 67108864.0 * var_H)));
    *humidity = var_H * (1.0 - calib.dig_H1 * var_H / 524288.0);
    if (*humidity > 100.0)
        *humidity = 100.0;
    else if (*humidity < 0.0)
        *humidity = 0.0;

    return 0;
}

// BME280 verify chip ID function
int bme280_verify_chip_id(int i2c_handle) {
    uint8_t chip_id;
    if (i2cReadByteData(i2c_handle, BME280_REG_CHIPID) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID\n");
        return -1;
    }
    chip_id = i2cReadByteData(i2c_handle, BME280_REG_CHIPID);
    if (chip_id != 0x60) {
        fprintf(stderr, "Error: Incorrect chip ID: 0x%x\n", chip_id);
        return -1;
    }
    return 0;
}

// BME280 log data function
