#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// GPIO pin for alert
#define ALERT_GPIO 24

// Circular buffer size (60 seconds)
#define BUFFER_SIZE 60

// Structure to hold BMP180 calibration data
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

// Structure to hold pressure readings and timestamps
typedef struct {
    time_t timestamp;
    float pressure;
} pressure_reading_t;

// Global variables
int i2c_handle;
bmp180_calibration_data_t calibration_data;
pressure_reading_t pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;
int running = 1;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *cal_data);
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_pressure(int32_t raw_temp, int32_t raw_pressure, bmp180_calibration_data_t cal_data);
void add_reading(float pressure);
float calculate_rolling_average();
void check_alert(float current_pressure, float average_pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, BMP180 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *cal_data) {
    char data[22];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, data, 22) != 22) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    cal_data->ac1 = (data[0] << 8) | data[1];
    cal_data->ac2 = (data[2] << 8) | data[3];
    cal_data->ac3 = (data[4] << 8) | data[5];
    cal_data->ac4 = (data[6] << 8) | data[7];
    cal_data->ac5 = (data[8] << 8) | data[9];
    cal_data->ac6 = (data[10] << 8) | data[11];
    cal_data->b1 = (data[12] << 8) | data[13];
    cal_data->b2 = (data[14] << 8) | data[15];
    cal_data->mb = (data[16] << 8) | data[17];
    cal_data->mc = (data[18] << 8) | data[19];
    cal_data->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature value
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    buf[0] = BMP180_CMD_TEMP;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing temperature command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for temperature read\n");
        return -1;
    }
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    *raw_temp = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure value
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    buf[0] = BMP180_CMD_PRESSURE0;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }
    gpioDelay(5000); // Wait 5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for pressure read\n");
        return -1;
    }
    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - 0); // Oss = 0
    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int32_t raw_temp, int32_t raw_pressure, bmp180_calibration_data_t cal_data) {
    int32_t X1 = ((raw_temp - (int32_t)cal_data.ac6) * (int32_t)cal_data.ac5) >> 15;
    int32_t X2 = ((int32_t)cal_data.mc << 11) / (X1 + cal_data.md);
    int32_t B5 = X1 + X2;
    int32_t B6 = B5 - 4000;
    X1 = ((int32_t)cal_data.b2 * (B6 * B6) >> 12) >> 11;
    X2 = ((int32_t)cal_data.ac2 * B6) >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((int32_t)cal_data.ac1 * 4 + X3) << 0);
    X1 = ((int32_t)cal_data.ac3 * B6) >> 13;
    X2 = ((int32_t)cal_data.b1 * (B6 * B6) >> 12) >> 16;
    int32_t X3_pressure = ((X1 + X2) + 2) >> 2;
    int32_t B4 = ((int32_t)cal_data.ac4 * (X3_pressure + 32768)) >> 15;
    int32_t B7 = ((int32_t)raw_pressure - B3) * (50000 >> 0);
    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure / 100.0; // Convert to hPa
}

// Function to add a pressure reading to the circular buffer
void add_reading(float pressure) {
    pressure_buffer[buffer_index].timestamp = time(NULL);
    pressure_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the rolling average of pressure readings
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += pressure_buffer[i].pressure;
    }
    return sum / BUFFER_SIZE;
}

// Function to check for pressure deviations and trigger an alert
void check_alert(float current_pressure, float average_pressure) {
    float deviation = fabs(current_pressure - average_pressure);
    if (deviation > 5.0) {
        gpioWrite(ALERT_GPIO, 1); // Assert alert
        fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Average: %.2f hPa\n", current_pressure, average_pressure);
    } else {
        gpioWrite(ALERT_GPIO, 0); // De-assert alert
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(ALERT_GPIO, 0); // Ensure alert is de-asserted
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure it starts LOW

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up timer function
    gpioSetTimerFuncEx(0, 50, (gpioTimerFuncEx_t)timer_callback, NULL);

    // Main loop
    while (running) {
        int32_t raw_temp, raw_pressure;
        float pressure;

        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            // Calculate pressure
            pressure = calculate_pressure(raw_temp, raw_pressure, calibration_data);

            // Add reading to circular buffer
            add_reading(pressure);

            // Calculate rolling average
            float average_pressure = calculate_rolling_average();

            // Check for alert
            check_alert(pressure, average_pressure);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Clean up and exit
    cleanup();
    return 0;
}

// Timer callback function
void timer_callback() {
    // Read raw temperature and pressure
    int32_t raw_temp, raw_pressure;
    float pressure;

