void timer_callback()
{
    int32_t ut, up;
    double temperature, pressure;

    ut = read_raw_temperature();
    up = read_raw_pressure();

    if (ut == -1 || up == -1) {
        fprintf(stderr, "Error reading temperature or pressure. Skipping logging.\n");
        return;
    }

    temperature = calculate_temperature(ut);
    pressure = calculate_pressure(up, ut);

    log_data(temperature, pressure);
}

// Signal handler function
void signal_handler(int signal)
{
    fprintf(stderr, "Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c()
{
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, BMP180 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("bmp180_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer interrupt (500ms)
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL); // Timer 0, every 500ms

    // Main loop (keep the program running until a signal is received)
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Clean up
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

