#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_GPIO 18
#define PWM_FREQUENCY 25000
#define PWM_RANGE 255
#define LOG_FILE "fan_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping...\n", signal);
}

float read_cpu_temperature() {
    FILE *fp;
    int temp_raw;
    float temperature;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_raw) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temperature = (float)temp_raw / 1000.0;
    return temperature;
}

int map_temperature_to_duty_cycle(float temperature) {
    if (temperature < 40.0) {
        return 0;
    } else if (temperature > 70.0) {
        return PWM_RANGE;
    } else {
        return (int)((temperature - 40.0) * (PWM_RANGE / (70.0 - 40.0)));
    }
}

int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    gpioPWM(PWM_GPIO, duty_cycle);
    return 0;
}

int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f°C, Duty Cycle: %d%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider adding a delay here to avoid flooding the console with errors
        } else {
            int duty_cycle = map_temperature_to_duty_cycle(temperature);
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed\n");
            }
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(5);
    }

    gpioPWM(PWM_GPIO, 0); // Stop the fan
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

