#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_ID 0xD0
#define BMP280_REG_CALIB_00 0x88

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_fd;
int bmp280_address = BMP280_ADDR_1;
bmp280_calib_data calib;
FILE *weather_data_file = NULL;

// Function prototypes
int bmp280_init(int i2c_fd, bmp280_calib_data *calib);
int bmp280_read_calibration_data(int i2c_fd, bmp280_calib_data *calib);
int bmp280_read_raw_data(int i2c_fd, int32_t *temperature, int32_t *pressure);
double bmp280_compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib);
