void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (weather_data_file != NULL) {
        fclose(weather_data_file);
    }
    gpioTerminate();
    exit(0);
}

// BMP280 initialization function
int bmp280_init(int i2c_fd, bmp280_calib_data *calib) {
    // Check the device ID
    int chip_id = i2cReadByteData(i2c_fd, BMP280_REG_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%x\n", chip_id);
        return -1;
    }

    // Read calibration data
    if (bmp280_read_calibration_data(i2c_fd, calib) != 0) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }

    // Set forced mode
    if (bmp280_set_forced_mode(i2c_fd) != 0) {
        fprintf(stderr, "Error: Failed to set forced mode\n");
        return -1;
    }

    return 0;
}

// BMP280 read calibration data function
int bmp280_read_calibration_data(int i2c_fd, bmp280_calib_data *calib) {
    uint8_t data[26];
    if (i2cReadI2CBlockData(i2c_fd, BMP280_REG_CALIB_00, (char *)data, 26) != 26) {
        fprintf(stderr, "Error: Failed to read calibration data block 1\n");
        return -1;
    }

    calib->dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib->dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib->dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib->dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib->dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib->dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib->dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib->dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib->dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib->dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib->dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib->dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// BMP280 read raw data function
int bmp280_read_raw_data(int i2c_fd, int32_t *temperature, int32_t *pressure) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_fd, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }

    *pressure = (int32_t)data[0] << 12 | (int32_t)data[1] << 4 | (int32_t)data[2] >> 4;
    *temperature = (int32_t)data[3] << 12 | (int32_t)data[4] << 4 | (int32_t)data[5] >> 4;

    return 0;
}

// BMP280 compensate temperature function
double bmp280_compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib) {
    double var1, var2, T;
    var1 = (((double)raw_temperature) / 16384.0 - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temperature) / 131072.0 - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    double t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// BMP280 compensate pressure function
double bmp280_compensate_pressure(int32_t raw_pressure, double t_fine, bmp280_calib_data calib) {
    double var1, var2, p;
    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);
    if (var1 == 0)
    {
        return 0;
    }
    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;
    return p;
}

// BMP280 set forced mode function
int bmp280_set_forced_mode(int i2c_fd) {
    uint8_t config = 0b00100011; // Oversampling x1, Normal mode
    if (i2cWriteByteData(i2c_fd, BMP280_REG_CTRL_MEAS, config) != 0) {
        fprintf(stderr, "Error: Failed to write to CTRL_MEAS register\n");
        return -1;
    }
    return 0;
}

// BMP280 read data function
int bmp280_read_data(int i2c_fd, double *temperature, double *pressure) {
    int32_t raw_temperature, raw_pressure;

    if (bmp280_read_raw_data(i2c_fd, &raw_temperature, &raw_pressure) != 0) {
        fprintf(stderr, "Error: Failed to read raw data\n");
        return -1;
    }

    *temperature = bmp280_compensate_temperature(raw_temperature, calib);
    *pressure = bmp280_compensate_pressure(raw_pressure, *temperature, calib);

    return 0;
}

// Log data function
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(weather_data_file, "%s, Temperature: %.2f \u00b0C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(weather_data_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, bmp280_address) < 0) {
        fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (bmp280_init(i2c_fd, &calib) != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open weather_data.txt file
    weather_data_file = fopen("weather_data.txt", "a");
    if (weather_data_file == NULL) {
        fprintf(stderr, "Error: Could not open weather_data.txt: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
