#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define LED_GPIO 18
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL_SEC 1
#define TEMPERATURE_THRESHOLD 28.0

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
double temperature_sum = 0.0;
pthread_mutex_t buffer_mutex;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_temperature(double *temperature);
void update_circular_buffer(double temperature);
double calculate_running_average();
void control_led(double average_temperature);
void *sensor_monitoring_thread(void *arg);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    double temperature;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from the LM75 sensor
int read_temperature(double *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature (see LM75 datasheet)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (double)raw_temp * 0.125; // Each bit is 0.125 degrees C

    return 0;
}

// Function to update the circular buffer
void update_circular_buffer(double temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[0] = temperature; // Initialize the first element
    for (int i = 1; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = temperature_buffer[i - 1];
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
double calculate_running_average() {
    pthread_mutex_lock(&buffer_mutex);
    double sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Function to control the LED based on the average temperature
void control_led(double average_temperature) {
    if (average_temperature > TEMPERATURE_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Thread function for sensor monitoring
void *sensor_monitoring_thread(void *arg) {
    while (program_running) {
        double temperature;
        if (read_temperature(&temperature) == 0) {
            update_circular_buffer(temperature);
            temperature_sum += temperature;
            pthread_mutex_lock(&buffer_mutex);
            temperature_buffer[0] = temperature; // Update the first element
            for (int i = 1; i < BUFFER_SIZE; i++) {
                temperature_buffer[i] = temperature_buffer[i - 1];
            }
            pthread_mutex_unlock(&buffer_mutex);
            pthread_mutex_lock(&buffer_mutex);
            temperature_sum -= temperature_buffer[BUFFER_SIZE - 1];
            temperature_buffer[BUFFER_SIZE - 1] = 0.0; // Remove the oldest value
            pthread_mutex_unlock(&buffer_mutex);
            pthread_mutex_lock(&buffer_mutex);
            temperature_buffer[0] = 0.0; // Reset the buffer
            pthread_mutex_unlock(&buffer_mutex);
            pthread_mutex_lock(&buffer_mutex);
            double average_temperature = calculate_running_average();
            control_led(average_temperature);
            printf("Temperature: %.2f°C, Average: %.2f°C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Error reading temperature. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                program_running = 0; // Stop the thread
            }
        }
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 1 second
    }
    return NULL;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    pthread_mutex_destroy(&buffer_mutex);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially turn off the LED

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create sensor monitoring thread
    pthread_t sensor_thread;
    if (pthread_create(&sensor_thread, NULL, sensor_monitoring_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create sensor monitoring thread\n");
        cleanup();
        return 1;
    }

    // Main loop (wait for signal)
    while (program_running) {
        gpioDelay(100000); // Sleep for 0.1 seconds
    }

    // Wait for sensor thread to finish
    pthread_join(sensor_thread, NULL);

    // Cleanup and exit
    cleanup();
    return 0;
}

