double read_rtd_resistance() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int result;
    double rtd_resistance;

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    tx_buffer[0] = 0x01; // Read RTD MSB
    tx_buffer[1] = 0x00; // Dummy byte for reading MSB
    tx_buffer[2] = 0x00; // Dummy byte for reading LSB

    result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        log_error("SPI transfer failed");
        return -1.0; // Indicate error
    }

    // Combine MSB and LSB to get RTD resistance
    rtd_resistance = ((double)((rx_buffer[1] << 8) | rx_buffer[2])) * 0.003125; // 0.3125 V/ohm

    return rtd_resistance;
}

// Function to calculate temperature from RTD resistance
double calculate_temperature(double rtd_resistance) {
    double r0 = 430.0; // Reference resistor value
    double rs = rtd_resistance / 100.0; // RTD resistance divided by 100 (nominal 100 ohms)
    double temperature = (rs - r0) / r0 * 100.0;
    return temperature;
}

