        target_temperature = 25.0;
        Kp = 1.0;
        Ki = 0.1;
        Kd = 0.01;
        return;
    }

    json_t *target_temp = json_object_get(root, "target_temperature");
    if (target_temp) {
        target_temperature = json_real_value(target_temp);
    } else {
        fprintf(stderr, "Warning: 'target_temperature' not found in config file, using default value.\n");
    }

    json_t *Kp_json = json_object_get(root, "Kp");
    if (Kp_json) {
        Kp = json_real_value(Kp_json);
    } else {
        fprintf(stderr, "Warning: 'Kp' not found in config file, using default value.\n");
    }

    json_t *Ki_json = json_object_get(root, "Ki");
    if (Ki_json) {
        Ki = json_real_value(Ki_json);
    } else {
        fprintf(stderr, "Warning: 'Ki' not found in config file, using default value.\n");
    }

    json_t *Kd_json = json_object_get(root, "Kd");
    if (Kd_json) {
