        // Failsafe
        if (temperature > 80.0) {
            log_error("Temperature exceeds 80°C, shutting down heater.");
            set_heater_pwm(0.0);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }

        // Log data
