#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// Calibration data structure
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data;

// Global variables
int i2c_handle;
bmp180_calibration_data calibration;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, bmp180_calibration_data *calibration);
int read_raw_temperature(int i2c_handle);
int read_raw_pressure(int i2c_handle, int oss);
double calculate_temperature(int raw_temp, bmp180_calibration_data calibration);
double calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data calibration, int oss);
int check_breach(double temperature, double pressure);
int log_breach(double temperature, double pressure);
void signal_handler(int signal);

// Function to read calibration data from BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data *calibration) {
    unsigned char data[22];
    int result;

    // Read calibration data from registers 0xAA to 0xBF
    result = i2cReadI2CBlockData(i2c_handle, 0xAA, (char *)data, 22);
    if (result != 22) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration->ac1 = (data[0] << 8) | data[1];
    calibration->ac2 = (data[2] << 8) | data[3];
    calibration->ac3 = (data[4] << 8) | data[5];
    calibration->ac4 = (data[6] << 8) | data[7];
    calibration->ac5 = (data[8] << 8) | data[9];
    calibration->ac6 = (data[10] << 8) | data[11];
    calibration->b1 = (data[12] << 8) | data[13];
    calibration->b2 = (data[14] << 8) | data[15];
    calibration->mb = (data[16] << 8) | data[17];
    calibration->mc = (data[18] << 8) | data[19];
    calibration->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data from BMP180
int read_raw_temperature(int i2c_handle) {
    unsigned char data[2];
    int result;

    // Write temperature conversion command
    result = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature conversion command: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 4.5ms)
    gpioDelay(5000); // 5ms

    // Read raw temperature data
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature data: %d\n", result);
        return -1;
    }

    return (data[0] << 8) | data[1];
}

// Function to read raw pressure data from BMP180
int read_raw_pressure(int i2c_handle, int oss) {
    unsigned char data[3];
    int result;

    // Write pressure conversion command
    result = i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE0 + (oss << 6));
    if (result != 0) {
        fprintf(stderr, "Error writing pressure conversion command: %d\n", result);
        return -1;
    }

    // Wait for conversion (2.5ms for OSS = 0, 5.5ms for OSS = 1, 11ms for OSS = 2, 21ms for OSS = 3)
    gpioDelay(1000); // 1ms

    // Read raw pressure data
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure data: %d\n", result);
        return -1;
    }

    return ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - oss);
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp, bmp180_calibration_data calibration) {
    long x1, x2, b5;
    double temperature;

    x1 = (((long)raw_temp - (long)calibration.ac6) * (long)calibration.ac5) >> 15;
    x2 = ((long)calibration.mc << 11) / (x1 + calibration.md);
    b5 = x1 + x2;
    temperature = ((b5 + 8) >> 4) / 10.0;

    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int raw_pressure, int raw_temp, bmp180_calibration_data calibration, int oss) {
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;
    double pressure;

    long ut = ((long)raw_temp - (long)calibration.ac6) * ((long)calibration.ac5) >> 15;
    long up = ((long)calibration.b2 * ((ut * ut) >> 12)) >> 11;
    up = up + ((long)calibration.b1 * ut) >> 11;
    long b3_long = (((long)calibration.ac3 * ut) >> 13) + ((long)calibration.ac2 * up) >> 13;
    long b6_long = ((long)calibration.ac4 * (up + ((long)calibration.ac1 * 4096))) >> 15;
    b6_long = b6_long - ((b3_long * (b3_long * (b3_long * 4096)) >> 21) >> 13);
    b6_long = (b6_long * 3125) >> 13;
    b7 = ((unsigned long)b6_long + 2) >> 2;
    b4 = ((unsigned long)calibration.ac1 * (unsigned long)(up + ((long)calibration.ac1 * 4096))) >> 15;
    b7 = b7 - (b4 * 4096) >> 4;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b6_long;
    } else {
        p = (b7 / b6_long) * 2;
    }
    x1 = (p >> 8) - 4000;
    x2 = (p >> 8) - 8192;
    x3 = (x1 * x2) >> 12;
    b3 = x1 + x3;
    x1 = (b3 >> 15) * (b3 >> 15);
    x2 = (x1 >> 12) * (b3 >> 12);
    x3 = (x2 >> 12) * (b3 >> 12);
    b3 = (b3 + x1 + x2 + x3) >> 12;
    x1 = (calibration.b2 * (b3 >> 13)) >> 11;
    x2 = (calibration.ac2 * (b3 >> 13)) >> 13;
    x3 = ((x1 + x2) + 2) >> 2;
    pressure = (double)x3;

    return pressure;
}

// Function to check if temperature or pressure exceeds the threshold
int check_breach(double temperature, double pressure) {
    return (temperature > 30.0 || pressure < 950.0);
}

// Function to log breach to file
int log_breach(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Temperature: %.2f°C, Pressure: %.2f hPa\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int raw_temp, raw_pressure;
    double temperature, pressure;
    int breach_detected;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration) != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("breach_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        raw_temp = read_raw_temperature(i2c_handle);
        if (raw_temp < 0) {
            fprintf(stderr, "Error reading raw temperature\n");
            continue; // Skip to the next iteration
        }

        raw_pressure = read_raw_pressure(i2c_handle, 3); // OSS = 3
        if (raw_pressure < 0) {
            fprintf(stderr, "Error reading raw pressure\n");
            continue; // Skip to the next iteration
        }

        // Calculate temperature and pressure
        temperature = calculate_temperature(raw_temp, calibration);
        pressure = calculate_pressure(raw_pressure, raw_temp, calibration, 3);

        // Check for breach
        breach_detected = check_breach(temperature, pressure);

        // Log breach if detected
        if (breach_detected) {
            log_breach(temperature, pressure);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

