        fprintf(stderr, "Error writing pressure command\n");
        return -1;
    }

    switch (oss) {
        case 0: gpioDelay(5000); break;
        case 1: gpioDelay(7500); break;
        case 2: gpioDelay(13500); break;
        case 3: gpioDelay(25500); break;
        default: fprintf(stderr, "Invalid OSS value\n"); return -1;
    }

    uint8_t buffer[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buffer, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    return ((buffer[0] << 16) | (buffer[1] << 8) | buffer[2]) >> (8 - oss);
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature, bmp180_calibration_data_t calibration_data) {
    long X1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
