float calculate_pressure(int raw_pressure, int raw_temperature, bmp180_calibration_data_t calibration_data, int oss) {
    long X1 = ((long)raw_temperature - (long)calibration_data.ac6) * ((long)calibration_data.ac5) / pow(2, 15);
    long X2 = ((long)calibration_data.mc * pow(2, 11)) / (X1 + calibration_data.md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)calibration_data.b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)calibration_data.ac2 * B6) / pow(2, 11);
    long B3 = (((long)calibration_data.ac1 * 4 + X3 + X4 + 2) / 4);

    unsigned long X1_pressure = ((unsigned long)calibration_data.ac3 * B6) / pow(2, 13);
    unsigned long X2_pressure = ((unsigned long)calibration_data.b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
