#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define HEATER_GPIO 17
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0
#define LOG_FILE "heater_log.csv"
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_max31855(int spi_handle, float *temperature);
int set_heater_duty_cycle(int gpio_pin, int duty_cycle);
float calculate_pi_controller(float setpoint, float actual_temperature, float *integral, float *previous_error, float dt);
void log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int spi_read_max31855(int spi_handle, float *temperature) {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1; // Indicate failure
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -2; // Indicate fault
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to ground\n");
        return -3; // Indicate fault
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -4; // Indicate fault
    }

    // Extract temperature data (14-bit, signed)
    int16_t raw_temp = ((data[0] << 6) | (data[1] >> 2)) >> 4;
    if (raw_temp & 0x2000) {
        raw_temp |= 0xC000; // Sign extend
    }

    *temperature = raw_temp * 0.25;
    return 0; // Indicate success
}

// Function to set heater duty cycle using PWM
int set_heater_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1; // Indicate failure
    }

    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM duty cycle\n");
        return -2; // Indicate failure
    }
    return 0; // Indicate success
}

// PI controller function
float calculate_pi_controller(float setpoint, float actual_temperature, float *integral, float *previous_error, float dt) {
    float error = setpoint - actual_temperature;
    *integral += error * dt;
    float derivative = (error - *previous_error) / dt;
    float output = (*integral) + (*previous_error) + derivative;
    *previous_error = error;
    return output;
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float temperature, integral = 0.0, previous_error = 0.0;
    int duty_cycle;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set heater GPIO as output
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read temperature
        result = spi_read_max31855(spi_handle, &temperature);
        if (result != 0) {
            fprintf(stderr, "Failed to read temperature, setting duty cycle to 0%%\n");
            duty_cycle = 0;
        } else {
            // Calculate PI controller output
            duty_cycle = calculate_pi_controller(TARGET_TEMPERATURE, temperature, &integral, &previous_error, 0.1); // 0.1 second interval

            // Set duty cycle
            if (set_heater_duty_cycle(HEATER_GPIO, (int)duty_cycle) != 0) {
                fprintf(stderr, "Failed to set duty cycle, setting duty cycle to 0%%\n");
                duty_cycle = 0;
            }
        }

        // Log data
        log_data(temperature, duty_cycle);

        // Sleep for 1 second
        gpioDelay(1000);
    }

    // Shutdown sequence
    fprintf(stderr, "Shutting down...\n");
    set_heater_duty_cycle(HEATER_GPIO, 0); // Turn off heater
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

