#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_SEC 5
#define JSON_BUFFER_SIZE 256

// Global variables
static volatile int running = 1;
static int sockfd = -1;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} sensor_data_t;

// Function prototypes
int init_gpio();
int read_dht22(sensor_data_t *data);
int validate_checksum(const unsigned char *data, int len);
int post_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        running = 0;
    } else if (signal == SIGTERM) {
        printf("Caught SIGTERM, exiting gracefully.\n");
        running = 0;
    }
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DHT22_GPIO, PI_OUTPUT); // Set GPIO as output
    gpioWrite(DHT22_GPIO, 1); // Set high initially
    return 0;
}

// Read DHT22 sensor data
int read_dht22(sensor_data_t *data) {
    unsigned char data_buffer[5] = {0};
    int i, j;

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    // Set GPIO as input
    gpioSetMode(DHT22_GPIO, PI_INPUT);
    gpioDelay(1); // Wait for the sensor to pull the line low

    // Read data
    for (i = 0; i < 40; i++) {
        int count = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            count++;
            gpioDelay(1); // Delay 1us
            if (count > 200) {
                fprintf(stderr, "DHT22 timeout waiting for HIGH\n");
                return -1;
            }
        }

        count = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            count++;
            gpioDelay(1); // Delay 1us
            if (count > 200) {
                fprintf(stderr, "DHT22 timeout waiting for LOW\n");
                return -1;
            }
        }

        if (count > 40) {
            data_buffer[i / 8] <<= 1;
            if (count > 16) {
                data_buffer[i / 8] |= 1;
            }
        }
    }

    // Validate checksum
    if (!validate_checksum(data_buffer, 40)) {
        fprintf(stderr, "DHT22 checksum validation failed\n");
        return -1;
    }

    // Convert data
    data->humidity = (float)((data_buffer[0] << 8) | data_buffer[1]) / 10.0;
    data->temperature = (float)(((data_buffer[2] & 0x7F) << 8) | data_buffer[3]) / 10.0;
    if (data_buffer[2] & 0x80) {
        data->temperature *= -1;
    }
    data->valid = 1;

    return 0;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0;
    for (int i = 0; i < len - 1; i++) {
        checksum += data[i];
    }
    unsigned char calculated_checksum = 0;
    for (int i = 0; i < len; i++) {
        calculated_checksum += data[i];
    }
    return (calculated_checksum == checksum);
}

// Post data to server
int post_data(const sensor_data_t *data) {
    char json_string[JSON_BUFFER_SIZE];
    int retries = 0;

    snprintf(json_string, JSON_BUFFER_SIZE, "{\"temperature\": %.1f, \"humidity\": %.1f}", data->temperature, data->humidity);

    while (retries < MAX_RETRIES) {
        if (sendto(sockfd, json_string, strlen(json_string), 0, (struct sockaddr *) &server_addr, sizeof(server_addr)) < 0) {
            perror("sendto failed");
            retries++;
            gpioDelay(RETRY_DELAY_SEC * 1000); // Delay in milliseconds
        } else {
            printf("Data sent successfully.\n");
            return 0; // Success
        }
    }

    fprintf(stderr, "Failed to post data after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (sockfd != -1) {
        close(sockfd);
    }
    gpioTerminate();
}

int main() {
    sensor_data_t sensor_data;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Create socket
    struct sockaddr_in server_addr;
    sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        cleanup();
        return 1;
    }

    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // HTTP port
    if (inet_pton(AF_INET, SERVER_URL, &server_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        result = read_dht22(&sensor_data);
        if (result == 0) {
            if (post_data(&sensor_data) != 0) {
                fprintf(stderr, "Failed to post data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 sensor.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

