    delay(26); // Wait 25.5ms
    *raw_pressure = wiringPiI2CReadReg16(i2c_fd, BMP180_REG_MSB);
    if (*raw_pressure == -1) return -1;
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int raw_pressure, double temperature) {
    long X1 = ((long)temperature * 10) - 4000;
    long X2 = X1 * X1 / pow(2, 12);
    long X3 = X2 + (X1 * (long)b2) / pow(2, 11);
    long B5 = ((long)ac2 * 4 + X3) / 4;
    long B6 = X1 * (long)ac1 / pow(2, 11);
    long X4 = ((long)b1 * (X1 * (long)ac3 / pow(2, 13) + 2)) / pow(2, 2);
    long X5 = ((long)ac4 * (X1 * (long)ac3 / pow(2, 13) + 2)) / pow(2, 2);
    long B3 = ((long)ac3 * (X1 * (long)ac3 / pow(2, 13) + 2)) / pow(2, 2);
    long B4 = B5 + X4 + X5;
    long B7 = ((long)ac1 * (long)(B6 + 32768)) / pow(2, 15);
    long p;
    if (B7 < 0x80000000)
        p = (B7 * 2) / B4;
    else
        p = (B7 / B4) * 2;
    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure;
