    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    if (init_i2c() == -1) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return 1;
    }

    // Set interrupt pin as input with pull-up resistor
    pinMode(INTERRUPT_PIN, INPUT);
    pullUpDnControl(INTERRUPT_PIN, PUD_UP);

    // Set up interrupt handler
    if (wiringPiISR(INTERRUPT_PIN, INT_EDGE_FALLING, &interrupt_handler) < 0) {
