        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("BMP180 data logger started. Press Ctrl+C to exit.\n");

    int raw_temp, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temp) == -1 || read_raw_pressure(&raw_pressure) == -1) {
                fprintf(stderr, "Error reading sensor data\n");
