#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <jansson.h>
#include <time.h>

// Configuration
#define DEFAULT_API_URL "http://your-the-library-s-api-call.com/api/humidity"
#define DEFAULT_LOG_LEVEL 1
#define DEFAULT_RETRIES 3
#define DEFAULT_DELAY 10 // seconds

// DHT22 Constants
#define DHT22_START_BIT 0x06
#define DHT22_END_BIT 0x06
#define DHT22_CHECKSUM_BIT 0x00
#define DHT22_MAX_RETRIES 3
#define DHT22_RETRY_DELAY 2 // seconds

// Global Variables
static char *api_url = DEFAULT_API_URL;
static int log_level = DEFAULT_LOG_LEVEL;
static int retries = DEFAULT_RETRIES;
static int delay = DEFAULT_DELAY;
static volatile int running = 1;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Structure to hold the response from the DHT22 sensor
typedef struct {
    unsigned int data[40];
} DHT22Response;

// Structure to hold the configuration
typedef struct {
    char *api_url;
    int log_level;
    int retries;
    int delay;
} Config;

// Structure to hold the DHT22 response
typedef struct {
    unsigned int data[40];
} DHT22Response;

// Function prototypes
int init_gpio();
int read_dht22(DHT22Response *response);
int validate_checksum(DHT22Response *response);
int format_json(DHT22Data data, char *json_string);
int post_data(const char *json_string);
int handle_error(const char *message, int retry_count);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize the pigpio library
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Function to read data from the DHT22 sensor
int read_dht22(DHT22Response *response) {
    int i;
    unsigned int bit_count = 0;
    unsigned int data_buffer[40];

    // Send start signal
    gpioSetMode(4, PI_OUTPUT);
    gpioWrite(4, 0);
    gpioDelay(1); // 1ms
    gpioWrite(4, 1);
    gpioDelay(40); // 40us

    // Read data
    for (i = 0; i < 40; i++) {
        gpioSetMode(4, PI_INPUT);
        while (gpioRead(4) == 0) {
            bit_count++;
            if (bit_count > 1000) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for start bit");
                return -1;
            }
            gpioDelay(1); // 1us
        }

        while (gpioRead(4) == 1) {
            bit_count++;
            if (bit_count > 1000) {
                log_message(LOG_ERR, "DHT22: Timeout waiting for end bit");
                return -1;
            }
            gpioDelay(1); // 1us
        }

        data_buffer[i] = bit_count;
        bit_count = 0;
    }

    // Validate checksum
    if (!validate_checksum(response)) {
        log_message(LOG_ERR, "DHT22: Checksum validation failed");
        return -1;
    }

    // Convert data to humidity and temperature
    response->data[0] = DHT22_START_BIT | (response->data[0] << 8);
    response->data[1] = DHT22_START_BIT | (response->data[1] << 8);
    response->data[2] = DHT22_START_BIT | (response->data[2] << 8);
    response->data[3] = DHT22_START_BIT | (response->data[3] << 8);

    response->data[4] = DHT22_END_BIT | (response->data[4] << 8);
    response->data[5] = DHT22_END_BIT | (response->data[5] << 8);
    response->data[6] = DHT22_END_BIT | (response->data[6] << 8);
    response->data[7] = DHT22_END_BIT | (response->data[7] << 8);

    response->data[8] = DHT22_END_BIT | (response->data[8] << 8);
    response->data[9] = DHT22_END_BIT | (response->data[9] << 8);
    response->data[10] = DHT22_END_BIT | (response->data[10] << 8);
    response->data[11] = DHT22_END_BIT | (response->data[11] << 8);

    response->data[12] = DHT22_END_BIT | (response->data[12] << 8);
    response->data[13] = DHT22_END_BIT | (response->data[13] << 8);
    response->data[14] = DHT22_END_BIT | (response->data[14] << 8);
    response->data[15] = DHT22_END_BIT | (response->data[15] << 8);

    response->data[16] = DHT22_END_BIT | (response->data[16] << 8);
    response->data[17] = DHT22_END_BIT | (response->data[17] << 8);
    response->data[18] = DHT22_END_BIT | (response->data[18] << 8);
    response->data[19] = DHT22_END_BIT | (response->data[19] << 8);

    response->data[20] = DHT22_END_BIT | (response->data[20] << 8);
    response->data[21] = DHT22_END_BIT | (response->data[21] << 8);
    response->data[22] = DHT22_END_BIT | (response->data[22] << 8);
    response->data[23] = DHT22_END_BIT | (response->data[23] << 8);

    response->data[24] = DHT22_END_BIT | (response->data[24] << 8);
    response->data[25] = DHT22_END_BIT | (response->data[25] << 8);
    response->data[26] = DHT22_END_BIT | (response->data[26] << 8);
    response->data[27] = DHT22_END_BIT | (response->data[27] << 8);

    response->data[28] = DHT22_END_BIT | (response->data[28] << 8);
    response->data[29] = DHT22_END_BIT | (response->data[29] << 8);
    response->data[30] = DHT22_END_BIT | (response->data[30] << 8);
    response->data[31] = DHT22_END_BIT | (response->data[31] << 8);

    response->data[32] = DHT22_END_BIT | (response->data[32] << 8);
    response->data[33] = DHT22_END_BIT | (response->data[33] << 8);
    response->data[34] = DHT22_END_BIT | (response->data[34] << 8);
    response->data[35] = DHT22_END_BIT | (response->data[35] << 8);

    response->data[36] = DHT22_END_BIT | (response->data[36] << 8);
    response->data[37] = DHT22_END_BIT | (response->data[37] << 8);
    response->data[38] = DHT22_END_BIT | (response->data[38] << 8);
    response->data[39] = DHT22_END_BIT | (response->data[39] << 8);

    // Convert data to humidity and temperature
    response->humidity = (float)((response->data[0] << 8) | response->data[1]) / 10.0;
    response->temperature = (float)(((response->data[2] & 0x7F) << 8) | response->data[3]) / 10.0;
    if (response->data[2] & 0x80) {
        response->temperature *= -1;
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(DHT22Response *response) {
    unsigned int calculated_checksum = 0;
    for (int i = 0; i < 38; i++) {
        calculated_checksum += response->data[i];
    }
    return (calculated_checksum == response->data[38]);
}

// Function to format the data as JSON
int format_json(DHT22Data data, char *json_string) {
    json_t *root = json_object();
    json_object_set_new(root, "temperature", json_real(data.temperature));
    json_object_set_new(root, "humidity", json_real(data.humidity));

    int ret = json_dumps(root, json_string);
    json_decref(root);
    if (ret < 0) {
        log_message(LOG_ERR, "Failed to format JSON");
        return -1;
    }
    return 0;
}

// Function to post the data to the API endpoint
int post_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    int retries = 0;
    int delay_seconds = 0;

    while (retries < retries) {
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, api_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
            curl_easy_setopt(curl, CURLOPT_TIMEOUT, 10L); // Timeout after 10 seconds

            // Set the Content-Type header to application/json
            struct curl_slist *headers = NULL;
