#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"

// Structure to hold fan speed and state
typedef struct {
    int speed;
    int state;
} FanState;

// Global variable to track program state for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_temperature(float *temperature);
int read_fan_state(int *fan_state);
int set_fan_speed(int speed);
int validate_max_state(int max_state);
int log_event(const char *message);
void signal_handler(int signal);

// Function to read CPU temperature from file
int read_temperature(float *temperature) {
    FILE *fp;
    char buffer[10];
    int temp_milli;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening temperature file.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading temperature from file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &temp_milli) != 1) {
        log_event("Error parsing temperature from file.");
        return -1;
    }

    *temperature = (float)temp_milli / 1000.0;
    return 0;
}

// Function to read fan state from file
int read_fan_state(int *fan_state) {
    FILE *fp;
    char buffer[2];

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening fan state file.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading fan state from file.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", fan_state) != 1) {
        log_event("Error parsing fan state from file.");
        return -1;
    }

    return 0;
}

// Function to set fan speed
int set_fan_speed(int speed) {
    int max_state;
    int current_state;
    int diff;

    if (validate_max_state(max_state) != 0) {
        log_event("Error validating max_state.");
        return -1;
    }

    if (speed < 0 || speed > max_state) {
        log_event("Invalid fan speed.");
        return -1;
    }

    if (speed == 0) {
        current_state = 0;
        diff = max_state - current_state;
    } else {
        current_state = speed;
        diff = max_state - current_state;
    }

    if (write(FAN_FILE, &current_state, 1) != 1) {
        log_event("Error writing fan state.");
        return -1;
    }

    return 0;
}

// Function to validate max_state
int validate_max_state(int max_state) {
    FILE *fp;
    char buffer[2];

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening fan state file for validation.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading fan state for validation.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &max_state) != 1) {
        log_event("Error parsing max_state from file for validation.");
        return -1;
    }

    return 0;
}

// Function to log events to file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received shutdown signal. Shutting down...");
        program_running = 0;
        set_fan_speed(0); // Turn off the fan
    }
}

int main() {
    float temperature;
    int fan_state;
    int new_fan_state = 0; // Initialize fan state to off

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Fan control program started.");

    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            if (read_fan_state(&fan_state) == 0) {
                if (fan_state != new_fan_state) {
                    new_fan_state = fan_state;
                    if (set_fan_speed(new_fan_state) == 0) {
                        log_event("Fan speed set to " + new_fan_state);
                    } else {
                        log_event("Error setting fan speed.");
                    }
                }
            } else {
                log_event("Error reading fan state.");
            }
        } else {
            log_event("Error reading temperature.");
        }

        sleep(5);
    }

    log_event("Fan control program stopped.");

    return 0;
}

