        log_event("Error validating max_state.");
        return -1;
    }

    if (speed < 0 || speed > max_state) {
        log_event("Invalid fan speed.");
        return -1;
    }

    if (speed == 0) {
        current_state = 0;
        diff = max_state - current_state;
    } else {
        current_state = speed;
        diff = max_state - current_state;
    }

    if (write(FAN_FILE, &current_state, 1) != 1) {
        log_event("Error writing fan state.");
        return -1;
    }

    return 0;
}

// Function to validate max_state
int validate_max_state(int max_state) {
    FILE *fp;
    char buffer[2];

    fp = fopen(FAN_FILE, "r");
    if (fp == NULL) {
        log_event("Error opening fan state file for validation.");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        log_event("Error reading fan state for validation.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    if (sscanf(buffer, "%d", &max_state) != 1) {
        log_event("Error parsing max_state from file for validation.");
        return -1;
    }

    return 0;
}

// Function to log events to file
int log_event(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_event("Received shutdown signal. Shutting down...");
        program_running = 0;
        set_fan_speed(0); // Turn off the fan
    }
}

int main() {
    float temperature;
    int fan_state;
    int new_fan_state = 0; // Initialize fan state to off

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Fan control program started.");

    while (program_running) {
        if (read_temperature(&temperature) == 0) {
            if (read_fan_state(&fan_state) == 0) {
                if (fan_state != new_fan_state) {
                    new_fan_state = fan_state;
                    if (set_fan_speed(new_fan_state) == 0) {
                        log_event("Fan speed set to " + new_fan_state);
                    } else {
                        log_event("Error setting fan speed.");
                    }
                }
            } else {
                log_event("Error reading fan state.");
            }
        } else {
            log_event("Error reading temperature.");
        }

        sleep(5);
    }

    log_event("Fan control program stopped.");

    return 0;
}

