#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500kHz
#define MAX31855_DO 9
#define MAX31855_CLK 11
#define MAX31855_CS 8 // CE0
#define TARGET_TEMPERATURE 50.0
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01
#define LOG_FILE "heater_log.txt"
#define FLAILS_THRESHOLD 100.0 // 100°C
#define FLAILS_ACTION 0 // Disable heater
#define PWM_DUTY_CYCLE 0 // Disable heater

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// PID variables
double integral = 0.0;
double previous_error = 0.0;

// Function prototypes
int spi_read_max31855(int *raw_data);
double convert_raw_to_temperature(int raw_data);
double calculate_pid(double current_temperature, double target_temperature, double *integral, double previous_error);
void set_pwm_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();

// SPI read function for MAX31855
int spi_read_max31855(int *raw_data) {
    int handle;
    char tx_buf[4] = {0x00, 0x00, 0x00, 0x00}; // Dummy data to initiate read
    char rx_buf[4];

    handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Open SPI channel
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return -1;
    }

    if (spiXfer(handle, tx_buf, rx_buf, 4) != 0) {
        fprintf(stderr, "Error during SPI transfer\n");
        spiClose(handle);
        return -1;
    }

    spiClose(handle);

    // Check for fault bits
    if (rx_buf[3] & 0x01) {
        fprintf(stderr, "Open circuit fault detected\n");
        log_data(0.0, PWM_DUTY_CYCLE, FLAILS_ACTION);
        return -1; // Indicate error
    } else if (rx_buf[3] & 0x02) {
        fprintf(stderr, "Short to GND fault detected\n");
        log_data(0.0, PWM_DUTY_CYCLE, FLAILS_ACTION);
        return -1; // Indicate error
    } else if (rx_buf[3] & 0x04) {
        fprintf(stderr, "Short to VCC fault detected\n");
        log_data(0.0, PWM_DUTY_CYCLE, FLAILS_ACTION);
        return -1; // Indicate error
    }

    *raw_data = ((int)rx_buf[0] << 24) | ((int)rx_buf[1] << 16) | ((int)rx_buf[2] << 8) | (int)rx_buf[3];
    *raw_data = *raw_data >> 4; // Shift right by 4 bits

    return 0; // Success
}

// Temperature conversion function
double convert_raw_to_temperature(int raw_data) {
    // Extract thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask out fault bits
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend if negative
    }

    double temperature = thermocouple_data * 0.25;
    return temperature;
}

// PID calculation function
double calculate_pid(double current_temperature, double target_temperature, double *integral, double previous_error) {
    double error = target_temperature - current_temperature;
    *integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    previous_error = error;
    return output;
}

// PWM duty cycle setting function
void set_pwm_duty_cycle(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Data logging function
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    set_pwm_duty_cycle(PWM_DUTY_CYCLE); // Disable heater
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int raw_data;
    double temperature, pid_output;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read temperature from MAX31855
        if (spi_read_max31855(&raw_data) != 0) {
            fprintf(stderr, "Error reading temperature, disabling heater\n");
            set_pwm_duty_cycle(PWM_DUTY_CYCLE);
            log_data(0.0, PWM_DUTY_CYCLE, FLAILS_ACTION);
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Convert raw data to temperature
        temperature = convert_raw_to_temperature(raw_data);

        // Calculate PID output
        pid_output = calculate_pid(temperature, TARGET_TEMPERATURE, &integral, &previous_error);

        // Set PWM duty cycle
        set_pwm_duty_cycle(pid_output);

        // Log data
        log_data(temperature, pid_output, pid_output);

        // Failsafe check
        if (temperature > FLAILS_THRESHOLD || temperature < 0.0) {
            fprintf(stderr, "Temperature out of range, disabling heater\n");
            set_pwm_duty_cycle(PWM_DUTY_CYCLE);
            log_data(0.0, PWM_DUTY_CYCLE, FLAILS_ACTION);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

