#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define LOG_FILE "cooling_log.csv"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold program state
typedef struct {
    int fan_gpio;
    int pwm_frequency;
    char *log_file;
} ProgramState;

// Function prototypes
float read_cpu_temperature();
int map_temperature_to_duty_cycle(float temperature);
int set_fan_speed(int duty_cycle);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    set_fan_speed(0); // Turn off the fan
    gpioTerminate();   // Terminate pigpio
    exit(0);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    float temperature = 0.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fread(buffer, 1, sizeof(buffer) - 1, fp) <= 0) {
        perror("Error reading temperature file");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    buffer[sizeof(buffer) - 1] = '\0'; // Ensure null termination
    temperature = atof(buffer) / 1000.0; // Convert to Celsius

    return temperature;
}

// Function to map temperature to PWM duty cycle
int map_temperature_to_duty_cycle(float temperature) {
    if (temperature < 40.0) {
        return 0;
    } else if (temperature > 70.0) {
        return 100;
    } else {
        return (int)(((temperature - 40.0) / (70.0 - 40.0)) * 100.0);
    }
}

// Function to set fan speed using pigpio
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Duty cycle out of range (0-100)\n");
        return -1;
    }

    int pwm_value = (int)((duty_cycle / 100.0) * PWM_FREQUENCY);
    gpioPWM(FAN_GPIO, pwm_value); // Set PWM duty cycle
    return 0;
}

// Function to log data to a CSV file
int log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
    return 0;
}

int main() {
    ProgramState state = {FAN_GPIO, PWM_FREQUENCY, LOG_FILE};
    int duty_cycle;
    float temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(state.fan_gpio, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(state.fan_gpio, state.pwm_frequency);

    // Set PWM range (0-255)
    gpioSetPWMrange(state.fan_gpio, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature-controlled fan started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read CPU temperature
        temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
        } else {
            // Map temperature to duty cycle
            duty_cycle = map_temperature_to_duty_cycle(temperature);

            // Set fan speed
            if (set_fan_speed(duty_cycle) != 0) {
                fprintf(stderr, "Error setting fan speed.\n");
            }

            // Log data
            if (log_data(temperature, duty_cycle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Clean up and exit
    set_fan_speed(0); // Turn off the fan
    gpioTerminate();   // Terminate pigpio
    return 0;
}

