// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define log file path
#define LOG_FILE "flow_log.txt"

// Define retry count
#define RETRY_COUNT 3

// Define CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sensor(int i2c_handle, uint8_t *data);
int validate_checksum(uint8_t *data, uint8_t crc);
int log_data(FILE *fp, uint16_t flow1, uint16_t flow2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t flow;
    uint8_t checksum;
} sensor_data_t;

// Function to read data from a single sensor
int read_sensor(int i2c_handle, uint8_t *data) {
    int result, i;
    uint8_t buffer[3];

    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
        if (result == 3) {
            // Data read successfully
            break;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, result);
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    if (result != 3) {
        fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
        return -1; // Indicate failure
    }

    // Validate CRC checksum
    if (validate_checksum(buffer, buffer[2])) {
        // CRC check passed
        return 0; // Indicate success
    } else {
        fprintf(stderr, "CRC check failed.\n");
        return -1; // Indicate failure
    }
}

// Function to validate the CRC checksum
int validate_checksum(uint8_t *data, uint8_t crc) {
    uint8_t crc_calculated = 0xFF;
    uint8_t data_length = 2; // Data length is 2 bytes

    // Calculate CRC
    for (int i = 0; i < data_length; i++) {
        crc_calculated ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc_calculated & 0x80) {
                crc_calculated = (crc_calculated << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc_calculated <<= 1;
            }
        }
    }

    // Compare calculated CRC with received CRC
    return (crc_calculated == crc);
}

// Function to log data to a file
int log_data(FILE *fp, uint16_t flow1, uint16_t flow2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (flow1 != 0 && flow2 != 0) {
        fprintf(fp, "%s,%u,%u\n", timestamp, flow1, flow2);
        fflush(fp); // Ensure data is written to file immediately
        return 0; // Indicate success
    } else {
        fprintf(stderr, "Skipping log entry due to invalid flow data.\n");
        return -1; // Indicate failure
    }
}

