    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor 1
        result = read_sensor(i2c_handle1, sensor1_data);
        if (result == 0) {
            flow1 = (sensor1_data[0] << 8) | sensor1_data[1];
        } else {
            fprintf(stderr, "Failed to read sensor 1 data.\n");
            flow1 = 0; // Set to 0 to avoid using invalid data
        }

