#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the encoder
#define ENCODER_A 17
#define ENCODER_B 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360

// Define the angular resolution
#define ANGULAR_RESOLUTION 0.001 // 0.1 degrees per pulse

// Global variables
volatile int encoder_state = 0; // 0: A high, 1: B high
volatile int last_encoder_state = 0; // Store the last encoder state
volatile unsigned long last_interrupt_time = 0; // Time of last interrupt

// Function prototypes
void interrupt_handler(int gpio, int level, unsigned int tick, void *user);
double calculate_angle(int pulses);
void log_position(double angle);
void signal_handler(int signal);

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user)
{
    unsigned long current_time = gpioTick();

    // Debounce the interrupt
    if (current_time - last_interrupt_time > 1000) // 1ms debounce
    {
        int current_state = gpioRead(ENCODER_A);

        if (current_state != last_encoder_state)
        {
            last_encoder_state = current_state;

            if (current_state == 1) // Encoder A high
            {
                encoder_state = 1;
            }
            else // Encoder B high
            {
                encoder_state = 0;
            }

            last_interrupt_time = current_time;
        }
    }
}

// Function to calculate the angular position
double calculate_angle(int pulses)
{
    return (double)pulses * ANGULAR_RESOLUTION;
}

// Function to log the position to a file
void log_position(double angle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL)
    {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, angle);

    fclose(fp);
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupts
    gpioSetISRFuncEx(ENCODER_A, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B, RISING_EDGE, 0, NULL, NULL);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    // Set up interrupt handlers for both channels
    gpioSetISRFuncEx(ENCODER_A, RISING_EDGE, 0, interrupt_handler, NULL);
    gpioSetISRFuncEx(ENCODER_B, RISING_EDGE, 0, interrupt_handler, NULL);

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int pulses = 0;
    double angle;

    printf("Monitoring encoder... Press Ctrl+C to exit.\n");

    while (1)
    {
        // Read the current encoder state
        int current_state = gpioRead(ENCODER_A);

        if (current_state != last_encoder_state)
        {
            // Calculate the number of pulses since the last state change
            pulses = (current_state == 1) ? 1 : -1; // 1 for A high, -1 for B high

            // Update the last state
            last_encoder_state = current_state;

            // Increment the pulse count
            pulses += pulses; // Handle wrap-around

            // Calculate the angular position
            angle = calculate_angle(pulses);

            // Log the position
            log_position(angle);

            // Reset the pulse count for the next revolution
            pulses = 0;
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(1000); // 1ms delay
    }

    return 0;
}

