#include <string.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define LOG_FILE_NAME "audio_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int audio_level;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);

    // Set GPIO18 as output
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);

    // Set initial gain to 60dB
    gpioWrite(GAIN_SELECT_PIN, 0);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read audio input
        audio_level = gpioRead(AUDIO_INPUT_PIN);

        // Get current timestamp
        time(&current_time);
        time_info = localtime(&current_time);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

        // Log audio event
        if (audio_level == 1) {
            fprintf(log_file, "%s LEVEL\n", timestamp);
            fflush(log_file); // Ensure data is written to file immediately
            printf("%s Audio event detected!\n", timestamp);
        }

        // Delay for 10ms
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

