// Define the I2C address of the SLF3S-4000B sensor
#define SLF3S_I2C_ADDR 0x36

// Define the flow rate conversion factor (adjust based on sensor datasheet)
#define FLOW_RATE_CONVERSION_FACTOR 0.01 // Example: 1 unit = 0.01 mL/min

// Define the CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Define the log file name
#define LOG_FILE "flow_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t raw_flow_rate;
    uint8_t crc_byte;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_crc(const sensor_data_t *data);
float convert_to_flow_rate(int16_t raw_flow_rate);
int log_data(float flow_rate);
void signal_handler(int signal);

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SLF3S_I2C_ADDR, 0); // Bus 1, address 0x36, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    data->raw_flow_rate = (int16_t)((buf[0] << 8) | buf[1]);
    data->crc_byte = buf[2];

    return 0;
}

// Function to validate the CRC checksum
int validate_crc(const sensor_data_t *data) {
    uint8_t crc = 0xFF;
    uint8_t bit;

    for (int i = 0; i < 8; i++) {
        crc ^= data->crc_byte & 0x80;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }

    if (crc != data->crc_byte) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

