    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(&sensor_data) == 0) {
                // Convert to flow rate
                float flow_rate = convert_to_flow_rate(sensor_data.raw_flow_rate);

                // Log the data
                log_data(flow_rate);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1000 milliseconds
        gpioDelay(1000); // pigpio's delay function
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

