#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TAMPER_SENSOR_GPIO 17
#define TAMPER_THRESHOLD_MS 5000
#define TAMPER_THRESHOLD_US (TAMPER_THRESHOLD_MS * 1000)

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int pigpio_init_result = gpioInitialise();
    if (pigpio_init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", pigpio_init_result);
        return EXIT_FAILURE;
    }

    // Set GPIO 17 as an input
    gpioSetMode(TAMPER_SENSOR_GPIO, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t last_touch_time = 0;
    int tamper_detected = 0;

    while (program_running) {
        int sensor_value = gpioRead(TAMPER_SENSOR_GPIO);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value: %d\n", sensor_value);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) {
            // Tamper detected
            if (!tamper_detected) {
                time_t current_time = time(NULL);
                if (difftime(current_time, last_touch_time) > (double)TAMPER_THRESHOLD_MS / 1000.0) {
                    printf("Intrusion Detected!\n");
                    tamper_detected = 1;
                    last_touch_time = current_time;
                }
            }
        } else {
            // Sensor released
            tamper_detected = 0;
        }

        gpioDelay(100); // Check every 100ms
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

