#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_GPIO 4
#define FAN_GPIO 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_MS 50

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            control_fan(1); // Flame detected
            log_event("Flame Detected");
        } else if (flame_detected == 1) {
            control_fan(0); // No flame
            log_event("Flame End");
        } else {
            // Sensor timeout
            log_event("Sensor Timeout");
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    return 0;
}

// Read flame sensor with debounce
int read_flame_sensor() {
    int i;
    int value;
    int timeout_count = 0;

    for (i = 0; i < 10; i++) { // Retry 10 times
        value = gpioRead(FLAME_SENSOR_GPIO);
        if (value == 0) { // Flame detected (LOW)
            return 0; // Return immediately if flame detected
        }
        gpioDelay(1000); // 1ms delay
        timeout_count++;
        if (timeout_count > 100) { // Timeout after 100 attempts
            fprintf(stderr, "Timeout reading flame sensor\n");
            return 1; // Indicate timeout
        }
    }

    return 1; // Return if no flame detected after timeout
}

// Control the cooling fan
void control_fan(int flame_detected) {
    if (flame_detected == 0) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Log events to file
void log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

