#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration struct
typedef struct {
    float start_frequency;
    float end_frequency;
    int num_chirps;
    int num_samples;
} radar_config_t;

// Global variables
int spi_handle;
int frame_trigger_gpio = 23;
int data_ready_gpio = 24;
FILE *log_file = NULL;
radar_config_t config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int spi_channel, int spi_speed_hz, int spi_mode);
int configure_sensor(int spi_handle, radar_config_t config);
int capture_frame(int spi_handle, int frame_number, int *data);
int log_frame(FILE *log_file, int frame_number, int *data, int num_samples);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize SPI
int initialize_spi(int spi_channel, int spi_speed_hz, int spi_mode) {
    int handle = spiOpen(spi_channel, spi_speed_hz, spi_mode);
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to configure the sensor
int configure_sensor(int spi_handle, radar_config_t config) {
    // Placeholder for sensor configuration logic
    // Replace with actual configuration commands based on the AWR1642 SDK
    // This example sets the start and end frequencies and number of chirps
    char config_data[64];
    snprintf(config_data, sizeof(config_data), "start_freq=%.2f,end_freq=%.2f,num_chirps=%d,num_samples=%d", config.start_frequency, config.end_frequency, config.num_chirps, config.num_samples);
    int result = spiWrite(spi_handle, config_data, strlen(config_data));
    if (result < 0) {
        fprintf(stderr, "Sensor configuration failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(int spi_handle, int frame_number, int *data) {
    // Placeholder for frame capture logic
    // Replace with actual SPI read commands to read the heatmap data
    // This example reads 32768 bytes from the SPI device
    char read_command[1];
    snprintf(read_command, sizeof(read_command), "read_frame_%d", frame_number);
    int result = spiWrite(spi_handle, read_command, strlen(read_command));
    if (result < 0) {
        fprintf(stderr, "Frame read failed: %d\n", result);
        return -1;
    }

    // Simulate reading data from SPI
    for (int i = 0; i < 32768; i++) {
        data[i] = (rand() % 256) + 1; // Simulate data with values between 1 and 256
    }

    return 0;
}

// Function to log a frame
int log_frame(FILE *log_file, int frame_number, int *data, int num_samples) {
    // Calculate the timestamp
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Calculate the offset in the file
    long offset = (frame_number - 1) * 32768 + 8; // 8 bytes for magic number and config struct

    // Write the magic number
    fwrite(&offset, 1, 1, log_file);

    // Write the configuration struct
    fwrite(&config, sizeof(radar_config_t), 1, log_file);

    // Write the per-frame timestamps and frame numbers
    for (int i = 0; i < num_samples; i++) {
        fwrite(&timestamp, 1, 1, log_file);
        fwrite(&data[i], 1, 1, log_file);
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    spi_handle = initialize_spi(0, 1000000, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    config.start_frequency = 77.0f;
    config.end_frequency = 79.0f;
    config.num_chirps = 64;
    config.num_samples = 256;
    if (configure_sensor(spi_handle, config) != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(frame_trigger_gpio, PI_INPUT);
    gpioSetMode(data_ready_gpio, PI_INPUT);

    // Set pull-up/down resistors (optional, adjust as needed)
    gpioSetPullUpDown(frame_trigger_gpio, PI_PUD_DOWN);
    gpioSetPullUpDown(data_ready_gpio, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen("radar_data.bin", "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    int frame_number = 0;
    while (!terminate) {
        // Wait for frame trigger
        while (gpioRead(frame_trigger_gpio) == 0) {
            gpioDelay(1); // Wait 1 us
        }
        gpioDelay(1); // Small delay after trigger

        // Wait for data ready
        while (gpioRead(data_ready_gpio) == 0) {
            gpioDelay(1); // Wait 1 us
        }
        gpioDelay(1); // Small delay after data ready

        // Capture a frame
        int data[32768];
        if (capture_frame(spi_handle, frame_number, data) != 0) {
            fprintf(stderr, "Frame capture failed\n");
            continue; // Try again
        }

        // Log the frame
        if (log_frame(log_file, frame_number, data, config.num_samples) != 0) {
            fprintf(stderr, "Frame logging failed\n");
        }

        // Increment frame number
        frame_number++;

        // Reset data ready flag
        gpioDelay(1); // Small delay after logging
        gpioSetAlertFuncEx(data_ready_gpio, NULL, NULL); // Disable interrupt
        gpioDelay(1); // Small delay after resetting interrupt
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

