    int handle = spiOpen(spi_channel, spi_speed_hz, spi_mode);
    if (handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to configure the sensor
int configure_sensor(int spi_handle, radar_config_t config) {
    // Placeholder for sensor configuration logic
    // Replace with actual configuration commands based on the AWR1642 SDK
    // This example sets the start and end frequencies and number of chirps
    char config_data[64];
    snprintf(config_data, sizeof(config_data), "start_freq=%.2f,end_freq=%.2f,num_chirps=%d,num_samples=%d", config.start_frequency, config.end_frequency, config.num_chirps, config.num_samples);
    int result = spiWrite(spi_handle, config_data, strlen(config_data));
    if (result < 0) {
