static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 UTC format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, int flame_detected) {
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s,%d\n", timestamp, flame_detected);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

// Function to read the flame sensor state
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO20 as an input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();
        char *timestamp = get_iso8601_timestamp();

        if (timestamp != NULL) {
            if (log_flame_state(timestamp, flame_detected) != 0) {
                fprintf(stderr, "Error logging flame state\n");
            }
            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error getting timestamp\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

