#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONTINUOUS_CONVERSION_MODE 0x01
#define ALS_RANGE_AUTO 0x00
#define CONVERSION_TIME 100 // milliseconds
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(float *lux);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    char config_data[2];
    config_data[0] = CONTINUOUS_CONVERSION_MODE;
    config_data[1] = ALS_RANGE_AUTO;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to configure sensor: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read sensor data and convert to lux
int read_sensor_data(float *lux) {
    char data[2];
    int result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int16_t raw_value = (data[0] << 8) | data[1];

    // Convert raw value to lux (example conversion, adjust as needed)
    *lux = (float)raw_value * 0.0576; // Example conversion factor

    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float lux;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&lux) == 0) {
            log_data(lux);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 1 second.\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

