#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LINE_REQUEST_ID 1
#define CHIP_ID 1

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int status;
    char timestamp[20];
    int flame_detected;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Request GPIO line for input
    status = gpioRequestLine(GPIO_PIN, LINE_REQUEST_ID, CHIP_ID);
    if (status < 0) {
        fprintf(stderr, "Failed to request GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Flame detection started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read the GPIO line value
        flame_detected = gpioRead(GPIO_PIN);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the status to the console
        printf("%s Flame Detected: %s\n", timestamp, flame_detected ? "NO" : "YES");

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Release the line request
    status = gpioReleaseLine(GPIO_PIN, LINE_REQUEST_ID, CHIP_ID);
    if (status < 0) {
        fprintf(stderr, "Failed to release GPIO line %d: %s\n", GPIO_PIN, strerror(errno));
    }

    // Close the chip
    status = gpioClose(CHIP_ID);
    if (status < 0) {
        fprintf(stderr, "Failed to close chip: %s\n", strerror(errno));
    }

    // Free all configuration and settings objects
    gpioTerminate();

    printf("Flame detection stopped.\n");

    return 0;
}

