#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define the GPIO pins connected to the touch sensor outputs
#define SENSOR_1 2
#define SENSOR_2 3
#define SENSOR_3 4
#define SENSOR_4 5
#define SENSOR_5 6
#define SENSOR_6 7
#define SENSOR_7 8
#define SENSOR_8 9

// Structure to hold the sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
    int sensor4;
    int sensor5;
    int sensor6;
    int sensor7;
    int sensor8;
} sensor_data_t;

// Global variable to store the sensor data
sensor_data_t sensor_data;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to read the sensor data
int read_sensor_data(sensor_data_t *data) {
    // Read the digital values from the sensor pins
    data->sensor1 = gpioRead(SENSOR_1);
    data->sensor2 = gpioRead(SENSOR_2);
    data->sensor3 = gpioRead(SENSOR_3);
    data->sensor4 = gpioRead(SENSOR_4);
    data->sensor5 = gpioRead(SENSOR_5);
    data->sensor6 = gpioRead(SENSOR_6);
    data->sensor7 = gpioRead(SENSOR_7);
    data->sensor8 = gpioRead(SENSOR_8);

    // Return 0 on success, -1 on failure
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(SENSOR_3, PI_PUD_DOWN);
    gpioSetMode(SENSOR_4, PI_INPUT);
    gpioSetPullUpDown(SENSOR_4, PI_PUD_DOWN);
    gpioSetMode(SENSOR_5, PI_INPUT);
    gpioSetPullUpDown(SENSOR_5, PI_PUD_DOWN);
    gpioSetMode(SENSOR_6, PI_INPUT);
    gpioSetPullUpDown(SENSOR_6, PI_PUD_DOWN);
    gpioSetMode(SENSOR_7, PI_INPUT);
    gpioSetPullUpDown(SENSOR_7, PI_PUD_DOWN);
    gpioSetMode(SENSOR_8, PI_INPUT);
    gpioSetPullUpDown(SENSOR_8, PI_PUD_DOWN);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read the sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            gpioTerminate();
            return 1;
        }

        // Print the sensor data
        printf("[-%d ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               sensor_data.sensor1, sensor_data.sensor2, sensor_data.sensor3,
               sensor_data.sensor4, sensor_data.sensor5, sensor_data.sensor6,
               sensor_data.sensor7, sensor_data.sensor8);

        // Wait for 100 milliseconds
        gpioDelay(100000);
    }

    // This point will not be reached due to the infinite loop,
    // but it's good practice to include gpioTerminate()
    gpioTerminate();
    return 0;
}

