#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02
#define SI1145_REG_INTCFG 0x03
#define SI1145_REG_IRQEN 0x04
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_UV_INDEX0 0x24
#define SI1145_REG_UV_INDEX1 0x25
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_RESPONSE 0x20

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(uint16_t *uv_index, uint16_t *als_visible);
void log_data(uint16_t uv_index, uint16_t als_visible);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t uv_index;
    uint16_t als_visible;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_fd = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the Si1145 sensor
int init_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_fd, SI1145_REG_COMMAND, 0x00) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_fd, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, SI1145_REG_MEAS_RATE0, 0x08) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE0\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE1\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, SI1145_REG_INTCFG, 0x00) < 0) {
        fprintf(stderr, "Failed to write INTCFG\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, SI1145_REG_IRQEN, 0x00) < 0) {
        fprintf(stderr, "Failed to write IRQEN\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_fd, SI1145_REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Failed to write command to start measurement\n");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *uv_index, uint16_t *als_visible) {
    uint8_t buffer[4];

    // Read UV Index
    if (i2cReadI2CBlockData(i2c_fd, SI1145_REG_UV_INDEX0, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Failed to read UV Index\n");
        return -1;
    }
    *uv_index = (buffer[1] << 8) | buffer[0];

    // Read Visible Light
    if (i2cReadI2CBlockData(i2c_fd, SI1145_REG_ALS_VIS_DATA0, (char *)buffer, 2) != 2) {
        fprintf(stderr, "Failed to read Visible Light\n");
        return -1;
    }
    *als_visible = (buffer[1] << 8) | buffer[0];

    return 0;
}

// Log data to CSV file
void log_data(uint16_t uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize sensor
    if (init_sensor() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t uv_index, als_visible;

        if (read_sensor_data(&uv_index, &als_visible) == 0) {
            log_data(uv_index, als_visible);
            printf("UV Index: %u, Visible Light: %u\n", uv_index, als_visible);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

