    }
    return 0;
}

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle, float *flow_rate) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    // Convert raw data to flow rate (example, check datasheet)
    int raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 100.0; // Example scaling

    // Validate CRC
    if (!validate_crc(buffer, 2)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    return 0;
}

// Function to validate CRC
int validate_crc(unsigned char data[], int data_len) {
    unsigned char crc = CRC_INIT_VALUE;
    for (int i = 0; i < data_len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

// Function to calculate the average flow rate
float calculate_average_flow_rate(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// Function to control the alarm
int control_alarm(float average_flow_rate) {
    if (average_flow_rate < 0.5) {
        gpioWrite(ALARM_GPIO, 1); // Turn on alarm
    } else {
        gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    }
    return 0;
}

// Function to log data to file
int log_data(float flow1, float flow2, float average_flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor1: %.2f ml/min, Sensor2: %.2f ml/min, Average: %.2f ml/min\n",
                timestamp, flow1, flow2, average_flow_rate);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Initially turn off the alarm

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Start sensors
    if (start_sensor(i2c_handle1) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }
    if (start_sensor(i2c_handle2) != 0) {
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2, average_flow_rate;

    // Main loop
    while (!terminate) {
        // Read flow rates
        if (read_flow_rate(i2c_handle1, &flow1) == 0 && read_flow_rate(i2c_handle2, &flow2) == 0) {
            // Calculate average flow rate
            average_flow_rate = calculate_average_flow_rate(flow1, flow2);

            // Control alarm
            control_alarm(average_flow_rate);

            // Log data
            log_data(flow1, flow2, average_flow_rate);

            printf("Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min, Average: %.2f ml/min\n", flow1, flow2, average_flow_rate);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping this cycle.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioWrite(ALARM_GPIO, 0); // Turn off alarm
    gpioTerminate();
    fclose(log_file);

    return 0;
}

