#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_PIN 7
#define BUFFER_SIZE 100

// Structure to hold the circular buffer
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer sensor_buffer;
int running = 1;

// Function prototypes
int initialize_gpio();
void initialize_circular_buffer(CircularBuffer *cb);
void add_to_circular_buffer(CircularBuffer *cb, int value);
int get_from_circular_buffer(CircularBuffer *cb);
void detect_obstacle();
void signal_handler(int signal);
void print_buffer(CircularBuffer *cb);

// Initialize the circular buffer
void initialize_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add an element to the circular buffer
void add_to_circular_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the oldest element from the circular buffer
int get_from_circular_buffer(CircularBuffer *cb) {
    if (cb->count > 0) {
        int value = cb->buffer[cb->head];
        cb->head = (cb->head + 1) % BUFFER_SIZE;
        cb->count--;
        return value;
    } else {
        return -1; // Indicate an empty buffer
    }
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor
    return 0; // Indicate success
}

// Detect obstacle based on sensor reading
void detect_obstacle() {
    int sensor_value = gpioRead(SENSOR_PIN);
    if (sensor_value == 0) { // Obstacle detected (LOW signal)
        printf("Obstacle detected!\n");
        add_to_circular_buffer(&sensor_buffer, 1); // Add 1 to the buffer
    } else {
        add_to_circular_buffer(&sensor_buffer, 0); // Add 0 to the buffer
    }
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
    print_buffer(&sensor_buffer);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize the circular buffer
    initialize_circular_buffer(&sensor_buffer);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if GPIO initialization fails
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        detect_obstacle();
        gpioDelay(50000); // 50ms delay (microseconds)
    }

    return 0;
}

