#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define D7S_ADDR 0x59
#define MODE_REG 0x00
#define DATA_REG 0x01
#define SAMPLE_RATE_MS 500

int i2c_fd;
FILE *csv_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the I2C connection
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to configure the D7S sensor
int configure_sensor() {
    // Set to accelerometer mode
    if (i2cWriteByteData(i2c_fd, MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the sensor
int read_acceleration(float *x, float *y, float *z) {
    char buf[6];
    int bytes_read = i2cReadI2CBlockData(i2c_fd, DATA_REG, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", bytes_read);
        return -1;
    }

    // Convert raw data to g-force units (adjust as needed based on sensor datasheet)
    *x = (float)((short)((buf[0] << 8) | buf[1])) / 1000.0; // Example scaling
    *y = (float)((short)((buf[2] << 8) | buf[3])) / 1000.0;
    *z = (float)((short)((buf[4] << 8) | buf[5])) / 1000.0;

    return 0;
}

// Function to log data to a CSV file
int log_data(float x, float y, float z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (csv_file == NULL) {
        csv_file = fopen("fan_health.csv", "a");
        if (csv_file == NULL) {
            fprintf(stderr, "Error opening CSV file\n");
            return -1;
        }
        // Write header if the file is newly created
        fseek(csv_file, 0, SEEK_END);
        long file_size = ftell(csv_file);
        if (file_size == 0) {
            fprintf(csv_file, "Timestamp,X,Y,Z\n");
        }
    }

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    float x, y, z;

    printf("Starting data acquisition...\n");

    while (1) {
        if (read_acceleration(&x, &y, &z) == 0) {
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, retrying...\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for SAMPLE_RATE_MS milliseconds
    }

    // The following lines will never be reached in normal execution
    // because the while loop runs indefinitely. However, they are
    // included for completeness and to avoid compiler warnings.
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

