#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 23
#define SENSOR2_PIN 24
#define LED_PIN 25

// Define constants
#define LED_ON_TIME_MS 500
#define DEBOUNCE_DELAY_MS 5

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as inputs
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sensor values
int read_sensors() {
    int sensor1_value = gpioRead(SENSOR1_PIN);
    int sensor2_value = gpioRead(SENSOR2_PIN);

    // Debouncing: Wait for a short period to avoid multiple triggers
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds

    return (sensor1_value == 0 || sensor2_value == 0) ? 1 : 0; // Return 1 if either sensor detects an obstacle, 0 otherwise
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    fprintf(stderr, "pigpio terminated\n");
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int obstacle_detected = read_sensors();

        if (obstacle_detected) {
            control_led(1); // Turn LED on
            gpioDelay(LED_ON_TIME_MS * 1000); // Wait for LED_ON_TIME_MS milliseconds
            control_led(0); // Turn LED off
        }

        gpioDelay(100 * 1000); // Poll every 100 milliseconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

