#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TMAG5170-Q1 I2C address
#define TMAG5170_ADDR 0x08

// TMAG5170-Q1 Register Addresses
#define TMAG5170_REG_XOUT 0x00
#define TMAG5170_REG_YOUT 0x02
#define TMAG5170_REG_ZOUT 0x04
#define TMAG5170_REG_CONFIG 0x06
#define TMAG5170_REG_STATUS 0x07

// Configuration values
#define CONFIG_CONTINUOUS_MODE 0x03 // Continuous conversion mode
#define CONFIG_50_mT_RANGE 0x00     // 50 mT range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int configure_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0); // I2C bus 1, address 0x08, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Sensor configuration function
int configure_sensor() {
    // Configure continuous conversion mode and 50 mT range
    uint8_t config_value = CONFIG_CONTINUOUS_MODE | CONFIG_50_mT_RANGE;
    int result = i2cWriteByteData(i2c_handle, TMAG5170_REG_CONFIG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }
    return 0;
}

// Sensor data reading function
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int result;

    result = i2cReadWordData(i2c_handle, TMAG5170_REG_XOUT);
    if (result < 0) {
        fprintf(stderr, "Failed to read X axis data: %d\n", result);
        data.x = 0; // Set to 0 to avoid garbage values
    } else {
        data.x = (int16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TMAG5170_REG_YOUT);
    if (result < 0) {
        fprintf(stderr, "Failed to read Y axis data: %d\n", result);
        data.y = 0; // Set to 0 to avoid garbage values
    } else {
        data.y = (int16_t)result;
    }

    result = i2cReadWordData(i2c_handle, TMAG5170_REG_ZOUT);
    if (result < 0) {
        fprintf(stderr, "Failed to read Z axis data: %d\n", result);
        data.z = 0; // Set to 0 to avoid garbage values
    } else {
        data.z = (int16_t)result;
    }

    return data;
}

// Data logging function
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        fprintf(stderr, "Sensor configuration failed\n");
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

