}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        FILE *fp = fopen(LOG_FILE, "a");
        if (fp) {
            fprintf(fp, "Error: pigpio initialisation failed\n");
            fclose(fp);
        }
        return 1; // Indicate failure
    }
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);
    return 0; // Indicate success
}

int read_sensor() {
    return gpioRead(GPIO_PIN);
}

void log_alert() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d ALERT: Water detected\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

void log_error(int error_code) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d ERROR: GPIO read failed (code %d)\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, error_code);
        fclose(fp);
    } else {
        perror("Error opening log file");
    }
}

void cleanup() {
    gpioTerminate();
    printf("pigpio terminated.\n");
}

