    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 1) {
            log_alert();
            log_error(1); // Simulate an error for logging purposes
        } else if (sensor_value < 0) {
            log_error(sensor_value); // Log the error code
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    cleanup();
    return 0;
}

