#include <errno.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_WINDOW_SEC 1

// Global variables
volatile int pulse_count = 0;
volatile int running = 1;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count);
void log_rpm(double rpm);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    FILE *log_file;
} program_state_t;

program_state_t state = {0, NULL};

// Interrupt handler for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

// Function to calculate RPM
double calculate_rpm(int pulse_count) {
    static double last_rpm = 0.0;
    double current_rpm = (double)pulse_count / (double)SAMPLE_WINDOW_SEC * 60.0;
    if (current_rpm != last_rpm) {
        last_rpm = current_rpm;
    }
    return last_rpm;
}

// Function to log RPM to file and stdout
void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (state.log_file != NULL) {
        fprintf(state.log_file, "%s %s\n", timestamp, rpm);
        fflush(state.log_file);
    } else {
        printf("%s %s\n", timestamp, rpm);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    printf("Caught signal, exiting gracefully...\n");
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    state.gpio_initialized = 1;

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler for rising edge detection
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set up interrupt handler\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    state.log_file = fopen(LOG_FILE, "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        double rpm = calculate_rpm(current_pulse_count);
        log_rpm(rpm);
        gpioDelay(1000); // Sample every 1 second
    }

    // Disable interrupt handler
    gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, NULL, NULL);

    // Close log file
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    // Cleanup pigpio
    gpioTerminate();

    printf("RPM monitoring stopped.\n");
    return 0;
}

