#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

#define SENSOR_PIN 23
#define LED_PIN 18

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    syslog(LOG_INFO, "Signal received, shutting down...");
}

int main() {
    int sensor_value;
    int led_state = 0; // 0 = off, 1 = on
    int last_sensor_value = 0;

    // Open syslog
    openlog("touch_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set sensor pin as input");
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED pin as output");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        sensor_value = gpioRead(SENSOR_PIN);

        if (sensor_value != last_sensor_value) {
            if (sensor_value == 1) {
                // Touch detected
                if (led_state == 0) {
                    if (gpioWrite(LED_PIN, 1) == 0) {
                        led_state = 1;
                        syslog(LOG_INFO, "Touch detected, LED turned on");
                    } else {
                        syslog(LOG_ERR, "Failed to write to LED pin");
                    }
                }
            } else {
                // Touch released
                if (led_state == 1) {
                    if (gpioWrite(LED_PIN, 0) == 0) {
                        led_state = 0;
                        syslog(LOG_INFO, "Touch released, LED turned off");
                    } else {
                        syslog(LOG_ERR, "Failed to write to LED pin");
                    }
                }
            }
            last_sensor_value = sensor_value;
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    closelog();

    return 0;
}

