#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN 17
#define LED_PIN 18
#define DEBOUNCE_DELAY_MS 50

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_PIN to input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED_PIN to output\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LED to LOW
    gpioWrite(LED_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor program running. Press Ctrl+C to exit.\n");

    while (running) {
        // Wait for rising edge on TOUCH_PIN
        result = gpioEventWait(TOUCH_PIN, PI_TIMEOUT_EVENTS, 1); // Wait for 1 event

        if (result < 0) {
            fprintf(stderr, "gpioEventWait failed: %d\n", result);
            gpioTerminate();
            return 1;
        }

        if (result > 0) {
            // Touch detected
            gpioWrite(LED_PIN, 1); // Turn LED on
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            gpioWrite(LED_PIN, 0); // Turn LED off
        }
    }

    // Cleanup
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

