#include <pigpio.h>

// Define GPIO pins
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define LED1_PIN 27
#define LED2_PIN 22

// Define buffer size
#define BUFFER_SIZE 100

// Structure to store sensor data
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} SensorEvent;

// Circular buffer
SensorEvent sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_overflow = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal, exiting gracefully...\n");
        program_running = 0;
        control_led(LED1_PIN, 0); // Turn off LED1
        control_led(LED2_PIN, 0); // Turn off LED2
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log sensor event
void log_event(int sensor_pin, int state) {
    time_t now = time(NULL);
    sensor_buffer[buffer_index].sensor_pin = sensor_pin;
    sensor_buffer[buffer_index].timestamp = now;
    sensor_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        buffer_overflow = 1; // Mark buffer as overflown
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED1_PIN, PI_OUTPUT);
    gpioSetMode(LED2_PIN, PI_OUTPUT);

    // Initialize LEDs to off
    control_led(LED1_PIN, 0);
    control_led(LED2_PIN, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        // Check for touch events
        if (sensor1_value == 1) {
            log_event(SENSOR1_PIN, 1);
            control_led(LED1_PIN, 1);
        } else {
            control_led(LED1_PIN, 0);
        }

        if (sensor2_value == 1) {
            log_event(SENSOR2_PIN, 1);
            control_led(LED2_PIN, 1);
        } else {
            control_led(LED2_PIN, 0);
        }

        // Small delay to avoid busy-waiting
        gpioDelay(50000); // 50ms
    }

    // Cleanup and exit
    control_led(LED1_PIN, 0);
    control_led(LED2_PIN, 0);
    gpioTerminate();

    printf("\n--- Sensor Log ---\n");
    if (buffer_overflow) {
        printf("Overflow: %d entries\n", BUFFER_SIZE);
    }
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        if (index < BUFFER_SIZE) {
            printf("Index: %d, Sensor: %d, Timestamp: %ld, State: %d\n", index, sensor_buffer[index].sensor_pin, sensor_buffer[index].timestamp, sensor_buffer[index].state);
        } else {
            printf("Index: %d, Sensor: %d, Timestamp: %ld, State: %d\n", (BUFFER_SIZE - 1 - i) % BUFFER_SIZE, sensor_buffer[BUFFER_SIZE - 1 - i].sensor_pin, sensor_buffer[BUFFER_SIZE - 1 - i].timestamp, sensor_buffer[BUFFER_SIZE - 1 - i].state);
        }
    }
    printf("Overflow Count: %d\n", buffer_overflow);

    return 0;
}

