#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "/var/log/rain_events.log"

static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    free(timestamp);
    fclose(fp);
    return 0;
}

// Function to read the sensor state
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_state = read_sensor();
        char *message = (sensor_state == 0) ? "Rain Detected" : "No Rain";
        if (log_event(message) != 0) {
            fprintf(stderr, "Failed to log event.\n");
        }
        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    gpioTerminate();
    printf("Rain sensor monitoring stopped.\n");
    return 0;
}

