#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define the debounce time in milliseconds
#define DEBOUNCE_TIME_MS 5

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold the last sensor states
struct {
    int sensor1_last_state;
    int sensor2_last_state;
} sensor_states = {0, 0};

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void log_data(int sensor1_state, int sensor2_state);
double calculate_rpm(int sensor1_state, int sensor2_state);
void signal_handler(int signal);

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", gpioInitialise());
        return -1;
    }

    // Set GPIO17 as input for sensor 1
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    // Set GPIO18 as input for sensor 2
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Function to cleanup the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

// Function to log the sensor data to a CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate the RPM based on the sensor states
double calculate_rpm(int sensor1_state, int sensor2_state) {
    // Assuming sensor 1 is connected to the rotating shaft
    // and sensor 2 is connected to a fixed point.
    // This is a simplified RPM calculation.
    // More sophisticated methods may be needed for accurate RPM measurement.
    static int last_state1 = 0; // Store the last known state of sensor 1
    static int last_state2 = 0; // Store the last known state of sensor 2
    static unsigned long last_transition1 = 0; // Store the last transition time for sensor 1
    static unsigned long last_transition2 = 0; // Store the last transition time for sensor 2

    unsigned long current_time = gpioTick();

    if (sensor1_state != last_state1) {
        if (current_time - last_transition1 > DEBOUNCE_TIME_MS * 1000) { // Convert ms to microseconds
            last_transition1 = current_time;
            last_state1 = sensor1_state;
        }
    }

    if (sensor2_state != last_state2) {
        if (current_time - last_transition2 > DEBOUNCE_TIME_MS * 1000) { // Convert ms to microseconds
            last_transition2 = current_time;
            last_state2 = sensor2_state;
        }
    }

    unsigned long time_diff = current_time - last_transition1; // Time difference in microseconds

    if (last_transition1 != 0) {
        // Calculate RPM based on the time difference
        double rpm = 60000000.0 / time_diff; // Divide by 1000000 to convert microseconds to seconds, then by 60 to get RPM
        return rpm;
    } else {
        return 0.0; // Return 0 RPM if no transition has been detected
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the sensor states
        int sensor1_state = gpioRead(SENSOR1_GPIO);
        int sensor2_state = gpioRead(SENSOR2_GPIO);

        // Log the data
        log_data(sensor1_state, sensor2_state);

        // Calculate the RPM
        double rpm = calculate_rpm(sensor1_state, sensor2_state);

        // Print the RPM to the console
        printf("RPM: %.2f\n", rpm);

        // Delay for a short period
        gpioDelay(10000); // 10ms delay (in microseconds)
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

