#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define constants
#define ALARM_DURATION 2 // seconds
#define LOG_FILE "bridge_integrity.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(const char *event_type);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

SensorStates current_states = {0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);

    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Initialize alarm to LOW

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log events to file
int log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Function to activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set alarm pin HIGH
}

// Function to deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0); // Set alarm pin LOW
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Deactivate alarm
    deactivate_alarm();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Cleanup pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        if (sensor1_value != current_states.sensor1_state) {
            if (sensor1_value == 1) {
                log_event("tilt_start");
                activate_alarm();
            } else {
                log_event("tilt_end");
                deactivate_alarm();
            }
            current_states.sensor1_state = sensor1_value;
        }

        if (sensor2_value != current_states.sensor2_state) {
            if (sensor2_value == 1) {
                log_event("tilt_start");
                activate_alarm();
            } else {
                log_event("tilt_end");
                deactivate_alarm();
            }
            current_states.sensor2_state = sensor2_value;
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alarm();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

