#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDA_GPIO 2
#define SCL_GPIO 3
#define CTRL1_REG 0x24
#define CTRL2_REG 0x25
#define CTRL3_REG 0x26
#define DATA_REG 0x27
#define THRESHOLD 500
#define LED_GPIO 17
#define LOG_FILE "seismic_events.log"
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int sda_gpio;
    int scl_gpio;
    int led_gpio;
    int threshold;
} sensor_config_t;

// Function prototypes
int initialize_sensor(int i2c_handle);
int read_sensor_data(int i2c_handle, int *vibration_magnitude);
int detect_earthquake(int vibration_magnitude, int threshold);
int log_event(int vibration_magnitude);
int control_led(int gpio, int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the sensor
int initialize_sensor(int i2c_handle) {
    int status;
    int retries = 0;

    // Clear power-down bit in CTRL1
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00); // Clear power-down bit
        if (status == 0) {
            break; // Success
        } else {
            fprintf(stderr, "Error writing to CTRL1_REG (attempt %d): %d\n", retries + 1, status);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to initialize CTRL1_REG after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Set other configuration registers (example values)
    status = i2cWriteByteData(i2c_handle, CTRL2_REG, 0x01); // Example value
    if (status != 0) {
        fprintf(stderr, "Error writing to CTRL2_REG: %d\n", status);
        return -1;
    }

    status = i2cWriteByteData(i2c_handle, CTRL3_REG, 0x00); // Example value
    if (status != 0) {
        fprintf(stderr, "Error writing to CTRL3_REG: %d\n", status);
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int *vibration_magnitude) {
    int status;
    int retries = 0;
    char buffer[2];

    while (retries < RETRY_COUNT) {
        status = i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, 2);
        if (status == 2) {
            *vibration_magnitude = (buffer[0] << 8) | buffer[1];
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data (attempt %d): %d\n", retries + 1, status);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to detect earthquake
int detect_earthquake(int vibration_magnitude, int threshold) {
    return (vibration_magnitude > threshold) ? 1 : 0;
}

// Function to log event
int log_event(int vibration_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Vibration Magnitude: %d\n", timestamp, vibration_magnitude);

    if (log_file != NULL) {
        fprintf(log_file, "%s", log_entry);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to control LED
int control_led(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

int main() {
    int vibration_magnitude;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, 0, 0); // 0 for default address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(i2c_handle, &vibration_magnitude);
        if (status == 0) {
            // Detect earthquake
            if (detect_earthquake(vibration_magnitude, THRESHOLD)) {
                printf("Earthquake detected! Vibration Magnitude: %d\n", vibration_magnitude);

                // Log event
                if (log_event(vibration_magnitude) != 0) {
                    fprintf(stderr, "Error logging event\n");
                }

                // Control LED
                if (control_led(LED_GPIO, 1) != 0) {
                    fprintf(stderr, "Error controlling LED\n");
                }
                gpioDelay(1000000); // 1 second
                if (control_led(LED_GPIO, 0) != 0) {
                    fprintf(stderr, "Error turning off LED\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

