}

// Function to log event
int log_event(int vibration_magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char log_entry[100];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Vibration Magnitude: %d\n", timestamp, vibration_magnitude);

    if (log_file != NULL) {
        fprintf(log_file, "%s", log_entry);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to control LED
int control_led(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

int main() {
    int vibration_magnitude;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, 0, 0); // 0 for default address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        status = read_sensor_data(i2c_handle, &vibration_magnitude);
        if (status == 0) {
            // Detect earthquake
            if (detect_earthquake(vibration_magnitude, THRESHOLD)) {
                printf("Earthquake detected! Vibration Magnitude: %d\n", vibration_magnitude);

                // Log event
                if (log_event(vibration_magnitude) != 0) {
                    fprintf(stderr, "Error logging event\n");
                }

                // Control LED
                if (control_led(LED_GPIO, 1) != 0) {
                    fprintf(stderr, "Error controlling LED\n");
                }
                gpioDelay(1000000); // 1 second
                if (control_led(LED_GPIO, 0) != 0) {
                    fprintf(stderr, "Error turning off LED\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

