#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_SENSORS 5
#define DEBOUNCE_DELAY_MS 50

// Structure to hold sensor information
typedef struct {
    int gpio_pin;
    int line_number;
    int line_fd;
    char line_buffer[256];
    volatile sig_atomic_t running;
} sensor_data_t;

// Global array of sensor data
sensor_data_t sensors[NUM_SENSORS];

// Function prototypes
int read_line(int line_number, char *buffer, size_t buffer_size);
int write_line(int line_number, const char *data);
int acquire_line(int line_number);
int request_line(int line_number);
int release_line(int line_number);
void log_event(int sensor_id, int gpio_pin, const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        syslog(LOG_INFO, "Signal received, shutting down...");
        sensors[0].running = 0; // Set the flag to exit the main loop
        cleanup();
        exit(0);
    }
}

// Function to acquire a line
int acquire_line(int line_number) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to acquire...", line_number);
        if (request_line(line_number) != 0) {
            syslog(LOG_ERR, "Failed to request line %d", line_number);
            return -1;
        }
        if (release_line(line_number) != 0) {
            syslog(LOG_ERR, "Failed to release line %d", line_number);
            return -1;
        }
        if (acquire_line(line_number) != 0) {
            syslog(LOG_ERR, "Failed to acquire line %d", line_number);
            return -1;
        }
    }
    return 0;
}

// Function to release a line
int release_line(int line_number) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) != -1) {
        syslog(LOG_INFO, "Releasing line %d", line_number);
        if (unlink(line_path) == -1) {
            syslog(LOG_ERR, "Failed to unlink line %d: %s", line_number, strerror(errno));
            return -1;
        }
        return 0;
    }
    return -1;
}

// Function to request a line
int request_line(int line_number) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to request...", line_number);
        if (mkfifo(line_path, 0666) == -1) {
            syslog(LOG_ERR, "Failed to create FIFO %s: %s", line_path, strerror(errno));
            return -1;
        }
        syslog(LOG_INFO, "Created FIFO for line %d", line_number);
        return 0;
    }
    syslog(LOG_INFO, "Line %d already exists", line_number);
    return 0;
}

// Function to write to a line
int write_line(int line_number, const char *data) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to write to...", line_number);
        return -1;
    }

    if (write(fileno(sensors[0].line_fd), data, strlen(data)) == -1) {
        syslog(LOG_ERR, "Failed to write to line %d: %s", line_number, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Wrote to line %d: %s", line_number, data);
    return 0;
}

// Function to read from a line
int read_line(int line_number, char *buffer, size_t buffer_size) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to read from...", line_number);
        return -1;
    }

    ssize_t bytes_read = read(fileno(sensors[0].line_fd), buffer, buffer_size - 1);
    if (bytes_read == -1) {
        syslog(LOG_ERR, "Failed to read from line %d: %s", line_number, strerror(errno));
        return -1;
    }
    buffer[bytes_read] = '\0'; // Null-terminate the buffer
    syslog(LOG_INFO, "Read from line %d: %s", line_number, buffer);
    return 0;
}

// Function to log an event
void log_event(int sensor_id, int gpio_pin, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s - Sensor ID: %d (GPIO %d) - %s",
             timestamp, sensor_id, gpio_pin, message);

    syslog(LOG_INFO, "%s", log_message);
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set up sensor data
    sensors[0].gpio_pin = 2;
    sensors[0].line_number = 0;
    sensors[0].line_fd = -1;
    sensors[0].running = 1;

    sensors[1].gpio_pin = 3;
    sensors[1].line_number = 1;
    sensors[1].line_fd = -1;
    sensors[1].running = 1;

    sensors[2].gpio_pin = 4;
    sensors[2].line_number = 2;
    sensors[2].line_fd = -1;
    sensors[2].running = 1;

    sensors[3].gpio_pin = 17;
    sensors[3].line_number = 3;
    sensors[3].line_fd = -1;
    sensors[3].running = 1;

    sensors[4].gpio_pin = 27;
    sensors[4].line_number = 4;
    sensors[4].line_fd = -1;
    sensors[4].running = 1;

    // Open log file
    FILE *log_file = fopen("/var/log/flame_events.log", "a");
    if (log_file == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        cleanup();
        closelog();
        return 1;
    }

    // Main loop
    while (sensors[0].running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            // Read sensor value
            int sensor_value = gpioRead(sensors[i].gpio_pin);

            if (sensor_value == 0) { // Flame detected (LOW signal)
                syslog(LOG_INFO, "Flame detected on sensor %d (GPIO %d)", sensors[i].line_number, sensors[i].gpio_pin);

                // Debounce and confirm flame detection
                for (int j = 0; j < DEBOUNCE_DELAY_MS; j++) {
                    gpioDelay(1000); // 1ms delay
                    if (read_line(sensors[i].line_number, sensors[i].line_buffer, sizeof(sensors[i].line_buffer)) == 0) {
                        if (strstr(sensors[i].line_buffer, "Flame Detected") != NULL) {
                            log_event(sensors[i].line_number, sensors[i].gpio_pin, "Flame Detected");
                            break; // Exit debounce loop if confirmed
                        }
                    } else {
                        syslog(LOG_ERR, "Failed to read line %d (GPIO %d) after debounce", sensors[i].line_number, sensors[i].gpio_pin);
                        break; // Exit debounce loop if read fails
                    }
                }

                // Write to log file
                char log_message[256];
                snprintf(log_message, sizeof(log_message), "Flame Detected on sensor %d (GPIO %d)", sensors[i].line_number, sensors[i].gpio_pin);
                if (write_line(sensors[i].line_number, log_message) != 0) {
                    syslog(LOG_ERR, "Failed to write to line %d (GPIO %d)", sensors[i].line_number, sensors[i].gpio_pin);
                }
            } else {
                // No flame detected
                syslog(LOG_INFO, "No flame detected on sensor %d (GPIO %d)", sensors[i].line_number, sensors[i].gpio_pin);
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup
    cleanup();
    closelog();
    return 0;
}

// Function to acquire a line
int acquire_line(int line_number) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to acquire...", line_number);
        if (request_line(line_number) != 0) {
            syslog(LOG_ERR, "Failed to request line %d", line_number);
            return -1;
        }
        if (release_line(line_number) != 0) {
            syslog(LOG_ERR, "Failed to release line %d", line_number);
            return -1;
        }
        if (acquire_line(line_number) != 0) {
            syslog(LOG_ERR, "Failed to acquire line %d", line_number);
            return -1;
        }
    }
    return 0;
}

// Function to release a line
int release_line(int line_number) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) != -1) {
        syslog(LOG_INFO, "Releasing line %d", line_number);
        if (unlink(line_path) == -1) {
            syslog(LOG_ERR, "Failed to unlink line %d: %s", line_number, strerror(errno));
            return -1;
        }
        return 0;
    }
    return -1;
}

// Function to request a line
int request_line(int line_number) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to request...", line_number);
        if (mkfifo(line_path, 0666) == -1) {
            syslog(LOG_ERR, "Failed to create FIFO %s: %s", line_path, strerror(errno));
            return -1;
        }
        syslog(LOG_INFO, "Created FIFO for line %d", line_number);
        return 0;
    }
    syslog(LOG_INFO, "Line %d already exists", line_number);
    return 0;
}

// Function to write to a line
int write_line(int line_number, const char *data) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to write to...", line_number);
        return -1;
    }

    ssize_t bytes_written = write(fileno(sensors[0].line_fd), data, strlen(data));
    if (bytes_written == -1) {
        syslog(LOG_ERR, "Failed to write to line %d: %s", line_number, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Wrote to line %d: %s", line_number, data);
    return 0;
}

// Function to read from a line
int read_line(int line_number, char *buffer, size_t buffer_size) {
    char line_path[50];
    snprintf(line_path, sizeof(line_path), "/dev/line%d", line_number);

    if (access(line_path, F_OK) == -1) {
        syslog(LOG_ERR, "Line %d not found, attempting to read from...", line_number);
        return -1;
    }

    ssize_t bytes_read = read(fileno(sensors[0].line_fd), buffer, buffer_size - 1);
    if (bytes_read == -1) {
        syslog(LOG_ERR, "Failed to read from line %d: %s", line_number, strerror(errno));
        return -1;
    }
    buffer[bytes_read] = '\0'; // Null-terminate the buffer
    syslog(LOG_INFO, "Read from line %d: %s", line_number, buffer);
    return 0;
}

void cleanup() {
    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close line file descriptors
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensors[i].line_fd != -1) {
            close(sensors[i].line_fd);
        }
    }

    // Close pigpio
    gpioTerminate();
}

