#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <stdint.h>

// Define the GPIO pins for the TTP226 sensor
#define OUT0_GPIO 5
#define OUT1_GPIO 6
#define OUT2_GPIO 13
#define OUT3_GPIO 19
#define OUT4_GPIO 26
#define OUT5_GPIO 12
#define OUT6_GPIO 16
#define OUT7_GPIO 20

// Define the SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define the chip select pin for the MCP3008
#define CS_PIN 8

// Define the number of channels to read
#define NUM_CHANNELS 8

// Define the delay between readings (in milliseconds)
#define READ_DELAY_MS 50

// Global variables
int spi_fd;
uint8_t *gpio_map;
uint32_t *gpio_values;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init(const char *device, int mode);
int gpio_map_gpio(int gpio);
int gpio_map_gpio_value(int gpio, int index);
int read_mcp3008(int channel);
void log_event(int index, int pin, int state);
void signal_handler(int signum);

// Structure to hold GPIO configuration
typedef struct {
    int gpio;
    uint32_t value;
} gpio_config_t;

// Function to initialize the SPI interface
int spi_init(const char *device, int mode) {
    int fd;
    uint8_t mode_value = mode;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to map a GPIO pin to its value in the GPIO memory
int gpio_map_gpio(int gpio) {
    return gpio / 1024; // Assuming GPIO pins are numbered 0-1023
}

// Function to map a GPIO pin to its value in the GPIO memory
int gpio_map_gpio_value(int gpio, int index) {
    return gpio_values[gpio / 1024] & (1 << index);
}

// Function to read the value from a specific channel of the MCP3008
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log an event to the console
void log_event(int index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - GPIO %d (BCM %d): %s\n", timestamp, index, pin, state ? "Touched" : "Released");
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the SPI interface
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Map the GPIO pins to their values in the GPIO memory
    gpio_map = (uint8_t *)mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);
    if (gpio_map == MAP_FAILED) {
        perror("mmap failed");
        close(spi_fd);
        return 1;
    }

    // Initialize the GPIO values
    for (int i = 0; i < 1024; i++) {
        gpio_values[i] = 0;
    }

    // Main loop
    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading channel %d\n", i);
                continue;
            }

            // Map the ADC value to a GPIO pin
            int gpio_index = gpio_map_gpio_value(i, adc_value);
            int gpio_value = gpio_values[gpio_index];

            // Check for state changes
            if (gpio_value != gpio_values[gpio_index]) {
                log_event(i, gpio_index, gpio_value != 0);
                gpio_values[gpio_index] = gpio_value;
            }
        }

        usleep(READ_DELAY_MS * 1000); // Delay for 50ms
    }

    // Unmap the GPIO memory
    if (munmap((void *)gpio_map, 4096) < 0) {
        perror("munmap failed");
    }

    // Close the SPI device
    close(spi_fd);

    printf("Program finished.\n");
    return 0;
}

