#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GPIO_LED 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define LOG_FILE "grow_log.txt"

// VEML7700 Registers
#define VEML7700_ALS_CONF 0x00
#define VEML7700_ALS_WH 0x01
#define VEML7700_ALS_WL 0x02
#define VEML7700_ALS 0x04
#define VEML7700_WHITE 0x05
#define VEML7700_POWER_SAVE 0x06

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_veml7700();
int read_veml7700(float *lux);
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int veml7700_address;
    int led_gpio;
    int pwm_frequency;
    int pwm_range;
    char log_file_name[64];
} config_t;

config_t config = {
    .i2c_bus = I2C_BUS,
    .veml7700_address = VEML7700_ADDR,
    .led_gpio = GPIO_LED,
    .pwm_frequency = PWM_FREQUENCY,
    .pwm_range = PWM_RANGE,
    .log_file_name = LOG_FILE
};

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize VEML7700
    if (init_veml7700() != 0) {
        fprintf(stderr, "VEML7700 initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(config.led_gpio, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(config.led_gpio, config.pwm_frequency);
    gpioSetPWMrange(config.led_gpio, config.pwm_range);

    // Main loop
    float lux;
    int brightness;
    int error_code;

    while (!terminate) {
        // Read lux value
        if (read_veml7700(&lux) != 0) {
            error_code = 1; // I2C read error
        } else {
            // Map lux to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            if (set_led_brightness(brightness) != 0) {
                error_code = 2; // LED control error
            }
        }

        // Log data
        if (log_data(lux, brightness, error_code) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.veml7700_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Initialize VEML7700 sensor
int init_veml7700() {
    // Configure VEML7700 for continuous mode, integration time 100ms, gain 2
    if (i2cWriteByteData(i2c_handle, VEML7700_ALS_CONF, 0x00) < 0) {
        fprintf(stderr, "Failed to write to VEML7700_ALS_CONF\n");
        return 1;
    }

    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, VEML7700_POWER_SAVE, 0x00) < 0) {
        fprintf(stderr, "Failed to write to VEML7700_POWER_SAVE\n");
        return 1;
    }

    return 0;
}

// Read lux value from VEML7700 sensor
int read_veml7700(float *lux) {
