#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensor channels
const int touch_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int led_pin = 17;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioWrite(led_pin, 0); // Turn off the LED
    gpioTerminate(); // Terminate the pigpio library
    exit(0);
}

// Function to read the state of a touch sensor channel
int read_touch_channel(int pin) {
    return gpioRead(pin);
}

// Function to log a touch event to a file
void log_touch_event(int channel) {
    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening touch_log.txt for writing!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel);
    fclose(fp);
}

// Function to update the LED based on the sensor readings
void update_led(int *sensor_states) {
    int led_state = 0;
    for (int i = 0; i < 8; i++) {
        if (sensor_states[i] == 1) {
            led_state = 1;
            break;
        }
    }
    gpioWrite(led_pin, led_state);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins for the touch sensor channels as inputs with pull-down resistors
    for (int i = 0; i < 8; i++) {
        gpioSetMode(touch_pins[i], PI_INPUT);
        gpioSetPullUpDown(touch_pins[i], PI_PUD_DOWN);
    }

    // Set the GPIO pin for the LED as an output
    gpioSetMode(led_pin, PI_OUTPUT);

    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_states[8];
        for (int i = 0; i < 8; i++) {
            sensor_states[i] = read_touch_channel(touch_pins[i]);
        }

        update_led(sensor_states);

        // Debounce the sensor readings
        gpioDelay(50); // Wait 50ms
    }

    // Clean up and exit
    gpioWrite(led_pin, 0); // Turn off the LED
    gpioTerminate(); // Terminate the pigpio library
    return 0;
}

