#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0x0000 // Continuous conversion mode, 100ms conversion time
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int config_opt3001(int handle, int config_value);
int read_opt3001(int handle, unsigned int *lux);
float convert_to_lux(unsigned int raw_data);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure OPT3001
int config_opt3001(int handle, int config_value) {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF; // MSB
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Failed to write to config register\n");
        return -1;
    }
    return 0;
}

// Read data from OPT3001
int read_opt3001(int handle, unsigned int *lux) {
    char buf[1];
    char data[2];
    int result;

    buf[0] = RESULT_REG;

    if (i2cWriteDevice(handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to write to result register\n");
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read from result register\n");
        return -1;
    }

    // Byte swap for big-endian to little-endian conversion
    unsigned int raw_data = ((unsigned int)data[0] << 8) | (unsigned int)data[1];
    *lux = raw_data;

    return 0;
}

// Convert raw data to lux
float convert_to_lux(unsigned int raw_data) {
    return (float)raw_data * 0.0036;
}

// Log data to file
int log_data(float lux_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, lux_value);
    fclose(fp);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure OPT3001
    if (config_opt3001(i2c_handle, CONFIG_VALUE) != 0) {
        cleanup();
        return 1;
    }

    unsigned int raw_data;
    float lux_value;

    // Main loop
    while (!terminate) {
        // Read data from OPT3001
        if (read_opt3001(i2c_handle, &raw_data) == 0) {
            // Convert to lux
            lux_value = convert_to_lux(raw_data);

            // Log data
            if (log_data(lux_value) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }

            printf("Lux: %.2f\n", lux_value);
        } else {
            fprintf(stderr, "Failed to read data from OPT3001\n");
        }

        sleep(1);
    }

    // Cleanup resources
    cleanup();

    return 0;
}

