#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 4
#define ALERT_GPIO 17
#define LOG_FILE "fire_events.log"

FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[21]; // YYYY-MM-DDTHH:MM:SSZ\0

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
void log_event(const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: Flame detected!\n", timestamp);
        fflush(log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle the flame detection event
void handle_flame_detection() {
    log_event(get_timestamp());
    gpioWrite(ALERT_GPIO, 1); // Set the alert pin HIGH
    gpioDelay(1000);          // Wait for 1 second
    gpioWrite(ALERT_GPIO, 0); // Set the alert pin LOW
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure alert pin is initially LOW

    return 0; // Indicate success
}

