#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define LOG_FILE "touch_log.txt"

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    FILE *log_file = NULL;
    int last_state = 0;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = gpioRead(TOUCH_PIN);

        if (current_state != last_state) {
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (current_state == 1) {
                fprintf(log_file, "%s: Touch Detected\n", timestamp);
                fflush(log_file);
                printf("%s: Touch Detected\n", timestamp);
            } else {
                fprintf(log_file, "%s: Touch Released\n", timestamp);
                fflush(log_file);
                printf("%s: Touch Released\n", timestamp);
            }
            last_state = current_state;
        }

        gpioDelay(50000); // 50ms debounce
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

