#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define FLOW_REG 0x00
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT_VALUE 0xFF
#define SLEEP_MS 1000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC_INIT_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from the sensor
int read_flow_rate(int i2c_handle, int *flow_rate) {
    char buf[3];
    int result;

    // Send measurement command (0x3608)
    result = i2cWriteByteData(i2c_handle, 0, 0x3608);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait at least 2ms
    gpioDelay(2000);

    // Read 3 bytes from the sensor
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Validate CRC
    uint8_t crc_calculated = crc8(buf, 2);
    if (crc_calculated != buf[2]) {
        fprintf(stderr, "CRC error: calculated 0x%02X, received 0x%02X\n", crc_calculated, buf[2]);
        return -1;
    }

    // Convert raw data to flow rate
    *flow_rate = (int16_t)((buf[0] << 8) | buf[1]);

    return 0;
}

// Function to validate flow rate
int validate_flow_rate(int flow_rate) {
    if (flow_rate < 0 || flow_rate > 1000) {
        return -1; // INVALID
    }
    return 0; // VALID
}

// Function to log data to a CSV file
void log_data(FILE *log_file, int flow_rate, int raw_flags, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%s\n", timestamp, flow_rate, raw_flags, (status == 0) ? "OK" : (status == 1) ? "CRC Error" : (status == 2) ? "FLOW OUT OF RANGE" : (status == 3) ? "I2C Error" : (status == 4) ? "FILE ERROR" : (status == 5) ? "UNKNOWN ERROR" : "UNKNOWN ERROR");
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int flow_rate;
    int raw_flags;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }
    fseek(log_file, 0, SEEK_END);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read flow rate
        if (read_flow_rate(i2c_handle, &flow_rate) == 0) {
            // Validate flow rate
            status = validate_flow_rate(flow_rate);

            // Log data
            log_data(log_file, flow_rate, raw_flags, status);
        } else {
            fprintf(stderr, "Error reading flow rate\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_MS * 1000);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

