#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_GPIO 17
#define MIDDLE_SENSOR_GPIO 27
#define RIGHT_SENSOR_GPIO 22
#define SAMPLE_INTERVAL_MS 50
#define LOG_FILE_NAME "path_log.csv"

static volatile bool running = true;

void signal_handler(int signal) {
    running = false;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

int get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    if (timeinfo == NULL) {
        fprintf(stderr, "Error: gmtime failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int log_data(const char *timestamp, int left_sensor, int middle_sensor, int right_sensor) {
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s: %s\n", LOG_FILE_NAME, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor);
    if (ferror(fp)) {
        fprintf(stderr, "Error writing to file %s: %s\n", LOG_FILE_NAME, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing file %s: %s\n", LOG_FILE_NAME, strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_GPIO, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    char timestamp_buffer[32]; // Buffer for ISO 8601 timestamp

    while (running) {
        // Read sensor values
        int left_sensor_value = read_sensor(LEFT_SENSOR_GPIO);
        int middle_sensor_value = read_sensor(MIDDLE_SENSOR_GPIO);
        int right_sensor_value = read_sensor(RIGHT_SENSOR_GPIO);

        // Get timestamp
        if (get_iso8601_timestamp(timestamp_buffer, sizeof(timestamp_buffer)) != 0) {
            fprintf(stderr, "Error getting timestamp, skipping log entry.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay to avoid flooding the console
            continue;
        }

        // Log data
        if (log_data(timestamp_buffer, left_sensor_value, middle_sensor_value, right_sensor_value) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Clean up GPIO lines and close the pigpio library
    gpioTerminate();

    return 0;
}

