        if (log_data(timestamp_buffer, left_sensor_value, middle_sensor_value, right_sensor_value) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 50ms
    }

    // Clean up GPIO lines and close the pigpio library
    gpioTerminate();

    return 0;
