#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24
#define LOG_FILE "touch_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_led();
void log_touch_event(const char *timestamp, int led_state);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED
void toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
}

// Function to log touch events to a file
void log_touch_event(const char *timestamp, int led_state) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s, %d\n", timestamp, led_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    printf("Touch lamp simulation started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_touch_sensor() == 1) {
            // Debounce: Wait for a short period to avoid multiple triggers
            gpioDelay(200000); // 200ms

            int led_state = gpioRead(LED_PIN);
            toggle_led();
            log_touch_event(ctime(NULL), led_state);
        }
        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

