#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <gpiod.h>

#define FLAME_SENSOR_CHIP "gpiochip0"
#define FLAME_SENSOR_LINE 17
#define BUZZER_CHIP "gpiochip0"
#define BUZZER_LINE 18

#define LOG_FILE "alert_log.txt"

static struct gpiod_chip *flame_sensor_chip = NULL;
static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function to log messages to the log file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Function to initialize GPIO lines
int initialize_gpio() {
    flame_sensor_chip = gpiod_chip_open_by_name(FLAME_SENSOR_CHIP);
    if (!flame_sensor_chip) {
        perror("Error opening flame sensor chip");
        return -1;
    }

    flame_sensor_line = gpiod_chip_get_line(flame_sensor_chip, FLAME_SENSOR_LINE);
    if (!flame_sensor_line) {
        perror("Error getting flame sensor line");
        gpiod_chip_close(flame_sensor_chip);
        return -1;
    }

    buzzer_line = gpiod_chip_get_line(buzzer_chip, BUZZER_LINE);
    if (!buzzer_line) {
        perror("Error getting buzzer line");
        gpiod_chip_close(flame_sensor_chip);
        gpiod_line_release(flame_sensor_line);
        return -1;
    }

    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        perror("Error requesting flame sensor line as input");
        gpiod_chip_close(flame_sensor_chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        perror("Error requesting buzzer line as output");
        gpiod_chip_close(flame_sensor_chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpiod_line_get_value(flame_sensor_line);
}

// Function to activate the buzzer
void activate_buzzer() {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        perror("Error setting buzzer line HIGH");
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        perror("Error setting buzzer line LOW");
    }
}

// Function to log flame detection
void log_flame_detection() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_message("FLAME DETECTED");
}

// Function to handle signals
void signal_handler(int sig) {
    program_running = 0;
    log_message("Signal received, shutting down...");

    // Turn off buzzer
    deactivate_buzzer();

    // Release GPIO lines
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close GPIO chip
    if (flame_sensor_chip) {
        gpiod_chip_close(flame_sensor_chip);
    }

    // Terminate program
    exit(0);
}

int main() {
    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return 1;
    }

    log_message("System started");

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        log_message("GPIO initialization failed");
        fclose(log_file);
        return 1;
    }

    // Main loop
    while (program_running) {
        int flame_detected = (read_flame_sensor() == 0); // Active low

        if (flame_detected) {
            log_flame_detection();
            activate_buzzer();
            sleep(2); // Buzzer for 2 seconds
            deactivate_buzzer();
        } else {
            // Poll every 500ms
            struct timespec req = {0};
            req.tv_sec = 0;
            req.tv_nsec = 500 * 1000 * 1000; // 500ms
            nanosleep(&req, NULL);
        }
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_buzzer();
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (flame_sensor_chip) {
        gpiod_chip_close(flame_sensor_chip);
    }
    fclose(log_file);

    return 0;
}

