#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SENSOR_PIN 4
#define LED_PIN 17
#define DEBOUNCE_DELAY_MS 200

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in UTC ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *info;
    char *buffer = malloc(sizeof(char) * 30); // Allocate memory for the timestamp string
    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    info = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(buffer, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return buffer;
}

// Function to log the timestamp to a file
int log_timestamp(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure the data is written to the file immediately
    return 0;
}

// Function to toggle the LED
void toggle_led() {
    int current_level = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_level);
}

// Function to debounce the sensor
void debounce() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

