#define SENSOR3_PIN 27

// Define the log file name
#define LOG_FILE "magnet_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL; // Or handle the error as appropriate
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the sensor state to a file
void log_sensor_state(int sensor_id, int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return;
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor_id, state);
    free(timestamp); // Free the allocated memory
    fclose(fp);
}

