        log_sensor_state(2, sensor2_state);
        log_sensor_state(3, sensor3_state);

        gpioDelay(100); // Wait 100ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

