#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define MOVING_AVG_SIZE 5
#define HEART_RATE_REG 0x24 // Example register address
#define LOG_FILE "heart_rate.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int *raw_data);
int validate_heart_rate(int *raw_data, int *filtered_data);
int log_data(int bpm);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t part_id;
    uint8_t hw_rev;
    uint8_t led_drive_strength;
    uint8_t measurement_mode;
} sensor_config_t;

// Function to read a single byte from the sensor with retry
int read_sensor_data_with_retry(int reg, uint8_t *data) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            *data = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s. Retrying...\n", reg, strerror(errno));
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

// Function to read multiple bytes from the sensor with retry
int read_sensor_data_with_retry_bytes(int reg, uint8_t *data, int count) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cReadI2CBlockData(i2c_handle, reg, (char *)data, count);
        if (result >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, count %d): %s. Retrying...\n", reg, count, strerror(errno));
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read sensor data after multiple retries.\n");
    return -1; // Failure
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Main loop
    int raw_data[MOVING_AVG_SIZE];
    int filtered_data[MOVING_AVG_SIZE];
    int filtered_index = 0;

    while (!terminate) {
        // Read raw sensor data
        if (read_sensor_data_with_retry(HEART_RATE_REG, &raw_data[filtered_index]) != 0) {
            fprintf(stderr, "Failed to read raw sensor data. Skipping.\n");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Apply moving average filter
        for (int i = 0; i < MOVING_AVG_SIZE; i++) {
            filtered_data[i] = raw_data[i];
        }

        // Validate heart rate
        if (validate_heart_rate(raw_data, filtered_data) != 0) {
            fprintf(stderr, "Invalid heart rate reading. Skipping.\n");
            gpioDelay(1000000); // 1 second delay
            continue;
        }

        // Log data
        if (log_data(filtered_data[0]) != 0) {
            fprintf(stderr, "Failed to log data. Skipping.\n");
        }

        // Delay for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the Si1182-A-GM sensor
int init_sensor() {
    uint8_t part_id, hw_rev;

    // Read PART_ID and HW_REV registers
    if (read_sensor_data_with_retry(0x00, &part_id) != 0 || read_sensor_data_with_retry(0x01, &hw_rev) != 0) {
        fprintf(stderr, "Failed to read PART_ID or HW_REV. Check sensor connection.\n");
        return -1;
    }

    // Example configuration (replace with actual configuration from datasheet)
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) != 0) { // Example config register
        fprintf(stderr, "Failed to write to config register: %s\n", strerror(errno));
        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Read raw heart rate data from the sensor
int read_sensor_data(int *raw_data) {
    uint8_t data[2];
    if (read_sensor_data_with_retry_bytes(HEART_RATE_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read heart rate data.\n");
        return -1;
    }

    *raw_data = (data[0] << 8) | data[1];
    return 0;
}

// Validate heart rate data
int validate_heart_rate(int *raw_data, int *filtered_data) {
    if (raw_data[0] < 30 || raw_data[0] > 220) {
        fprintf(stderr, "Invalid heart rate reading: %d BPM\n", raw_data[0]);
        return -1;
    }
    return 0;
}

// Log data to CSV file
int log_data(int bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

