    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_status;
    FILE *log_file;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    int flame_detected = 0;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-up resistor
    gpio_status = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input: %d\n", FLAME_SENSOR_GPIO, gpio_status);
        gpioTerminate();
        return 1;
    }

    gpio_status = gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    if (gpio_status != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO%d: %d\n", FLAME_SENSOR_GPIO, gpio_status);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_value = gpioRead(FLAME_SENSOR_GPIO);

        if (current_value == 0) { // Flame detected (LOW signal)
            // Check for duplicate alerts within 500ms
            time_t now = time(NULL);
            if (!flame_detected) {
                // Get current timestamp
                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Write to log file
                fprintf(log_file, "%s FLAME DETECTED\n", timestamp);
                fflush(log_file); // Ensure immediate write

                // Print to console
                printf("%s FLAME DETECTED\n", timestamp);

                flame_detected = 1; // Set flag to prevent duplicate alerts
            }
        } else {
            flame_detected = 0; // Reset flag if no flame detected
        }

        gpioDelay(100); // Wait 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

