#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Define GPIO pins for sensor inputs and output pins
#define SENSOR_PINS {5, 6, 7, 8, 9, 10, 11, 12}
#define OUTPUT_PINS {17, 18, 19, 20, 21, 22, 23, 24}
#define NUM_CHANNELS 8

// Define SPI parameters for MCP3008 ADC
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // Channel connected to the touch sensor

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Global variables
int spi_fd;
int spi_device = 0; // SPI device number (e.g., 0 for CE0)

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int read_sensor_channel(int channel);
int update_output_pin(int channel, int value);
int log_touch_event(int channel, int counter_value);
void signal_handler(int signal);

// Structure to hold GPIO and SPI configuration
typedef struct {
    int sensor_pins[NUM_CHANNELS];
    int output_pins[NUM_CHANNELS];
    int spi_fd;
    int spi_device;
} AppConfig;

AppConfig config;

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set sensor pins as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(config.sensor_pins[i], PI_INPUT);
    }

    // Set output pins as outputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioSetMode(config.output_pins[i], PI_OUTPUT);
        gpioWrite(config.output_pins[i], 0); // Initialize all output pins to 0
    }

    return 0;
}

// Function to initialize the SPI interface
int initialize_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read data from the MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct the SPI message to send to the MCP3008
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value from the received data
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to read the sensor channel value
int read_sensor_channel(int channel) {
    int adc_value = read_mcp3008(MCP3008_CHANNEL);
    if (adc_value < 0) {
        fprintf(stderr, "Error reading sensor channel %d\n", channel);
        return -1;
    }
    return adc_value;
}

// Function to update the output pin value
int update_output_pin(int channel, int value) {
    if (channel < 0 || channel >= NUM_CHANNELS) {
        fprintf(stderr, "Invalid channel number: %d\n", channel);
        return -1;
    }

    if (gpioWrite(config.output_pins[channel], value) != 0) {
        fprintf(stderr, "Error writing to output pin %d\n", channel);
        return -1;
    }
    return 0;
}

// Function to log the touch event to a file
int log_touch_event(int channel, int counter_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter_value);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Reset all output pins to 0
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioWrite(config.output_pins[i], 0);
    }

    // Close the SPI device
    if (spi_fd > 0) {
        close(spi_fd);
    }

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize configuration
    config.sensor_pins[0] = 5;
    config.sensor_pins[1] = 6;
    config.sensor_pins[2] = 7;
    config.sensor_pins[3] = 8;
    config.sensor_pins[4] = 9;
    config.sensor_pins[5] = 10;
    config.sensor_pins[6] = 11;
    config.sensor_pins[7] = 12;

    config.output_pins[0] = 17;
    config.output_pins[1] = 18;
    config.output_pins[2] = 19;
    config.output_pins[3] = 20;
    config.output_pins[4] = 21;
    config.output_pins[5] = 22;
    config.output_pins[6] = 23;
    config.output_pins[7] = 24;

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Stabilization delay
    gpioDelay(200000); // 200 ms

    // Main loop
    while (1) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int sensor_value = read_sensor_channel(i);
            if (sensor_value < 0) {
                fprintf(stderr, "Error reading sensor channel %d, skipping\n", i);
                continue;
            }

            // Increment the counter
            int counter_value = gpioRead(config.output_pins[i]);
            if (counter_value < 0) {
                fprintf(stderr, "Error reading output pin %d, skipping\n", i);
                continue;
            }

            counter_value++;
            if (counter_value >= 256) {
                counter_value = 0;
            }

            // Update the output pin
            if (update_output_pin(i, counter_value) != 0) {
                fprintf(stderr, "Error updating output pin %d\n", i);
            }

            // Log the touch event
            if (log_touch_event(i, counter_value) != 0) {
                fprintf(stderr, "Error logging touch event for channel %d\n", i);
            }

            printf("Touch on channel %d | Counter: %d\n", i, counter_value);
        }

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

