#define SENSOR_2_GPIO 18
#define SENSOR_3_GPIO 27
#define SENSOR_4_GPIO 22
#define POLLING_INTERVAL_MS 100

FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
