    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

int log_event(int sensor_number) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Sensor %d tilted\n", timestamp, sensor_number);
    fclose(fp);
    return 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes and pull-up resistors
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, but continue to the next iteration
            gpioDelay(100); // Small delay to avoid flooding the console with errors
            continue;
        }

        if (sensor1_value == 0) {
            if (log_event(1) == 0) {
                printf("Sensor 1 tilted\n");
            } else {
                fprintf(stderr, "Error logging event for sensor 1\n");
            }
        }

        if (sensor2_value == 0) {
            if (log_event(2) == 0) {
                printf("Sensor 2 tilted\n");
            } else {
                fprintf(stderr, "Error logging event for sensor 2\n");
            }
        }

        gpioDelay(100); // Poll every 100ms
    }

    gpioTerminate();
    printf("pigpio terminated.\n");
    return 0;
}

