#include <pigpio.h>

#define MIC_PIN 4
#define LED_PIN 17

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    signal(SIGINT, signal_handler);

    struct timespec ts;
    int peak_detected = 0;
    int last_state = 0;

    while (program_running) {
        int current_state = gpioRead(MIC_PIN);

        if (current_state != last_state) {
            if (current_state == 1) {
                peak_detected = 1;
            } else {
                peak_detected = 0;
            }
        }

        if (peak_detected) {
            clock_gettime(CLOCK_REALTIME, &ts);
            printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);

            gpioWrite(LED_PIN, 1);
            gpioDelay(100); // 100ms
            gpioWrite(LED_PIN, 0);
        }

        last_state = current_state;
        gpioDelay(125); // 125 us period
    }

    gpioTerminate();
    return 0;
}

