#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    fprintf(stderr, "SIGTERM received, exiting gracefully...\n");
    program_running = 0;
}

// Function to read the sensor state from a given GPIO pin
int read_sensor(int gpio_pin)
{
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to log the sensor states to the console
void log_sensor_states(int left_state, int center_state, int right_state)
{
    printf("Left: %d, Center: %d, Right: %d\n", left_state, center_state, right_state);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as inputs with active-low configuration and pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop to read and log sensor states
    while (program_running) {
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int center_state = read_sensor(CENTER_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        if (left_state == -1 || center_state == -1 || right_state == -1) {
            // Error occurred during sensor reading, exit the loop
            program_running = 0;
            continue; // Skip logging and retry
        }

        log_sensor_states(left_state, center_state, right_state);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

