#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from two registers
int16_t read_16bit_value(int handle, uint8_t lsb_reg, uint8_t msb_reg)
{
    int lsb = i2cReadByteData(handle, lsb_reg);
    int msb = i2cReadByteData(handle, msb_reg);

    if (lsb < 0 || msb < 0) {
        fprintf(stderr, "Error reading LSB or MSB register: %d, %d\n", lsb, msb);
        return -1; // Indicate error
    }

    return (int16_t)((msb << 8) | lsb);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read ALS data
        int16_t als_value = read_16bit_value(i2c_handle, SI1175_REG_ALS_VIS_DATA0, SI1175_REG_ALS_VIS_DATA1);

        if (als_value >= 0) {
            // Print the raw sensor reading
            printf("ALS Value: %d\n", als_value);
        } else {
            fprintf(stderr, "Failed to read ALS data\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

