#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the touch sensor channels
#define TP1 5
#define TP2 6
#define TP3 13
#define TP4 19
#define TP5 26
#define TP6 12
#define TP7 16
#define TP8 20

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, shutting down gracefully...\n");
    }
}

// Function to read the state of a single touch sensor channel
int read_touch_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to format the touch sensor data into a string
void format_touch_data(int sensor_values[], char *output_string, int num_sensors) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    for (int i = 0; i < num_sensors; i++) {
        char channel_str[20];
        snprintf(channel_str, sizeof(channel_str), "CH%d=%d", i + 1, sensor_values[i]);
        strcat(output_string, channel_str);
        if (i < num_sensors - 1) {
            strcat(output_string, ",");
        }
    }
    strcat(output_string, "\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(TP1, PI_INPUT);
    gpioSetMode(TP2, PI_INPUT);
    gpioSetMode(TP3, PI_INPUT);
    gpioSetMode(TP4, PI_INPUT);
    gpioSetMode(TP5, PI_INPUT);
    gpioSetMode(TP6, PI_INPUT);
    gpioSetMode(TP7, PI_INPUT);
    gpioSetMode(TP8, PI_INPUT);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to read and print the touch sensor data
    while (program_running) {
        int sensor_values[8];
        for (int i = 0; i < 8; i++) {
            sensor_values[i] = read_touch_sensor(i + 1);
            if (sensor_values[i] < 0) {
                // Error reading a sensor, set to 0 to avoid affecting the output
                sensor_values[i] = 0; // Or handle the error more appropriately
            }
        }

        char output_string[256];
        format_touch_data(sensor_values, output_string, 8);

        printf("%s", output_string);
        fflush(stdout); // Ensure the output is printed immediately

        gpioDelay(200); // Wait for 200 milliseconds
    }

    // Release the GPIO resources before exiting
    gpioTerminate();
    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

