#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define I2C address for BH1750 sensor
#define BH1750_ADDR 0x23

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define number of steps for linear interpolation
#define NUM_STEPS 50

// Define the duration of the fade in seconds
#define DURATION 5

// Global variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux);
void set_led_color(int red, int green, int blue);
void fade_led(float lux);
void signal_handler(int signal);

// Structure to hold RGB color values
typedef struct {
    int red;
    int green;
    int blue;
} RGBColor;

// Function to initialize the I2C bus
int initialize_i2c() {
    if ((i2c_fd = open("/dev/i2c-1", O_RDWR)) < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus: %m");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave: %m");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read light intensity from BH1750 sensor
int read_bh1750(float *lux) {
    unsigned char buf[2];
    int lux_raw;

    // Send start measurement command (High Resolution Mode)
    if (write(i2c_fd, "\x01", 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device: %m");
        return -1;
    }

    // Wait for measurement to complete (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from I2C device: %m");
        return -1;
    }

    // Convert raw data to lux
    lux_raw = (buf[0] << 8) | buf[1];
    *lux = (float)lux_raw / 1.2;

    return 0;
}

// Function to set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to perform linear interpolation to fade the LED
void fade_led(float lux) {
    float lux_range = 0.0;
    float lux_current = 0.0;
    float lux_step = lux_range / NUM_STEPS;
    float lux_increment = lux_step / 2.0;
    float lux_current_step = 0.0;

    for (int i = 0; i < NUM_STEPS; i++) {
        lux_current_step += lux_increment;

        // Clamp the lux value to the range 0-1000
        if (lux_current_step < 0.0) {
            lux_current_step = 0.0;
        } else if (lux_current_step > 1000.0) {
            lux_current_step = 1000.0;
        }

        // Calculate the RGB values based on the lux value
        float red = 255.0 * (lux_current_step / 1000.0);
        float green = 255.0 * (lux_current_step / 1000.0) * 0.5;
        float blue = 255.0 * (lux_current_step / 1000.0) * 0.5 * 0.5;

        // Set the LED color
        set_led_color(red, green, blue);

        // Update the current lux value
        lux_current = lux_current_step;

        // Wait for the specified duration
        usleep(DURATION * 1000000 / NUM_STEPS); // Convert seconds to microseconds
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...");
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("rgb_led_controller", LOG_PID | LOG_CONS, LOG_USER);

    // Seed the random number generator
    srand(time(NULL));

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        syslog(LOG_ERR, "I2C initialisation failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read light intensity from BH1750 sensor
        float lux;
        if (read_bh1750(&lux) == 0) {
            // Fade the LED based on the light intensity
            fade_led(lux);
        } else {
            syslog(LOG_ERR, "Failed to read light intensity");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Release I2C resources
    close(i2c_fd);

    // Release pigpio resources
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

