// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_COMMAND_BIT     0x80
#define TCS34725_ENABLE          0x00
#define TCS34725_ATIME           0x01
#define TCS34725_WTIME           0x03
#define TCS34725_AILTL           0x04
#define TCS34725_AILTH           0x05
#define TCS34725_AIHTL           0x06
#define TCS34725_AIHTH           0x07
#define TCS34725_ID              0x12
#define TCS34725_STATUS          0x13
#define TCS34725_CDATA           0x14
#define TCS34725_RDATA           0x16
#define TCS34725_GDATA           0x18
#define TCS34725_BDATA           0x1A

// LED GPIO Pin
#define LED_PIN                17

// Integration Time (154ms)
#define I2C_ADDRESS             0x29
#define I2C_BUS                "/dev/i2c-1"

// Global variables
int i2c_fd;
int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_sensor(int i2c_fd);
int read_sensor_data(int i2c_fd, unsigned int *red, unsigned int *green, unsigned int *blue, unsigned int *clear);
void control_led(unsigned int red);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    unsigned int red;
    unsigned int green;
    unsigned int blue;
    unsigned int clear;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor(int i2c_fd) {
    // Power on the sensor
    if (i2cWriteByteData(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x03) < 0) {
        perror("Failed to power on sensor");
        return -1;
    }
    gpioDelay(3); // Wait for power-on

    // Enable RGBC (AEN)
    if (i2cWriteByteData(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ENABLE, 0x0F) < 0) {
        perror("Failed to enable RGBC");
        return -1;
    }
    gpioDelay(3); // Wait for enable

    // Set integration time (ATIME)
    if (i2cWriteByteData(i2c_fd, TCS34725_COMMAND_BIT | TCS34725_ATIME, 0xEB) < 0) {
        perror("Failed to set integration time");
        return -1;
    }
    gpioDelay(3); // Wait for integration time

    return 0;
}

