    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int red, green, blue, clear;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &red, &green, &blue, &clear) == 0) {
            // Control LED
            control_led(red);

            // Print sensor data
            printf("Red: %u, Green: %u, Blue: %u, Clear: %u\n", red, green, blue, clear);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
