#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define NUM_LEDS 10
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750();
float read_lux();
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750() {
    int retries = 3;
    while (retries > 0) {
        i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
        if (i2c_handle >= 0) {
            // Set continuous high-resolution mode
            if (i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE) < 0) {
                fprintf(stderr, "Error setting mode: %d\n", i2c_handle);
                i2cClose(i2c_handle);
                i2c_handle = -1; // Reset handle to indicate failure
                retries--;
                gpioDelay(100000); // Wait 100ms before retrying
                continue;
            }
            printf("BH1750 initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
            i2c_handle = -1; // Reset handle to indicate failure
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize BH1750 after multiple retries.\n");
    return -1; // Failure
}

// Read lux value from BH1750 sensor
float read_lux() {
    unsigned char buffer[2];
    int retries = 3;
    while (retries > 0) {
        if (i2c_handle >= 0) {
            if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2) == 2) {
                unsigned int raw_value = (buffer[0] << 8) | buffer[1];
                float lux = (float)raw_value / 1.2;
                return lux;
            } else {
                fprintf(stderr, "Error reading data: %d\n", i2c_handle);
                i2cClose(i2c_handle);
                i2c_handle = -1; // Reset handle to indicate failure
                retries--;
                gpioDelay(100000); // Wait 100ms before retrying
            }
        } else {
            fprintf(stderr, "I2C handle is invalid, retrying...\n");
            i2c_handle = -1; // Reset handle to indicate failure
            retries--;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to read lux value after multiple retries.\n");
    return -1.0; // Indicate error
}

// Map lux value to brightness level (0-255) using logarithmic mapping
int map_lux_to_brightness(float lux) {
    if (lux <= 0) {
        return 0; // Avoid negative brightness
    }
    float brightness = log10(lux + 1) / log10(10000); // Scale to 0-1
    if (brightness < 0) brightness = 0;
    if (brightness > 1) brightness = 1;
    return (int)(brightness * PWM_RANGE);
}

// Set LED brightness using hardware PWM/wave capability
int set_led_brightness(int brightness) {
    int i;
    for (i = 0; i < NUM_LEDS; i++) {
        gpioWrite(18, 1); // High
        gpioDelay(500000 / (2 * PWM_FREQUENCY)); // Half period for 50Hz
        gpioWrite(18, 0); // Low
        gpioDelay(500000 / (2 * PWM_FREQUENCY)); // Half period for 50Hz
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(18, PI_OUTPUT);

    // Initialize BH1750 sensor
    if (init_bh1750() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            int brightness = map_lux_to_brightness(lux);
            set_led_brightness(brightness);
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }
        gpioDelay(500000); // Wait 500ms
    }

    // Clean up and exit
    set_led_brightness(0); // Turn off all LEDs
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

