#include <sys/time.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define SPI_DEVICE "/dev/spidev0.0"
#define NUM_LEDS 10
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_RETRY_COUNT 3
#define SPI_RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_sensor(int fd, uint16_t *light_level);
int spi_write_led_data(int fd, uint8_t *led_data, int num_leds);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// I2C read sensor function
int i2c_read_sensor(int fd, uint16_t *light_level) {
    uint8_t buf[2];
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        if (read(fd, buf, 2) == 2) {
            *light_level = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            perror("I2C read failed");
            retries++;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// SPI write LED data function
int spi_write_led_data(int fd, uint8_t *led_data, int num_leds) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)led_data,
        .rx_buf = (unsigned long)NULL,
        .len = num_leds * 4, // 4 bytes per LED (G, R, B, Global)
        .speed_hz = 1000000, // 1 MHz
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
    if (ret < 0) {
        perror("SPI write failed");
        return -1;
    }

    return 0;
}

int main() {
    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address (BH1750)
    if (ioctl(i2c_fd, I2C_SLAVE, 0x23) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Set BH1750 to continuous high-resolution mode
    uint8_t config_mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, &config_mode, 1) != 1) {
        perror("Failed to set BH1750 mode");
        close(i2c_fd);
        return 1;
    }

    // Initialize SPI
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        close(i2c_fd);
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Configure SPI max speed hz
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed hz");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Initialize LED strip with 32-bit zero start frame
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (spi_write_led_data(spi_fd, start_frame, NUM_LEDS) < 0) {
        fprintf(stderr, "Failed to initialize LED strip with start frame.\n");
        close(spi_fd);
        close(i2c_fd);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t light_level;
        if (i2c_read_sensor(i2c_fd, &light_level) == 0) {
            // Scale light level to 0-255 (brightness)
            int brightness = (int)((float)light_level / 65535.0 * 255.0);

            // Create LED data array
            uint8_t led_data[NUM_LEDS * 4];
            for (int i = 0; i < NUM_LEDS; i++) {
                led_data[i * 4 + 0] = 0x00; // Global brightness
                led_data[i * 4 + 1] = 0x00; // Green
                led_data[i * 4 + 2] = 0x00; // Red
                led_data[i * 4 + 3] = brightness; // Blue
            }

            // Write LED data to SPI
            if (spi_write_led_data(spi_fd, led_data, NUM_LEDS) < 0) {
                fprintf(stderr, "Failed to write LED data to SPI.\n");
            }
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }

        usleep(100000); // 100ms delay
    }

    // Turn off LEDs
    uint8_t zero_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (spi_write_led_data(spi_fd, zero_frame, NUM_LEDS) < 0) {
        fprintf(stderr, "Failed to turn off LEDs.\n");
    }

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    return 0;
}

