#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Define constants
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x46
#define APA102_SPI_CHANNEL 0
#define APA102_SPI_SPEED 1000000 // 1 MHz
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle_1 = -1;
int i2c_handle_2 = -1;
int i2c_handle_3 = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bh1750(int i2c_handle);
int read_bh1750(int i2c_handle);
float average_light_levels(int sensor1_value, int sensor2_value, int sensor3_value);
int init_apa102(int spi_handle);
int set_apa102_brightness(int spi_handle, int brightness);
void fade_brightness(int spi_handle, int target_brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize BH1750 sensor
int init_bh1750(int i2c_handle) {
    int result;
    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
        if (result == 0) {
            return 0; // Success
        }
        gpioDelay(1000); // Wait 1ms before retry
    }
    fprintf(stderr, "Error: Failed to initialize BH1750 sensor after %d retries. Error code: %d\n", I2C_RETRY_COUNT, errno);
    return -1; // Failure
}

// Read light level from BH1750 sensor
int read_bh1750(int i2c_handle) {
    int result;
    unsigned char buffer[2];
    for (int i = 0; i < I2C_RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2);
        if (result == 2) {
            return (buffer[0] << 8) | buffer[1]; // Combine bytes
        }
        gpioDelay(1000); // Wait 1ms before retry
    }
    fprintf(stderr, "Error: Failed to read BH1750 sensor after %d retries. Error code: %d\n", I2C_RETRY_COUNT, errno);
    return -1; // Failure
}

// Average light levels from three sensors
float average_light_levels(int sensor1_value, int sensor2_value, int sensor3_value) {
    if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
        return -1.0; // Indicate error
    }
    return (float)(sensor1_value + sensor2_value + sensor3_value) / 3.0;
}

// Initialize APA102 LED strip
int init_apa102(int spi_handle) {
    // This is a placeholder.  APA102 initialization requires more complex
    // configuration, including setting the start frame and sending individual LED data.
    // For a real implementation, you would need to generate the start frame and send
    // individual LED data frames.
    // This simplified example just prints a message.
    printf("Initializing APA102 LED strip...\n");
    return 0;
}

// Set APA102 LED strip brightness
int set_apa102_brightness(int spi_handle, int brightness) {
    // This is a placeholder.  APA102 brightness control requires sending
    // individual LED data frames with the desired brightness values.
    // For a real implementation, you would need to construct the data frames
    // and send them over the SPI bus.
    // This simplified example just prints a message.
    printf("Setting APA102 brightness to %d...\n", brightness);
    return 0;
}

// Fade brightness to target value
void fade_brightness(int spi_handle, int target_brightness) {
    int current_brightness = 0;
    int increment = 10; // Adjust for desired fading speed
    int delay_ms = 10;   // Adjust for desired fading speed

    while (current_brightness < target_brightness) {
        set_apa102_brightness(spi_handle, current_brightness);
        current_brightness += increment;
        gpioDelay(delay_ms * 1000); // Delay in microseconds
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for BH1750 sensors
    i2c_handle_1 = i2cOpen(1, BH1750_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 1 (address 0x%02X): %d\n", BH1750_ADDR_1, i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(1, BH1750_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 2 (address 0x%02X): %d\n", BH1750_ADDR_2, i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_3 = i2cOpen(1, BH1750_ADDR_3, 0);
    if (i2c_handle_3 < 0) {
        fprintf(stderr, "Error: Could not open I2C device 3 (address 0x%02X): %d\n", BH1750_ADDR_3, i2c_handle_3);
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        gpioTerminate();
        return 1;
    }

    // Initialize BH1750 sensors
    if (init_bh1750(i2c_handle_1) != 0 || init_bh1750(i2c_handle_2) != 0 || init_bh1750(i2c_handle_3) != 0) {
        fprintf(stderr, "Error: Failed to initialize one or more BH1750 sensors\n");
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        i2cClose(i2c_handle_3);
        gpioTerminate();
        return 1;
    }

    // Open SPI handle for APA102 LED strip
    spi_handle = spiOpen(APA102_SPI_CHANNEL, APA102_SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI device: %d\n", spi_handle);
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        i2cClose(i2c_handle_3);
        gpioTerminate();
        return 1;
    }

    // Initialize APA102 LED strip
    if (init_apa102(spi_handle) != 0) {
        fprintf(stderr, "Error: Failed to initialize APA102 LED strip\n");
        spiClose(spi_handle);
        i2cClose(i2c_handle_1);
        i2cClose(i2c_handle_2);
        i2cClose(i2c_handle_3);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read light levels from sensors
        int sensor1_value = read_bh1750(i2c_handle_1);
        int sensor2_value = read_bh1750(i2c_handle_2);
        int sensor3_value = read_bh1750(i2c_handle_3);

        // Average light levels
        float average_light = average_light_levels(sensor1_value, sensor2_value, sensor3_value);

        if (average_light != -1.0) {
            // Set APA102 brightness
            int target_brightness = (int)average_light; // Directly use the average light level as brightness
            set_apa102_brightness(spi_handle, target_brightness);

            // Fade brightness
            fade_brightness(spi_handle, target_brightness);
        } else {
            fprintf(stderr, "Error: Could not average light levels\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_apa102_brightness(spi_handle, 0); // Turn off LED strip
    spiClose(spi_handle);
    i2cClose(i2c_handle_1);
    i2cClose(i2c_handle_2);
    i2cClose(i2c_handle_3);
    gpioTerminate();

    return 0;
}

