int init_veml7700() {
    int retries = 3;
    int delay_ms = 100;

    while (retries > 0) {
        // Configure VEML7700 for continuous mode and 100ms integration time
        if (i2cWriteByteData(i2c_handle, VEML7700_CONFIG, 0x00) == 0) {
