    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int brightness;

    // Main loop
    while (!terminate) {
        // Read ambient light data
        if (read_veml7700(&lux) == 0) {
            // Apply gamma correction
