#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define constants
#define FLAME_DETECTED 0 // Active low
#define SENSOR_READ_INTERVAL_MS 100
#define SELF_TEST_DURATION_MS 1000
#define BUZZER_ERROR_DURATION_MS 300
#define BUZZER_ERROR_PATTERN_MS 200, 200, 600, 200
#define BUZZER_ERROR_REPEATS 3
#define LED_ERROR_DURATION_MS 500
#define LED_ERROR_REPEATS 2

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void cleanup_gpio();
void signal_handler(int signal);
void log_message(const char *message);
void self_test();
void flame_detected_callback(int gpio, int level, uint32_t tick);
void buzzer_error_callback(int gpio, int level, uint32_t tick);
void led_error_callback(int gpio, int level, uint32_t tick);

// Structure to hold GPIO pin configurations
typedef struct {
    int flame_sensor;
    int buzzer;
    int led;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
                t->tm_year + 1900, t->tm_mon + 1, t->tm_mday,
                t->tm_hour, t->tm_min, t->tm_sec, message);
        fflush(log_file);
    }
}

// Self-test function
void self_test() {
    log_message("Starting self-test...");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(LED_PIN, 0);

    for (int i = 0; i < 2; ++i) {
        for (int j = 0; j < 5; ++j) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
            gpioWrite(LED_PIN, 0);
            gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
        }
    }

    for (int i = 0; i < 5; ++i) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
        gpioWrite(LED_PIN, 0);
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    int flame_detected = 0;
    for (int i = 0; i < 5; ++i) {
        if (gpioRead(FLAME_SENSOR_PIN) == FLAME_DETECTED) {
            flame_detected = 1;
            break;
        }
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    if (flame_detected) {
        log_message("Self-test passed.");
    } else {
        log_message("Self-test failed.");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < BUZZER_ERROR_REPEATS; ++i) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(BUZZER_ERROR_DURATION_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(BUZZER_ERROR_DURATION_MS * 1000);
        }
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        cleanup_gpio();
        exit(1);
    }
}

// Callback function for flame sensor
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Flame detected (LOW)
        log_message("Flame detected!");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
    }
}

// Callback function for buzzer error
void buzzer_error_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Error condition
        log_message("Buzzer error condition detected.");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < BUZZER_ERROR_REPEATS; ++i) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(BUZZER_ERROR_PATTERN_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(BUZZER_ERROR_PATTERN_MS * 1000);
        }
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        cleanup_gpio();
        exit(1);
    }
}

// Callback function for LED error
void led_error_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Error condition
        log_message("LED error condition detected.");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        cleanup_gpio();
        exit(1);
    }
}

int main() {
    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Set up callback functions
    gpioSetAlertFuncEx(FLAME_SENSOR_PIN, flame_detected_callback, NULL);
    gpioSetAlertFuncEx(BUZZER_PIN, buzzer_error_callback, NULL);
    gpioSetAlertFuncEx(LED_PIN, led_error_callback, NULL);

    log_message("Program started.");

    // Main loop
    while (running) {
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    log_message("Program finished.");
    return 0;
}

