            gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
        }
    }

    for (int i = 0; i < 5; ++i) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
        gpioWrite(LED_PIN, 0);
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    int flame_detected = 0;
    for (int i = 0; i < 5; ++i) {
        if (gpioRead(FLAME_SENSOR_PIN) == FLAME_DETECTED) {
            flame_detected = 1;
            break;
        }
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    if (flame_detected) {
        log_message("Self-test passed.");
    } else {
        log_message("Self-test failed.");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < BUZZER_ERROR_REPEATS; ++i) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(BUZZER_ERROR_DURATION_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(BUZZER_ERROR_DURATION_MS * 1000);
        }
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        cleanup_gpio();
        exit(1);
    }
}

// Callback function for flame sensor
void flame_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Flame detected (LOW)
        log_message("Flame detected!");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
    }
}

// Callback function for buzzer error
void buzzer_error_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Error condition
        log_message("Buzzer error condition detected.");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < BUZZER_ERROR_REPEATS; ++i) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(BUZZER_ERROR_PATTERN_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(BUZZER_ERROR_PATTERN_MS * 1000);
        }
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        cleanup_gpio();
        exit(1);
    }
}

// Callback function for LED error
void led_error_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Error condition
        log_message("LED error condition detected.");
        gpioWrite(BUZZER_PIN, 1);
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(BUZZER_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(BUZZER_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        gpioWrite(LED_PIN, 1);
        for (int i = 0; i < LED_ERROR_REPEATS; ++i) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(LED_ERROR_DURATION_MS * 1000);
        }
        cleanup_gpio();
        exit(1);
    }
}

int main() {
    // Open log file
    log_file = fopen("flame_sensor.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    // Set up callback functions
    gpioSetAlertFuncEx(FLAME_SENSOR_PIN, flame_detected_callback, NULL);
    gpioSetAlertFuncEx(BUZZER_PIN, buzzer_error_callback, NULL);
    gpioSetAlertFuncEx(LED_PIN, led_error_callback, NULL);

    log_message("Program started.");

    // Main loop
    while (running) {
        gpioDelay(SENSOR_READ_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup_gpio();
    log_message("Program finished.");
    return 0;
}

