#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define MIN_FREQUENCY 0.5
#define MAX_FREQUENCY 5.0
#define MAX_LUX 1000.0

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_read_sensor(int fd, float *lux);
void circular_buffer_init(CircularBuffer *cb);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
void gpio_set_frequency(int pin, float average_lux);
void signal_handler(int signum);

// Function to read lux value from BH1750 sensor
int i2c_read_sensor(int fd, float *lux) {
    uint8_t buf[2];
    int result;

    // Send measurement mode command
    result = write(fd, &CONTINUOUS_HIGH_RES_MODE, 1);
    if (result != 1) {
        perror("Failed to set measurement mode");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    result = read(fd, buf, 2);
    if (result != 2) {
        perror("Failed to read sensor data");
        return -1;
    }

    // Convert to lux
    *lux = (float)((buf[0] << 8) | buf[1]) / 1.2;
    return 0;
}

// Function to initialize the circular buffer
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

// Function to add a value to the circular buffer
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Function to calculate the average of the values in the circular buffer
float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Function to set the GPIO frequency based on the average lux value
void gpio_set_frequency(int pin, float average_lux) {
    float frequency;

    // Map lux to frequency
    if (average_lux < 1000.0) {
        frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (1000.0 - average_lux) / (MAX_LUX - 1000.0);
    } else {
        frequency = MAX_FREQUENCY;
    }

    // Set GPIO frequency
    int result = set_gpio_frequency(pin, (int)frequency);
    if (result != 0) {
        fprintf(stderr, "Failed to set GPIO frequency: %s\n", strerror(errno));
    }
}

// Function to set the GPIO frequency using sysfs
int set_gpio_frequency(int pin, int frequency) {
    char path[64];
    FILE *fp;

    // Export GPIO
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO export file");
        return -1;
    }
    fprintf(fp, "%d", pin);
    fclose(fp);

    // Wait for the GPIO to be exported
    usleep(100000); // 100ms

    // Set direction to output
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open GPIO direction file");
        return -1;
    }
    fprintf(fp, "out");
    fclose(fp);

    // Set PWM frequency
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/frequency", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Failed to open PWM frequency file");
        return -1;
    }
    fprintf(fp, "%d", frequency);
    fclose(fp);

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

int main() {
    float lux;
    CircularBuffer cb;
    int result;

    // Initialize circular buffer
    circular_buffer_init(&cb);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read lux value
        result = i2c_read_sensor(i2c_fd, &lux);
        if (result != 0) {
            fprintf(stderr, "Error reading sensor, skipping this iteration.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Add to circular buffer
        circular_buffer_add(&cb, lux);

        // Calculate average lux
        float average_lux = circular_buffer_average(&cb);

        // Set GPIO frequency
        gpio_set_frequency(GPIO_PIN, average_lux);

        // Print lux value
        printf("Lux: %.2f, Average Lux: %.2f\n", lux, average_lux);

        // Wait for 1 second
        sleep(1);
    }

    // Clean up
    close(i2c_fd);
    gpio_set_frequency(GPIO_PIN, 0); // Set frequency to 0 to turn off LED

    return 0;
}

