#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment definitions (common cathode)
#define SEG_A 0
#define SEG_B 1
#define SEG_C 2
#define SEG_D 3
#define SEG_E 4
#define SEG_F 5
#define SEG_G 6
#define SEG_DP 7 // Not used in common cathode

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Cleaning up and exiting...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    return 0;
}

// Function to shift out data to the 74HC595
void shift_out(int data) {
    for (int i = 0; i < 8; i++) {
        gpioWrite(CLOCK_PIN, 1);
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 1);
        gpioWrite(CLOCK_PIN, 0);
    }
}

// Function to latch the data to the output
void latch() {
    gpioWrite(LATCH_PIN, 1);
    gpioWrite(LATCH_PIN, 0);
}

// Function to display the digit '5' on the seven-segment display
void display_five() {
    int data = 0b01010105; // 5 in 8-bit format
    shift_out(data);
    latch();
}

// Function to blink the digit '5'
void blink_five() {
    int delay_ms = 500;
    while (program_running) {
        display_five();
        gpioDelay(delay_ms * 1000); // Delay in microseconds
        display_five();
        gpioDelay(delay_ms * 1000); // Delay in microseconds
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        blink_five();
    }

    // Clean up GPIO
    gpioTerminate();

    return 0;
}

