#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define BUTTON_PIN 18

static volatile int running = 1;

void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    int led_state = 0;
    int button_state = 0;
    int led_value;
    int button_value;
    int led_request_result;
    int button_event_result;

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip 0
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Failed to open GPIO chip 0\n");
        gpioTerminate();
        return 1;
    }

    // Request LED line as output
    led_request_result = gpioSetMode(LED_PIN, PI_OUTPUT);
    if (led_request_result != 0) {
        fprintf(stderr, "Failed to set LED pin as output: %d\n", led_request_result);
        gpioTerminate();
        return 1;
    }

    // Request button line as input with pull-up resistor and edge detection
    button_request_result = gpioSetMode(BUTTON_PIN, PI_INPUT);
    if (button_request_result != 0) {
        fprintf(stderr, "Failed to set button pin as input: %d\n", button_request_result);
        gpioTerminate();
        return 1;
    }

    button_request_result = gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);
    if (button_request_result != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on button pin: %d\n", button_request_result);
        gpioTerminate();
        return 1;
    }

    button_event_result = gpioSetAlertFuncEx(BUTTON_PIN, button_callback, NULL);
    if (button_event_result != 0) {
        fprintf(stderr, "Failed to set alert function on button pin: %d\n", button_event_result);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Blink LED
        led_value = led_state;
        led_state = !led_state;
        gpioWrite(LED_PIN, led_value);
        gpioDelay(1000000); // 1 second

        // Check button state
        button_state = gpioRead(BUTTON_PIN);
        if (button_state == 0) {
            printf("Button pressed!\n");
            led_state = 0; // Turn off LED on button press
            gpioWrite(LED_PIN, led_state);
            gpioDelay(1000000); // 1 second delay after button press
        }
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Callback function for button press event
void button_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (diff < 500000) { // Debounce: ignore events within 0.5 seconds
        return;
    }

    last_tick = tick;

    printf("Button pressed!\n");
