#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 15

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C (SIGINT)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCtrl+C detected. Exiting gracefully...\n");
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return -1;
    }

    // Set button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return -1;
    }

    // Enable pull-down resistor on button pin
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on button pin\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the button state
int read_button() {
    return gpioRead(BUTTON_PIN);
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(500);        // Wait for 500ms
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(500);        // Wait for 500ms
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_button() == 1) {
            blink_led();
        } else {
            blink_led(); // Keep blinking even if button is released
        }
        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

