#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
        // Release GPIO pins
        gpioTerminate();
        exit(0);
    }
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and 100.\n");
        return;
    }

    // Calculate the number of microseconds for the high and low periods
    int high_time = (int)(duty_cycle * 1000000.0 / 100.0); // 100ms period
    int low_time = 1000000 - high_time;

    // Set the GPIO pin to HIGH
    gpioWrite(gpio_pin, 1);

    // Wait for the high time
    gpioDelay(high_time);

    // Set the GPIO pin to LOW
    gpioWrite(gpio_pin, 0);

    // Wait for the low time
    gpioDelay(low_time);
}

// Function to generate a random RGB color value
void generate_random_color(int *red, int *green, int *blue) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate random values for each color component
    *red   = rand() % 101;
    *green = rand() % 101;
    *blue  = rand() % 101;
}

// Function to set the RGB color of the LED
void set_led_color(int red, int green, int blue) {
    set_pwm_duty_cycle(RED_PIN, red);
    set_pwm_duty_cycle(GREEN_PIN, green);
    set_pwm_duty_cycle(BLUE_PIN, blue);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency to 100 Hz (10 ms period)
    gpioSetPWMfrequency(RED_PIN, 100);
    gpioSetPWMfrequency(GREEN_PIN, 100);
    gpioSetPWMfrequency(BLUE_PIN, 100);

    // Set PWM range to 100 (0-100)
    gpioSetPWMrange(RED_PIN, 100);
    gpioSetPWMrange(GREEN_PIN, 100);
    gpioSetPWMrange(BLUE_PIN, 100);

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int red, green, blue;
        generate_random_color(&red, &green, &blue);
        set_led_color(red, green, blue);
        gpioDelay(100); // Wait 100ms
    }

    // Release GPIO pins
    gpioTerminate();

    return 0;
}

