#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 500
#define LED_ON_THRESHOLD 1000 // Example threshold

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void log_data(const sensor_data_t *data);
void control_led(uint16_t als_value);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, terminating...\n");
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[8]; // Buffer to hold LSB and MSB for each channel

    // Read ALS data (LSB and MSB)
    if (i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error reading ALS data: %s\n", strerror(errno));
        return -1;
    }
    data->als = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];

    // Read Red data (LSB and MSB)
    if (i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error reading Red data: %s\n", strerror(errno));
        return -1;
    }
    data->red = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];

    // Read Green data (LSB and MSB)
    if (i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error reading Green data: %s\n", strerror(errno));
        return -1;
    }
    data->green = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];

    // Read Blue data (LSB and MSB)
    if (i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, buffer, 2) != 2) {
        fprintf(stderr, "Error reading Blue data: %s\n", strerror(errno));
        return -1;
    }
    data->blue = (uint16_t)buffer[1] << 8 | (uint16_t)buffer[0];

    return 0;
}

// Function to log data to CSV file
void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data->als, data->red, data->green, data->blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED brightness based on ALS value
void control_led(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)als_value / 65535.0) * PWM_RANGE);
    if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }
    gpioPWM(PWM_GPIO, duty_cycle);
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(PWM_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Configure PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(&sensor_data);
            control_led(sensor_data.als);

            // Example threshold-based LED control
            if (sensor_data.als > LED_ON_THRESHOLD) {
                gpioPWM(PWM_GPIO, PWM_RANGE); // Turn on LED
            } else {
                gpioPWM(PWM_GPIO, 0); // Turn off LED
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 100ms...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 500ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

