// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define FXOS8700CQ_WHO_AM_I 0x0D
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_CTRL_REG2 0x2B
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_OUT_X_LSB 0x02
#define FXOS8700CQ_OUT_Y_MSB 0x03
#define FXOS8700CQ_OUT_Y_LSB 0x04
#define FXOS8700CQ_OUT_Z_MSB 0x05
#define FXOS8700CQ_OUT_Z_LSB 0x06

// Impact threshold (in g)
#define IMPACT_THRESHOLD 1.5

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int fxos8700cq_init(int i2c_handle);
int fxos8700cq_read_acceleration(int i2c_handle, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void log_impact(float x, float y, float z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the FXOS8700CQ sensor
int fxos8700cq_init(int i2c_handle) {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xEA) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xEA, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Set standby mode
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Set ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    // Activate the sensor (set active mode and 200Hz ODR)
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x15) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the FXOS8700CQ sensor
int fxos8700cq_read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from OUT_X_MSB
    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    // Combine MSB and LSB to get 16-bit values
    x_raw = (int16_t)((raw_data[0] << 8) | raw_data[1]);
    y_raw = (int16_t)((raw_data[2] << 8) | raw_data[3]);
    z_raw = (int16_t)((raw_data[4] << 8) | raw_data[5]);

    // Convert to g units (assuming +/- 2g range)
    *x = (float)x_raw / 4096.0f;
    *y = (float)y_raw / 4096.0f;
    *z = (float)z_raw / 4096.0f;

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

// Log impact data to a file
