// Gyroscope I2C address
#define GYRO_ADDR 0x69

// Gyroscope register addresses
#define CTRL_REG1 0x20
#define CTRL_REG2 0x21
#define CTRL_REG3 0x22
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Calibration sample size
#define CALIBRATION_SAMPLES 100

// I2C bus
#define I2C_BUS 1

// Log file name
#define LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function prototypes
int init_gyro();
int read_gyro_data(gyro_data_t *data);
void calibrate_gyro(gyro_data_t *data);
void log_data(gyro_data_t data);
void check_thresholds(gyro_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize the gyroscope
int init_gyro() {
    // Set CTRL_REG1 to 0x0F (normal mode, 100Hz ODR)
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set CTRL_REG2 to 0x00 (all axes enabled)
    if (i2cWriteByteData(i2c_fd, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2: %s\n", strerror(errno));
        return -1;
    }

    // Set CTRL_REG3 to 0x00 (full scale range +/- 250 dps)
    if (i2cWriteByteData(i2c_fd, CTRL_REG3, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG3: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_fd, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading gyro data: %s\n", strerror(errno));
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate the gyroscope
void calibrate_gyro(gyro_data_t *data) {
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (read_gyro_data(&data[i]) < 0) {
            fprintf(stderr, "Error reading gyro data during calibration.\n");
            return;
        }
        x_sum += data[i].x;
        y_sum += data[i].y;
        z_sum += data[i].z;
        gpioDelay(1); // Small delay between samples
    }

    // Calculate offsets
    data[0].x = 0; // Replace with actual zero offset
    data[0].y = 0; // Replace with actual zero offset
    data[0].z = 0; // Replace with actual zero offset

    printf("Calibration complete. Offsets: X=%d, Y=%d, Z=%d\n", data[0].x, data[0].y, data[0].z);
}

// Log data to file
void log_data(gyro_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for threshold exceedances
void check_thresholds(gyro_data_t data) {
    if (fabs(data.x) > 50 || fabs(data.y) > 50 || fabs(data.z) > 50) {
        fprintf(stderr, "ALERT: Threshold exceeded! X=%d, Y=%d, Z=%d\n", data.x, data.y, data.z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    char who_am_i;
    if (i2cReadByteData(i2c_fd, 0x00) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }
    who_am_i = i2cReadByteData(i2c_fd, 0x00);
    if (who_am_i != 0x44) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data[CALIBRATION_SAMPLES];
    calibrate_gyro(gyro_data);

    // Main loop
    while (!terminate) {
        gyro_data_t data;
        if (read_gyro_data(&data) == 0) {
            log_data(data);
            check_thresholds(data);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }
        gpioDelay(50); // 20 Hz sampling rate
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_fd);
    gpioTerminate();

    return 0;
}

