#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Scaling factors
#define ACCEL_SCALE 0.000061  // +/- 2g, 16-bit
#define MAG_SCALE 0.1         // uT/LSB

// Global variables
int i2c_handle_accel = -1;
int i2c_handle_mag = -1;
FILE *log_file = NULL;

// Function prototypes
int init_i2c(int bus, int addr);
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint8_t reg, uint8_t value);
int read_sensor_data(int handle, float *x, float *y, float *z);
float calculate_heading(float x, float y);
void log_data(float x, float y, float z, float heading, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float x, y, z;
} sensor_data_t;

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Function to read a register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, float *x, float *y, float *z) {
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = read_register(handle, OUT_X_L_A);
    x_h = read_register(handle, OUT_X_H_A);
    y_l = read_register(handle, OUT_Y_L_A);
    y_h = read_register(handle, OUT_Y_H_A);
    z_l = read_register(handle, OUT_Z_L_A);
    z_h = read_register(handle, OUT_Z_H_A);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        return -1;
    }

    *x = (float)((short)(x_h << 8 | x_l)) * ACCEL_SCALE;
    *y = (float)((short)(y_h << 8 | y_l)) * ACCEL_SCALE;
    *z = (float)((short)(z_h << 8 | z_l)) * ACCEL_SCALE;

    return 0;
}

// Function to calculate heading
float calculate_heading(float x, float y) {
    float heading = atan2(y, x);
    if (heading < 0) {
        heading += 2 * M_PI;
    }
    return heading;
}

// Function to log data
void log_data(float x, float y, float z, float heading, float mag_x, float mag_y, float mag_z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, x, y, z, heading, mag_x, mag_y, mag_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle_accel >= 0) {
        i2cClose(i2c_handle_accel);
    }
    if (i2c_handle_mag >= 0) {
        i2cClose(i2c_handle_mag);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle_accel = init_i2c(1, LSM303_ACCEL_ADDR);
    if (i2c_handle_accel < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = init_i2c(1, LSM303_MAG_ADDR);
    if (i2c_handle_mag < 0) {
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    // Initialize accelerometer
    if (write_register(i2c_handle_accel, CTRL_REG1_A, 0x27) < 0) { // Enable all axes, 50Hz
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle_accel, CTRL_REG4_A, 0x00) < 0) { // +/- 2g
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (write_register(i2c_handle_mag, CRA_REG_M, 0x14) < 0) { // 75 Hz, normal mode
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }
    if (write_register(i2c_handle_mag, MR_REG_M, 0x00) < 0) { // Continuous conversion
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Heading,Mag_X,Mag_Y,Mag_Z\n");
    }
    fflush(log_file);

    float accel_x, accel_y, accel_z, mag_x, mag_y, mag_z;
    int retries = 3; // Number of retries for I2C operations

    while (1) {
        // Read sensor data with retries
        int read_success = 0;
        for (int i = 0; i < retries; ++i) {
            if (read_sensor_data(i2c_handle_accel, &accel_x, &accel_y, &accel_z) == 0) {
                read_success = 1;
                break;
            } else {
                fprintf(stderr, "Sensor read failed, retrying... (%d/%d)\n", i + 1, retries);
                gpioDelay(1000); // Wait 1ms before retrying
            }
        }

        if (!read_success) {
            fprintf(stderr, "Failed to read accelerometer data after %d retries.\n", retries);
            continue; // Skip to the next iteration
        }

        if (read_sensor_data(i2c_handle_mag, &mag_x, &mag_y, &mag_z) == 0) {
            // Calculate heading
            float heading = calculate_heading(accel_x, accel_y);

            // Log data
            log_data(accel_x, accel_y, accel_z, heading, mag_x, mag_y, mag_z);
        } else {
            fprintf(stderr, "Failed to read magnetometer data after %d retries.\n", retries);
        }

        gpioDelay(100000); // 100ms delay
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

