int spi_write_register(int spi_handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to write the register
    tx_buf[0] = reg_addr; // Write command (MSB = 0)
    tx_buf[1] = (data >> 8) & 0xFF; // MSB
    tx_buf[2] = data & 0xFF; // LSB

    // Transfer the data
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI write error: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read IMU data from the ADIS16488A
imu_data_t read_imu_data(int spi_handle) {
    imu_data_t data;
    uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    int stall_time_start = gpioTick();

    // Read gyroscope data
    if (spi_read_register(spi_handle, REG_GYRO_XOUT, &gyro_x) != 0) {
        fprintf(stderr, "Error reading gyro X\n");
        data.gyro_x = 0.0; // Set to 0 to avoid using garbage data
    }
    if (spi_read_register(spi_handle, REG_GYRO_YOUT, &gyro_y) != 0) {
        fprintf(stderr, "Error reading gyro Y\n");
        data.gyro_y = 0.0;
    }
    if (spi_read_register(spi_handle, REG_GYRO_ZOUT, &gyro_z) != 0) {
        fprintf(stderr, "Error reading gyro Z\n");
        data.gyro_z = 0.0;
    }

    // Read accelerometer data
    if (spi_read_register(spi_handle, REG_ACCEL_XOUT, &accel_x) != 0) {
        fprintf(stderr, "Error reading accel X\n");
        data.accel_x = 0.0;
    }
    if (spi_read_register(spi_handle, REG_ACCEL_YOUT, &accel_y) != 0) {
        fprintf(stderr, "Error reading accel Y\n");
        data.accel_y = 0.0;
    }
    if (spi_read_register(spi_handle, REG_ACCEL_ZOUT, &accel_z) != 0) {
        fprintf(stderr, "Error reading accel Z\n");
        data.accel_z = 0.0;
    }

    // Calculate millisecond timestamp
    data.timestamp_ms = (long)(gpioTick() / 1000);

    // Check for stall condition
    if (gpioTick() - stall_time_start < STALL_TIME_US) {
        fprintf(stderr, "Stall condition detected. Skipping sample.\n");
        data.gyro_x = 0.0;
        data.gyro_y = 0.0;
        data.gyro_z = 0.0;
        data.accel_x = 0.0;
        data.accel_y = 0.0;
        data.accel_z = 0.0;
        return data;
    }

    // Convert raw data to physical units
    data.gyro_x = (float)gyro_x * GYRO_SENSITIVITY;
    data.gyro_y = (float)gyro_y * GYRO_SENSITIVITY;
    data.gyro_z = (float)gyro_z * GYRO_SENSITIVITY;
    data.accel_x = (float)accel_x * ACCEL_SENSITIVITY;
    data.accel_y = (float)accel_y * ACCEL_SENSITIVITY;
    data.accel_z = (float)accel_z * ACCEL_SENSITIVITY;

    return data;
}

// Function to log IMU data to a CSV file
void log_imu_data(imu_data_t data) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    }

    fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            data.timestamp_ms,
            data.gyro_x,
            data.gyro_y,
            data.gyro_z,
            data.accel_x,
            data.accel_y,
            data.accel_z);

    fclose(fp);
}

// Function to cleanup resources before exiting
void cleanup(int spi_handle) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Signal received (%d).  Shutting down...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        imu_data_t data = read_imu_data(spi_handle);
        log_imu_data(data);
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup(spi_handle);
    return 0;
}

