#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Sensitivity scales (adjust as needed)
#define ACCEL_SCALE 16384.0f  // +/- 2g range
#define GYRO_SCALE  131.0f    // +/- 250 dps range

// Global variables
int i2c_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to initialize the MPU-6886
int init_mpu6886(int i2c_fd) {
    // Wake up the MPU-6886 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6886 (errno: %d)\n", errno);
        return -1;
    }
    return 0;
}

// Function to read raw sensor data from the MPU-6886
int read_raw_data(int i2c_fd, sensor_data_t *data) {
    char buf[14];
    int result;

    // Read accelerometer data
    result = i2cReadI2CBlockData(i2c_fd, ACCEL_XOUT_H, buf, 14);
    if (result < 0) {
        fprintf(stderr, "Error: Could not read sensor data (errno: %d)\n", errno);
        return -1;
    }

    // Combine high and low bytes for accelerometer values
    data->accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    data->accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    data->accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Combine high and low bytes for gyroscope values
    data->gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    data->gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    data->gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Function to convert raw data to physical units
