#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// GPIO pin for LED
#define LED_PIN 17

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.5

// Full-scale range (in g)
#define FULL_SCALE_RANGE 2.0

// Scaling factor (LSB/g)
#define SCALE_FACTOR 256.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int adxl345_read_acceleration(float *x, float *y, float *z);
int adxl345_verify_device_id();
void log_impact(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    // Set to measure mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(float *x, float *y, float *z) {
    char data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, data, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((data[1] << 8) | data[0]);
    y_raw = (int16_t)((data[3] << 8) | data[2]);
    z_raw = (int16_t)((data[5] << 8) | data[4]);

    // Convert to g units
    *x = (float)x_raw / SCALE_FACTOR;
    *y = (float)y_raw / SCALE_FACTOR;
    *z = (float)z_raw / SCALE_FACTOR;

    return 0;
}

// Function to verify the device ID
int adxl345_verify_device_id() {
    char device_id;
    int result;

    result = i2cReadByteData(i2c_handle, 0x00); // Read device ID register
    if (result < 0) {
        fprintf(stderr, "Error reading device ID: %s\n", strerror(errno));
        return -1;
    }
    device_id = (char)result;

    if (device_id != 0xAD) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X). Expected 0xAD.\n", device_id);
        return -1;
    }

    return 0;
}

// Function to log impact events
void log_impact(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Impact detected: X=%.3f g, Y=%.3f g, Z=%.3f g\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    float x, y, z;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify device ID
    if (adxl345_verify_device_id() < 0) {
        fprintf(stderr, "ADXL345 verification failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (adxl345_read_acceleration(&x, &y, &z) == 0) {
            // Calculate total acceleration magnitude
            float magnitude = sqrt(x * x + y * y + z * z);

            // Check for impact
            if (magnitude > IMPACT_THRESHOLD) {
                // Turn on LED
                gpioWrite(LED_PIN, 1);
                gpioDelay(500); // 500ms
                gpioWrite(LED_PIN, 0);

                // Log impact
                log_impact(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data.\n");
        }

        gpioDelay(10); // 10ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

