#include <signal.h>
#include <string.h>
#include <errno.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define WHO_AM_I 0x00
#define PWR_MGMT_1 0x06
#define ACCEL_XOUT_H 0x2D
#define GYRO_XOUT_H 0x33

// Scaling factors (adjust based on your configuration)
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE 131.0f    // +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the ICM-20602
int init_icm20602() {
    // Wake up the device (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up ICM-20602\n");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ICM-20602
int16_t read_16bit_value(int reg) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error: Could not read 16-bit value from register 0x%02X\n", reg);
        return -1;
    }
    return (int16_t)((buf[1] << 8) | buf[0]);
}

// Function to read accelerometer data
sensor_data_t read_accelerometer() {
    sensor_data_t data;
    int16_t raw_accel_x = read_16bit_value(ACCEL_XOUT_H);
    int16_t raw_accel_y = read_16bit_value(ACCEL_XOUT_H + 2);
    int16_t raw_accel_z = read_16bit_value(ACCEL_XOUT_H + 4);

    if (raw_accel_x == -1 || raw_accel_y == -1 || raw_accel_z == -1) {
        data.accel_x = data.accel_y = data.accel_z = 0.0f; // Set to 0 in case of error
    } else {
        data.accel_x = (float)raw_accel_x / ACCEL_SCALE;
        data.accel_y = (float)raw_accel_y / ACCEL_SCALE;
        data.accel_z = (float)raw_accel_z / ACCEL_SCALE;
    }
    return data;
}

// Function to read gyroscope data
sensor_data_t read_gyroscope() {
    sensor_data_t data;
    int16_t raw_gyro_x = read_16bit_value(GYRO_XOUT_H);
    int16_t raw_gyro_y = read_16bit_value(GYRO_XOUT_H + 2);
    int16_t raw_gyro_z = read_16bit_value(GYRO_XOUT_H + 4);

    if (raw_gyro_x == -1 || raw_gyro_y == -1 || raw_gyro_z == -1) {
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f; // Set to 0 in case of error
    } else {
        data.gyro_x = (float)raw_gyro_x / GYRO_SCALE;
        data.gyro_y = (float)raw_gyro_y / GYRO_SCALE;
        data.gyro_z = (float)raw_gyro_z / GYRO_SCALE;
    }
    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t accel, sensor_data_t gyro) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, accel.accel_x, accel.accel_y, accel.accel_z,
