#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define ACCEL_XOUT_MSB 0x01
#define ACCEL_YOUT_MSB 0x03
#define ACCEL_ZOUT_MSB 0x05
#define WHO_AM_I 0x0D
#define WHO_AM_I_VALUE 0x42
#define LED_GPIO 17
#define THRESHOLD_G 2.0
#define G_PER_COUNT 1024.0
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int verify_sensor_id();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void control_led(int on);
void log_data(accelerometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the sensor's WHO_AM_I register
int verify_sensor_id() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    return (who_am_i == WHO_AM_I_VALUE);
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    float x = (float)data.x / G_PER_COUNT;
    float y = (float)data.y / G_PER_COUNT;
    float z = (float)data.z / G_PER_COUNT;
    return sqrt(x * x + y * y + z * z);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Function to log data to a file
void log_data(accelerometer_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor ID
    if (!verify_sensor_id()) {
        fprintf(stderr, "Sensor ID verification failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        if (magnitude > THRESHOLD_G) {
            control_led(1); // Turn on LED
            gpioDelay(500);  // Wait 500ms
            control_led(0); // Turn off LED
        }

        log_data(data);
        gpioDelay(POLL_INTERVAL_MS); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

