#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define the I2C address of the TMAG5273 sensor
#define TMAG5273_I2C_ADDR 0x0E

// Define the register address for the magnetic field data (X, Y, Z)
#define TMAG5273_REG_X_MSB 0x00

// Define the number of bytes to read from the sensor
#define TMAG5273_READ_SIZE 6

// Define the sampling interval in seconds
#define SAMPLING_INTERVAL 1

// Define the log file name
#define LOG_FILE "magnetic_field_log.csv"

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer

// Function prototypes
int init_i2c();
int read_magnetic_field(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_fd = i2cOpen(1, TMAG5273_I2C_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read magnetic field data from the sensor
int read_magnetic_field(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[TMAG5273_READ_SIZE];
    int result = i2cReadI2CBlockData(i2c_fd, TMAG5273_REG_X_MSB, buffer, TMAG5273_READ_SIZE);

    if (result != TMAG5273_READ_SIZE) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    // Convert the raw data to signed 16-bit integers
    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to log the data to a CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
            return -1;
        }
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Main loop
    while (1) {
        int16_t x, y, z;

        // Read magnetic field data
        if (read_magnetic_field(&x, &y, &z) == 0) {
            // Log the data
            if (log_data(x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read magnetic field data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000000); // pigpio uses microseconds
    }

    return 0;
}

