        return -1;
    }
    return 0;
}

// Function to initialize the ADXL345
int adxl345_init() {
    // Set data format to +/- 2g and full resolution
    if (adxl345_write_register(i2c_fd, DATA_FORMAT, 0x0B) != 0) {
