        return -1;
    }

    // Enable measurement mode
    if (adxl345_write_register(i2c_fd, POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error enabling measurement mode\n");
        return -1;
    }

    // Configure INT1 interrupt (falling edge)
    if (adxl345_write_register(i2c_fd, INT1_CFG, 0x00) != 0) {
        fprintf(stderr, "Error configuring INT1 interrupt\n");
        return -1;
    }

    return 0;
}

