int read_acceleration(float *x, float *y, float *z) {
    uint8_t raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    if (adxl345_read_register(i2c_fd, DATAX0, &raw_data[0]) != 0) {
        fprintf(stderr, "Error reading X0\n");
        return -1;
    }
    if (adxl345_read_register(i2c_fd, DATAX1, &raw_data[1]) != 0) {
        fprintf(stderr, "Error reading X1\n");
        return -1;
    }
    if (adxl345_read_register(i2c_fd, DATAY0, &raw_data[2]) != 0) {
        fprintf(stderr, "Error reading Y0\n");
        return -1;
    }
    if (adxl345_read_register(i2c_fd, DATAY1, &raw_data[3]) != 0) {
        fprintf(stderr, "Error reading Y1\n");
        return -1;
    }
    if (adxl345_read_register(i2c_fd, DATAZ0, &raw_data[4]) != 0) {
        fprintf(stderr, "Error reading Z0\n");
        return -1;
    }
    if (adxl345_read_register(i2c_fd, DATAZ1, &raw_data[5]) != 0) {
        fprintf(stderr, "Error reading Z1\n");
        return -1;
    }

    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g's (assuming +/- 2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

