#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// Configuration values
#define ACCEL_RANGE 2.0f // ±2g
#define GYRO_RANGE 250.0f // ±250 dps
#define ODR 104 // 104 Hz
#define FALL_THRESHOLD 0.2f // 0.2g
#define IMPACT_THRESHOLD 2.5f // 2.5g
#define IMPACT_WINDOW 1.0f // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold IMU data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} imu_data_t;

// Function prototypes
int init_lsm6dsr();
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void fall_detection(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LSM6DSR IMU
int init_lsm6dsr() {
    // Check WHO_AM_I register (optional, but good practice)
    char who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, 0x0F, &who_am_i, 1) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x6A) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x6A, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: ±2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80 = 104 Hz, ±2g
        fprintf(stderr, "Error writing to CTRL1_XL: %s\n", strerror(errno));
        return -1;
    }

    // Configure gyroscope: ±250 dps range
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80 = ±250 dps
        fprintf(stderr, "Error writing to CTRL2_G: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read IMU data from the LSM6DSR
imu_data_t read_imu_data() {
    imu_data_t data;
    char buffer[12];

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12) < 0) {
        fprintf(stderr, "Error reading IMU data: %s\n", strerror(errno));
        data.accel_x = data.accel_y = data.accel_z = 0.0f;
        data.gyro_x = data.gyro_y = data.gyro_z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to g and dps
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to g and dps
    data.accel_x = (float)raw_accel_x / 16384.0f * ACCEL_RANGE; // 16384 LSB/g for ±2g range
    data.accel_y = (float)raw_accel_y / 16384.0f * ACCEL_RANGE;
    data.accel_z = (float)raw_accel_z / 16384.0f * ACCEL_RANGE;
    data.gyro_x = (float)raw_gyro_x / 131.0f; // 131 LSB/dps for ±250 dps range
    data.gyro_y = (float)raw_gyro_y / 131.0f;
    data.gyro_z = (float)raw_gyro_z / 131.0f;

    return data;
}

// Log IMU data to a CSV file
void log_data(imu_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Fall detection state machine
void fall_detection(imu_data_t data) {
    static int impact_detected = 0;
    static time_t impact_start_time = 0;
    static int impact_window_start = 0; // Start of the impact window

    // Check for impact
    if (fabs(data.accel_x) < IMPACT_THRESHOLD && fabs(data.accel_y) < IMPACT_THRESHOLD && fabs(data.accel_z) < IMPACT_THRESHOLD) {
        if (!impact_detected) {
            impact_detected = 1;
            impact_start_time = time(NULL);
            impact_window_start = time(NULL); // Reset the window start time
        }
    } else {
        impact_detected = 0;
    }

    // Check if impact window has started
    if (impact_detected && (time(NULL) - impact_start_time >= IMPACT_WINDOW)) {
        if (!impact_window_start) {
            fprintf(log_file, "IMPACT DETECTED\n");
            fflush(log_file);
            impact_window_start = time(NULL); // Reset the window start time
        } else {
            fprintf(log_file, "IMPACT WINDOW STARTED\n");
            fflush(log_file);
        }
        impact_detected = 0; // Reset impact detection
    }

    // Check for freefall
    if (fabs(data.accel_x) < FALL_THRESHOLD && fabs(data.accel_y) < FALL_THRESHOLD && fabs(data.accel_z) < FALL_THRESHOLD) {
        fprintf(log_file, "FREEFALL DETECTED\n");
        fflush(log_file);
        // Transition to IMPACT state
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0); // I2C bus 1, address 0x6A, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        imu_data_t data = read_imu_data();
        log_data(data);
        fall_detection(data);
        gpioDelay(10000); // 10ms delay (104 Hz ODR)
    }

    // Clean up
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

