#define REG_YGYRO_OUT 0x06
#define REG_ZGYRO_OUT 0x08
#define REG_TEMP_OUT 0x0A
#define REG_SMPL_PRD 0x0E
#define REG_GLOB_CMD 0x36

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_CPOL 1
#define SPI_CPHA 1

// Gyroscope Sensitivity
#define GYRO_SCALE_FACTOR 0.0305 // deg/sec/LSB

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int read_who_am_i(int handle);
int read_gyro_data(int handle, float *x, float *y, float *z);
int log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a 16-bit value from the ADIS16266 via SPI
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to read the register
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    // Perform the SPI transaction
    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI read failed (reg 0x%02X): %d\n", reg_addr, result);
        return -1;
    }

    // Extract the 16-bit data from the received bytes
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// Function to write a 16-bit value to the ADIS16266 via SPI
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to write the register
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF;      // LSB of data

    // Perform the SPI transaction
    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI write failed (reg 0x%02X, data 0x%04X): %d\n", reg_addr, data, result);
        return -1;
    }

    return 0;
}

// Function to read the WHO_AM_I register
int read_who_am_i(int handle) {
    uint16_t who_am_i;
    if (spi_read_register(handle, REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }

    // Check the WHO_AM_I value
    if (who_am_i != 0xAD10) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%04X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I: 0x%04X\n", who_am_i);
    return 0;
}

// Function to read the angular rate data from the gyroscope
int read_gyro_data(int handle, float *x, float *y, float *z) {
    uint16_t x_raw, y_raw, z_raw;

    if (spi_read_register(handle, REG_XGYRO_OUT, &x_raw) != 0) return -1;
    if (spi_read_register(handle, REG_YGYRO_OUT, &y_raw) != 0) return -1;
    if (spi_read_register(handle, REG_ZGYRO_OUT, &z_raw) != 0) return -1;

    // Convert raw values to degrees per second
    *x = (float)x_raw * GYRO_SCALE_FACTOR;
    *y = (float)y_raw * GYRO_SCALE_FACTOR;
    *z = (float)z_raw * GYRO_SCALE_FACTOR;

    return 0;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }

    // Read WHO_AM_I register
    if (read_who_am_i(spi_handle) != 0) {
        fprintf(stderr, "Error: WHO_AM_I verification failed.\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set sample period
    if (spi_write_register(spi_handle, REG_SMPL_PRD, 0x000A) != 0) {
        fprintf(stderr, "Error: Failed to set sample period.\n");
        fclose(log_file);
