                result = i2cWriteI2CBlockData(i2c_handle, CTRL_REG1, 0x0F, 1);
                if (result == 1) {
                    // Initialize CTRL_REG4 (8.75 mdps/LSB)
                    result = i2cWriteI2CBlockData(i2c_handle, CTRL_REG4, 0x00, 1);
                    if (result == 1) {
                        return 0; // Success
                    } else {
