#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

static volatile int running = 1;

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log a flame event to the file
int log_flame_event(const char* timestamp, const char* status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s – Flame detected: %s\n", timestamp, status);
    fflush(fp); // Ensure data is written to disk immediately
    fclose(fp);
    return 0;
}

// Function to print a flame event to the console
void print_flame_event(const char* timestamp, const char* status) {
    printf("%s – Flame detected: %s\n", timestamp, status);
}

// Function to handle the flame sensor reading
int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin mode to input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor(GPIO_PIN);
        if (sensor_value < 0) {
            // Error reading sensor, log to file and exit
            fprintf(stderr, "Error reading sensor, exiting.\n");
            gpioTerminate();
            return 1;
        }

        char* timestamp = get_timestamp();
        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (log_flame_event(timestamp, "YES") != 0) {
                fprintf(stderr, "Error logging flame event.\n");
            }
            print_flame_event(timestamp, "YES");
        } else {
            if (log_flame_event(timestamp, "NO") != 0) {
                fprintf(stderr, "Error logging no flame event.\n");
            }
        }

        gpioDelay(500); // Wait 500ms
    }

    // Clean up and exit
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

