#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the Omron D7S-0001 sensor
#define D7S_I2C_ADDR 0x4C

// Define the register addresses for X, Y, and Z axis data
#define D7S_REG_X_LSB 0x02
#define D7S_REG_X_MSB 0x03
#define D7S_REG_Y_LSB 0x04
#define D7S_REG_Y_MSB 0x05
#define D7S_REG_Z_LSB 0x06
#define D7S_REG_Z_MSB 0x07

// Define the sampling rate in milliseconds
#define SAMPLE_RATE_MS 100

// Define the log file name
#define LOG_FILE "vibration_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
void process_sensor_data(const sensor_data_t *data);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Cleaning up and exiting.\n");
        program_running = 0;
    }
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, D7S_I2C_ADDR, 0); // Bus 1, address 0x4C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data from the Omron D7S-0001
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result;

    // Read X axis data
    result = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    // Combine LSB and MSB for each axis
    data->x = (int16_t)((buf[1] << 8) | buf[0]);
    data->y = (int16_t)((buf[3] << 8) | buf[2]);
    data->z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to process sensor data (currently just logs it)
void process_sensor_data(const sensor_data_t *data) {
    // In a real application, you would perform some processing here
    // such as filtering, calibration, or anomaly detection.
    log_data(data);
}

// Function to log sensor data to a CSV file
void log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    // Get the current time
    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format the timestamp as ISO 8601 UTC
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Append the timestamp, X, Y, and Z values to the log file
    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data->x, data->y, data->z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    sensor_data_t sensor_data;

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row to the log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Process the sensor data
            process_sensor_data(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping.\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_RATE_MS * 1000); // pigpioDelay takes microseconds
    }

    // Clean up resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

