        fflush(log_file); // Ensure data is written to disk immediately

        // Check for halt condition
        if (sensor1_state == 1 && sensor2_state == 1) {
            printf("Halt condition detected!\n");
            fprintf(log_file, "Halt condition detected!\n");
            fflush(log_file);
        }

        // Wait 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

