#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MMA8452Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define CTRL_REG4 0x2B
#define OUT_X_MSB_REG 0x01
#define OUT_X_LSB_REG 0x02
#define OUT_Y_MSB_REG 0x03
#define OUT_Y_LSB_REG 0x04
#define OUT_Z_MSB_REG 0x05
#define OUT_Z_LSB_REG 0x06
#define TILT_THRESHOLD 45.0f
#define SAMPLE_RATE_HZ 100
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mma8452q(int i2c_fd);
int read_mma8452q_data(int i2c_fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
void log_tilt_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize MMA8452Q
int init_mma8452q(int i2c_fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_fd, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x41\n", who_am_i);
        return -1;
    }

    // Place sensor in standby mode
    if (i2cWriteByteData(i2c_fd, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Configure data rate to 100 Hz
    if (i2cWriteByteData(i2c_fd, CTRL_REG4, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_mma8452q_data(int i2c_fd, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_fd, OUT_X_MSB_REG, buffer, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate tilt angle
float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0f;
    float y_g = (float)y / 16384.0f;
    float z_g = (float)z / 16384.0f;

    float tilt_x = x_g * 180.0f;
    float tilt_y = y_g * 180.0f;
    float tilt_z = z_g * 180.0f;

    float tilt_magnitude = sqrt(tilt_x * tilt_x + tilt_y * tilt_y + tilt_z * tilt_z);

    return tilt_magnitude;
}

// Log tilt event
void log_tilt_event(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %6d, Y: %6d, Z: %6d\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, MMA8452Q_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MMA8452Q
    if (init_mma8452q(i2c_fd) < 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("fall_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float tilt;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_mma8452q_data(i2c_fd, &x, &y, &z) == 0) {
            // Calculate tilt
            tilt = calculate_tilt(x, y, z);

            // Check for tilt threshold
            if (tilt > TILT_THRESHOLD) {
                log_tilt_event(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
        }

        // Delay for the sample period
        gpioDelay(SAMPLE_PERIOD_MS * 1000); // pigpioDelay takes microseconds
    }

    // Close I2C device and log file
    i2cClose(i2c_fd);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

