#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define LIS3MDL_ADDR 0x1E
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)
#define METAL_DETECTION_THRESHOLD 800.0f // mG
#define METAL_DETECTION_WINDOW_MS 100
#define LOG_FILE_NAME "magnetic_log.txt"

// Calibration constants (example values, replace with your calibrated values)
#define X_OFFSET 0.0f
#define Y_OFFSET 0.0f
#define Z_OFFSET 0.0f
#define X_SCALE 1.0f
#define Y_SCALE 1.0f
#define Z_SCALE 1.0f

// Global variables
int i2c_handle;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int initialize_i2c();
int configure_magnetometer();
int read_magnetometer_data(magnetometer_data_t *data);
float apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z);
void log_data(magnetometer_data_t data);
void check_metal_detector(magnetometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3MDL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Magnetometer configuration
int configure_magnetometer() {
    // Set continuous conversion mode and 100 Hz output data rate
    char config_data[2];
    config_data[0] = 0x70; // Continuous conversion mode
    config_data[1] = 0x00; // 100 Hz output data rate

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error configuring magnetometer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Apply calibration
    data->x = apply_calibration(raw_x, raw_y, raw_z);
    data->y = apply_calibration(raw_x, raw_y, raw_z);
    data->z = apply_calibration(raw_x, raw_y, raw_z);

    return 0;
}

// Apply calibration
float apply_calibration(int16_t raw_x, int16_t raw_y, int16_t raw_z) {
    return (float)raw_x * X_SCALE + (float)raw_y * Y_SCALE + (float)raw_z * Z_SCALE + X_OFFSET + Y_OFFSET + Z_OFFSET;
