#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define ADXL354B register addresses
#define ADXL354B_REG_PARTID 0x02
#define ADXL354B_REG_STATUS 0x03
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_XDATA_H 0x09
#define ADXL354B_REG_YDATA_L 0x0A
#define ADXL354B_REG_YDATA_H 0x0B
#define ADXL354B_REG_ZDATA_L 0x0C
#define ADXL354B_REG_ZDATA_H 0x0D

// Define reset value
#define ADXL354B_RESET_VALUE 0x8000

// Define retry count
#define MAX_RETRIES 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int spi_read_register(int reg, uint8_t *data, int len);
int spi_write_register(int reg, uint8_t data);
int adxl354b_reset();
int adxl354b_verify_presence();
int adxl354b_read_acceleration(accelerometer_data_t *data);
void log_data(accelerometer_data_t data);
void signal_handler(int signal);

// Function to read multiple bytes from SPI
int spi_read_register(int reg, uint8_t *data, int len) {
    char tx[len + 1];
    char rx[len + 1];

    tx[0] = reg | 0x80; // Set MSB for read operation
    memset(tx + 1, 0, len); // Fill with dummy data for reading

    gpioWrite(8, 0); // Set CE0 low
    int result = spiXfer(spi_handle, tx, rx, len + 1);
    gpioWrite(8, 1); // Set CE0 high

    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    memcpy(data, rx + 1, len);
    return 0;
}

// Function to write a single byte to SPI
int spi_write_register(int reg, uint8_t data) {
    char tx[2];
    char rx[2];

    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = data;

    gpioWrite(8, 0); // Set CE0 low
    int result = spiXfer(spi_handle, tx, rx, 2);
    gpioWrite(8, 1); // Set CE0 high

    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to reset the ADXL354B
int adxl354b_reset() {
    uint8_t reset_value = ADXL354B_RESET_VALUE;
    if (spi_write_register(0x2D, reset_value) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Function to verify the presence of the ADXL354B
int adxl354b_verify_presence() {
    uint8_t part_id;
    if (spi_read_register(ADXL354B_REG_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID register\n");
        return -1;
    }

    if (part_id != 0xAD) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X\n", part_id);
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the ADXL354B
int adxl354b_read_acceleration(accelerometer_data_t *data) {
    uint8_t x_l, x_h, y_l, y_h, z_l, z_h;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (spi_read_register(ADXL354B_REG_XDATA_L, &x_l, 1) != 0) {
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (spi_read_register(ADXL354B_REG_XDATA_H, &x_h, 1) != 0) {
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (spi_read_register(ADXL354B_REG_YDATA_L, &y_l, 1) != 0) {
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (spi_read_register(ADXL354B_REG_YDATA_H, &y_h, 1) != 0) {
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (spi_read_register(ADXL354B_REG_ZDATA_L, &z_l, 1) != 0) {
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        if (spi_read_register(ADXL354B_REG_ZDATA_H, &z_h, 1) != 0) {
            retries++;
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }

        data->x = (int16_t)((x_h << 8) | x_l);
        data->y = (int16_t)((y_h << 8) | y_l);
        data->z = (int16_t)((z_h << 8) | z_l);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read acceleration data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to log data to a file
void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    if (adxl354b_verify_presence() != 0) {
        fprintf(stderr, "ADXL354B verification failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Reset the ADXL354B
    if (adxl354b_reset() != 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    accelerometer_data_t data;
    while (!terminate) {
        if (adxl354b_read_acceleration(&data) == 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

