#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define GPIO_CHIP 4
#define GPIO_LINE 17

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int status;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    if ((status = gpioInitialise(GPIO_CHIP)) < 0) {
        fprintf(stderr, "Failed to open GPIO chip %d\n", GPIO_CHIP);
        gpioTerminate();
        return 1;
    }

    // Request GPIO line
    if ((status = gpioSetMode(GPIO_LINE, PI_INPUT)) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_LINE);
        gpioTerminate();
        return 1;
    }

    printf("Self-parking sequence started. Monitoring obstacle detection...\n");

    // Main loop
    while (running) {
        // Read sensor value
        int sensor_value = gpioRead(GPIO_LINE);

        // Check for obstacle detection (LOW level)
        if (sensor_value == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log message to console
            printf("%s - Obstacle detected! Self-parking sequence started\n", timestamp);

            // Simulate self-parking routine (1 second delay)
            gpioDelay(1000); // 1 second delay

            // Log message to console
            printf("%s - Self-parking sequence completed\n", timestamp);
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Clean up and exit
    printf("Cleaning up and exiting...\n");
    gpioTerminate();
    return 0;
}

