#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define POLLING_INTERVAL_MS 100

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int read_sensors(int *sensor1_value, int *sensor2_value) {
    int result = gpioRead(SENSOR_1_GPIO);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor 1: %d\n", result);
        return -1; // Indicate failure
    }
    *sensor1_value = (result == 0) ? 0 : 1; // Active low

    result = gpioRead(SENSOR_2_GPIO);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor 2: %d\n", result);
        return -1; // Indicate failure
    }
    *sensor2_value = (result == 0) ? 0 : 1; // Active low

    return 0; // Indicate success
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int sensor1_value, sensor2_value;
    time_t current_time;

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        if (read_sensors(&sensor1_value, &sensor2_value) == 0) {
            current_time = time(NULL);
            printf("%s Sensor 1: %d, Sensor 2: %d\n", ctime(&current_time), sensor1_value, sensor2_value);
        } else {
            fprintf(stderr, "Failed to read sensors. Retrying...\n");
        }

        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

