int spi_write_register(int spi_handle, uint8_t address, uint16_t data);
float read_gyro_data(int spi_handle);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a 16-bit value from the ADIS16266
int spi_read_register(int spi_handle, uint8_t address, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to read the register
    tx_buf[0] = address | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading
    tx_buf[2] = 0x00; // Dummy byte for reading

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1; // Indicate error
    }

    // Extract the 16-bit data from the received bytes
    *data = (rx_buf[1] << 8) | rx_buf[2];

    return 0; // Indicate success
}

