#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D

// I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the LSM6DSR
int init_lsm6dsr(int handle)
{
    // Check WHO_AM_I register
    int who_am_i = read_register(handle, WHO_AM_I);
    if (who_am_i < 0) return -1;
    if (who_am_i != 0x69) {
        fprintf(stderr, "Error: WHO_AM_I returned 0x%02X, expected 0x69\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, +/- 2g
    if (write_register(handle, CTRL1_XL, 0x80) < 0) return -1; // 104 Hz, 2g

    // Configure gyroscope: 104 Hz, 250 dps
