        int16_t acc_y = (int16_t)((read_register(i2c_handle, OUTY_H_XL) << 8) | read_register(i2c_handle, OUTY_L_XL));
        int16_t acc_z = (int16_t)((read_register(i2c_handle, OUTZ_H_XL) << 8) | read_register(i2c_handle, OUTZ_L_XL));

        // Read gyroscope data
        int16_t gyro_x = (int16_t)((read_register(i2c_handle, OUTX_H_G) << 8) | read_register(i2c_handle, OUTX_L_G));
        int16_t gyro_y = (int16_t)((read_register(i2c_handle, OUTY_H_G) << 8) | read_register(i2c_handle, OUTY_L_G));
        int16_t gyro_z = (int16_t)((read_register(i2c_handle, OUTZ_H_G) << 8) | read_register(i2c_handle, OUTZ_L_G));

        // Print the data
        printf("%d,%d,%d,%d,%d,%d\n", acc_x, acc_y, acc_z, gyro_x, gyro_y, gyro_z);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (never reached in normal operation due to the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

