#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1F

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_ACCEL_DATA_START 0x01
#define FXOS8700_MAG_DATA_START 0x33

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retrying...\n", reg, result);
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X)\n", reg);
    return -1; // Indicate failure
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result, retries = 3;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %d. Retrying...\n", reg, value, result);
            gpioDelay(1000); // 1ms delay
            retries--;
        }
    }
    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X)\n", reg, value);
    return -1; // Indicate failure
}

// Function to read the WHO_AM_I register and check the device ID
int check_device_id(int handle) {
    int who_am_i = i2c_read_byte(handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != 0x41) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X (expected 0x41)\n", who_am_i);
        return -1;
    }
    printf("FXOS8700 WHO_AM_I: 0x%02X (OK)\n", who_am_i);
    return 0;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700(int handle) {
    // Set accelerometer to active mode, 100 Hz ODR
    if (i2c_write_byte(handle, FXOS8700_CTRL_REG1, 0x01 | (1 << 2)) < 0) {
        fprintf(stderr, "Failed to set accelerometer mode.\n");
        return -1;
    }

    // Set magnetometer to active mode, 100 Hz ODR
    if (i2c_write_byte(handle, FXOS8700_M_CTRL_REG1, 0x01 | (1 << 2)) < 0) {
        fprintf(stderr, "Failed to set magnetometer mode.\n");
        return -1;
    }

    return 0;
}

// Function to read a 12-byte block of data from the FXOS8700
int read_fxos8700_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *mag_x, int16_t *mag_y, int16_t *mag_z) {
    char buffer[12];
    int result = i2cReadI2CBlockData(handle, FXOS8700_ACCEL_DATA_START, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Failed to read data block: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for each axis
    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *mag_x = (int16_t)((buffer[6] << 8) | buffer[7]);
    *mag_y = (int16_t)((buffer[8] << 8) | buffer[9]);
    *mag_z = (int16_t)((buffer[10] << 8) | buffer[11]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check device ID
    if (check_device_id(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
