#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Tilt angle threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int adxl345_init();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
int log_tilt_event(double tilt_angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
}

// Initialize the ADXL345 accelerometer
int adxl345_init() {
    // Set power control register to start measurement
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set ADXL345 power control register.\n");
        return -1;
    }
    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate the tilt angle in degrees
double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double angle_x = (double)x / 256.0;
    double angle_y = (double)y / 256.0;
    double angle_z = (double)z / 256.0;

    double tilt_angle = atan2(angle_y, angle_x) * 180.0 / M_PI;

    // Normalize tilt angle to be between -90 and 90 degrees
    if (tilt_angle > 90.0) {
        tilt_angle -= 180.0;
    } else if (tilt_angle < -90.0) {
        tilt_angle += 180.0;
    }

    return tilt_angle;
}

// Log a tilt event to the log file
int log_tilt_event(double tilt_angle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return -1;
    }

    fprintf(fp, "%s Tilt angle: %.2f degrees\n", timestamp, tilt_angle);
    fclose(fp);

    return 0;
}

int main() {
    int16_t x, y, z;
    double tilt_angle;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("ADXL345 tilt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Calculate tilt angle
            tilt_angle = calculate_tilt_angle(x, y, z);

            // Log tilt event if threshold exceeded
            if (fabs(tilt_angle) > TILT_THRESHOLD) {
                if (log_tilt_event(tilt_angle) == 0) {
                    printf("Tilt event logged: %.2f degrees\n", tilt_angle);
                } else {
                    fprintf(stderr, "Error: Failed to log tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read acceleration data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("ADXL345 tilt monitoring stopped.\n");

    return 0;
}

