#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_DURATION_SEC 5

// Global variables
volatile int high_count = 0;
volatile int running = 1;

// Function prototypes
int initialize_gpio();
int read_gpio();
void increment_high_count();
void print_status(int high_count);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int threshold;
} ProgramState;

ProgramState state = {0}; // Initialize threshold to 0

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    if (sscanf(argv[1], "%d", &state.threshold) != 1 || state.threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time, current_time;
    double elapsed_time;
    int high_count_per_window;

    while (running) {
        time(&start_time);
        high_count_per_window = 0;
        while (time(NULL) - start_time < WINDOW_DURATION_SEC) {
            if (read_gpio() == 1) {
                increment_high_count();
            }
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
        }
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        print_status(high_count_per_window);
        gpioDelay(1000000); // Pause for 1 second
    }

    gpioTerminate();
    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

int read_gpio() {
    return gpioRead(GPIO_PIN);
}

void increment_high_count() {
    high_count++;
}

void print_status(int high_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (high_count > state.threshold) {
        printf("%s ALERT: High count exceeded threshold (%d > %d)\n", timestamp, high_count, state.threshold);
    } else {
        printf("%s Status: High count = %d (threshold = %d)\n", timestamp, high_count, state.threshold);
    }
}

void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioTerminate();
    exit(0);
}

