#define UNLOCK_DURATION_MS 5000
#define MAX_CODE_LENGTH 10
#define MAX_RETRIES 3

volatile sig_atomic_t program_running = 1;

// Function to generate a random six-digit code
char* generate_code() {
    char* code = malloc(MAX_CODE_LENGTH + 1);
    if (code == NULL) {
        perror("Failed to allocate memory for code");
        return NULL;
    }
    for (int i = 0; i < MAX_CODE_LENGTH; i++) {
        code[i] = '0' + rand() % 9; // Generate digits 0-9
    }
    code[MAX_CODE_LENGTH] = '\0';
    return code;
}

// Function to log access attempts
void log_access(const char* code, const char* user_input) {
    FILE* log_file = fopen("access_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open access_log.txt");
        return;
    }

    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct);

    fprintf(log_file, "%s,%s\n", buf, user_input);
    fclose(log_file);
