#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LOG_FILE "light_log.txt"

int i2c_handle;
FILE *log_file;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the BH1750 sensor
int init_bh1750() {
    int result = i2cWriteByteData(i2c_handle, 0x00, CONTINUOUS_HIGH_RES_MODE);
    if (result != 0) {
        fprintf(stderr, "Error initializing BH1750: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read illuminance from the BH1750 sensor
int read_bh1750(uint16_t *lux) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading BH1750: %d\n", result);
        return -1;
    }

    *lux = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to log the illuminance reading to a file
int log_reading(uint16_t lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(log_file, "Timestamp: %s, Lux: %u\n", timestamp, lux);
    fclose(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize BH1750 sensor
    if (init_bh1750() != 0) {
        fprintf(stderr, "BH1750 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t lux;

    // Main loop
    while (1) {
        if (read_bh1750(&lux) == 0) {
            if (lux > 0) {
                if (log_reading(lux) != 0) {
                    fprintf(stderr, "Error logging reading\n");
                }
            } else {
                fprintf(stderr, "Invalid lux value: %u\n", lux);
            }
        } else {
            fprintf(stderr, "Failed to read illuminance\n");
        }

        sleep(5);
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

