#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define PORT 12345
#define MPR121_ADDR 0x5A
#define GPIO_PWM 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 20
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int authenticate_client(const char *client_ip, const char *client_port);
int play_tone(int frequency);
int log_frequency(int frequency);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Configure electrodes (example: enable all electrodes)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to configure electrodes\n");
        return -1;
    }

    // Configure touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error: Failed to configure touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error: Failed to configure release threshold for electrode %d\n", i);
            return -1;
        }
    }

    return 0;
}

// Authenticate client
int authenticate_client(const char *client_ip, const char *client_port) {
    char command[256];
    char response[256];
    int bytes_received;

    // Receive command from client
    bytes_received = recv(new_socket, command, sizeof(command) - 1, 0);
    if (bytes_received < 0) {
        perror("Error receiving command");
        return -1;
    }
    command[bytes_received] = '\0';

    // Check if the command starts with "MOTION_DETECTED:"
    if (strncmp(command, "MOTION_DETECTED:", 16) != 0) {
        fprintf(stderr, "Error: Invalid command format\n");
        return -1;
    }

    // Extract the shared secret
    const char *secret = strstr(command, "MySecretKey");
    if (secret == NULL) {
        fprintf(stderr, "Error: Shared secret not found in command\n");
        return -1;
    }

    // Verify the shared secret
    if (strcmp(secret, "MySecretKey") != 0) {
        fprintf(stderr, "Error: Incorrect shared secret\n");
        return -1;
    }

    // Generate a random 16-byte nonce
    unsigned char nonce[16];
    for (int i = 0; i < 16; i++) {
        nonce[i] = rand() % 256;
    }

    // Create the authentication message
    snprintf(response, sizeof(response), "MOTION_DETECTED: %s", secret);

    // Send the nonce to the client
    if (send(new_socket, nonce, sizeof(nonce), 0) < 0) {
        perror("Error sending nonce");
        return -1;
    }

    printf("Authentication successful. Nonce sent: %s\n", nonce);
    return 0;
}

// Play tone
int play_tone(int frequency) {
    if (gpioPWM(GPIO_PWM, 128) != 0) { // 50% duty cycle
        fprintf(stderr, "Error: Failed to set PWM duty cycle\n");
        return -1;
    }
    gpioSetPWMfrequency(GPIO_PWM, frequency);
    return 0;
}

// Log frequency
int log_frequency(int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Frequency: %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

int main() {
    int frequency;
    int client_fd, new_socket;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[1024] = {0};
    int addrlen = sizeof(client_addr);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 to output mode
    gpioSetMode(GPIO_PWM, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("Error creating socket");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set socket options to reuse address
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error binding socket");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Error listening on socket");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", PORT);

    // Main loop
    while (!terminate) {
        // Accept connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len)) < 0) {
            perror("Error accepting connection");
            continue; // Continue listening
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_addr.sin_addr), ntohs(client_addr.sin_port));

        // Authenticate client
        if (authenticate_client(inet_ntoa(client_addr.sin_addr), inet_ntoa(client_addr.sin_port)) == 0) {
            // Generate a random frequency between 200 and 2000 Hz
            frequency = rand() % 2000 + 200;

            // Play tone
            if (play_tone(frequency) == 0) {
                // Log frequency
                log_frequency(frequency);

                // Play tone for 5 seconds
                gpioDelay(5000000); // 5 seconds

                // Stop PWM
                gpioPWM(GPIO_PWM, 0);
            } else {
                fprintf(stderr, "Error: Failed to play tone\n");
            }
        } else {
            fprintf(stderr, "Error: Authentication failed\n");
        }

        // Close socket
        close(new_socket);
    }

    // Clean up
    printf("Cleaning up and exiting...\n");
    gpioPWM(GPIO_PWM, 0); // Stop PWM
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

