#include <string.h>

// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC Magnetometer Registers
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x28
#define OUT_X_H_M 0x29
#define OUT_Y_L_M 0x2A
#define OUT_Y_H_M 0x2B
#define OUT_Z_L_M 0x2C
#define OUT_Z_H_M 0x2D

// GPIO pin for LED (BCM numbering)
#define LED_PIN 17

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_magnetometer(int i2c_handle);
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z);
float calculate_z_magnitude(int16_t z);
void set_led_brightness(int gpio_pin, float magnitude);
void log_data(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the magnetometer
int init_magnetometer(int i2c_handle) {
    // Enable continuous measurement mode (100 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_M\n");
        return -1;
    }
    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int i2c_handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *z = (int16_t)((buffer[3] << 8) | buffer[2]);
    *y = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate Z-axis field magnitude
float calculate_z_magnitude(int16_t z) {
    // Convert to milliGauss (adjust scale factor as needed)
    return (float)z * 0.0039; // Example scale factor
}

// Set LED brightness using PWM
void set_led_brightness(int gpio_pin, float magnitude) {
    int duty_cycle = (int)(magnitude / 100.0 * 255.0); // Map magnitude to 0-255
    gpioPWM(gpio_pin, duty_cycle);
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, float magnitude) {
    fprintf(log_file, "%d,%d,%d,%.2f\n", x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer(i2c_handle) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(LED_PIN, 255); // Set PWM range

    // Open log file
    log_file = fopen("magnetometer_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_handle, &x, &y, &z) == 0) {
            // Calculate Z-axis magnitude
            magnitude = calculate_z_magnitude(z);

            // Set LED brightness
            set_led_brightness(LED_PIN, magnitude);

            // Log data
            log_data(x, y, z, magnitude);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error\n");
        }

        gpioDelay(100); // Sample every 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioPWM(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

