#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Structure to hold magnetometer data with offset
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_offset_t;

// Circular buffer for magnetometer data
#define BUFFER_SIZE 100
magnetometer_data_t magnetometer_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_hmc5883l();
int read_magnetometer_data(magnetometer_data_t *data);
void update_circular_buffer(magnetometer_data_t data);
magnetometer_data_offset_t calculate_offset(const magnetometer_data_t *data);
void print_offset_corrected_data(const magnetometer_data_offset_t *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the HMC5883L
int initialize_hmc5883l() {
    // Set configuration register A to 0x70 (8-average, 15 Hz, normal measurement)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B to 0xA0 (Gain = 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register to continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to update the circular buffer
void update_circular_buffer(magnetometer_data_t data) {
    magnetometer_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the offset
magnetometer_data_offset_t calculate_offset(const magnetometer_data_t *data) {
    magnetometer_data_offset_t offset;
    int16_t x_sum = 0, y_sum = 0, z_sum = 0;

    for (int i = 0; i < BUFFER_SIZE; i++) {
        x_sum += magnetometer_buffer[i].x;
        y_sum += magnetometer_buffer[i].y;
        z_sum += magnetometer_buffer[i].z;
    }

    offset.x = x_sum / BUFFER_SIZE;
    offset.y = y_sum / BUFFER_SIZE;
    offset.z = z_sum / BUFFER_SIZE;

    return offset;
}

// Function to print the offset-corrected data
void print_offset_corrected_data(const magnetometer_data_offset_t *data) {
    printf("X: %d, Y: %d, Z: %d\n", data->x, data->y, data->z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    magnetometer_data_t raw_data;
    magnetometer_data_offset_t offset_data;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&raw_data) == 0) {
            // Update circular buffer
            update_circular_buffer(raw_data);

            // Calculate offset
            offset_data = calculate_offset(&raw_data);

            // Subtract offset
            raw_data.x -= offset_data.x;
            raw_data.y -= offset_data.y;
            raw_data.z -= offset_data.z;

            // Print offset-corrected data
            print_offset_corrected_data(&offset_data);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        gpioDelay(500); // 500ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

