#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D

// Interrupt pin
#define INT1_PIN 23

// Circular buffer size
#define BUFFER_SIZE 64

// Sensitivity (mg/LSB)
#define SENSITIVITY 0.061

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Circular buffer
accelerometer_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_lsm303d();
int read_accelerometer_data(accelerometer_data_t *data);
void interrupt_handler(int gpio, int level, uint32_t tick);
void dump_buffer_to_console();
void signal_handler(int signal);

// Function to initialize the LSM303D accelerometer
int init_lsm303d() {
    // Check device ID
    char device_id;
    if (i2cReadI2CBlockData(i2c_handle, 0x00, &device_id, 1) != 1) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (device_id != 0x40) {
        fprintf(stderr, "Incorrect device ID: 0x%02x\n", device_id);
        return -1;
    }

    // Configure accelerometer for 100 Hz data rate and +/- 2g range
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) != 0) { // 0b01010111
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) != 0) { // 0b00000000
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        dump_buffer_to_console();
    }
}

// Function to dump the contents of the circular buffer to the console
void dump_buffer_to_console() {
    printf("Timestamp, ");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        printf("%ld, ", circular_buffer[i].x);
    }
    printf("\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() != 0) {
        fprintf(stderr, "LSM303D initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set interrupt handler
    if (gpioSetMode(INT1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetISRFuncEx(INT1_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        accelerometer_data_t data;

        if (read_accelerometer_data(&data) == 0) {
            // Store data in circular buffer
            circular_buffer[buffer_index] = data;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Dump buffer to console on rising edge of INT1 pin
            if (gpioRead(INT1_PIN) == 1) {
                dump_buffer_to_console();
            }
        } else {
            fprintf(stderr, "Error reading accelerometer data, skipping sample\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    // Disable accelerometer
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x00) != 0) {
        fprintf(stderr, "Error disabling accelerometer\n");
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

