#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Function prototypes
int initialize_gpio(void);
void activate_solenoid(int solenoid_pin);
void deactivate_solenoid(int solenoid_pin);
void switch_solenoids(void);
void cleanup_gpio(void);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Solenoid control program started. Press Ctrl+C to exit.\n");

    // Main loop: switch solenoids every 500ms
    while (program_running) {
        switch_solenoids();
        gpioDelay(500); // Delay for 500ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Solenoid control program finished.\n");
    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_1_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SOLENOID_2_PIN);
        gpioTerminate();
        return 1;
    }

    // Set initial state to LOW (solenoids deactivated)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);

    return 0;
}

// Function to activate a solenoid by setting the corresponding GPIO pin HIGH
void activate_solenoid(int solenoid_pin) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Failed to write HIGH to GPIO%d\n", solenoid_pin);
    }
}

// Function to deactivate a solenoid by setting the corresponding GPIO pin LOW
void deactivate_solenoid(int solenoid_pin) {
    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", solenoid_pin);
    }
}

// Function to switch the active solenoid line
void switch_solenoids(void) {
    deactivate_solenoid(SOLENOID_1_PIN);
    activate_solenoid(SOLENOID_2_PIN);
}

// Function to clean up GPIO resources and terminate the pigpio library
void cleanup_gpio(void) {
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();
}

// Signal handler function to catch SIGINT and SIGTERM signals
void signal_handler(int signal) {
    program_running = 0; // Set the flag to exit the main loop
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

