#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <errno.h>

// Define UART port names
#define UART_PRIMARY "/dev/serial0"
#define UART_SECONDARY "/dev/serial1"

// Define GPIO pins for relay control
#define RELAY_PRIMARY_PIN 17
#define RELAY_SECONDARY_PIN 27

// Define expected code length
#define CODE_LENGTH 6

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Define expected code
const char *expected_code = "123456";

// Global variables
int uart_fd_primary = -1;
int uart_fd_secondary = -1;
int lock_state = 0; // 0 = unlocked, 1 = locked

// Function prototypes
int initialize_uart(const char *port_name);
int read_uart_port(int fd, char *buffer, int max_len);
int validate_code(const char *code);
int control_relay(int gpio_pin, int state);
void log_error(const char *message);
void signal_handler(int signal);

// Structure to hold UART configuration
typedef struct {
    char port_name[20];
    int fd;
} uart_config_t;

// Function to initialize a UART port
int initialize_uart(const char *port_name) {
    uart_config_t config;
    strcpy(config.port_name, port_name);
    config.fd = open(port_name, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (config.fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(config.fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(config.fd);
        return -1;
    }

    tty.c_cflag = B9600 | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(config.fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(config.fd);
        return -1;
    }

    return config.fd;
}

// Function to read from a UART port
int read_uart_port(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0; // No data read
        } else {
            perror("Error reading from UART port");
            return -1;
        }
    } else if (bytes_read == 0) {
        // Timeout occurred
        return 0; // No data read
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

// Function to validate the received code
int validate_code(const char *code) {
    if (strcmp(code, expected_code) == 0) {
        return 1; // Code matches
    } else {
        return 0; // Code does not match
    }
}

// Function to control the relay
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        return -1; // Error writing to GPIO
    }
    return 0;
}

// Function to log errors
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    control_relay(RELAY_PRIMARY_PIN, 0); // Unlock both locks
    control_relay(RELAY_SECONDARY_PIN, 0);
    if (uart_fd_primary != -1) close(uart_fd_primary);
    if (uart_fd_secondary != -1) close(uart_fd_secondary);
    gpioTerminate();
    exit(0);
}

