int uart_fd_secondary = -1;
int lock_state = 0; // 0 = unlocked, 1 = locked

// Function prototypes
int initialize_uart(const char *port_name);
int read_uart_port(int fd, char *buffer, int max_len);
int validate_code(const char *code);
int control_relay(int gpio_pin, int state);
void log_error(const char *message);
void signal_handler(int signal);

// Structure to hold UART configuration
typedef struct {
    char port_name[20];
    int fd;
} uart_config_t;

// Function to initialize a UART port
int initialize_uart(const char *port_name) {
    uart_config_t config;
    strcpy(config.port_name, port_name);
    config.fd = open(port_name, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (config.fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(config.fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(config.fd);
        return -1;
    }

    tty.c_cflag = B9600 | CS8 | CLOCAL | CREAD;  // 9600 baud, 8 data bits, no parity, 1 stop bit
    tty.c_iflag = IGNPAR; // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0; // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(config.fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(config.fd);
        return -1;
    }

    return config.fd;
}

// Function to read from a UART port
int read_uart_port(int fd, char *buffer, int max_len) {
    ssize_t bytes_read = read(fd, buffer, max_len - 1);
    if (bytes_read == -1) {
        if (errno == EAGAIN || errno == EWOULDBLOCK) {
            // Timeout occurred
            return 0; // No data read
        } else {
            perror("Error reading from UART port");
            return -1;
        }
    } else if (bytes_read == 0) {
        // Timeout occurred
        return 0; // No data read
    } else {
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return bytes_read;
    }
}

