#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/file.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <pthread.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define PIR_PIN 4
#define RELAY_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_CS_PIN 8
#define LOG_FILE "/var/log/motion_detector.log"
#define SHM_KEY 1234
#define SHM_SIZE 1024
#define SEM_KEY 5678
#define SEM_MAX_MESSAGES 10
#define SEM_TIMEOUT 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd = -1;
int shmid = -1;
sem_t *sem = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int spi_init(int channel, int speed, int mode);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int channel);
void *relay_control_thread(void *arg);
void signal_handler(int sig);
void log_message(int priority, const char *message);
void log_error(const char *message);
void log_warning(const char *message);
void log_shutdown(const char *message);

// GPIO functions
int gpio_export(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /sys/class/gpio/export");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd == -1) {
        perror("Failed to open /sys/class/gpio/unexport");
        return -1;
    }

    bytes_written = snprintf(buffer, sizeof(buffer), "%d", pin);
    write(fd, buffer, bytes_written);
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) == -1) {
        perror("Failed to set GPIO direction");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) == -1) {
        perror("Failed to read GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd == -1) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }

    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);

    if (write(fd, val_str, 1) == -1) {
        perror("Failed to write GPIO value");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// SPI functions
int spi_init(int channel, int speed, int mode) {
    int fd;
    unsigned int mode_value = 0;

    if (mode == 0) {
        mode_value = 0x00;
    } else if (mode == 1) {
        mode_value = 0x02;
    } else if (mode == 2) {
        mode_value = 0x03;
    } else {
        fprintf(stderr, "Invalid SPI mode: %d\n", mode);
        return -1;
    }

    if ((fd = open("/dev/spidev0.0", O_RDWR)) < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Failed to set SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &8) == -1) {
        perror("Failed to set bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Failed to set max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Failed to transfer SPI data");
        return -1;
    }

    return 0;
}

// MCP3008 functions
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_fd < 0) {
        log_error("SPI device not initialized");
        return -1;
    }

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) != 0) {
        log_error("SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Thread function for relay control
void *relay_control_thread(void *arg) {
    int relay_state = 0; // 0 = off, 1 = on
    int relay_fd = -1;
    int shmid_relay = -1;
    int shm_size = sizeof(int);

    // Initialize shared memory for relay state
    if ((shmid_relay = shmget(SHM_KEY, shm_size, IPC_CREAT | 0666)) < 0) {
        perror("shmget failed");
        log_error("Failed to initialize shared memory for relay state");
        pthread_exit(NULL);
    }

    if ((relay_fd = shmat(shmid_relay, NULL, 0)) < 0) {
        perror("shmat failed");
        log_error("Failed to attach shared memory for relay state");
        pthread_exit(NULL);
    }

    // Initialize semaphore for relay control
    if ((sem = sem_open(SEM_KEY, O_CREAT | O_RDWR, 0, SEM_MAX_MESSAGES, SEM_TIMEOUT)) < 0) {
        perror("sem_open failed");
        log_error("Failed to initialize semaphore for relay control");
        shmdt(relay_fd);
        shmdel(shmid_relay);
        pthread_exit(NULL);
    }

    while (program_running) {
        int current_relay_state = gpio_read(RELAY_PIN);
        if (current_relay_state < 0) {
            log_error("Failed to read relay state");
            break;
        }

        if (current_relay_state == 1 && relay_state == 0) {
            // Turn relay on
            if (gpio_write(RELAY_PIN, 1) != 0) {
                log_error("Failed to write to relay pin");
                break;
            }
            log_message(LOG_INFO, "Relay turned ON");
            relay_state = 1;

            // Acquire semaphore
            if (sem_wait(sem) != 0) {
                log_error("Failed to acquire semaphore");
                break;
            }

            // Log relay state change
            char message[100];
            snprintf(message, sizeof(message), "Relay state changed to ON");
            log_message(LOG_INFO, message);
        } else if (current_relay_state == 0 && relay_state == 1) {
            // Turn relay off
            if (gpio_write(RELAY_PIN, 0) != 0) {
                log_error("Failed to write to relay pin");
                break;
            }
            log_message(LOG_INFO, "Relay turned OFF");
            relay_state = 0;

            // Release semaphore
            if (sem_post(sem) != 0) {
                log_error("Failed to release semaphore");
                break;
            }

            // Log relay state change
            char message[100];
            snprintf(message, sizeof(message), "Relay state changed to OFF");
            log_message(LOG_INFO, message);
        }

        usleep(100000); // 100ms delay
    }

    // Cleanup
    if (relay_fd != -1) {
        shmdt(relay_fd);
    }
    if (sem != NULL) {
        sem_close(sem);
        sem_unlink(SEM_KEY);
    }
    log_message(LOG_INFO, "Relay control thread exiting");
    pthread_exit(NULL);
}

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_message(LOG_INFO, "Signal received, shutting down...");
        program_running = 0;
    }
}

// Logging functions
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: ", timestamp);
    snprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), "%s", message);

    syslog(priority, log_entry);
}

void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: ERROR: %s", timestamp, message);

    syslog(LOG_ERR, log_entry);
}

void log_warning(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: WARNING: %s", timestamp, message);

    syslog(LOG_WARNING, log_entry);
}

void log_shutdown(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s: SHUTDOWN: %s", timestamp, message);

    syslog(LOG_CRIT, log_entry);
}

int main() {
    // Initialize syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // GPIO initialization
    if (gpio_export(PIR_PIN) != 0) return 1;
    if (gpio_set_direction(PIR_PIN, "in") != 0) return 1;
    if (gpio_export(RELAY_PIN) != 0) return 1;
    if (gpio_set_direction(RELAY_PIN, "out") != 0) return 1;

    // SPI initialization
    spi_fd = spi_init(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_fd < 0) {
        log_error("SPI initialization failed");
        gpio_unexport(PIR_PIN);
        gpio_unexport(RELAY_PIN);
        closelog();
        return 1;
    }

    // Relay control thread
    pthread_t relay_thread;
    if (pthread_create(&relay_thread, NULL, relay_control_thread, NULL) != 0) {
        log_error("Failed to create relay control thread");
        gpio_unexport(PIR_PIN);
        gpio_unexport(RELAY_PIN);
        close(spi_fd);
        closelog();
        return 1;
    }

    // Main loop
    while (program_running) {
        int pir_value = gpio_read(PIR_PIN);
        if (pir_value < 0) {
            log_error("Failed to read PIR sensor value");
            break;
        }

        if (pir_value == 1) {
            log_message(LOG_INFO, "Motion detected!");
            log_warning("Motion detected, relay control thread running");
            if (gpio_write(RELAY_PIN, 0) != 0) {
                log_error("Failed to write to relay pin");
                break;
            }
            log_message(LOG_INFO, "Relay de-energized");
            usleep(100000); // 100ms delay
            if (gpio_write(RELAY_PIN, 1) != 0) {
                log_error("Failed to write to relay pin");
                break;
            }
            log_message(LOG_INFO, "Relay energized");
            usleep(1000000); // 1 second delay
            if (gpio_write(RELAY_PIN, 0) != 0) {
                log_error("Failed to write to relay pin");
                break;
            }
            log_message(LOG_INFO, "Relay de-energized");
        } else {
            // Check for continuous HIGH for 10 seconds
            int high_count = 0;
            while (program_running) {
                int current_pir_value = gpio_read(PIR_PIN);
                if (current_pir_value < 0) {
                    log_error("Failed to read PIR sensor value");
                    break;
                }
                if (current_pir_value == 1) {
                    high_count++;
                } else {
                    break;
                }
                usleep(50000); // 50ms delay
            }

            if (high_count > 10) {
                log_warning("Motion detected for extended period, triggering failsafe");
                log_shutdown("Motion detected for extended period, triggering failsafe");
                // De-energize relay
                if (gpio_write(RELAY_PIN, 0) != 0) {
                    log_error("Failed to write to relay pin");
                    break;
                }
                log_message(LOG_WARNING, "Failsafe triggered: Relay de-energized");
            }
        }
    }

    // Cleanup
    pthread_join(relay_thread, NULL);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (sem != NULL) {
        sem_close(sem);
        sem_unlink(SEM_KEY);
    }
    log_message(LOG_INFO, "Program exiting");
    closelog();
