#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <stdbool.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the timer interval in seconds
#define TIMER_INTERVAL 60

// Define the activation time for each relay in seconds
#define ACTIVATION_TIME 300

// Define the pause time between activations in seconds
#define PAUSE_TIME 60

// Define the number of relays
#define NUM_RELAYS 4

// Define the state machine states
typedef enum {
    STATE_IDLE,
    STATE_ACTIVATE_1,
    STATE_ACTIVATE_2,
    STATE_ACTIVATE_3,
    STATE_ACTIVATE_4,
    STATE_PAUSED
} state_t;

// Global variables
volatile sig_atomic_t program_running = 1;
state_t current_state = STATE_IDLE;

// Function prototypes
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void state_machine();
void signal_handler(int signal);

// Function to activate a relay
void activate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 0) != 0) {
        syslog(LOG_ERR, "Failed to activate relay on GPIO %d", relay_pin);
        fprintf(stderr, "Failed to activate relay on GPIO %d\n", relay_pin);
    } else {
        syslog(LOG_INFO, "Activated relay on GPIO %d", relay_pin);
        fprintf(stderr, "Activated relay on GPIO %d\n", relay_pin);
    }
}

// Function to deactivate a relay
void deactivate_relay(int relay_pin) {
    if (gpioWrite(relay_pin, 1) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay on GPIO %d", relay_pin);
        fprintf(stderr, "Failed to deactivate relay on GPIO %d\n", relay_pin);
    } else {
        syslog(LOG_INFO, "Deactivated relay on GPIO %d", relay_pin);
        fprintf(stderr, "Deactivated relay on GPIO %d\n", relay_pin);
    }
}

// State machine function
void state_machine() {
    switch (current_state) {
        case STATE_IDLE:
            // Check if the timer has reached the activation time
            if (time(NULL) % TIMER_INTERVAL == 0) {
                current_state = STATE_ACTIVATE_1;
            }
            break;

        case STATE_ACTIVATE_1:
            activate_relay(RELAY1_PIN);
            current_state = STATE_PAUSED;
            break;

        case STATE_ACTIVATE_2:
            activate_relay(RELAY2_PIN);
            current_state = STATE_PAUSED;
            break;

        case STATE_ACTIVATE_3:
            activate_relay(RELAY3_PIN);
            current_state = STATE_PAUSED;
            break;

        case STATE_ACTIVATE_4:
            activate_relay(RELAY4_PIN);
            current_state = STATE_PAUSED;
            break;

        case STATE_PAUSED:
            deactivate_relay(RELAY1_PIN);
            deactivate_relay(RELAY2_PIN);
            deactivate_relay(RELAY3_PIN);
            deactivate_relay(RELAY4_PIN);
            current_state = STATE_IDLE;
            break;
    }
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
        fprintf(stderr, "Received signal %d, shutting down...\n", signal);

        // Deactivate all relays
        deactivate_relay(RELAY1_PIN);
        deactivate_relay(RELAY2_PIN);
        deactivate_relay(RELAY3_PIN);
        deactivate_relay(RELAY4_PIN);

        // Release GPIO resources
        gpioTerminate();

        // Close syslog
        closelog();

        // Exit the program
        exit(0);
    }
}

int main() {
    // Initialize syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        fprintf(stderr, "pigpio initialisation failed\n");
        closelog();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial state
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Start the timer
    gpioSetTimerFuncEx(0, TIMER_INTERVAL, state_machine, NULL);

    // Main loop
    while (program_running) {
        // Check for termination signal
        if (program_running) {
            sleep(1); // Sleep for 1 second to avoid busy-waiting
        }
    }

    // Cleanup (should not reach here if signal handler is working correctly)
    gpioTerminate();
    closelog();
    return 0;
}

