#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/time.h>
#include <pthread.h>
#include <stdbool.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Acceleration range (2g)
#define ACCEL_SCALE 16384.0f

// Circular buffer size
#define BUFFER_SIZE 100

// Timer interval (microseconds)
#define TIMER_INTERVAL 10000 // 100 Hz

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float x[BUFFER_SIZE];
    float y[BUFFER_SIZE];
    float z[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t buffer;

// Mutex for buffer access
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
int init_i2c(void);
int read_mpu6050(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
float get_latest_reading(void);
void *timer_handler(void *arg);
void signal_handler(int sig);
void cleanup(void);

// Function to initialize the I2C bus
int init_i2c(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Wake up the MPU6050 (clear sleep mode bit)
    uint8_t wake_up_data[] = {0x00};
    if (write(i2c_fd, wake_up_data, sizeof(wake_up_data)) != sizeof(wake_up_data)) {
        perror("Error writing to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read accelerometer data from the MPU6050
int read_mpu6050(float *x, float *y, float *z) {
    uint8_t buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of accelerometer data
    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert raw values to g-force units
    *x = (float)raw_x / ACCEL_SCALE;
    *y = (float)raw_y / ACCEL_SCALE;
    *z = (float)raw_z / ACCEL_SCALE;

    return 0;
}

// Function to add a new reading to the circular buffer
void add_to_buffer(float x, float y, float z) {
    pthread_mutex_lock(&buffer_mutex);

    buffer.x[buffer.head] = x;
    buffer.y[buffer.head] = y;
    buffer.z[buffer.head] = z;

    buffer.head = (buffer.head + 1) % BUFFER_SIZE;
    if (buffer.count < BUFFER_SIZE) {
        buffer.count++;
    }

    pthread_mutex_unlock(&buffer_mutex);
}

// Function to get the latest reading from the circular buffer
float get_latest_reading(void) {
    pthread_mutex_lock(&buffer_mutex);
    float x = buffer.x[(buffer.head + BUFFER_SIZE - 1) % BUFFER_SIZE];
    float y = buffer.y[(buffer.head + BUFFER_SIZE - 1) % BUFFER_SIZE];
    float z = buffer.z[(buffer.head + BUFFER_SIZE - 1) % BUFFER_SIZE];
    pthread_mutex_unlock(&buffer_mutex);
    return x;
}

// Timer handler function
void *timer_handler(void *arg) {
    float x, y, z;

    while (program_running) {
        if (read_mpu6050(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
        } else {
            fprintf(stderr, "Error reading MPU6050 data\n");
        }
        usleep(TIMER_INTERVAL);
    }

    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", sig);
        program_running = 0;
    }
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up resources...\n");

    // Close I2C bus
    if (i2c_fd > 0) {
        close(i2c_fd);
    }

    // Destroy mutex
    pthread_mutex_destroy(&buffer_mutex);

    printf("Cleanup complete.\n");
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.count = 0;

    // Create timer
    pthread_t timer_thread;
    if (pthread_create(&timer_thread, NULL, timer_handler, NULL) != 0) {
        perror("Error creating timer thread");
        cleanup();
        return 1;
    }

    // Wait for the timer thread to finish (or until a signal is received)
    pthread_join(timer_thread, NULL);

    // Clean up resources
    cleanup();

    return 0;
}

