#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define prime numbers for the intervals (in seconds)
#define INTERVAL1 2
#define INTERVAL2 3
#define INTERVAL3 5
#define INTERVAL4 7

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
    }
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
        return -1; // Indicate an error
    }
    return 0; // Indicate success
}

// Function to toggle the state of a relay
int toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    if (current_state == PI_LOW) {
        return set_relay_state(gpio_pin, PI_HIGH);
    } else {
        return set_relay_state(gpio_pin, PI_LOW);
    }
}

// Function to get the current time in seconds since the epoch
double get_current_time() {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
}

// Function to wait for a specified interval
void wait_interval(int interval_seconds) {
    double current_time = get_current_time();
    double wait_time = current_time + interval_seconds;
    while (get_current_time() < wait_time) {
        gpioDelay(1000); // Wait 1ms
    }
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set the initial state of all relays to OFF (LOW)
    set_relay_state(RELAY1_PIN, PI_LOW);
    set_relay_state(RELAY2_PIN, PI_LOW);
    set_relay_state(RELAY3_PIN, PI_LOW);
    set_relay_state(RELAY4_PIN, PI_LOW);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Toggle relay 1
        if (toggle_relay(RELAY1_PIN)) {
            fprintf(stderr, "Error toggling relay 1\n");
        }

        // Wait for the specified interval for relay 1
        wait_interval(INTERVAL1);

        // Toggle relay 2
        if (toggle_relay(RELAY2_PIN)) {
            fprintf(stderr, "Error toggling relay 2\n");
        }

        // Wait for the specified interval for relay 2
        wait_interval(INTERVAL2);

        // Toggle relay 3
        if (toggle_relay(RELAY3_PIN)) {
            fprintf(stderr, "Error toggling relay 3\n");
        }

        // Wait for the specified interval for relay 3
        wait_interval(INTERVAL3);

        // Toggle relay 4
        if (toggle_relay(RELAY4_PIN)) {
            fprintf(stderr, "Error toggling relay 4\n");
        }

        // Wait for the specified interval for relay 4
        wait_interval(INTERVAL4);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

