#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 500

// Define relay activation time (in seconds)
#define RELAY_ACTIVATION_TIME 3

// Global variable to track relay state
static volatile int relay_active = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void deactivate_relay();
void log_alarm();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sound_sensor_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set pull-up resistor on the sound sensor pin (optional, depending on sensor)
    // gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
void activate_relay() {
    if (!relay_active) {
        gpioWrite(RELAY_PIN, 1); // Activate relay
        relay_active = 1;
        printf("Relay activated\n");
    }
}

// Function to deactivate the relay
void deactivate_relay() {
    if (relay_active) {
        gpioWrite(RELAY_PIN, 0); // Deactivate relay
        relay_active = 0;
        printf("Relay deactivated\n");
    }
}

// Function to log the alarm event
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s - Alarm triggered\n", s);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate the relay
    deactivate_relay();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 0) { // Assuming LOW signal indicates sound
            activate_relay();
            log_alarm();
            gpioDelay(RELAY_ACTIVATION_TIME * 1000000); // Delay for 3 seconds
            deactivate_relay();
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

