    fprintf(fp, "%s - Alarm triggered\n", s);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate the relay
    deactivate_relay();

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 0) { // Assuming LOW signal indicates sound
            activate_relay();
            log_alarm();
            gpioDelay(RELAY_ACTIVATION_TIME * 1000000); // Delay for 3 seconds
            deactivate_relay();
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

