    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int addr);
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
float calculate_magnitude(gyro_data_t data);
void trigger_callback(float magnitude);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

