int init_i2c(int addr) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(gyro_data_t *data) {
    uint8_t buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading gyro data");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the magnitude of the angular velocity vector
float calculate_magnitude(gyro_data_t data) {
    float x = (float)data.x / 131.0; // Sensitivity scale factor
    float y = (float)data.y / 131.0;
    float z = (float)data.z / 131.0;
    return sqrt(x * x + y * y + z * z);
}

// Trigger callback function
void trigger_callback(float magnitude) {
    if (magnitude > 50.0) {
        printf("Angular velocity magnitude exceeded 50.0 degrees/second: %.2f\n", magnitude);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU-6050 (wake it up)
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }
    uint8_t pwr_mgmt_1 = 0x00;
    if (write(i2c_fd, &pwr_mgmt_1, 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    gyro_data_t gyro_data;
    timestamp_t timestamp;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Calculate the magnitude of the angular velocity vector
            float magnitude = calculate_magnitude(gyro_data);

            // Trigger callback if the magnitude exceeds the threshold
            trigger_callback(magnitude);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }

        // Delay for 100ms (10Hz sampling rate)
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 100000000; // 100ms
        nanosleep(&delay, NULL);
    }

    // Close I2C device
    close(i2c_fd);

    return 0;
}

