#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/mman.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_INTERVAL 5 // seconds
#define CO2_THRESHOLD 1000 // ppm
#define LOG_FILE "co2_log.json"
#define ERROR_LOG "co2_error.log"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int uart_fd = -1;
int i2c_fd = -1;
int spi_fd = -1;
FILE *log_fp = NULL;
FILE *error_fp = NULL;
volatile unsigned char *uart_buffer = NULL;
volatile unsigned char *i2c_buffer = NULL;
volatile unsigned char *spi_buffer = NULL;
volatile int uart_buffer_size = 0;
volatile int i2c_buffer_size = 0;
volatile int spi_buffer_size = 0;
volatile int uart_read_ready = 0;
volatile int i2c_read_ready = 0;
volatile int spi_read_ready = 0;
volatile int running = 1;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float ppm;
    int error;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, int baud_rate);
int init_i2c(int bus, int address);
int init_spi(int device, int mode, int bits, int speed);
int read_uart(int fd, unsigned char *buffer, int size);
int write_uart(int fd, const unsigned char *buffer, int size);
int read_i2c(int fd, unsigned char *buffer, int size);
int write_i2c(int fd, const unsigned char *buffer, int size);
int read_spi(int fd, unsigned char *buffer, int size);
int write_spi(int fd, const unsigned char *buffer, int size);
int read_sensor_data(int uart_fd, int i2c_fd, int spi_fd, float *ppm);
int log_data(FILE *fp, sensor_data_t data);
int log_error(FILE *fp, const char *message);
void signal_handler(int signal);
int setup_gpio();

// Helper function to convert microseconds to seconds
double microseconds_to_seconds(unsigned int microseconds) {
    return (double)microseconds / 1000000.0;
}

// Function to initialize UART
int init_uart(const char *device, int baud_rate) {
    uart_fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (uart_fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(uart_fd, &tty) != 0) {
        perror("Error getting UART attributes");
        close(uart_fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag = 0;
    tty.c_oflag = 0;
    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 5; // Timeout of 0.5 seconds

    if (tcsetattr(uart_fd, TCSANOW, &tty) != 0) {
        perror("Error setting UART attributes");
        close(uart_fd);
        return -1;
    }

    return uart_fd;
}

// Function to initialize I2C
int init_i2c(int bus, int address) {
    i2c_fd = open(SPI_DEVICE, O_RDWR);
    if (i2c_fd == -1) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return i2c_fd;
}

// Function to initialize SPI
int init_spi(int device, int mode, int bits, int speed) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("Error opening SPI device");
        return -1;
    }

    int mode_value = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    int bits_per_word = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    int speed_value = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_value) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from UART
int read_uart(int fd, unsigned char *buffer, int size) {
    int bytes_read = read(fd, buffer, size);
    if (bytes_read < 0) {
        perror("Error reading from UART");
        return -1;
    }
    return bytes_read;
}

// Function to write to UART
int write_uart(int fd, const unsigned char *buffer, int size) {
    int bytes_written = write(fd, buffer, size);
    if (bytes_written < 0) {
        perror("Error writing to UART");
        return -1;
    }
    return bytes_written;
}

// Function to read from I2C
int read_i2c(int fd, unsigned char *buffer, int size) {
    int bytes_read = read(fd, buffer, size);
    if (bytes_read < 0) {
        perror("Error reading from I2C");
        return -1;
    }
    return bytes_read;
}

// Function to write to I2C
int write_i2c(int fd, const unsigned char *buffer, int size) {
    int bytes_written = write(fd, buffer, size);
    if (bytes_written < 0) {
        perror("Error writing to I2C");
        return -1;
    }
    return bytes_written;
}

// Function to read from SPI
int read_spi(int fd, unsigned char *buffer, int size) {
    int bytes_read = read(fd, buffer, size);
    if (bytes_read < 0) {
        perror("Error reading from SPI");
        return -1;
    }
    return bytes_read;
}

// Function to write to SPI
int write_spi(int fd, const unsigned char *buffer, int size) {
    int bytes_written = write(fd, buffer, size);
    if (bytes_written < 0) {
        perror("Error writing to SPI");
        return -1;
    }
    return bytes_written;
}

// Function to read sensor data
int read_sensor_data(int uart_fd, int i2c_fd, int spi_fd, float *ppm) {
    unsigned char command[9] = {0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    unsigned char response[9];
    int i;

    // Send command sequence
    if (write_uart(uart_fd, command, sizeof(command)) != sizeof(command)) {
        log_error(error_fp, "Failed to send command to UART");
        return -1;
    }
    gpioDelay(10); // Small delay after sending command

    // Read response from UART
    if (read_uart(uart_fd, response, sizeof(response)) != sizeof(response)) {
        log_error(error_fp, "Failed to read response from UART");
        return -1;
    }

    // Read from I2C
    if (read_i2c(i2c_fd, i2c_buffer, sizeof(i2c_buffer)) != sizeof(i2c_buffer)) {
        log_error(error_fp, "Failed to read from I2C");
        return -1;
    }

    // Read from SPI
    if (read_spi(spi_fd, spi_buffer, sizeof(spi_buffer)) != sizeof(spi_buffer)) {
        log_error(error_fp, "Failed to read from SPI");
        return -1;
    }

    // Combine I2C and SPI data (assuming I2C is the primary source)
    unsigned char combined_data[9];
    for (i = 0; i < 3; i++) {
        combined_data[i] = i2c_buffer[i];
        combined_data[i + 3] = spi_buffer[i];
    }

    // Convert combined data to ppm (example conversion, adjust as needed)
    int raw_ppm = 0;
    for (i = 0; i < 3; i++) {
        raw_ppm = (raw_ppm << 8) | combined_data[i];
    }

    *ppm = (float)raw_ppm * 0.1; // Example scaling

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, sensor_data_t data) {
    if (fprintf(fp, "{\"timestamp\": %ld, \"ppm\": %.2f, \"error\": 0}\n", data.timestamp, data.ppm) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Function to log errors to file
int log_error(FILE *fp, const char *message) {
    if (fprintf(fp, "{\"timestamp\": %ld, \"error\": \"%s\", \"error_code\": -1}\n", time(NULL), message) < 0) {
        perror("Error writing to error log");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Setup GPIO using pigpio
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // No GPIO configuration needed for this example, pigpio handles it internally.
    gpioTerminate();
    return 0;
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (init_uart(UART_DEVICE, BAUD_RATE) == -1) {
        fprintf(stderr, "UART initialization failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c(I2C_BUS, I2C_ADDRESS) == -1) {
        fprintf(stderr, "I2C initialization failed\n");
        close(uart_fd);
        return 1;
    }

    // Initialize SPI
    if (init_spi(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED) == -1) {
        fprintf(stderr, "SPI initialization failed\n");
        close(uart_fd);
        close(i2c_fd);
        return 1;
    }

    // Allocate memory for buffers
    uart_buffer = (volatile unsigned char *)mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, uart_fd, 0);
    i2c_buffer = (volatile unsigned char *)mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, i2c_fd, 0);
    spi_buffer = (volatile unsigned char *)mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, spi_fd, 0);

    if (uart_buffer == MAP_FAILED || i2c_buffer == MAP_FAILED || spi_buffer == MAP_FAILED) {
        perror("Error mapping memory");
        close(uart_fd);
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    uart_buffer_size = 4096;
    i2c_buffer_size = 4096;
    spi_buffer_size = 4096;

    // Initialize log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        munmap(uart_buffer, uart_buffer_size);
        munmap(i2c_buffer, i2c_buffer_size);
        munmap(spi_buffer, spi_buffer_size);
        close(uart_fd);
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Initialize error log file
    error_fp = fopen(ERROR_LOG, "a");
    if (error_fp == NULL) {
        perror("Error opening error log file");
        fclose(log_fp);
        munmap(uart_buffer, uart_buffer_size);
        munmap(i2c_buffer, i2c_buffer_size);
        munmap(spi_buffer, spi_buffer_size);
        close(uart_fd);
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed\n");
        fclose(log_fp);
        fclose(error_fp);
        munmap(uart_buffer, uart_buffer_size);
        munmap(i2c_buffer, i2c_buffer_size);
        munmap(spi_buffer, spi_buffer_size);
        close(uart_fd);
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (running) {
        sensor_data_t data;
        data.timestamp = time(NULL);
        data.ppm = 0.0;
        data.error = 0;

        // Retry loop for sensor reading
        for (int retries = 0; retries < MAX_RETRIES; retries++) {
