    if (write_uart(uart_fd, command, sizeof(command)) != sizeof(command)) {
        log_error(error_fp, "Failed to send command to UART");
        return -1;
    }
    gpioDelay(10); // Small delay after sending command

    // Read response from UART
    if (read_uart(uart_fd, response, sizeof(response)) != sizeof(response)) {
        log_error(error_fp, "Failed to read response from UART");
        return -1;
    }

    // Read from I2C
    if (read_i2c(i2c_fd, i2c_buffer, sizeof(i2c_buffer)) != sizeof(i2c_buffer)) {
