#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Target heading
#define TARGET_HEADING 90.0

// Hard iron offsets
#define X_OFFSET 100
#define Y_OFFSET -50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Circular buffer structure
typedef struct {
    magnetometer_data_t data[BUFFER_SIZE];
    int head;
} circular_buffer_t;

// Function prototypes
int init_hmc5883l();
int read_magnetometer_data(magnetometer_data_t *data);
void apply_hard_iron_compensation(magnetometer_data_t *data);
void store_heading(circular_buffer_t *buffer, int heading);
int get_heading(circular_buffer_t *buffer);
void control_led(int deviation);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the HMC5883L magnetometer
int init_hmc5883l() {
    // Set configuration register A to 0x70 (8-average, 15 Hz, normal measurement)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B to 0xA0 (Gain = 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register to continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->z = (int16_t)((buffer[2] << 8) | buffer[3]);
    data->y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Apply hard iron compensation
void apply_hard_iron_compensation(magnetometer_data_t *data) {
    data->x -= X_OFFSET;
    data->y -= Y_OFFSET;
}

// Store heading in circular buffer
void store_heading(circular_buffer_t *buffer, int heading) {
    buffer->data[buffer->head] = (magnetometer_data_t){heading, 0, 0};
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
}

// Get heading from circular buffer
int get_heading(circular_buffer_t *buffer) {
    if (buffer->head == 0) {
        return 0; // Return 0 if the buffer is empty
    }
    return buffer->data[(buffer->head - 1 + BUFFER_SIZE) % BUFFER_SIZE].x;
}

// Control LED based on deviation from target heading
void control_led(int deviation) {
    if (deviation > 10) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize circular buffer
    circular_buffer_t heading_buffer;
    heading_buffer.head = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        magnetometer_data_t data;
        int heading;

        // Read magnetometer data
        if (read_magnetometer_data(&data) == 0) {
            // Apply hard iron compensation
            apply_hard_iron_compensation(&data);

            // Store heading in circular buffer
            heading = data.x; // Assuming X is the heading
            store_heading(&heading_buffer, heading);

            // Get heading from circular buffer
            heading = get_heading(&heading_buffer);

            // Calculate deviation from target heading
            int deviation = abs(heading - TARGET_HEADING);

            // Control LED
            control_led(deviation);

            // Print heading
            printf("Heading: %d degrees\n", heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

