#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RED 17
#define GPIO_GREEN 27
#define GPIO_BLUE 22
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_MED 150.0
#define LUX_THRESHOLD_HIGH 300.0
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
float read_lux();
void control_relays(float lux);
void log_data(float lux, int red_on, int green_on, int blue_on);
void signal_handler(int signal);
void cleanup();

// Structure to hold relay states
typedef struct {
    int red_on;
    int green_on;
    int blue_on;
} RelayStates;

RelayStates relay_states = {0, 0, 0};

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read lux value from BH1750
float read_lux() {
    char config[1] = {0x10}; // Continuous high resolution mode
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1.0;
    }
    gpioDelay(200); // Wait for measurement (at least 180ms)

    char buffer[2];
    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;
    return lux;
}

// Function to control relays based on lux value
void control_relays(float lux) {
    int red_on = 0, green_on = 0, blue_on = 0;

    if (lux < LUX_THRESHOLD_LOW) {
        gpioWrite(GPIO_RED, 1); // Turn on red relay
        red_on = 1;
    } else if (lux >= LUX_THRESHOLD_LOW && lux < LUX_THRESHOLD_MED) {
        // Green relay is on
    } else if (lux >= LUX_THRESHOLD_MED && lux < LUX_THRESHOLD_HIGH) {
        gpioWrite(GPIO_GREEN, 1); // Turn on green relay
        green_on = 1;
    } else if (lux >= LUX_THRESHOLD_HIGH && lux < LUX_THRESHOLD_HIGH + 100) {
        gpioWrite(GPIO_BLUE, 1); // Turn on blue relay
        blue_on = 1;
    } else if (lux >= LUX_THRESHOLD_HIGH + 100 && lux < LUX_THRESHOLD_HIGH + 200) {
        gpioWrite(GPIO_RED, 1); // Turn on red relay
        gpioWrite(GPIO_GREEN, 1); // Turn on green relay
        red_on = 1;
        green_on = 1;
    } else if (lux >= LUX_THRESHOLD_HIGH + 200 && lux < LUX_THRESHOLD_HIGH + 300) {
        gpioWrite(GPIO_RED, 1); // Turn on red relay
        gpioWrite(GPIO_GREEN, 1); // Turn on green relay
        gpioWrite(GPIO_BLUE, 1); // Turn on blue relay
        red_on = 1;
        green_on = 1;
        blue_on = 1;
    } else {
        // Turn off all relays
        gpioWrite(GPIO_RED, 0);
        gpioWrite(GPIO_GREEN, 0);
        gpioWrite(GPIO_BLUE, 0);
    }

    relay_states.red_on = red_on;
    relay_states.green_on = green_on;
    relay_states.blue_on = blue_on;
}

// Function to log data to file
void log_data(float lux, int red_on, int green_on, int blue_on) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %d, %d, %d\n", timestamp, lux, red_on, green_on, blue_on);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_RED, 0);
    gpioWrite(GPIO_GREEN, 0);
    gpioWrite(GPIO_BLUE, 0);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for relays
    gpioSetMode(GPIO_RED, PI_OUTPUT);
    gpioSetMode(GPIO_GREEN, PI_OUTPUT);
    gpioSetMode(GPIO_BLUE, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux = read_lux();
        if (lux >= 0) {
            control_relays(lux);
            log_data(lux, relay_states.red_on, relay_states.green_on, relay_states.blue_on);
        } else {
            fprintf(stderr, "Error reading lux value\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

