#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Ultrasonic sensor
#define TRIGGER_PIN 24
#define ECHO_PIN 25

// Distance threshold
#define DISTANCE_THRESHOLD 50.0

// PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void cleanup();
void set_motor_direction(int motor, int direction);
void set_motor_speed(int motor, int speed);
float read_distance();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping motors and cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to stop motors and terminate pigpio
void cleanup() {
    set_motor_speed(1, 0); // Stop Motor A
    set_motor_speed(2, 0); // Stop Motor B
    gpioTerminate();
}

// Function to set motor direction
void set_motor_direction(int motor, int direction) {
    if (motor == 1) {
        if (direction == 1) {
            gpioWrite(MOTOR_A_IN1, 1);
            gpioWrite(MOTOR_A_IN2, 0);
        } else if (direction == 0) {
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 1);
        } else {
            gpioWrite(MOTOR_A_IN1, 0);
            gpioWrite(MOTOR_A_IN2, 0);
        }
    } else if (motor == 2) {
        if (direction == 1) {
            gpioWrite(MOTOR_B_IN3, 1);
            gpioWrite(MOTOR_B_IN4, 0);
        } else if (direction == 0) {
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, 1);
        } else {
            gpioWrite(MOTOR_B_IN3, 0);
            gpioWrite(MOTOR_B_IN4, 0);
        }
    }
}

// Function to set motor speed using PWM
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        if (speed < 0) speed = 0;
        if (speed > 255) speed = 255;
        gpioPWM(MOTOR_A_IN2, speed);
    } else if (motor == 2) {
        if (speed < 0) speed = 0;
        if (speed > 255) speed = 255;
        gpioPWM(MOTOR_B_IN4, speed);
    }
}

// Function to read distance from ultrasonic sensor
float read_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0, end_tick = 0;

    // Wait for echo to go high (with timeout)
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1.0; // Indicate error
    }

    start_tick = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: Echo signal not received (timeout)\n");
        return -1.0; // Indicate error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    float distance = (float)diff / 2.0 / 29.1; // cm

    return distance;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <distance_cm>\n", argv[0]);
        return 1;
    }

    float distance = atof(argv[1]);

    if (distance < 10.0 || distance > 100.0) {
        fprintf(stderr, "Error: Distance must be between 10 and 100 cm\n");
        return 1;
    }

    if (distance < DISTANCE_THRESHOLD) {
        set_motor_direction(1, 1); // Motor A forward
        set_motor_speed(1, (int)(distance / DISTANCE_THRESHOLD * 255.0)); // Proportional speed
        set_motor_direction(2, 1); // Motor B forward
        set_motor_speed(2, (int)(distance / DISTANCE_THRESHOLD * 255.0)); // Proportional speed
    } else {
        set_motor_direction(1, 0); // Motor A backward
        set_motor_speed(1, 0); // Stop Motor A
        set_motor_direction(2, 0); // Motor B backward
        set_motor_speed(2, 0); // Stop Motor B
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR_A_IN2, 255);
    gpioSetPWMrange(MOTOR_B_IN4, 255);

    // Set initial motor speed to 0
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance: %.2f cm, Speed: %.2f\n", distance, (distance / DISTANCE_THRESHOLD * 100.0));

    // Main loop
    while (program_running) {
        float current_distance = read_distance();
        if (current_distance < 0) {
            fprintf(stderr, "Error reading distance, using previous value\n");
        } else {
            if (current_distance < DISTANCE_THRESHOLD) {
                set_motor_direction(1, 1);
                set_motor_speed(1, (int)(current_distance / DISTANCE_THRESHOLD * 255.0));
                set_motor_direction(2, 1);
                set_motor_speed(2, (int)(current_distance / DISTANCE_THRESHOLD * 255.0));
            } else {
                set_motor_direction(1, 0);
                set_motor_speed(1, 0);
                set_motor_direction(2, 0);
                set_motor_speed(2, 0);
            }
        }
        gpioDelay(100); // 100ms delay
    }

    return 0;
}

