#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68
#define SERVO_GPIO 18
#define PWM_PERIOD 1000000 // 1ms
#define SERVO_MIN_PULSE_WIDTH 1000 // us
#define SERVO_MAX_PULSE_WIDTH 2000 // us
#define SERVO_RANGE 180.0 // degrees
#define LOG_FILE "solar_tracker.log"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
int set_servo_angle(float angle);
int log_data(float pitch, float roll, float position);
void signal_handler(int sig);

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read MPU6050 data
int read_mpu6050(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    if (read(i2c_fd, buf, 14) != 14) {
        perror("Error reading MPU6050 data");
        return -1;
    }

    *accel_x = (buf[0] << 8) | buf[1];
    *accel_y = (buf[2] << 8) | buf[3];
    *accel_z = (buf[4] << 8) | buf[5];
    *gyro_x = (buf[8] << 8) | buf[9];
    *gyro_y = (buf[10] << 8) | buf[11];
    *gyro_z = (buf[12] << 8) | buf[13];

    return 0;
}

// Calculate pitch and roll
float calculate_pitch_roll(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    float pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    float roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
    return pitch; // Return only pitch for simplicity
}

// Set servo angle
int set_servo_angle(float angle) {
    int pulse_width = (int)(SERVO_MIN_PULSE_WIDTH + (angle / SERVO_RANGE) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    char path[50];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0/pwm_range");
    if (write(i2c_fd, path, strlen(path)) != strlen(path)) {
        perror("Error writing to PWM range file");
        return -1;
    }
    if (write(i2c_fd, &pulse_width, sizeof(pulse_width)) != sizeof(pulse_width)) {
        perror("Error writing to PWM range file");
        return -1;
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip2/pwm0/pwm_duty_cycle");
    if (write(i2c_fd, &pulse_width, sizeof(pulse_width)) != sizeof(pulse_width)) {
        perror("Error writing to PWM duty cycle file");
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(float pitch, float roll, float position) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll, position;

    // Main loop
    while (!terminate) {
        // Read MPU6050 data
        if (read_mpu6050(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch_roll(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Set servo angle
            if (set_servo_angle(pitch) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }

            // Get position (simulated)
            position = 100.0 + 50.0 * sin(2.0 * M_PI * pitch / 180.0); // Example: Position changes with pitch

            // Log data
            log_data(pitch, roll, position);
        } else {
            fprintf(stderr, "Failed to read MPU6050 data\n");
        }

        sleep(1); // Delay for 1 second
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

