        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll, position;

    // Main loop
    while (!terminate) {
        // Read MPU6050 data
        if (read_mpu6050(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate pitch and roll
            pitch = calculate_pitch_roll(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Set servo angle
            if (set_servo_angle(pitch) != 0) {
                fprintf(stderr, "Failed to set servo angle\n");
            }

            // Get position (simulated)
            position = 100.0 + 50.0 * sin(2.0 * M_PI * pitch / 180.0); // Example: Position changes with pitch

