#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Global variables
FILE *schedule_file;
int running = 1;

// Structure to hold the current state of the relays
typedef struct {
    int relay1_state;
    int relay2_state;
    int relay3_state;
    int relay4_state;
} RelayState;

RelayState current_state = {0, 0, 0, 0};

// Function prototypes
int load_schedule(const char *filename);
void fade_lamp(int relay_number, int duration_seconds);
void turn_lamp_on(int relay_number);
void turn_lamp_off(int relay_number);
void signal_handler(int signal);
void cleanup();

// Function to load the schedule from the file
int load_schedule(const char *filename) {
    int schedule_duration = FADE_DURATION; // Default duration
    int relay_number = -1;
    char line[256];
    int relay_index = -1;

    schedule_file = fopen(filename, "r");
    if (schedule_file == NULL) {
        fprintf(stderr, "Error: Could not open schedule file %s\n", filename);
        return -1;
    }

    // Read the first line to determine the schedule duration
    if (fgets(line, sizeof(line), schedule_file) == NULL) {
        fprintf(stderr, "Error: Could not read schedule duration from file\n");
        fclose(schedule_file);
        return -1;
    }

    if (sscanf(line, "%d", &schedule_duration) != 1) {
        fprintf(stderr, "Error: Could not parse schedule duration from file\n");
        fclose(schedule_file);
        return -1;
    }

    // Read the schedule entries
    while (fgets(line, sizeof(line), schedule_file) != NULL) {
        if (sscanf(line, "%[^,]:%d:%d:%d,%d,%d",
                   &relay_index, &relay_number, &relay_state, &relay_duration) == 5) {
            if (relay_index != -1 && relay_number != -1) {
                if (relay_state == 0 || relay_state == 1) {
                    if (relay_number == -1) {
                        relay_number = relay_index;
                    } else if (relay_index != -1) {
                        relay_index = -1; // Reset index if multiple relays are present
                    }
                } else {
                    fprintf(stderr, "Error: Invalid relay state in schedule file\n");
                    fclose(schedule_file);
                    return -1;
                }
            } else {
                fprintf(stderr, "Error: Invalid schedule entry in file\n");
                fclose(schedule_file);
                return -1;
            }
        } else {
            fprintf(stderr, "Error: Could not parse schedule entry from file\n");
            fclose(schedule_file);
            return -1;
        }
    }

    fclose(schedule_file);

    if (relay_number == -1 && relay_index == -1) {
        fprintf(stderr, "Error: No valid schedule entries found in file\n");
        return -1;
    }

    return 0;
}

