void fade_lamp(int relay_number, int duration_seconds) {
    time_t start_time = time(NULL);
    int current_time;
    int duty_cycle;

    while (time(NULL) - start_time < duration_seconds) {
        current_time = time(NULL);
        duty_cycle = (int)(((float)(current_time - start_time) / duration_seconds) * 100.0);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 100) duty_cycle = 100;

        gpioPWM(RELAY1_PIN, duty_cycle); // Assuming relay1_pin is the GPIO pin for the relay
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay to achieve the desired PWM frequency
    }

    turn_lamp_off(relay_number);
}

