void turn_lamp_on(int relay_number) {
    if (relay_number == -1) {
        fprintf(stderr, "Error: Invalid relay number for turn_lamp_on\n");
        return;
    }

    if (gpioWrite(RELAY1_PIN, 1) != 0) {
        fprintf(stderr, "Error: Could not turn lamp %d on\n", relay_number);
        return;
    }
    current_state.relay1_state = 1;
    current_state.relay2_state = 0;
    current_state.relay3_state = 0;
    current_state.relay4_state = 0;
}

// Function to turn a lamp off
void turn_lamp_off(int relay_number) {
    if (relay_number == -1) {
        fprintf(stderr, "Error: Invalid relay number for turn_lamp_off\n");
        return;
    }

    if (gpioWrite(RELAY1_PIN, 0) != 0) {
        fprintf(stderr, "Error: Could not turn lamp %d off\n", relay_number);
        return;
    }
    current_state.relay1_state = 0;
    current_state.relay2_state = 0;
    current_state.relay3_state = 0;
    current_state.relay4_state = 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        running = 0;
    }
}

// Cleanup function to turn off all relays and release GPIO resources
void cleanup() {
    printf("Cleaning up and exiting...\n");
    turn_lamp_off(RELAY1_PIN);
    turn_lamp_off(RELAY2_PIN);
    turn_lamp_off(RELAY3_PIN);
    turn_lamp_off(RELAY4_PIN);

    gpioTerminate();
}

