    // Load the schedule
    if (load_schedule("lighting_schedule.txt") != 0) {
        fprintf(stderr, "Error: Could not load schedule\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Check for schedule updates every second
        time_t now = time(NULL);
        if (now % 1 == 0) {
            if (load_schedule("lighting_schedule.txt") != 0) {
                fprintf(stderr, "Error: Could not reload schedule\n");
            }
        }

        // Check if it's time to fade any lamps
        for (int i = 0; i < 4; i++) {
            if (current_state.relay1_state == 0 && current_state.relay1_state != -1) {
