            if (current_state.relay4_state == 0 && current_state.relay4_state != -1) {
                fade_lamp(i + 3, FADE_DURATION);
            }
        }

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

