#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0    // cm
#define MIN_TIME 0.01          // seconds
#define MAX_TIME 0.10         // seconds
#define MIN_PULSE_WIDTH 10000  // nanoseconds
#define MAX_PULSE_WIDTH 50000 // nanoseconds
#define MIN_DISTANCE_CHANGE 1.0 // cm
#define MAX_DISTANCE_CHANGE 50.0 // cm
#define MIN_FREQUENCY_CHANGE 100.0 // Hz
#define MAX_FREQUENCY_CHANGE 500.0 // Hz
#define MIN_TIME_CHANGE 0.001 // seconds
#define MAX_TIME_CHANGE 0.010 // seconds
#define MIN_DISTANCE_THRESHOLD 10.0 // cm
#define MAX_DISTANCE_THRESHOLD 50.0 // cm
#define MIN_FREQUENCY_THRESHOLD 200.0 // Hz
#define MAX_FREQUENCY_THRESHOLD 1000.0 // Hz
#define MIN_TIME_THRESHOLD 0.06 // seconds
#define MAX_TIME_THRESHOLD 0.10 // seconds

// Global variables
static volatile int running = 1;
static volatile unsigned int start_time = 0;
static volatile unsigned int end_time = 0;
static volatile int echo_received = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
double calculate_frequency(double distance);
void set_buzzer_frequency(double frequency);
void log_error(const char *message);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set trigger pin low initially
    gpioWrite(TRIGGER_PIN, 0);

    // Set up callback for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(MIN_PULSE_WIDTH); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick, void *user_data) {
    if (level == 1) {
        echo_received = 1;
        start_time = tick;
    } else if (level == 0 && echo_received) {
        end_time = tick;
        echo_received = 0;
    }
}

// Calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        log_error("Invalid pulse width");
        return -1.0; // Indicate error
    }

    double time_taken = (double)(end_time - start_time) / 1000000.0; // in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    // Clamp distance to valid range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    return distance;
}

// Calculate frequency from distance
double calculate_frequency(double distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        log_error("Invalid distance");
        return -1.0; // Indicate error
    }

    // Linear mapping
    double frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);

    // Clamp frequency to valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    return frequency;
}

// Set buzzer frequency using PWM
void set_buzzer_frequency(double frequency) {
    if (frequency < MIN_FREQUENCY || frequency > MAX_FREQUENCY) {
        log_error("Invalid frequency");
        return;
    }

    int duty_cycle = 0;
    if (frequency > 0) {
        duty_cycle = (int)(((double)1000000.0 / frequency) * 255.0); // Calculate duty cycle (0-255)
    }

    gpioPWM(BUZZER_PIN, duty_cycle);
}

// Log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Cleanup GPIO resources
void cleanup() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        // Trigger sensor
        trigger_sensor();

        // Calculate distance
        unsigned int pulse_width = 0;
        if (echo_received) {
            pulse_width = end_time - start_time;
        } else {
            log_error("No echo received");
            pulse_width = 0; // Or some default value
        }

        double distance = calculate_distance(pulse_width);

        if (distance < 0) {
            log_error("Distance calculation failed");
            continue; // Skip to the next iteration
        }

        // Calculate frequency
        double frequency = calculate_frequency(distance);

        if (frequency < 0) {
            log_error("Frequency calculation failed");
            continue; // Skip to the next iteration
        }

        // Set buzzer frequency
        set_buzzer_frequency(frequency);

        // Check for significant changes in distance or frequency
        if (distance > MAX_DISTANCE_THRESHOLD || distance < MIN_DISTANCE_THRESHOLD) {
            log_error("Significant distance change detected");
        }

        // Check for significant changes in frequency
        if (frequency > MAX_FREQUENCY_THRESHOLD || frequency < MIN_FREQUENCY_THRESHOLD) {
            log_error("Significant frequency change detected");
        }

        // Wait for 60ms
