#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED (common anode)
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the pigpio library and set up GPIO pins
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency to 1 kHz
    if (gpioSetPWMfrequency(RED_PIN, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", RED_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", GREEN_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, 1000) != 0) {
        fprintf(stderr, "Failed to set PWM frequency for GPIO%d\n", BLUE_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to generate a smooth color transition using a sine wave
void generate_color_transition(float time, float *red, float *green, float *blue) {
    // Calculate the sine wave value
    float sine_value = 0.5 * (1.0 + sin(2.0 * M_PI * time));

    // Map the sine wave value to the RGB color space
    *red   = sine_value;
    *green = (1.0 - sine_value) * 0.5; // Green is the complement of red
    *blue  = (1.0 - sine_value) * 0.5; // Blue is the complement of red

    // Clamp the values to the range [0.0, 1.0]
    if (*red   > 1.0)   *red   = 1.0;
    if (*green > 1.0)   *green = 1.0;
    if (*blue  > 1.0)   *blue  = 1.0;
    if (*red   < 0.0)   *red   = 0.0;
    if (*green < 0.0)   *green = 0.0;
    if (*blue  < 0.0)   *blue  = 0.0;
}

// Function to set the RGB LED color using PWM
void set_led_color(float red, float green, float blue) {
    // Common anode, so invert the PWM duty cycle
    int red_pwm = (int)(1.0 - red);
    int green_pwm = (int)(1.0 - green);
    int blue_pwm = (int)(1.0 - blue);

    // Set PWM duty cycles for each color
    gpioPWM(RED_PIN, red_pwm);
    gpioPWM(GREEN_PIN, green_pwm);
    gpioPWM(BLUE_PIN, blue_pwm);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting\n");
        return 1;
    }

    float time = 0.0;
    float red, green, blue;

    // Main loop
    while (program_running) {
        // Generate color transition
        generate_color_transition(time, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Increment time
        time += 0.01; // Simulate a time increment (10ms)
        if (time > 1.0) {
            time = 0.0;
        }

        // Delay to control the speed of the color transition
        usleep(10000); // 10ms
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

