#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Scaling factor for gyroscope data (LSB/deg/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050(int i2c_fd) {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(int i2c_fd, gyro_data_t *data) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    if (i2cReadI2CBlockData(i2c_fd, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data: %s\n", strerror(errno));
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert raw data to degrees per second
    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Function to log gyroscope data to a file
int log_gyro_data(FILE *log_file, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Write data to file
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(1, MPU6050_ADDR, 0); // Bus 1, address 0x68, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) < 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gyro_data_t gyro_data;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_data) == 0) {
            // Log gyroscope data
            log_gyro_data(log_file, gyro_data);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
        }

        // Sleep for 100 milliseconds
        usleep(100000); // 100 ms
    }

    // Close I2C device and log file
    i2cClose(i2c_fd);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated gracefully.\n");
    return 0;
}

