#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/file.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define DEFAULT_TIMEOUT 1000

// Structure to hold the last five events
typedef struct {
    time_t timestamp[5];
    int value[5];
    int index;
} EventWindow;

EventWindow event_window = {{0}, {0}, 0};

volatile sig_atomic_t program_running = 1;

void signal_handler(int sig) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(const char *event_type) {
    int fd = open(LOG_FILE, O_WRONLY | O_APPEND | O_CREAT, 0644);
    if (fd == -1) {
        perror("Failed to open log file");
        return -1;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Failed to get file status");
        close(fd);
        return -1;
    }

    // Acquire an exclusive lock on the file
    if (flock(fd, LOCK_EX) == -1) {
        perror("Failed to acquire file lock");
        close(fd);
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        flock(fd, LOCK_UN);
        close(fd);
        return -1;
    }

    char log_entry[200];
    snprintf(log_entry, sizeof(log_entry), "%s: %s\n", timestamp, event_type);

    if (write(fd, log_entry, strlen(log_entry)) == -1) {
        perror("Failed to write to log file");
        flock(fd, LOCK_UN);
        close(fd);
        free(timestamp);
        return -1;
    }

    flock(fd, LOCK_UN);
    close(fd);
    free(timestamp);

    return 0;
}

// Function to add an event to the sliding window
void add_event(int value) {
    time_t now = time(NULL);
    event_window.timestamp[event_window.index] = now;
    event_window.value[event_window.index] = value;
    event_window.index = (event_window.index + 1) % 5;
}

// Function to check if the last five events indicate an earthquake
int is_earthquake_imminent() {
    int count = 0;
    for (int i = 0; i < 5; i++) {
        if (event_window.value[i] == 1) {
            count++;
        }
    }
    return (count >= 3);
}

// Function to print an earthquake alert message
void print_earthquake_alert() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        return;
    }

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
    free(timestamp);
}

// Function to read the GPIO pin with edge detection
int read_gpio_with_edge_detection(int gpio, int timeout_ms) {
    int level = gpioRead(gpio);
    gpioDelay(timeout_ms * 1000); // Convert ms to microseconds
    return level;
}

int main(int argc, char *argv[]) {
    int timeout_ms = DEFAULT_TIMEOUT;

    // Parse command-line arguments
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: %d ms\n", DEFAULT_TIMEOUT);
            timeout_ms = DEFAULT_TIMEOUT;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as an input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int rising_edge = read_gpio_with_edge_detection(GPIO_PIN, timeout_ms);
        int falling_edge = read_gpio_with_edge_detection(GPIO_PIN, timeout_ms);
        int current_value = read_gpio_with_edge_detection(GPIO_PIN, timeout_ms);

        if (rising_edge == 1) {
            add_event(1);
        }
        if (falling_edge == 1) {
            add_event(0);
        }
        if (current_value == 1) {
            add_event(1);
        }
        if (current_value == 0) {
            add_event(0);
        }

        if (is_earthquake_imminent()) {
            print_earthquake_alert();
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup
    gpioTerminate();

    return 0;
}

