#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_M 0x20
#define CTRL_REG4_M 0x23
#define OUT_X_L_M 0x28
#define OUT_X_H_M 0x29
#define OUT_Y_L_M 0x2A
#define OUT_Y_H_M 0x2B
#define OUT_Z_L_M 0x2C
#define OUT_Z_H_M 0x2D

// Calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// Compass directions
const char *compass_directions[8] = {
    "N", "NE", "E", "SE", "S", "SW", "W", "NW"
};

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
int init_magnetometer();
int read_magnetometer_data(magnetometer_data_t *data);
void calibrate_magnetometer(magnetometer_data_t *data);
float calculate_heading(magnetometer_data_t data);
void log_data(magnetometer_data_t data, float heading);
void print_compass_direction(float heading);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(1, LSM303_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer() {
    // Set to continuous measurement mode, 50 Hz output rate
    if (i2cWriteByteData(i2c_fd, CTRL_REG1_M, 0x70) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_M\n");
        return -1;
    }

    // Set gain to +/- 1.3 Ga
    if (i2cWriteByteData(i2c_fd, CTRL_REG4_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_M\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(magnetometer_data_t *data) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_fd, OUT_X_L_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_magnetometer(magnetometer_data_t *data) {
    data->x -= X_OFFSET;
    data->y -= Y_OFFSET;
    data->z -= Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(magnetometer_data_t data) {
    float heading = atan2(data.y, data.x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to CSV file
void log_data(magnetometer_data_t data, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.2f\n", timestamp, data.x, data.y, data.z, heading);
    fflush(log_file); // Ensure data is written to file immediately
}

// Print compass direction
void print_compass_direction(float heading) {
    int direction = (int)(heading / 45.0);
    if (direction < 0) direction = 0;
    if (direction > 7) direction = 7;

    printf("Heading: %.2f degrees - Compass direction: %s\n", heading, compass_directions[direction]);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() != 0) {
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("mag_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    magnetometer_data_t data;
    float heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer_data(&data) == 0) {
            // Calibrate the data
            calibrate_magnetometer(&data);

            // Calculate the heading
            heading = calculate_heading(data);

            // Log the data
            log_data(data, heading);

            // Print the compass direction
            print_compass_direction(heading);
        } else {
            fprintf(stderr, "Error reading magnetometer data, skipping sample.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

