#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static volatile int running = 1;

// Function prototypes
void touch_callback(int gpio, int level, unsigned int tick, void *user);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_event(const char *relay_state);

// Structure to hold program state
typedef struct {
    int touch_sensor_pin;
    int relay_pin;
    int debounce_time;
    int *last_touch_time;
    int *relay_state;
    int running;
} ProgramState;

ProgramState state = {TOUCH_SENSOR_PIN, RELAY_PIN, DEBOUNCE_TIME, (int *)malloc(sizeof(unsigned long)), (int *)malloc(sizeof(int)), 1};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(state.touch_sensor_pin, PI_INPUT);
    gpioSetPullUpDown(state.touch_sensor_pin, PI_PUD_DOWN);
    gpioSetMode(state.relay_pin, PI_OUTPUT);
    gpioWrite(state.relay_pin, 0); // Initialize relay to OFF

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(state.relay_pin, 0); // Ensure relay is OFF
    gpioTerminate();
}

// Function to log events to a JSON file
void log_event(const char *relay_state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(buf));
    json_object_set_new(root, "relay_state", json_string(relay_state));

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(5));
    if (json_str) {
        FILE *fp = fopen("relay_log.json", "a");
        if (fp) {
            fprintf(fp, "%s\n", json_str);
            fclose(fp);
        } else {
            fprintf(stderr, "Error opening relay_log.json for writing\n");
        }
        free(json_str);
    } else {
        fprintf(stderr, "Error creating JSON object\n");
    }
    json_decref(root);
}

// Interrupt service routine for touch sensor
void touch_callback(int gpio, int level, unsigned int tick, void *user) {
    unsigned long current_time = gpioTick();

    // Debounce logic
    if (current_time - state.last_touch_time > state.debounce_time * 1000) {
        if (level == 1) { // Rising edge (touch detected)
            relay_state = !relay_state;
            gpioWrite(state.relay_pin, relay_state);
            log_event(relay_state ? "ON" : "OFF");
            state.last_touch_time = current_time;
        }
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Shutting down gracefully...\n");
        running = 0;
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up interrupt on touch sensor pin
    if (gpioSetISRFuncEx(state.touch_sensor_pin, RISING_EDGE, 0, touch_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        cleanup_gpio();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    printf("Cleaning up and exiting...\n");
    cleanup_gpio();
    return 0;
}

