#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable to store the seed for the random number generator
static unsigned long seed = 0;

// Function prototypes
int initialize_gpio();
int read_soil_moisture();
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Release GPIO lines
    gpioTerminate();

    // Close the log file
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set initial state of all relays to inactive (high)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to read the simulated soil moisture value
int read_soil_moisture() {
    // Seed the random number generator with the current time
    unsigned long current_time = time(NULL);
    seed = current_time;
    srand(seed);

    // Generate a random number between 0 and 100
    return rand() % 101;
}

// Function to activate a relay
void activate_relay(int relay_number) {
    int pin;
    if (relay_number == 1) {
        pin = RELAY1_PIN;
    } else if (relay_number == 2) {
        pin = RELAY2_PIN;
    } else if (relay_number == 3) {
        pin = RELAY3_PIN;
    } else {
        pin = RELAY4_PIN;
    }

    gpioWrite(pin, 0); // Set the pin to active low (0)
    gpioDelay(5000);   // Wait for 5 seconds
    deactivate_relay(relay_number);
}

// Function to deactivate a relay
void deactivate_relay(int relay_number) {
    int pin;
    if (relay_number == 1) {
        pin = RELAY1_PIN;
    } else if (relay_number == 2) {
        pin = RELAY2_PIN;
    } else if (relay_number == 3) {
        pin = RELAY3_PIN;
    } else {
        pin = RELAY4_PIN;
    }

    gpioWrite(pin, 1); // Set the pin to inactive high (1)
}

// Function to log an event to the log file
void log_event(int relay_number, int moisture_level) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fclose(log_file);
}

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and set GPIO modes
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the simulated soil moisture value
        int moisture_level = read_soil_moisture();

        // Check if the moisture level is below the threshold
        if (moisture_level < 30) {
            printf("Soil moisture level: %d\n", moisture_level);

            // Activate the relays sequentially
            activate_relay(1);
            activate_relay(2);
            activate_relay(3);
            activate_relay(4);

            // Log the event
            log_event(1, moisture_level);
            log_event(2, moisture_level);
            log_event(3, moisture_level);
            log_event(4, moisture_level);
        }

        // Wait for 10 seconds
        gpioDelay(10000); // 10000 milliseconds = 10 seconds
    }

    return 0;
}

