#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for L293D IN1-IN4 coil inputs
#define IN1 4
#define IN2 17
#define IN3 27
#define IN4 22

// Define GPIO pins for LOCK button
#define LOCK_BUTTON 24

// Define GPIO pins for UNLOCK button
#define UNLOCK_BUTTON 23

// Define delay between steps (in milliseconds)
#define STEP_DELAY 3

// Define number of steps for LOCK and UNLOCK
#define LOCK_STEPS 512
#define UNLOCK_STEPS 512

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int step_motor(int direction);
int debounce_button(int gpio);
void lock_door();
void unlock_door();
void signal_handler(int signal);

// Function to step the motor one step
int step_motor(int direction) {
    int coil_states[4] = {0, 0, 0, 0};

    if (direction == 1) { // Clockwise
        coil_states[0] = 1;
        coil_states[1] = 0;
        coil_states[2] = 0;
        coil_states[3] = 0;
    } else { // Counter-clockwise
        coil_states[0] = 0;
        coil_states[1] = 0;
        coil_states[2] = 1;
        coil_states[3] = 0;
    }

    gpioWrite(IN1, coil_states[0]);
    gpioWrite(IN2, coil_states[1]);
    gpioWrite(IN3, coil_states[2]);
    gpioWrite(IN4, coil_states[3]);

    gpioDelay(STEP_DELAY);

    return 0;
}

// Function to debounce the button
int debounce_button(int gpio) {
    int i, value;
    int debounced_value = 0;

    for (i = 0; i < 5; i++) {
        value = gpioRead(gpio);
        if (value == 0) { // Assuming active low
            debounced_value = 1;
            break;
        }
        gpioDelay(1); // Small delay for debouncing
    }

    return debounced_value;
}

// Function to lock the door
void lock_door() {
    printf("Locking door...\n");
    for (int i = 0; i < LOCK_STEPS; i++) {
        step_motor(1); // Clockwise
    }
    printf("Door locked.\n");
}

// Function to unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    for (int i = 0; i < UNLOCK_STEPS; i++) {
        step_motor(0); // Counter-clockwise
    }
    printf("Door unlocked.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(IN1, PI_OUTPUT);
    gpioSetMode(IN2, PI_OUTPUT);
    gpioSetMode(IN3, PI_OUTPUT);
    gpioSetMode(IN4, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Door control program started. Press LOCK button (active low) or UNLOCK button (active low).\n");

    // Main loop
    while (program_running) {
        // Check for LOCK button press
        if (debounce_button(LOCK_BUTTON)) {
            lock_door();
        }

        // Check for UNLOCK button press
        if (debounce_button(UNLOCK_BUTTON)) {
            unlock_door();
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Clean up and exit
    gpioWrite(IN1, 0);
    gpioWrite(IN2, 0);
    gpioWrite(IN3, 0);
    gpioWrite(IN4, 0);
    gpioTerminate();
    return 0;
}

