#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define TIMEOUT_US 50000 // 50ms
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to measure distance in centimeters
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high with timeout
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        gpioDelay(1); // Check every 1 us
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not received (high)\n");
        return -1.0;
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        gpioDelay(1);
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal not received (low)\n");
        return -1.0;
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters (speed of sound: 343 m/s)
    // distance = (time * speed_of_sound) / 2
    // distance = (diff * 0.000001) / 2
    float distance = (float)diff * 0.0343 / 2.0;

    return distance;
}

// Function to log distance to file
void log_distance(float distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", s, distance);
    fclose(fp);
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = measure_distance();

        if (distance >= 0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Error: Distance measurement failed\n");
            log_distance(-1.0); // Log -1 to indicate error
        }

        gpioDelay(1000); // Wait 1 second
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

