    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buf[0] << 8) | buf[1]);
    *gyro_y = (int16_t)((buf[2] << 8) | buf[3]);
    *gyro_z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Function to convert raw gyro data to degrees per second
void convert_gyro_data(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *x, float *y, float *z)
{
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    float gyro_x, gyro_y, gyro_z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&raw_gyro_x, &raw_gyro_y, &raw_gyro_z) == 0) {
            // Convert raw data to degrees per second
            convert_gyro_data(raw_gyro_x, raw_gyro_y, raw_gyro_z, &gyro_x, &gyro_y, &gyro_z);

            // Print gyroscope data
            printf("Gyro X: %.2f deg/s, Gyro Y: %.2f deg/s, Gyro Z: %.2f deg/s\n", gyro_x, gyro_y, gyro_z);
        } else {
            fprintf(stderr, "Error: Failed to read gyro data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C device and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

