    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set all GPIO pins HIGH initially (inactive)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to activate a relay for a specified duration
void activate_relay(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 0); // Set the GPIO pin LOW (active)
    gpioDelay(duration_ms * 1000); // Delay for the specified duration (in microseconds)
    gpioWrite(gpio_pin, 1); // Set the GPIO pin HIGH (inactive)
}

// Function to log the start time of a watering cycle to a file
