    if (log_start_time(LOG_FILE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop to simulate the watering cycle
    while (program_running) {
        watering_cycle(RELAY1_PIN);
        watering_cycle(RELAY2_PIN);
        watering_cycle(RELAY3_PIN);
        watering_cycle(RELAY4_PIN);

        // Wait for 86400 seconds (24 hours)
        gpioDelay(86400 * 1000000); // Delay for 24 hours (in microseconds)
    }

