        fclose(fp);
    } else {
        fprintf(stderr, "Error opening log file for end time logging\n");
    }

    // Release all GPIO lines, close the chip, and exit
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

