#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 255

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800

// Define log file name
#define LOG_FILE "smart_lighting.log"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int initialize_pwm(int pin, int frequency, int range);
int set_pwm_duty_cycle(int pin, int duty_cycle);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold relay states
typedef struct {
    int relay1_state;
    int relay2_state;
    int relay3_state;
    int relay4_state;
} RelayStates;

RelayStates relay_states = {0, 0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize PWM on a GPIO pin
int initialize_pwm(int pin, int frequency, int range) {
    int result = gpioSetPWMfrequency(pin, frequency);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM frequency on pin %d: %d\n", pin, result);
        return 1;
    }

    result = gpioSetPWMrange(pin, range);
    if (result != 0) {
        fprintf(stderr, "Failed to set PWM range on pin %d: %d\n", pin, result);
        return 1;
    }

    return 0;
}

// Function to set the PWM duty cycle on a GPIO pin
int set_pwm_duty_cycle(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > range) {
        fprintf(stderr, "Invalid duty cycle: %d. Must be between 0 and %d\n", duty_cycle, range);
        return 1;
    }

    gpioPWM(pin, duty_cycle);
    return 0;
}

// Function to log an event with a timestamp
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed. Exiting.");
        cleanup();
        return 1;
    }

    // Initialize PWM on each relay pin
    if (initialize_pwm(RELAY1_PIN, PWM_FREQUENCY, PWM_RANGE) != 0 ||
        initialize_pwm(RELAY2_PIN, PWM_FREQUENCY, PWM_RANGE) != 0 ||
        initialize_pwm(RELAY3_PIN, PWM_FREQUENCY, PWM_RANGE) != 0 ||
        initialize_pwm(RELAY4_PIN, PWM_FREQUENCY, PWM_RANGE) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    int current_duty_cycle = 0;
    int increment = 0;
    time_t start_time = time(NULL);

    while (running && (time(NULL) - start_time < SUNRISE_DURATION)) {
        // Update relay states
        relay_states.relay1_state = set_pwm_duty_cycle(RELAY1_PIN, current_duty_cycle);
        relay_states.relay2_state = set_pwm_duty_cycle(RELAY2_PIN, current_duty_cycle);
        relay_states.relay3_state = set_pwm_duty_cycle(RELAY3_PIN, current_duty_cycle);
        relay_states.relay4_state = set_pwm_duty_cycle(RELAY4_PIN, current_duty_cycle);

        // Log the current state
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Relay 1: %d, Relay 2: %d, Relay 3: %d, Relay 4: %d",
                 relay_states.relay1_state, relay_states.relay2_state, relay_states.relay3_state, relay_states.relay4_state);
        log_event(log_message);

        // Increment the duty cycle
        current_duty_cycle += increment;
        if (current_duty_cycle >= PWM_RANGE) {
            current_duty_cycle = 0;
            increment = 1;
        } else {
            increment = 1;
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function in milliseconds
    }

    // Finalize PWM and cleanup
    set_pwm_duty_cycle(RELAY1_PIN, 0);
    set_pwm_duty_cycle(RELAY2_PIN, 0);
    set_pwm_duty_cycle(RELAY3_PIN, 0);
    set_pwm_duty_cycle(RELAY4_PIN, 0);

    cleanup();

    return 0;
}

