#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// LED GPIO pin
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Sampling period (in milliseconds)
#define SAMPLE_PERIOD 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
int check_threshold(const circular_buffer_t *buffer);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // I2C bus 1, address 0x68, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
