#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CS_GPIO 8 // BCM GPIO 8
#define GYRO_X_REG 0x43
#define GYRO_Y_REG 0x45
#define GYRO_Z_REG 0x47
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "gyro_log.txt"

// Global variables
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
    int16_t z_rate;
} gyro_data_t;

// Function prototypes
int spi_init(const char *device, int speed, int mode, int cs_gpio);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int spi_read_gyro(int fd, gyro_data_t *data);
int log_data(FILE *fp, struct timespec ts, gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// SPI initialization function
int spi_init(const char *device, int speed, int mode, int cs_gpio) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_value = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_value) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    uint8_t bits_per_word = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI max speed
    uint32_t speed_hertz = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_hertz) == -1) {
        perror("Error setting SPI max speed");
        close(fd);
        return -1;
    }

    // Set chip select GPIO
    gpioSetMode(cs_gpio, PI_OUTPUT);
    gpioWrite(cs_gpio, 1); // De-assert CS initially

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// SPI read gyro function
int spi_read_gyro(int fd, gyro_data_t *data) {
    uint8_t tx_buf[1] = {GYRO_X_REG}; // Register address
    uint8_t rx_buf[1] = {0}; // Dummy buffer for reading
    uint8_t tx_buf_y[1] = {GYRO_Y_REG};
    uint8_t rx_buf_y[1] = {0};
    uint8_t tx_buf_z[1] = {GYRO_Z_REG};
    uint8_t rx_buf_z[1] = {0};

    if (spi_transfer(fd, tx_buf, rx_buf, 1) != 0) return -1;
    if (spi_transfer(fd, tx_buf_y, rx_buf_y, 1) != 0) return -1;
    if (spi_transfer(fd, tx_buf_z, rx_buf_z, 1) != 0) return -1;

    // Combine the two bytes to form the 16-bit gyroscope data
    data->x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    data->y_rate = (int16_t)((rx_buf_y[0] << 8) | rx_buf_y[1]);
    data->z_rate = (int16_t)((rx_buf_z[0] << 8) | rx_buf_z[1]);

    return 0;
}

// Log data function
int log_data(FILE *fp, struct timespec ts, gyro_data_t data) {
    char timestamp[30];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S.%09ldZ", gmtime(&ts.tv_sec)) != 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, data.x_rate, data.y_rate, data.z_rate) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_SPEED, SPI_MODE, CS_GPIO);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read gyroscope data with retries
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (spi_read_gyro(spi_fd, &gyro_data) == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "SPI read failed, retrying (%d/%d)\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read gyroscope data after %d retries\n", RETRY_COUNT);
        }

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("clock_gettime");
            continue; // Continue to the next iteration
        }

        // Log data
        if (log_data(log_file, ts, gyro_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    cleanup();

    return 0;
}

