#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_CE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_RATE 100   // Hz
#define SAMPLE_DELAY_MS 10
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define GYRO_RATE_SCALE 0.001 // degrees/second per LSB (example value, check datasheet)

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    long long timestamp;
    int16_t gyro_x;
    int16_t gyro_y;
} gyro_data_t;

// Function prototypes
int spi_read_register(int spi_handle, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int spi_handle, uint8_t reg_addr, uint8_t data);
int read_gyro_data(int spi_handle, int16_t *gyro_x, int16_t *gyro_y);
void log_data(FILE *fp, long long timestamp, int16_t gyro_x, int16_t gyro_y);
void signal_handler(int signal);

// SPI read function
int spi_read_register(int spi_handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[2];
    char rx_buf[len];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, len) != len) {
        fprintf(stderr, "SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    memcpy(data, rx_buf, len);
    return 0;
}

// SPI write function
int spi_write_register(int spi_handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    if (spiWrite(spi_handle, tx_buf, 2) != 2) {
        fprintf(stderr, "SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(int spi_handle, int16_t *gyro_x, int16_t *gyro_y) {
    uint8_t data[2];
    if (spi_read_register(spi_handle, GYRO_X_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read GYRO_X_REG\n");
        return -1;
    }
    *gyro_x = (int16_t)((data[1] << 8) | data[0]);

    if (spi_read_register(spi_handle, GYRO_Y_REG, data, 2) != 0) {
        fprintf(stderr, "Failed to read GYRO_Y_REG\n");
        return -1;
    }
    *gyro_y = (int16_t)((data[1] << 8) | data[0]);

    return 0;
}

// Log data to file
void log_data(FILE *fp, long long timestamp, int16_t gyro_x, int16_t gyro_y) {
    fprintf(fp, "%lld,%d,%d\n", timestamp, gyro_x, gyro_y);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,gyro_x,gyro_y\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t gyro_x, gyro_y;
    long long timestamp;
    struct timespec ts;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(spi_handle, &gyro_x, &gyro_y) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                timestamp = (long long)ts.tv_sec * 1000000000LL + (long long)ts.tv_nsec;

                // Log data
                log_data(fp, timestamp, gyro_x, gyro_y);
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data, retrying SPI initialization...\n");
            spiClose(spi_handle);
            spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
            if (spi_handle < 0) {
                fprintf(stderr, "SPI re-initialization failed\n");
                terminate = 1; // Exit if re-initialization fails
            }
        }

        // Delay
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Convert ms to microseconds
    }

    // Clean up
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

