#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define seismic event duration
#define SEISMIC_DURATION 2000 // milliseconds

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    unsigned long long last_seismic_time;
} SensorState;

SensorState sensor_state = {0, 0, 0};

// Function prototypes
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data);
void seismic_event_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);
int initialize_gpio();
int open_log_file();
void close_log_file();
void cleanup();

// Callback function for sensor 1
void sensor_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor1_state = level;
    if (sensor1_state == 1) {
        sensor_state.sensor1_state = 1;
    } else {
        sensor_state.sensor1_state = 0;
    }
}

// Callback function for sensor 2
void sensor_callback_2(int gpio, int level, uint32_t tick, void *user_data) {
    int sensor2_state = level;
    if (sensor2_state == 1) {
        sensor_state.sensor2_state = 1;
    } else {
        sensor_state.sensor2_state = 0;
    }
}

// Seismic event handler
void seismic_event_handler(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        sensor_state.last_seismic_time = tick;
    } else if (level == 0) { // Falling edge
        if (sensor_state.last_seismic_time != 0) {
            unsigned long long current_time = tick;
            if (current_time - sensor_state.last_seismic_time >= SEISMIC_DURATION * 1000) {
                // Trigger alert
                gpioWrite(ALERT_PIN, 1);
                gpioDelay(2000); // 2 seconds
                gpioWrite(ALERT_PIN, 0);

                // Log event
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

                fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
                fflush(log_file);

                printf("%s - Seismic event detected!\n", timestamp);

                sensor_state.last_seismic_time = 0; // Reset seismic time
            }
        }
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is initially LOW

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Open log file
int open_log_file() {
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }
    return 0;
}

// Close log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(ALERT_PIN, 0); // Ensure alert pin is LOW
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        cleanup();
        return 1;
    }

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 1\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor_callback_2, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 2\n");
        cleanup();
        return 1;
    }

    // Register seismic event handler
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, seismic_event_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 1 seismic event\n");
        cleanup();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, seismic_event_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for sensor 2 seismic event\n");
        cleanup();
        return 1;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

