#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

// Define PWM frequency and range
#define PWM_FREQUENCY 100
#define PWM_RANGE 255

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nSIGINT received. Shutting down gracefully...\n");
    }
}

// Function to validate the duration argument
int validate_duration(const char *duration_str) {
    if (duration_str == NULL || strlen(duration_str) == 0) {
        fprintf(stderr, "Error: Duration argument is required and must be a positive integer.\n");
        return 0;
    }

    if (sscanf(duration_str, "%d", &duration) != 1 || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: Duration must be an integer between 1 and 3600 seconds.\n");
        return 0;
    }

    return 1;
}

// Function to initialize the pigpio library and set up PWM
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 0;
    }

    // Set GPIO pins to output mode
    gpioSetMode(LAMP1_PIN, PI_OUTPUT);
    gpioSetMode(LAMP2_PIN, PI_OUTPUT);
    gpioSetMode(LAMP3_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(LAMP1_PIN, PWM_RANGE);
    gpioSetPWMrange(LAMP2_PIN, PWM_RANGE);
    gpioSetPWMrange(LAMP3_PIN, PWM_RANGE);

    return 1;
}

// Function to fade a lamp to a specific duty cycle
void fade_lamp(int gpio_pin, int duration, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Duty cycle must be between 0 and %d.\n", PWM_RANGE - 1);
        return;
    }

    // Calculate the number of steps
    int num_steps = 100; // Number of steps for the fade

    // Calculate the increment per step
    int increment = (int)(((float)(duty_cycle) / PWM_RANGE) * num_steps);

    // Calculate the delay per step (in microseconds)
    int delay_us = 1000000 / PWM_FREQUENCY; // Delay for 1ms

    // Fade the lamp
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(gpio_pin, increment);
        gpioDelay(delay_us);
    }
}

// Function to run the sunset sequence
void run_sunset_sequence(int duration) {
    time_t start_time = time(NULL);
    time_t current_time;
    int elapsed_time;
    int lamp1_duty_cycle = 100;
    int lamp2_duty_cycle = 100;
    int lamp3_duty_cycle = 100;

    printf("Sunset sequence started. Duration: %d seconds\n", duration);

    while (program_running && (time(NULL) - start_time) < duration) {
        // Fade lamp 1
        fade_lamp(LAMP1_PIN, duration, lamp1_duty_cycle);
        lamp1_duty_cycle -= 10;
        if (lamp1_duty_cycle < 0) {
            lamp1_duty_cycle = 0;
        }

        // Fade lamp 2
        fade_lamp(LAMP2_PIN, duration, lamp2_duty_cycle);
        lamp2_duty_cycle -= 10;
        if (lamp2_duty_cycle < 0) {
            lamp2_duty_cycle = 0;
        }

        // Fade lamp 3
        fade_lamp(LAMP3_PIN, duration, lamp3_duty_cycle);
        lamp3_duty_cycle -= 10;
        if (lamp3_duty_cycle < 0) {
            lamp3_duty_cycle = 0;
        }

        // Check if all lamps are off
        if (lamp1_duty_cycle == 0 && lamp2_duty_cycle == 0 && lamp3_duty_cycle == 0) {
            printf("Sunset sequence complete.\n");
            break;
        }

        // Calculate elapsed time
        current_time = time(NULL);
        elapsed_time = (int)(current_time - start_time);
        if (elapsed_time >= duration) {
            break;
        }

        // Wait for the specified duration
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1ms
    }

    // Turn off all lamps
    fade_lamp(LAMP1_PIN, duration, 0);
    fade_lamp(LAMP2_PIN, duration, 0);
    fade_lamp(LAMP3_PIN, duration, 0);

    printf("Sunset sequence finished.\n");
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_in_seconds>\n", argv[0]);
        return 1;
    }

    // Validate the duration argument
    if (!validate_duration(argv[1])) {
        return 1;
    }

    // Initialize the pigpio library
    if (!initialize_gpio()) {
        return 1;
    }

    // Set up signal handling for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Run the sunset sequence
    run_sunset_sequence(atoi(argv[1]));

    // Turn off all lamps before exiting
    fade_lamp(LAMP1_PIN, 3600, 0);
    fade_lamp(LAMP2_PIN, 3600, 0);
    fade_lamp(LAMP3_PIN, 3600, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

