#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RED_RELAY 17
#define RED_YELLOW_RELAY 22
#define GREEN_RELAY 23
#define YELLOW_RELAY 24

// Define the duration of each state in seconds
#define RED_DURATION 10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to set the state of a relay
void set_relay_state(int relay_pin, int state)
{
    gpioWrite(relay_pin, state);
    printf("Relay %d set to %d\n", relay_pin, state);
}

// Function to cycle through the traffic light sequence
void cycle_traffic_light()
{
    // Red
    set_relay_state(RED_RELAY, 0); // Active low
    set_relay_state(RED_YELLOW_RELAY, 0);
    set_relay_state(GREEN_RELAY, 0);
    set_relay_state(YELLOW_RELAY, 0);
    printf("Red\n");
    sleep(RED_DURATION);

    // Red + Yellow
    set_relay_state(RED_RELAY, 0); // Active low
    set_relay_state(RED_YELLOW_RELAY, 1);
    set_relay_state(GREEN_RELAY, 0);
    set_relay_state(YELLOW_RELAY, 0);
    printf("Red + Yellow\n");
    sleep(RED_YELLOW_DURATION);

    // Green
    set_relay_state(RED_RELAY, 1); // Active low
    set_relay_state(RED_YELLOW_RELAY, 0);
    set_relay_state(GREEN_RELAY, 0);
    set_relay_state(YELLOW_RELAY, 0);
    printf("Green\n");
    sleep(GREEN_DURATION);

    // Yellow
    set_relay_state(RED_RELAY, 0); // Active low
    set_relay_state(RED_YELLOW_RELAY, 0);
    set_relay_state(GREEN_RELAY, 0);
    set_relay_state(YELLOW_RELAY, 1);
    printf("Yellow\n");
    sleep(YELLOW_DURATION);
}

int main()
{
    // Initialize the pigpio library
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_RELAY, PI_OUTPUT);
    gpioSetMode(RED_YELLOW_RELAY, PI_OUTPUT);
    gpioSetMode(GREEN_RELAY, PI_OUTPUT);
    gpioSetMode(YELLOW_RELAY, PI_OUTPUT);

    // Set initial relay states to off (HIGH)
    set_relay_state(RED_RELAY, 1);
    set_relay_state(RED_YELLOW_RELAY, 1);
    set_relay_state(GREEN_RELAY, 1);
    set_relay_state(YELLOW_RELAY, 1);

    // Install signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Main loop to continuously cycle the traffic light
    while (program_running)
    {
        cycle_traffic_light();
    }

    // Clean up and terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

