#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_TIMEOUT_MS 10
#define TOUCH_THRESHOLD 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(uint16_t *touch_status);
int debounce_touch_event(uint16_t touch_status);
int toggle_relay(int current_state);
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Function to initialize the MPR121
int initialize_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x00) < 0) {
        log_error("Failed to set MPR121 to stop mode");
        return -1;
    }

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        log_error("Failed to set electrode configuration");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0; i < 12; i++) {
