#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define constants
#define FLAME_DETECTED_THRESHOLD 3
#define FLAME_READ_INTERVAL_MS 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_flame_sensor(int pin);
int check_flame_condition(int pin, int threshold);
void activate_buzzer(int pin);
void deactivate_buzzer(int pin);
void activate_led(int pin);
void deactivate_led(int pin);
void log_flame_event(const char *filename);
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check if the flame condition is detected
int check_flame_condition(int pin, int threshold) {
    int i;
    int readings[threshold];
    int index = 0;

    for (i = 0; i < threshold; i++) {
        readings[i] = read_flame_sensor(pin);
        gpioDelay(FLAME_READ_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Check if all readings are LOW
    for (i = 0; i < threshold; i++) {
        if (readings[i] == 0) {
            return 1; // Flame detected
        }
    }

    return 0; // No flame detected
}

// Function to activate the buzzer
void activate_buzzer(int pin) {
    gpioWrite(pin, 1); // Set pin HIGH
}

// Function to deactivate the buzzer
void deactivate_buzzer(int pin) {
    gpioWrite(pin, 0); // Set pin LOW
}

// Function to activate the LED
void activate_led(int pin) {
    gpioWrite(pin, 1); // Set pin HIGH
}

// Function to deactivate the LED
void deactivate_led(int pin) {
    gpioWrite(pin, 0); // Set pin LOW
}

// Function to log the flame event
void log_flame_event(const char *filename) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", filename);
        perror("fopen");
        return;
    }

    fprintf(log_file, "%s - Flame Detected\n", timestamp);
    fclose(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    // Release GPIO resources
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioWrite(LED_PIN, 0);    // Ensure LED is off

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (check_flame_condition(FLAME_SENSOR_PIN, FLAME_DETECTED_THRESHOLD)) {
            log_flame_event("flame_log.txt");
            activate_buzzer(BUZZER_PIN);
            activate_led(LED_PIN);
        } else {
            deactivate_buzzer(BUZZER_PIN);
            deactivate_led(LED_PIN);
        }

        gpioDelay(100000); // Check every 0.1 seconds
    }

    return 0;
}

