#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define the dispensing duration in milliseconds
#define DISPENSE_DURATION 1000

// Define the log file name
#define LOG_FILE "dispense_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Dispensing stopped and solenoids deactivated.\n");
        program_running = 0;
        // Deactivate both solenoids
        gpioWrite(SOLENOID_1_PIN, 0);
        gpioWrite(SOLENOID_2_PIN, 0);

        // Terminate the pigpio library
        gpioTerminate();

        // Close the log file
        FILE *log_file = fopen(LOG_FILE, "a");
        if (log_file != NULL) {
            fclose(log_file);
        } else {
            fprintf(stderr, "Error closing log file.\n");
        }

        exit(0);
    }
}

// Function to log a dispense event to the log file
int log_dispense_event(int solenoid_pin, int duration_ms) {
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file for writing.\n");
        return -1; // Indicate failure
    }

    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[20]; // Buffer to hold the formatted timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    fprintf(log_file, "%s, Solenoid %d, %d ms\n", timestamp, solenoid_pin, duration_ms);
    fclose(log_file);
    return 0; // Indicate success
}

// Function to dispense using the solenoids
int dispense(int solenoid_pin, int duration_ms) {
    if (gpioWrite(solenoid_pin, 1) != 0) {
        fprintf(stderr, "Error activating solenoid %d.\n", solenoid_pin);
        return -1;
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds
    if (gpioWrite(solenoid_pin, 0) != 0) {
        fprintf(stderr, "Error deactivating solenoid %d.\n", solenoid_pin);
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set the GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Main loop to continuously dispense
    while (program_running) {
        // Dispense using solenoid 1
        if (dispense(SOLENOID_1_PIN, 500) != 0) {
            fprintf(stderr, "Error dispensing with solenoid 1.\n");
        }

        // Dispense using solenoid 2
        if (dispense(SOLENOID_2_PIN, 500) != 0) {
            fprintf(stderr, "Error dispensing with solenoid 2.\n");
        }

        // Log the dispense event
        if (log_dispense_event(SOLENOID_1_PIN, 500) != 0) {
            fprintf(stderr, "Error logging dispense event for solenoid 1.\n");
        }
        if (log_dispense_event(SOLENOID_2_PIN, 500) != 0) {
            fprintf(stderr, "Error logging dispense event for solenoid 2.\n");
        }

        // Delay before the next dispensing cycle
        gpioDelay(1000000); // 1 second delay
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0; // Indicate success
}

