#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable PWM for Motor A and B
#define ENA 24
#define ENB 25

// Ultrasonic Sensor
#define TRIGGER_PIN 26
#define ECHO_PIN 27

// Obstacle Avoidance Threshold
#define OBSTACLE_THRESHOLD 20.0

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Log File
#define LOG_FILE "balance_log.txt"

// Global Variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function Prototypes
void signal_handler(int signal);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void set_motor_speed(int motor_a_speed, int motor_b_speed);
float simulate_tilt_error();
float simulate_distance();
void obstacle_avoidance();
void cleanup();

// PID Variables
float integral = 0.0;
float previous_error = 0.0;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to log data to a file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to set motor speeds
void set_motor_speed(int motor_a_speed, int motor_b_speed) {
    if (motor_a_speed > 255) motor_a_speed = 255;
    if (motor_a_speed < -255) motor_a_speed = -255;
    if (motor_b_speed > 255) motor_b_speed = 255;
    if (motor_b_speed < -255) motor_b_speed = -255;

    if (motor_a_speed != 0) {
        gpioWrite(MOTOR_A_FORWARD, (motor_a_speed > 0) ? 1 : 0);
        gpioWrite(MOTOR_A_BACKWARD, (motor_a_speed < 0) ? 1 : 0);
    }
    if (motor_b_speed != 0) {
        gpioWrite(MOTOR_B_FORWARD, (motor_b_speed > 0) ? 1 : 0);
        gpioWrite(MOTOR_B_BACKWARD, (motor_b_speed < 0) ? 1 : 0);
    }
}

// Function to simulate tilt error
float simulate_tilt_error() {
    return (float)(rand() % 21 - 10.0); // Simulate tilt error between -10.0 and 10.0 degrees
}

// Function to simulate distance
float simulate_distance() {
    return (float)(rand() % 380 + 2.0); // Simulate distance between 2.0 and 400.0 cm
}

// Function to perform obstacle avoidance
void obstacle_avoidance() {
    printf("Obstacle detected! Reversing motors at 50% speed.\n");
    set_motor_speed(-255, -255); // Reverse both motors at 50% speed
    set_motor_speed(255, 255);   // Clamp all motor speeds to ±255
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(ENA, 0); // Disable PWM
    gpioWrite(ENB, 0); // Disable PWM
    gpioWrite(MOTOR_A_FORWARD, 0); // Stop Motor A
    gpioWrite(MOTOR_A_BACKWARD, 0); // Stop Motor A
    gpioWrite(MOTOR_B_FORWARD, 0); // Stop Motor B
    gpioWrite(MOTOR_B_BACKWARD, 0); // Stop Motor B
    gpioTerminate(); // Terminate pigpio

    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Initialize random seed
    srand(time(NULL));

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate(); // Terminate pigpio
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Self-balancing robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Simulate tilt error and distance
        float tilt_error = simulate_tilt_error();
        float distance = simulate_distance();

        // Calculate motor speeds using PID control
        float error = tilt_error;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        // Clamp output to ±255
        if (output > 255) output = 255;
        if (output < -255) output = -255;

        int motor_a_speed = (int)output;
        int motor_b_speed = (int)output;

        // Set motor speeds
        set_motor_speed(motor_a_speed, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Check for obstacle
        if (distance < OBSTACLE_THRESHOLD) {
            obstacle_avoidance();
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

