#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <alsa/asoundlib.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define SAMPLE_RATE 8000
#define NUM_CHANNELS 1
#define SAMPLE_SIZE 16
#define PERIOD_SIZE 1024
#define PERIOD_COUNT 4
#define PERIOD_SIZE_MS 10
#define RMS_THRESHOLD 0.5
#define DEFAULT_GAIN 1.0
#define DEFAULT_RED_PWM_FREQ 1000
#define DEFAULT_GREEN_PWM_FREQ 2000
#define DEFAULT_BLUE_PWM_FREQ 3000
#define DEFAULT_RED_PWM_DUTY 50
#define DEFAULT_GREEN_PWM_DUTY 50
#define DEFAULT_BLUE_PWM_DUTY 50

// GPIO pins for RGB LED
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27

// Global variables
snd_pcm_t *pcm_handle;
int running = 1;
double sensitivity = DEFAULT_GAIN;
int red_pwm_freq = DEFAULT_RED_PWM_FREQ;
int green_pwm_freq = DEFAULT_GREEN_PWM_FREQ;
int blue_pwm_freq = DEFAULT_BLUE_PWM_FREQ;
int red_pwm_duty = DEFAULT_RED_PWM_DUTY;
int green_pwm_duty = DEFAULT_GREEN_PWM_DUTY;
int blue_pwm_duty = DEFAULT_BLUE_PWM_DUTY;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle, const char *device_name, int sample_rate, int channels, int sample_size, int period_size, int period_count, int flags);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames);
double calculate_rms(const short *buffer, int frames);
int map_amplitude_to_color(double rms_amplitude, double sensitivity, int red_pwm_freq, int green_pwm_freq, int blue_pwm_freq, int red_pwm_duty, int green_pwm_duty, int blue_pwm_duty);
void set_led_color(int red_pwm_freq, int green_pwm_freq, int blue_pwm_freq, int red_pwm_duty, int green_pwm_duty, int blue_pwm_duty);
void signal_handler(int signal);
void cleanup();

// ALSA initialization function
int init_alsa(snd_pcm_t **pcm_handle, const char *device_name, int sample_rate, int channels, int sample_size, int period_size, int period_count, int flags) {
    int err;
    snd_pcm_hw_params_t *hw_params;

    if ((err = snd_pcm_open(pcm_handle, device_name, SND_PCM_STREAM_CAPTURE, flags)) < 0) {
        fprintf(stderr, "Error opening PCM device %s: %s\n", device_name, snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, channels)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_rate(*pcm_handle, hw_params, sample_rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, period_size, period_count)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Audio capture function
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading audio: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

// RMS amplitude calculation function
double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / frames);
}

// Amplitude mapping function
int map_amplitude_to_color(double rms_amplitude, double sensitivity, int red_pwm_freq, int green_pwm_freq, int blue_pwm_freq, int red_pwm_duty, int green_pwm_duty, int blue_pwm_duty) {
    double amplitude_scaled = rms_amplitude * sensitivity;

    // Clamp amplitude to 0-1 range
    if (amplitude_scaled < 0.0) amplitude_scaled = 0.0;
    if (amplitude_scaled > 1.0) amplitude_scaled = 1.0;

    // Map amplitude to PWM duty cycle (0-100%)
    int red_duty = (int)(amplitude_scaled * (red_pwm_duty / 100.0));
    int green_duty = (int)(amplitude_scaled * (green_pwm_duty / 100.0));
    int blue_duty = (int)(amplitude_scaled * (blue_pwm_duty / 100.0));

    // Clamp duty cycle to 0-100%
    if (red_duty < 0) red_duty = 0;
    if (red_duty > 100) red_duty = 100;
    if (green_duty < 0) green_duty = 0;
    if (green_duty > 100) green_duty = 100;
    if (blue_duty < 0) blue_duty = 0;
    if (blue_duty > 100) blue_duty = 100;

    return (red_duty + green_duty + blue_duty) / 3; // Average duty cycle
}

// LED control function
void set_led_color(int red_pwm_freq, int green_pwm_freq, int blue_pwm_freq, int red_pwm_duty, int green_pwm_duty, int blue_pwm_duty) {
    gpioPWM(RED_PIN, red_pwm_duty);
    gpioPWM(GREEN_PIN, green_pwm_duty);
    gpioPWM(BLUE_PIN, blue_pwm_duty);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Cleanup function
void cleanup() {
    if (pcm_handle) {
