int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int frames) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading audio: %s\n", snd_strerror(err));
        return -1;
    }
    return 0;
}

// RMS amplitude calculation function
double calculate_rms(const short *buffer, int frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / frames);
}

// Amplitude mapping function
int map_amplitude_to_color(double rms_amplitude, double sensitivity, int red_pwm_freq, int green_pwm_freq, int blue_pwm_freq, int red_pwm_duty, int green_pwm_duty, int blue_pwm_duty) {
    double amplitude_scaled = rms_amplitude * sensitivity;

    // Clamp amplitude to 0-1 range
    if (amplitude_scaled < 0.0) amplitude_scaled = 0.0;
    if (amplitude_scaled > 1.0) amplitude_scaled = 1.0;

    // Map amplitude to PWM duty cycle (0-100%)
    int red_duty = (int)(amplitude_scaled * (red_pwm_duty / 100.0));
    int green_duty = (int)(amplitude_scaled * (green_pwm_duty / 100.0));
    int blue_duty = (int)(amplitude_scaled * (blue_pwm_duty / 100.0));

