#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         0x29
#define TCS34725_ENABLE          0x80
#define TCS34725_ATIME           0x81
#define TCS34725_CONTROL         0x8F
#define TCS34725_CDATA           0x94
#define TCS34725_RDATA           0x96
#define TCS34725_GDATA           0x98
#define TCS34725_BDATA           0x9A

// I2C Bus
#define I2C_BUS_NUMBER          1

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int initialize_sensor();
color_data_t read_color_data();
void log_data(color_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable power and ADC
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Could not enable power and ADC.\n");
        return -1;
    }

    // Set integration time (154ms)
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xEB) < 0) {
        fprintf(stderr, "Error: Could not set integration time.\n");
        return -1;
    }

    // Set gain (1x)
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set gain.\n");
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
color_data_t read_color_data() {
    color_data_t data;
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) < 0) {
        fprintf(stderr, "Error: Could not read color data.\n");
        data.clear = 0; // Set to 0 to indicate error
        data.red = 0;
        data.green = 0;
        data.blue = 0;
        return data;
    }

    data.clear = (buffer[1] << 8) | buffer[0];
    data.red   = (buffer[3] << 8) | buffer[2];
    data.green = (buffer[5] << 8) | buffer[4];
    data.blue  = (buffer[7] << 8) | buffer[6];

    return data;
}

// Function to log data to a CSV file
void log_data(color_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, data.clear, data.red, data.green, data.blue);
    fflush(fp); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS_NUMBER, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the CSV file for appending
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open color_data.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Clear,Red,Green,Blue\n");
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        color_data_t data = read_color_data();
        if (data.clear == 0) {
            fprintf(stderr, "Error: Could not read color data. Skipping this cycle.\n");
        } else {
            log_data(data);
        }
        gpioDelay(500); // Sample every 500ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

