#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-1000000)
#define PWM_RANGE 1000000

// Define sunrise/sunset duration (seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime duration (seconds)
#define DAYTIME_DURATION 6 * 3600

// Define nighttime duration (seconds)
#define NIGHTTIME_DURATION 14.4 * 3600

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, exiting gracefully...\n");
    }
}

// Function to set the duty cycle of a relay
void set_relay_duty_cycle(int relay_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid duty cycle value. Must be between 0 and %d.\n", PWM_RANGE);
        gpioPWM(relay_pin, 0); // Turn off the relay if duty cycle is invalid
        return;
    }

    gpioPWM(relay_pin, duty_cycle);
}

// Function to simulate sunrise
void sunrise() {
    printf("Starting sunrise phase...\n");
    for (int i = 0; i < SUNRISE_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, i * 10000); // Increase duty cycle linearly
        set_relay_duty_cycle(RELAY2_PIN, i * 10000);
        set_relay_duty_cycle(RELAY3_PIN, i * 10000);
        set_relay_duty_cycle(RELAY4_PIN, i * 10000);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Sunrise complete.\n");
}

// Function to simulate daytime
void daytime() {
    printf("Starting daytime phase...\n");
    for (int i = 0; i < DAYTIME_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, PWM_RANGE - (i * 10000)); // Decrease duty cycle linearly
        set_relay_duty_cycle(RELAY2_PIN, PWM_RANGE - (i * 10000));
        set_relay_duty_cycle(RELAY3_PIN, PWM_RANGE - (i * 10000));
        set_relay_duty_cycle(RELAY4_PIN, PWM_RANGE - (i * 10000));
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Daytime complete.\n");
}

// Function to simulate sunset
void sunset() {
    printf("Starting sunset phase...\n");
    for (int i = 0; i < SUNSET_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, PWM_RANGE - (i * 10000)); // Decrease duty cycle linearly
        set_relay_duty_cycle(RELAY2_PIN, PWM_RANGE - (i * 10000));
        set_relay_duty_cycle(RELAY3_PIN, PWM_RANGE - (i * 10000));
        set_relay_duty_cycle(RELAY4_PIN, PWM_RANGE - (i * 10000));
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Sunset complete.\n");
}

// Function to simulate nighttime
void nighttime() {
    printf("Starting nighttime phase...\n");
    for (int i = 0; i < NIGHTTIME_DURATION; i++) {
        set_relay_duty_cycle(RELAY1_PIN, i * 10000); // Increase duty cycle linearly
        set_relay_duty_cycle(RELAY2_PIN, i * 10000);
        set_relay_duty_cycle(RELAY3_PIN, i * 10000);
        set_relay_duty_cycle(RELAY4_PIN, i * 10000);
        gpioDelay(1000); // Delay for 1 second
    }
    printf("Nighttime complete.\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop: cycle through sunrise, daytime, sunset, and nighttime
    while (program_running) {
        sunrise();
        daytime();
        sunset();
        nighttime();
    }

    // Turn off all relays before exiting
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

