#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define DEBOUNCE_INTERVAL_MS 200
#define VIDEO_CAPTURE_DURATION_SEC 5
#define LOG_FILE_PATH "/home/pi/logs/motion_log.txt"
#define VIDEO_CAPTURE_DIR "/home/pi/videos/"

static volatile int running = 1;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a motion event to the log file
int log_motion_event(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
    return 0;
}

// Function to capture video using raspivid
int capture_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, VIDEO_CAPTURE_DURATION_SEC * 1000); // Convert seconds to milliseconds

    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "raspivid exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to handle motion detection
void handle_motion_detection() {
    int last_motion_time = 0;
    while (running) {
        int motion_detected = gpioRead(GPIO_PIN);

        if (motion_detected == 0) { // Active low
            time_t current_time = time(NULL);
            if (current_time - last_motion_time > DEBOUNCE_INTERVAL_MS / 1000.0) { // Debounce
                char *timestamp = get_iso8601_timestamp();
                if (timestamp != NULL) {
                    if (log_motion_event(timestamp) != 0) {
                        fprintf(stderr, "Failed to log motion event\n");
                    }
                    free(timestamp);

                    if (capture_video(VIDEO_CAPTURE_DIR) != 0) {
                        fprintf(stderr, "Failed to capture video\n");
                    }
                }
                last_motion_time = current_time;
            }
        }
        gpioDelay(100); // Check every 100ms
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set pull-up resistor (if needed, depends on sensor module)
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Or PI_PUD_DOWN if needed

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Start motion detection loop
    handle_motion_detection();

    // Clean up resources before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

