#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    long long timestamp_sec;
    long long timestamp_usec;
    float x_degps;
    float y_degps;
    float z_degps;
} gyro_data_t;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
int log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Initialize the MPU-6050
int init_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050 (set sleep bit to 0)
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050 (attempt %d).\n", 4 - retries);
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Configure gyroscope range (+/- 250 deg/s)
        if (i2cWriteByteData(i2c_handle, 0x1B, 0x00) < 0) {
            fprintf(stderr, "Error: Could not configure gyroscope range (attempt %d).\n", 4 - retries);
            retries--;
            usleep(100000);
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU-6050 after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data from the MPU-6050
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of gyroscope data (X, Y, Z)
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (buf[0] << 8) | buf[1];
    raw_y = (buf[2] << 8) | buf[3];
    raw_z = (buf[4] << 8) | buf[5];

    // Convert raw data to degrees per second
    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0; // Success
}

// Log data to a CSV file
int log_data(gyro_data_t data) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp_str[30];

    // Get current timestamp with millisecond precision
    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), sizeof(timestamp_str) - strlen(timestamp_str), ".%03ld", (long int)tv.tv_usec / 1000);

    // Write data to the log file
    fprintf(log_file, "%s,%lld,%.2f,%.2f,%.2f\n", timestamp_str, data.timestamp_sec, data.x_degps, data.y_degps, data.z_degps);
    fflush(log_file); // Flush the buffer to ensure data is written immediately

    return 0; // Success
}

int main() {
    gyro_data_t gyro_data;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0); // I2C bus 1, MPU6050 address, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialization failed.\n");
        i2cClose(i2c_handle);
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp_sec,timestamp_usec,X_degps,Y_degps,Z_degps\n");
    }
    rewind(log_file);

    // Main loop
    float x, y, z;
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Get current timestamp
            gettimeofday(&gyro_data.timestamp_sec, NULL);
            gyro_data.timestamp_usec = (long long)(tv_usec & 0xFFFFFFFF); // Keep only microseconds

            // Log data
            log_data(gyro_data);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data.\n");
        }

        // Delay for 10 milliseconds
        usleep(10000);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    return 0;
}

