#define RELAY_ZONE_2 17
#define RELAY_ZONE_3 27
#define RELAY_ZONE_4 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the GPIO pin mode
int set_gpio_mode(int gpio_pin, int mode) {
    if (gpioSetMode(gpio_pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to set the relay state (ON/OFF)
int set_relay_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Failed to set GPIO %d to state %d\n", gpio_pin, state);
        return -1;
    }
    return 0;
}

// Function to generate a random moisture value
int generate_moisture_value() {
    return rand() % 101; // Generates a value between 0 and 100
}

// Function to determine the irrigation state based on the moisture value
int determine_irrigation_state(int moisture_value) {
    if (moisture_value < 30) {
        return 0; // Dry
    } else {
        return 1; // Wet
    }
}

// Function to log the sensor data to a file
int log_data(int moisture_value, int relay_zone_1_state, int relay_zone_2_state, int relay_zone_3_state, int relay_zone_4_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Moisture: %d, Relay Zone 1: %d, Relay Zone 2: %d, Relay Zone 3: %d, Relay Zone 4: %d\n",
            timestamp, moisture_value, relay_zone_1_state, relay_zone_2_state, relay_zone_3_state, relay_zone_4_state);

    fclose(fp);
    return 0;
}

