    if (set_gpio_mode(RELAY_ZONE_1, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY_ZONE_2, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY_ZONE_3, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY_ZONE_4, PI_OUTPUT) != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Generate a random moisture value
        int moisture_value = generate_moisture_value();

        // Determine the irrigation state
        int irrigation_state = determine_irrigation_state(moisture_value);

        // Set the relay states
        if (irrigation_state == 0) { // Dry
            if (set_relay_state(RELAY_ZONE_1, 0) != 0 ||
                set_relay_state(RELAY_ZONE_2, 0) != 0 ||
                set_relay_state(RELAY_ZONE_3, 0) != 0 ||
                set_relay_state(RELAY_ZONE_4, 0) != 0) {
                fprintf(stderr, "Failed to set relays to ON state\n");
                program_running = 0; // Exit loop on error
            }
        } else { // Wet
            if (set_relay_state(RELAY_ZONE_1, 1) != 0 ||
                set_relay_state(RELAY_ZONE_2, 1) != 0 ||
                set_relay_state(RELAY_ZONE_3, 1) != 0 ||
                set_relay_state(RELAY_ZONE_4, 1) != 0) {
                fprintf(stderr, "Failed to set relays to OFF state\n");
                program_running = 0; // Exit loop on error
            }
        }

        // Log the data
        if (log_data(moisture_value, 0, 0, 0, 0) != 0) {
            fprintf(stderr, "Failed to log data\n");
            program_running = 0; // Exit loop on error
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Deactivate all relays
    if (set_relay_state(RELAY_ZONE_1, 1) != 0 ||
        set_relay_state(RELAY_ZONE_2, 1) != 0 ||
        set_relay_state(RELAY_ZONE_3, 1) != 0 ||
        set_relay_state(RELAY_ZONE_4, 1) != 0) {
        fprintf(stderr, "Failed to set relays to ON state during shutdown\n");
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

