#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// GPIO pin for alarm
#define ALARM_GPIO 27

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.2

// Free-fall duration (in seconds)
#define FREEFALL_DURATION 0.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
int detect_freefall(accelerometer_data_t data);
void trigger_alarm();
void log_freefall_event(accelerometer_data_t data);
void signal_handler(int signal);

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Set data format to +/- 2g and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to g units
    data.x = (float)((int16_t)(raw_data[1] << 8 | raw_data[0])) / 256.0;
    data.y = (float)((int16_t)(raw_data[3] << 8 | raw_data[2])) / 256.0;
    data.z = (float)((int16_t)(raw_data[5] << 8 | raw_data[4])) / 256.0;

    return data;
}

// Function to detect free-fall
int detect_freefall(accelerometer_data_t data) {
    if (fabs(data.x) < FREEFALL_THRESHOLD &&
        fabs(data.y) < FREEFALL_THRESHOLD &&
        fabs(data.z) < FREEFALL_THRESHOLD) {
        return 1; // Free-fall detected
    }
    return 0; // Not in free-fall
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set GPIO high
    gpioDelay(5000);          // Wait for 5 seconds
    gpioWrite(ALARM_GPIO, 0); // Set GPIO low
}

// Function to log free-fall event
void log_freefall_event(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially low

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        if (detect_freefall(data)) {
            printf("Free-fall detected!\n");
            if (log_freefall_event(data) == 0) {
                printf("Free-fall event logged.\n");
            } else {
                fprintf(stderr, "Error logging free-fall event\n");
            }
            trigger_alarm();
        }
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is off
    gpioTerminate();

    return 0;
}

