#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <errno.h>

#define TRIG_PIN 4
#define ECHO_PIN 18
#define MAX_DISTANCE 4000 // Maximum measurable distance in cm
#define TIMEOUT_THRESHOLD 100 // Timeout threshold in milliseconds
#define MAX_PULSE_WIDTH 23200 // Maximum pulse width in microseconds

// Mutex type
typedef struct {
    pthread_mutex_t mutex;
} Mutex;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static Mutex mutex;

// Function prototypes
void trigger_pulse(int trigger_pin);
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
void *sensor_thread(void *arg);
void signal_handler(int signal);
void cleanup(void);

// Function to trigger the ultrasonic sensor
void trigger_pulse(int trigger_pin) {
    gpioWrite(trigger_pin, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(trigger_pin, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static int echo_valid = 0;
    int pulse_width;

    if (level == 1) {
        start_tick = tick;
        echo_valid = 0; // Reset echo_valid
    } else if (level == 0) {
        if (start_tick != 0) {
            pulse_width = tick - start_tick;
            if (pulse_width > 0 && pulse_width < MAX_PULSE_WIDTH) {
                echo_valid = 1;
            } else {
                fprintf(stderr, "Error: Invalid pulse width: %u\n", pulse_width);
            }
        }
        start_tick = 0; // Reset start_tick
    }
}

// Sensor thread function
void *sensor_thread(void *arg) {
    while (running) {
        trigger_pulse(TRIG_PIN);
        gpioDelay(200); // Wait 200ms between trigger cycles

        // Wait for the echo callback to be triggered
        int timeout_counter = 0;
        while (!echo_valid && timeout_counter < 1000) {
            gpioDelay(1); // Wait 1ms
            timeout_counter++;
        }

        if (!echo_valid) {
            fprintf(stderr, "Error: Timeout waiting for echo.\n");
            continue; // Skip to the next iteration
        }

        // Read the pulse width
        int pulse_width = gpioTick() - start_tick;
        if (pulse_width < 0) {
            pulse_width += 0xFFFFFFFF; // Handle tick counter wrap-around
        }

        // Validate the pulse width
        if (pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Pulse width exceeds maximum allowed value: %u\n", pulse_width);
            continue; // Skip to the next iteration
        }

        // Calculate the distance in centimeters
        float distance_cm = (pulse_width / 2.0) / 29.1;

        // Log the data to a file
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
        long timestamp_ns = (long)time(NULL) * 1000000000; // Get nanoseconds since epoch

        if (log_file != NULL) {
            fprintf(log_file, "%ld,%.2f\n", timestamp_ns, distance_cm);
            fflush(log_file); // Flush the buffer to ensure data is written to the file
        } else {
            fprintf(stderr, "Error: Log file is not open.\n");
        }

        echo_valid = 0; // Reset echo_valid after processing
    }

    pthread_exit(NULL);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup(void) {
    printf("Cleaning up...\n");

    // Cancel the sensor thread
    pthread_cancel(sensor_thread_id);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&mutex);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Error: Mutex initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO_PIN
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set TRIG_PIN to LOW initially
    gpioWrite(TRIG_PIN, 0);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the sensor thread
    pthread_t sensor_thread_id;
    if (pthread_create(&sensor_thread_id, NULL, sensor_thread, NULL) != 0) {
        fprintf(stderr, "Error: Could not create sensor thread\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Wait for the sensor thread to finish
    pthread_join(sensor_thread_id, NULL);

    // Cleanup and exit
    cleanup();

    return 0;
}

