#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Default threshold
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
int i2c_address = LIS3DH_ADDR;
float threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize LIS3DH sensor
int init_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1: 100Hz, ±2g range, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: High-resolution, left-justified
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t x_raw, y_raw, z_raw;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g-force units (assuming +/- 2g range)
    *x = (float)x_raw / 16384.0;
    *y = (float)y_raw / 16384.0;
    *z = (float)z_raw / 16384.0;

    return 0;
}

// Log acceleration data to file
void log_acceleration(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, x, y, z);
    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                if (i2c_address != LIS3DH_ADDR && i2c_address != 0x19) {
                    fprintf(stderr, "Invalid I2C address. Must be 0x18 or 0x19.\n");
                    return 1;
                }
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0) {
                    fprintf(stderr, "Invalid threshold. Must be greater than 0.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH sensor
    if (init_lis3dh(i2c_handle) < 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_acceleration(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Continuing...\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

