#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for sensors and motor
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define MOTOR_PIN 22

// Define motor control functions (replace with your actual implementation)
void forward(int gpio, int speed);
void turnLeft(int gpio, int speed);
void turnRight(int gpio, int speed);
void stop(int gpio);

// Circular buffer for sensor readings
int sensor_readings[5];
int buffer_index = 0;

// Function prototypes
int read_sensor(int gpio);
void update_circular_buffer(int left, int center, int right);
void check_line_status(int left, int center, int right);
void handle_line_absence();
void handle_line_presence();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    stop(MOTOR_PIN);
    gpioTerminate();
    exit(0);
}

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to update the circular buffer
void update_circular_buffer(int left, int center, int right) {
    sensor_readings[buffer_index] = left;
    sensor_readings[buffer_index + 1] = center;
    sensor_readings[buffer_index + 2] = right;
    sensor_readings[buffer_index + 3] = -1; // Mark as empty
    sensor_read_index = (sensor_read_index + 1) % 5; // Increment index, wrap around
}

// Function to check line status
void check_line_status(int left, int center, int right) {
    static int line_absent_count = 0;
    static int line_present_count = 0;

    if (center == 0) {
        line_absent_count++;
    } else {
        line_present_count++;
    }

    if (line_absent_count == 5) {
        handle_line_absence();
    } else if (line_present_count == 5) {
        handle_line_presence();
    }
}

// Function to handle line absence
void handle_line_absence() {
    printf("Line absent for 5 consecutive readings!\n");
    gpioWrite(MOTOR_PIN, 1); // Move forward
    gpioDelay(2000); // Move for 2 seconds
    gpioWrite(MOTOR_PIN, 0); // Stop
}

// Function to handle line presence
void handle_line_presence() {
    printf("Line present for 5 consecutive readings!\n");
    gpioWrite(MOTOR_PIN, 1); // Move forward
    gpioDelay(2000); // Move for 2 seconds
    gpioWrite(MOTOR_PIN, 0); // Stop
}

// Function to control the motor
void forward(int gpio, int speed) {
    gpioWrite(gpio, 1); // Set GPIO HIGH
    gpioDelay(speed);   // Delay for speed milliseconds
    gpioWrite(gpio, 0); // Set GPIO LOW
}

void turnLeft(int gpio, int speed) {
    gpioWrite(gpio, 1); // Set GPIO HIGH
    gpioDelay(speed);   // Delay for speed milliseconds
    gpioWrite(gpio, 0); // Set GPIO LOW
}

void turnRight(int gpio, int speed) {
    gpioWrite(gpio, 1); // Set GPIO HIGH
    gpioDelay(speed);   // Delay for speed milliseconds
    gpioWrite(gpio, 0); // Set GPIO LOW
}

void stop(int gpio) {
    gpioWrite(gpio, 0); // Set GPIO LOW
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_PIN, PI_OUTPUT);

    // Initialize circular buffer index
    sensor_read_index = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Update circular buffer
        update_circular_buffer(left, center, right);

        // Check line status
        check_line_status(left, center, right);

        // Delay for 10 milliseconds
        gpioDelay(10);
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    gpioTerminate();
    return 0;
}

