#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0 // mT
#define POLL_DELAY_MS 100
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_magnetic_field(int *raw_value);
float convert_to_mT(int raw_value);
int check_threshold(float mT);
int control_relay(int state);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    int raw_value;
    float mT;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read magnetic field data
int read_magnetic_field(int *raw_value) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    *raw_value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to convert raw value to mT
float convert_to_mT(int raw_value) {
    // Assuming a linear relationship between raw value and mT
    // Adjust the scaling factor as needed based on the sensor's datasheet
    return (float)raw_value * 0.001; // Example scaling
}

// Function to check if the magnetic field exceeds the threshold
int check_threshold(float mT) {
    return (mT > THRESHOLD_MT) ? 1 : 0;
}

// Function to control the relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Function to log events
int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Deactivate relay
    gpioTerminate();
}

int main() {
    int raw_value;
    float mT;
    int threshold_exceeded;
    int relay_state = 0; // 0 = off, 1 = on
    int retries = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 17 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Starting magnetic field monitoring...\n");

    while (program_running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_magnetic_field(&raw_value) == 0) {
                mT = convert_to_mT(raw_value);
                threshold_exceeded = check_threshold(mT);

                if (threshold_exceeded) {
                    if (relay_state == 0) {
                        control_relay(1);
                        relay_state = 1;
                        log_event("Relay activated");
                    }
                } else {
                    if (relay_state == 1) {
                        control_relay(0);
                        relay_state = 0;
                        log_event("Relay deactivated");
                    }
                }

                char log_message[100];
                snprintf(log_message, sizeof(log_message), "Raw: %d, mT: %.2f, Threshold: %d", raw_value, mT, threshold_exceeded);
                log_event(log_message);
                break; // Exit retry loop on success
            } else {
                char log_message[100];
                snprintf(log_message, sizeof(log_message), "I2C read failed, retry %d", retries + 1);
                log_event(log_message);
                gpioWrite(RELAY_GPIO, 0); // Deactivate relay on I2C failure
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retrying
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "I2C read failed after %d retries", MAX_RETRIES);
            log_event(log_message);
            gpioWrite(RELAY_GPIO, 0); // Deactivate relay on timeout
            program_running = 0; // Exit the loop
        }

        gpioDelay(POLL_DELAY_MS * 1000); // Delay for 100ms
    }

    cleanup();
    return 0;
}

