#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int setup_gpio(int pin);
int setup_socket(int port);
int handle_client(int client_fd);
int log_event(const char *event);
void cleanup(int signum);

// Function to set up the GPIO pin
int setup_gpio(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 0); // Initialize relay to OFF state
    return 0;
}

// Function to set up the TCP socket
int setup_socket(int port) {
    int server_fd;
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(port);

    // Forcefully attaching socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        return -1;
    }
    return server_fd;
}

// Function to handle client connection
int handle_client(int client_fd) {
    char buffer[1024] = {0};
    int valread;

    while (program_running) {
        valread = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
        if (valread > 0) {
            buffer[valread] = '\0';
            printf("Received: %s\n", buffer);

            if (strcmp(buffer, "ON") == 0) {
                if (gpioWrite(GPIO_PIN, 1) != 0) {
                    log_event("GPIO write failed");
                }
                log_event("Relay ON");
            } else if (strcmp(buffer, "OFF") == 0) {
                if (gpioWrite(GPIO_PIN, 0) != 0) {
                    log_event("GPIO write failed");
                }
                log_event("Relay OFF");
            } else {
                log_event("Invalid command");
            }
        } else if (valread == 0) {
            printf("Client disconnected\n");
            break;
        } else {
            perror("recv failed");
            break;
        }
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event);
        fflush(log_file); // Ensure immediate write
        return 0;
    } else {
        fprintf(stderr, "Log file not opened\n");
        return -1;
    }
}

// Function to handle signals for graceful shutdown
void cleanup(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    program_running = 0;

    // Turn off the relay
    gpioWrite(GPIO_PIN, 0);

    // Close the socket
    if (server_fd != -1) {
        close(server_fd);
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    int client_fd;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};
    int opt = 1;

    // Register signal handlers
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Initialize GPIO
    if (setup_gpio(GPIO_PIN) != 0) {
        return 1;
    }

    // Setup socket
    server_fd = setup_socket(PORT);
    if (server_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        close(server_fd);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    while (program_running) {
        // Accept incoming connections
        if ((client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_event("Socket accept failed");
            continue; // Continue listening
        }

        printf("Connection accepted\n");

        // Handle the client
        handle_client(client_fd);

        // Close the client connection
        close(client_fd);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

