int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(int i2c_handle, uint8_t *data);
int validate_crc(const uint8_t *data, int len, uint8_t polynomial);
float calculate_flow_rate(const uint8_t *data);
void control_relay(int state);
void log_flow_data(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int valid;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c(int address) {
    int handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to validate CRC-8
int validate_crc(const uint8_t *data, int len, uint8_t polynomial) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return (crc == 0);
}

