            continue; // Skip to the next iteration
        }

        // Read sensor data
        if (read_sensor_data(i2c_handle1, sensor1_data) != 0) {
            fprintf(stderr, "Error reading sensor 1 data.\n");
            continue; // Skip to the next iteration
        }
        if (read_sensor_data(i2c_handle2, sensor2_data) != 0) {
            fprintf(stderr, "Error reading sensor 2 data.\n");
            continue; // Skip to the next iteration
        }

        // Validate CRC
        if (!validate_crc(sensor1_data, 2, CRC_POLYNOMIAL) || !validate_crc(sensor2_data, 2, CRC_POLYNOMIAL)) {
            fprintf(stderr, "CRC validation failed for either sensor.\n");
            continue; // Skip to the next iteration
        }

        // Calculate flow rates
        float flow1 = calculate_flow_rate(sensor1_data);
        float flow2 = calculate_flow_rate(sensor2_data);

        // Control relay
        if (flow1 < FLOW_THRESHOLD_LOW || flow2 < FLOW_THRESHOLD_LOW) {
            control_relay(1); // Energize relay
        } else {
            control_relay(0); // De-energize relay
        }

        // Log flow data
        log_flow_data(flow1, flow2);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

