#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define RAIN_DETECTED_THRESHOLD 3
#define MOTOR_RUN_TIME 5000 // 5 seconds in microseconds
#define DEBOUNCE_DELAY 200 // Debounce delay in milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void control_motor(int start);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO pin configurations
typedef struct {
    int rain_sensor_pin;
    int motor_ena_pin;
    int motor_in1_pin;
    int motor_in2_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
void control_motor(int start) {
    gpioWrite(MOTOR_ENA_PIN, start ? 1 : 0);
    gpioWrite(MOTOR_IN1_PIN, start ? 1 : 0);
    gpioWrite(MOTOR_IN2_PIN, start ? 0 : 1);
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

// Cleanup function to stop the motor and terminate pigpio
void cleanup() {
    log_event("Stopping motor...");
    control_motor(0); // Stop the motor
    log_event("Terminating pigpio...");
    gpioTerminate();
    log_event("Exiting program...");
    closelog();
    exit(0);
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    int rain_detected = 0;
    int rain_count = 0;

    while (program_running) {
        int rain_sensor_value = read_rain_sensor();

        if (rain_sensor_value == 0) { // Rain detected (LOW)
            rain_count++;
            if (rain_count >= RAIN_DETECTED_THRESHOLD) {
                log_event("Rain detected, starting motor sequence");
                control_motor(1); // Start the motor
                gpioDelay(MOTOR_RUN_TIME); // Run the motor for 5 seconds
                control_motor(0); // Stop the motor
                rain_count = 0; // Reset the count
            }
        } else {
            rain_count = 0; // Reset the count if no rain is detected
        }

        gpioDelay(DEBOUNCE_DELAY); // Debounce delay
    }

    cleanup();
    return 0;
}

