#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_GPIO 21
#define UNLOCK_BUTTON_GPIO 22
#define SERVO_GPIO 18

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 5

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        printf("\nCaught signal, shutting down...\n");
    }
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width) {
    if (gpioServo(gpio, pulse_width) != 0) {
        fprintf(stderr, "Error setting servo pulse width for GPIO %d\n", gpio);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to lock the door
int lock_door() {
    if (set_servo_pulse_width(SERVO_GPIO, SERVO_MAX_PULSE_WIDTH) != 0) {
        return -1; // Indicate failure
    }
    printf("Door locked\n");
    return 0; // Indicate success
}

// Function to unlock the door
int unlock_door() {
    if (set_servo_pulse_width(SERVO_GPIO, SERVO_MIN_PULSE_WIDTH) != 0) {
        return -1; // Indicate failure
    }
    printf("Door unlocked\n");
    return 0; // Indicate success
}

// Function to check button state
int check_button(int gpio) {
    int button_state = gpioRead(gpio);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    return button_state;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_GPIO, PI_INPUT);
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set pull-up resistors for the buttons
    gpioSetPullUpDown(LOCK_BUTTON_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_GPIO, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (check_button(LOCK_BUTTON_GPIO)) {
            if (lock_door() != 0) {
                fprintf(stderr, "Error locking door\n");
            }
        }

        // Check unlock button
        if (check_button(UNLOCK_BUTTON_GPIO)) {
            if (unlock_door() != 0) {
                fprintf(stderr, "Error unlocking door\n");
            }
        }

        // Small delay to reduce CPU usage
        usleep(10000); // 10 milliseconds
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_servo_pulse_width(SERVO_GPIO, 0); // Stop the servo
    if (set_servo_pulse_width(SERVO_GPIO, SERVO_MIN_PULSE_WIDTH) != 0) {
        fprintf(stderr, "Error setting servo pulse width for shutdown\n");
    }
    gpioTerminate(); // Terminate pigpio

    return 0;
}

