#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define PIR_THRESHOLD 500 // Adjust this value based on your PIR sensor

// Global variables for signal handling
volatile sig_atomic_t terminate = 0;
int server_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int initialize_socket();
void handle_client(int client_fd);
void handle_command(const char *command);
void log_message(int priority, const char *message, ...);
void cleanup();
void signal_handler(int signum);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to initialize the socket
int initialize_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message(LOG_ERR, "Socket creation failed");
        return -1;
    }

    // Forcefully attaching socket to the port 5000
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message(LOG_ERR, "Setsockopt failed");
        close(server_fd);
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Forcefully attaching socket to the port 5000
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message(LOG_ERR, "Bind failed");
        close(server_fd);
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        log_message(LOG_ERR, "Listen failed");
        close(server_fd);
        return -1;
    }
    log_message(LOG_INFO, "Server listening on port 5000");
    return 0;
}

// Function to handle client connection
void handle_client(int client_fd) {
    char buffer[1024] = {0};
    int valread;

    while ((valread = recv(client_fd, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[valread] = '\0';
        printf("Received: %s\n", buffer);
        handle_command(buffer);
    }

    if (valread == 0) {
        printf("Client disconnected\n");
    } else if (valread < 0) {
        perror("recv failed");
    }

    close(client_fd);
}

// Function to handle commands
void handle_command(const char *command) {
    if (strncmp(command, "the library's API call", 20) == 0) {
        int angle = atoi(command + 20);
        if (angle >= 0 && angle <= 180) {
            int pulse_width_us = (int)(((float)angle / 180.0) * PWM_PERIOD_US) * 2000; // 2ms pulse width
            gpioPWM(SERVO_GPIO, pulse_width_us);
            char response[100];
            snprintf(response, sizeof(response), "Servo set to %d degrees", angle);
            log_message(LOG_INFO, response);
            send(client_fd, response, strlen(response), 0);
        } else {
            log_message(LOG_ERR, "Invalid angle in command");
            const char *response = "Invalid angle";
            send(client_fd, response, strlen(response), 0);
        }
    } else if (strcmp(command, "PIR") == 0) {
        int pir_state = gpioRead(PIR_GPIO);
        char response[50];
        snprintf(response, sizeof(response), "PIR: %d", pir_state);
        log_message(LOG_INFO, response);
        send(client_fd, response, strlen(response), 0);
    } else {
        log_message(LOG_ERR, "Unknown command");
        const char *response = "Unknown command";
        send(client_fd, response, strlen(response), 0);
    }
}

// Function to log messages
void log_message(int priority, const char *message, ...) {
    va_list args;
    va_start(args, message);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
    char log_entry[256];
    snprintf(log_entry, sizeof(log_entry), "%s [%s] ", timestamp, message);
    vsyslog(priority, log_entry, args);
    va_end(args);
}

// Function to perform cleanup
void cleanup() {
    log_message(LOG_INFO, "Cleaning up...");
    if (server_fd != -1) {
        close(server_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    log_message(LOG_INFO, "Cleanup complete");
    closelog();
    exit(0);
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        terminate = 1;
        cleanup();
    }
}

int main() {
    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_message(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize socket
    if (initialize_socket() != 0) {
        log_message(LOG_ERR, "Socket initialization failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Open log file
    log_file = fopen("security.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        log_message(LOG_ERR, "Failed to open log file");
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "Security system started");

    // Accept incoming connections
    fd_set readfds;
    int client_fd;
    struct sockaddr_in address;
    int addrlen = sizeof(address);

    readfds.fd = server_fd;
    FD_ZERO(&readfds);
    FD_SET(server_fd, &readfds);

    while (!terminate) {
        int select_result = select(server_fd + 1, &readfds, NULL, NULL, NULL);

        if (select_result == -1) {
            log_message(LOG_ERR, "Select error");
            break;
        } else if (select_result > 0) {
            if (FD_ISSET(server_fd, &readfds)) {
                client_fd = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen);
                if (client_fd < 0) {
                    log_message(LOG_ERR, "Accept failed");
                    continue; // Continue listening for other connections
                }
                log_message(LOG_INFO, "Client connected");
                handle_client(client_fd);
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

