#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL 2 // seconds
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_gpio();
int init_logging();
int read_lux(float *lux);
int control_relay(int state);
int log_data(float lux);
void cleanup();
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_address;
    int relay_pin;
    float lux_threshold;
} sensor_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO mode\n");
        return -1;
    }
    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_lux(float *lux) {
    char buf[2];
    int result;

    // Send start measurement command (High Resolution Mode)
    result = i2cWriteByte(i2c_handle, 0x10); // 0x10 for high resolution mode
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    // Wait for measurement (at least 120ms)
    gpioDelay(120000); // 120ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2; // BH1750 datasheet conversion

    return 0;
}

// Control the grow light relay
int control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Lux: %.2f\n", timestamp, lux);
        fflush(log_file); // Ensure data is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    control_relay(0); // Deactivate relay
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
    cleanup();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int retries = 0;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_lux(&lux) == 0) {
                log_data(lux);
                if (lux < LUX_THRESHOLD) {
                    control_relay(1); // Activate relay
                } else {
                    control_relay(0); // Deactivate relay
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Sensor read failed, retrying...\n");
                retries++;
                gpioDelay(100000); // Wait 100ms before retrying
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Sensor read failed after %d retries. Skipping relay control.\n", MAX_RETRIES);
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Wait for the next sample
    }

    cleanup();
    return 0;
}

