#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Define constants
#define MAX_RETRIES 3
#define TIMEOUT_US 1000000 // 1 second timeout
#define DEFAULT_THRESHOLD 1000
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 500

// Global variables
static volatile int running = 1;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int tare_count = 0;
static int tare_sum = 0;

// Function prototypes
int read_hx711(int sck_pin, int dos_pin);
double calculate_weight(int raw_value, double scale);
void control_solenoid(int solenoid_pin, int state, int duration_ms);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to read HX711
int read_hx711(int sck_pin, int dos_pin) {
    int i, bit;
    long value = 0;

    // Wait for DOUT to go LOW
    int timeout_counter = 0;
    while (gpioRead(dos_pin) == 1 && timeout_counter < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 us
        timeout_counter++;
    }

    if (timeout_counter >= TIMEOUT_US) {
        log_message(LOG_ERR, "Timeout waiting for HX711 DOUT to go LOW");
        return -1; // Indicate error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // Short delay
        value = value << 1;
        if (gpioRead(dos_pin)) {
            value++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // Short delay
    }

    // One extra clock pulse to select Channel A gain 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // Short delay
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // Short delay

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return (int)value;
}

// Function to calculate weight
double calculate_weight(int raw_value, double scale) {
    return (double)raw_value / scale;
}

// Function to control the solenoid
void control_solenoid(int solenoid_pin, int state, int duration_ms) {
    gpioWrite(solenoid_pin, state);
    gpioDelay(duration_ms * 1000); // Convert ms to us
    gpioWrite(solenoid_pin, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message(LOG_INFO, "Received signal, shutting down...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
    exit(0);
}

// Function to log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

int main(int argc, char *argv[]) {
    int opt;
    int i;
    int raw_value;
    double weight;
    int tare_sum_local;
    int tare_count_local;
    int retry_count;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:d:t:")) != -1) {
        switch (opt) {
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 't':
                tare_count = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale] [-d duration] [-t tare_count]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid to initial state (LOW)
    gpioWrite(SOLENOID_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    tare_sum_local = 0;
    tare_count_local = 0;
    for (i = 0; i < tare_count; i++) {
        retry_count = 0;
        while (retry_count < MAX_RETRIES) {
            raw_value = read_hx711(HX711_SCK, HX711_DOUT);
            if (raw_value != -1) {
                tare_sum_local += raw_value;
                tare_count_local++;
                break; // Exit retry loop on success
            } else {
                log_message(LOG_ERR, "Error reading HX711 during tare, retrying...");
                retry_count++;
                gpioDelay(1000); // Wait 1 ms before retrying
            }
        }
        if (retry_count == MAX_RETRIES) {
            log_message(LOG_ERR, "Failed to tare HX711 after %d retries, exiting.", MAX_RETRIES);
            gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
            gpioTerminate(); // Terminate pigpio
            closelog();
            return 1;
        }
    }
    tare_sum_local /= tare_count_local;
    log_message(LOG_INFO, "Tare complete, average = %d", tare_sum_local);

    // Main loop
    while (running) {
        tare_sum_local = 0;
        tare_count_local = 0;
        for (i = 0; i < 5; i++) {
            retry_count = 0;
            while (retry_count < MAX_RETRIES) {
                raw_value = read_hx711(HX711_SCK, HX711_DOUT);
                if (raw_value != -1) {
                    tare_sum_local += raw_value;
                    tare_count_local++;
                    break; // Exit retry loop on success
                } else {
                    log_message(LOG_ERR, "Error reading HX711, retrying...");
                    retry_count++;
                    gpioDelay(1000); // Wait 1 ms before retrying
                }
            }
            if (retry_count == MAX_RETRIES) {
                log_message(LOG_ERR, "Failed to read HX711 after %d retries, exiting.", MAX_RETRIES);
                running = 0; // Exit the loop
                break;
            }
        }

        if (tare_count_local > 0) {
            weight = calculate_weight(tare_sum_local, scale);
            char weight_str[20];
            snprintf(weight_str, sizeof(weight_str), "Weight: %.2f grams", weight);
            log_message(LOG_INFO, weight_str);

            if (weight > 1000) {
                log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid.");
                control_solenoid(SOLENOID_PIN, 1, duration);
            }
        } else {
            log_message(LOG_ERR, "Invalid tare count, skipping weight reading.");
        }

        gpioDelay(duration_ms * 1000); // Delay for specified duration
    }

    // Cleanup
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog

    return 0;
}

