// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Set relay to OFF initially
    log_message(LOG_INFO, "GPIO initialized and relay set to OFF");
    return 0;
}

// Function to initialize the MQTT client
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, NULL);
    mosquitto_message_callback_set(mosq, NULL);
    mosquitto_subscribe_callback_set(mosq, NULL);

    int rc = mosquitto_connect(mosq, "localhost", MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        return -1;
    }

    mosquitto_loop_start(mosq);
    log_message(LOG_INFO, "MQTT client connected to broker");
    return 0;
}

// Function to handle MQTT messages
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        char payload[256];
        strncpy(payload, (char *)message->payload, sizeof(payload) - 1);
        payload[sizeof(payload) - 1] = '\0'; // Ensure null termination

        if (strcmp(payload, "ON") == 0) {
            log_message(LOG_INFO, "Received ON command, setting relay ON");
            gpioWrite(GPIO_PIN, 1); // Set relay to ON
        } else if (strcmp(payload, "OFF") == 0) {
            log_message(LOG_INFO, "Received OFF command, setting relay OFF");
            gpioWrite(GPIO_PIN, 0); // Set relay to OFF
        } else {
            log_message(LOG_WARNING, "Received invalid command");
        }
    } else {
        log_message(LOG_WARNING, "Received empty message");
    }
}

// Function to handle MQTT connection
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_message(LOG_INFO, "MQTT client connected to broker");
    } else {
        log_message(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_connack_string(result));
    }
}

// Function to handle MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    log_message(LOG_INFO, "MQTT client disconnected with code %d", rc);
}

// Function to handle MQTT reconnection
void on_reconnect(struct mosquitto *mosq, void *userdata, int *count) {
    log_message(LOG_INFO, "Reconnecting to MQTT broker...");
