#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse width limits (in microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths (in microseconds)
#define TARGET_PULSE_WIDTH1 1000
#define TARGET_PULSE_WIDTH2 1500
#define TARGET_PULSE_WIDTH3 2000
#define TARGET_PULSE_WIDTH4 500
#define TARGET_PULSE_WIDTH5 2500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCtrl+C detected. Cleaning up and exiting...\n");
}

// Function to set the pulse width for a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width_us) {
    if (gpioPWM(gpio_pin, pulse_width_us) != 0) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to move a servo to a specific position
int move_servo(int gpio_pin, int target_pulse_width_us) {
    if (target_pulse_width_us < MIN_PULSE_WIDTH || target_pulse_width_us > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Target pulse width %d is out of range (%d-%d us)\n", target_pulse_width_us, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }

    if (set_servo_pulse_width(gpio_pin, target_pulse_width_us) != 0) {
        return -1;
    }

    printf("Servo on GPIO %d moved to pulse width %d us\n", gpio_pin, target_pulse_width_us);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set GPIO pins to output mode
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set PWM frequency to 50 Hz
    gpioSetPWMfrequency(SERVO1_PIN, 50);
    gpioSetPWMfrequency(SERVO2_PIN, 50);
    gpioSetPWMfrequency(SERVO3_PIN, 50);
    gpioSetPWMfrequency(SERVO4_PIN, 50);
    gpioSetPWMfrequency(SERVO5_PIN, 50);

    // Move each servo to its target position
    if (move_servo(SERVO1_PIN, TARGET_PULSE_WIDTH1) != 0) {
        gpioTerminate();
        return 1;
    }
    if (move_servo(SERVO2_PIN, TARGET_PULSE_WIDTH2) != 0) {
        gpioTerminate();
        return 1;
    }
    if (move_servo(SERVO3_PIN, TARGET_PULSE_WIDTH3) != 0) {
        gpioTerminate();
        return 1;
    }
    if (move_servo(SERVO4_PIN, TARGET_PULSE_WIDTH4) != 0) {
        gpioTerminate();
        return 1;
    }
    if (move_servo(SERVO5_PIN, TARGET_PULSE_WIDTH5) != 0) {
        gpioTerminate();
        return 1;
    }

    // Stop PWM and release resources
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    gpioTerminate();

    return 0;
}

