#include <math.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_A_PWM 22
#define MOTOR_A_ENCODER_A_A 4
#define MOTOR_A_ENCODER_A_B 5

// Motor B
#define MOTOR_B_IN3 23
#define MOTOR_B_IN4 22
#define MOTOR_B_PWM 22
#define MOTOR_B_ENCODER_B_A 6
#define MOTOR_B_ENCODER_B_B 12

// Target RPM
#define TARGET_RPM 50.0

// Stall detection timeout (seconds)
#define STALL_TIMEOUT 2.0

// Global variables
volatile int motor_a_ticks_a = 0;
volatile int motor_a_ticks_b = 0;
volatile int motor_b_ticks_a = 0;
volatile int motor_b_ticks_b = 0;
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int encoder_a_last_count = 0;
volatile int encoder_b_last_count = 0;
volatile int encoder_a_stalled = 0;
volatile int encoder_b_stalled = 0;

// PID gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// PWM frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Function prototypes
void motor_a_forward();
void motor_a_backward();
void motor_a_stop();
void motor_b_forward();
void motor_b_backward();
void motor_b_stop();
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int ticks);
double calculate_error(double target_rpm, double actual_rpm);
double calculate_proportional(double error);
double calculate_integral(double error);
double calculate_derivative(double error);
double calculate_pid(double proportional, double integral, double derivative);
void set_motor_speed(int motor_num, int pwm_pin, int direction_pin, int duty_cycle);
void signal_handler(int signal);

// Motor control functions
void motor_a_forward() {
    gpioWrite(MOTOR_A_IN1, 1);
    gpioWrite(MOTOR_A_IN2, 0);
    set_motor_speed(0, MOTOR_A_PWM, MOTOR_A_IN1, MOTOR_A_IN2);
}

void motor_a_backward() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 1);
    set_motor_speed(0, MOTOR_A_PWM, MOTOR_A_IN1, MOTOR_A_IN2);
}

void motor_a_stop() {
    gpioWrite(MOTOR_A_IN1, 0);
    gpioWrite(MOTOR_A_IN2, 0);
    set_motor_speed(0, MOTOR_A_PWM, MOTOR_A_IN1, MOTOR_A_IN2);
}

void motor_b_forward() {
    gpioWrite(MOTOR_B_IN3, 1);
    gpioWrite(MOTOR_B_IN4, 0);
    set_motor_speed(1, MOTOR_B_PWM, MOTOR_B_IN3, MOTOR_B_IN4);
}

void motor_b_backward() {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 1);
    set_motor_speed(1, MOTOR_B_PWM, MOTOR_B_IN3, MOTOR_B_IN4);
}

void motor_b_stop() {
    gpioWrite(MOTOR_B_IN3, 0);
    gpioWrite(MOTOR_B_IN4, 0);
    set_motor_speed(1, MOTOR_B_PWM, MOTOR_B_IN3, MOTOR_B_IN4);
}

// Set motor speed using PWM and direction
void set_motor_speed(int motor_num, int pwm_pin, int direction_pin, int duty_cycle) {
    if (motor_num == 0) {
        gpioPWM(MOTOR_A_PWM, duty_cycle);
        gpioWrite(MOTOR_A_IN1, (duty_cycle > 128) ? 1 : 0);
        gpioWrite(MOTOR_A_IN2, (duty_cycle > 128) ? 0 : 1);
    } else if (motor_num == 1) {
        gpioPWM(MOTOR_B_PWM, duty_cycle);
        gpioWrite(MOTOR_B_IN3, (duty_cycle > 128) ? 1 : 0);
        gpioWrite(MOTOR_B_IN4, (duty_cycle > 128) ? 0 : 1);
    }
}

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;
