#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define DEBOUNCE_TIMEOUT_US 1000000 // 1 second
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define HYSTERESIS 0.5
#define LOG_FILE "water_flow.log"

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
double flow_rate = 0.0;
double last_flow_rate = 0.0;
int solenoid_state = 1; // 1 = open, 0 = closed
FILE *log_file = NULL;

// Function prototypes
void *flow_monitor_thread(void *arg);
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data);
void log_data(double flow_rate, int solenoid_state);
void signal_handler(int signal);

// Function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to log data to file
void log_data(double flow_rate, int solenoid_state)
{
    char timestamp[20];
    get_timestamp(timestamp);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, Flow Rate: %.2f LPM, Solenoid State: %s\n", timestamp, flow_rate, solenoid_state ? "closed" : "open");
        fflush(log_file); // Ensure data is written to disk immediately
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal)
{
    printf("Signal received: %d. Cleaning up and exiting.\n", signal);

    // Cleanup resources
    if (log_file != NULL)
    {
        fclose(log_file);
    }
    gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    exit(0);
}

// Function to monitor water flow
void *flow_monitor_thread(void *arg)
{
    int last_flow_rate_local = 0.0;
    while (1)
    {
        // Debounce the pulse count
        gpioDelay(DEBOUNCE_TIMEOUT_US); // Wait for the debounce timeout

        // Read the pulse count
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset the pulse count

        // Calculate the flow rate
        if (current_pulse_count > last_pulse_count)
        {
            double flow_rate_local = (double)current_pulse_count * 60.0 / DEBOUNCE_TIMEOUT_US; // LPM
            flow_rate = flow_rate * 0.9 + flow_rate_local * 0.1; // Apply hysteresis
        }
        else
        {
            flow_rate = last_flow_rate_local;
        }

        last_flow_rate_local = flow_rate;

        // Log the data
        log_data(flow_rate, solenoid_state);

        // Control the solenoid
        if (flow_rate > LPM_THRESHOLD_HIGH && solenoid_state == 1)
        {
            gpioWrite(SOLENOID_GPIO, 0); // Close the solenoid
            solenoid_state = 0;
            printf("Flow rate exceeded threshold. Closing solenoid.\n");
        }
        else if (flow_rate < LPM_THRESHOLD_LOW && solenoid_state == 0)
        {
            gpioWrite(SOLENOID_GPIO, 1); // Open the solenoid
            solenoid_state = 1;
            printf("Flow rate below threshold. Opening solenoid.\n");
        }

        // Sleep for 1 second
        gpioDelay(1000000); // 1 second
    }
    return NULL;
}

// Interrupt service routine for pulse counting
void pulse_counter(int gpio, int level, uint32_t tick, void *user_data)
{
    (void)gpio; // unused
    (void)tick; // unused
    (void)user_data; // unused
    (void)level; // unused
    pthread_mutex_lock(&pulse_mutex);
    pulse_count++;
    pthread_mutex_unlock(&pulse_mutex);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Set initial solenoid state
    gpioWrite(SOLENOID_GPIO, solenoid_state);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create the flow monitoring thread
    pthread_t flow_thread;
    if (pthread_create(&flow_thread, NULL, flow_monitor_thread, NULL) != 0)
    {
        fprintf(stderr, "Error creating flow monitoring thread\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Wait for the flow monitoring thread to finish (which it won't, but it's good practice)
    pthread_join(flow_thread, NULL);

    // Cleanup resources (should not reach here normally due to signal handler)
    fclose(log_file);
    gpioWrite(SOLENOID_GPIO, 1); // Open solenoid
    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    return 0;
}

