#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVO_MIN_PULSE_WIDTH 1000
#define DEFAULT_SERVO_MAX_PULSE_WIDTH 2000

// HX711 GPIO pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24

// Servo motor GPIO pin
#define SERVO_PIN 18

// TCP port
#define PORT 12345

// API call URL
#define API_URL "http://api.example.com/dispense"

// Timeout for HX711 readings (in attempts)
#define HX711_TIMEOUT 100

// Structure to hold configuration data
typedef struct {
    float calibration_factor;
    int servo_min_pulse_width;
    int servo_max_pulse_width;
} Config;

// Global variables
int server_socket = -1;
FILE *log_file = NULL;
Config config;

// Function prototypes
int initialize_gpio();
int read_hx711(int *raw_value);
float calibrate_weight(int raw_value, float calibration_factor);
int map_weight_to_pulse_width(float target_weight, float calibration_factor, int min_pulse_width, int max_pulse_width);
int send_api_call(float target_weight, int pulse_width);
int receive_api_response(float *actual_weight);
int log_event(float target_weight, float actual_weight, const char *error_message);
void signal_handler(int signal);
int read_config(Config *config);

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    return 0;
}

// Function to read from HX711
int read_hx711(int *raw_value) {
    int attempts = 0;
    int data = 0;

    while (attempts < HX711_TIMEOUT) {
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Small delay for stable clock
        data = gpioRead(HX711_DATA_PIN);
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Small delay for stable clock

        if (data == 0 || data == 1) {
            *raw_value = data;
            return 0; // Success
        } else {
            attempts++;
            if (attempts >= HX711_TIMEOUT) {
                fprintf(stderr, "HX711 timeout after %d attempts\n", HX711_TIMEOUT);
                return 1; // Timeout
            }
            gpioDelay(1); // Small delay before retry
        }
    }

    fprintf(stderr, "HX711 read failed after %d attempts\n", HX711_TIMEOUT);
    return 1; // Failure
}

// Function to calibrate weight
float calibrate_weight(int raw_value, float calibration_factor) {
    return (float)raw_value * calibration_factor;
}

// Function to map weight to pulse width
int map_weight_to_pulse_width(float target_weight, float calibration_factor, int min_pulse_width, int max_pulse_width) {
    float normalized_weight = target_weight / 1000.0; // Assuming target weight is in grams
    float pulse_width = min_pulse_width + (normalized_weight * (max_pulse_width - min_pulse_width));
    return (int)pulse_width;
}

// Function to send API call
int send_api_call(float target_weight, int pulse_width) {
    char json_data[256];
    snprintf(json_data, sizeof(json_data), "{\"target_weight\": %.2f, \"pulse_width\": %d}", target_weight, pulse_width);

    int sock = 0;
    struct sockaddr_in serv_addr;

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return 1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, API_URL, &serv_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sock);
        return 1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("Connection Failed");
        close(sock);
        return 1;
    }

    if (send(sock, json_data, strlen(json_data), 0) < 0) {
        perror("Send failed");
        close(sock);
        return 1;
    }

    close(sock);
    return 0;
}

// Function to receive API response
int receive_api_response(float *actual_weight) {
    int sock = 0, port = PORT;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("Socket creation error");
        return 1;
    }

