#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO 17

// Global variables
static volatile int running = 1;
static int debounce_delay = 50; // Default debounce delay in milliseconds

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_relay(int current_state);
int log_relay_state(int state);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int relay_state;
    int last_relay_state;
} ProgramState;

ProgramState state = {0, 0};

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_delay = atoi(optarg);
                if (debounce_delay <= 0) {
                    fprintf(stderr, "Error: Invalid debounce delay. Using default value of 50ms.\n");
                    debounce_delay = 50;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_delay]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected) {
            // Debounce
            gpioDelay(debounce_delay * 1000); // Convert ms to microseconds
            if (read_touch_sensor() == 1) {
                int new_relay_state = toggle_relay(state.relay_state);
                state.relay_state = new_relay_state;
                state.last_relay_state = new_relay_state;

                if (new_relay_state != state.relay_state) {
                    log_relay_state(new_relay_state);
                }
            }
        }

        gpioDelay(1000); // Check every 1ms
    }

    // Cleanup and exit
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
    printf("Relay control stopped.\n");
    return 0;
}

// Initializes the pigpio library and sets the GPIO modes.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF

    return 0;
}

// Reads the touch sensor state.
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_GPIO);
}

// Toggles the relay state.
int toggle_relay(int current_state) {
    int new_state = !current_state;
    gpioWrite(RELAY_GPIO, new_state);
    return new_state;
}

// Logs the relay state to the console with a timestamp.
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    return 0;
}

// Signal handler for graceful shutdown.
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;

    // Turn off relay
    gpioWrite(RELAY_GPIO, 0);

    // Release resources
    gpioTerminate();

    exit(0);
}

