// Define the GPIO pin for the servo
#define SERVO_PIN 18

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Define the minimum and maximum pulse widths (us)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Global variable to store the current angle
int current_angle = 90;

// Function prototypes
int set_servo_angle(int angle);
void handle_key_press(char key);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioPWM(SERVO_PIN, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0); // Exit the program
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    // Calculate the pulse width based on the angle
    int pulse_width = MIN_PULSE_WIDTH + (angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);

    // Set the pulse width using gpioPWM
    if (gpioPWM(SERVO_PIN, pulse_width) != 0) {
        fprintf(stderr, "Error setting PWM: %d\n", gpioPWM(SERVO_PIN, pulse_width));
        return -1; // Indicate an error
    }

    // Print the current angle
    printf("Current angle: %d degrees, Pulse width: %d us\n", angle, pulse_width);

    return 0; // Indicate success
}

// Function to handle key presses
void handle_key_press(char key) {
    switch (key) {
        case '+':
            current_angle += 10;
            if (current_angle > 180) {
                current_angle = 180;
            }
            break;
        case '-':
            current_angle -= 10;
            if (current_angle < 0) {
                current_angle = 0;
            }
            break;
        case 'q':
            // Stop PWM and terminate pigpio
            gpioPWM(SERVO_PIN, 0);
            gpioTerminate();
            exit(0);
        default:
            // Ignore invalid key presses
            break;
    }

    // Set the servo angle
    if (set_servo_angle(current_angle) != 0) {
        fprintf(stderr, "Error setting servo angle.\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pin to output mode
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(SERVO_PIN, 1000); // Range of 0-1000

    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Main loop to read key presses
    char key;
    while (1) {
        // Read a key press from the terminal
        key = getchar();

        // Handle the key press
        handle_key_press(key);

        // Read the next key press
        key = getchar();
    }

    // The program should never reach here, but include this for completeness
    gpioTerminate();
    return 0;
}

