#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/time.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_WINDOW_MS 2
#define LOG_INTERVAL_SEC 5
#define LOG_FILE "motor_rpm.log"

// Global variables
volatile int pulse_count = 0;
volatile unsigned long last_pulse_time = 0;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void pulse_callback(int gpio, int level, uint32_t tick);
double calculate_rpm();
void log_rpm(double rpm);
void print_rpm();
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int log_file_open;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }
    state.gpio_initialized = 1;

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s. Exiting.\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    state.log_file_open = 1;

    // Main loop
    while (1) {
        double rpm = calculate_rpm();
        if (rpm >= 0) {
            log_rpm(rpm);
            print_rpm();
        } else {
            fprintf(stderr, "Failed to calculate RPM. Retrying.\n");
        }
        sleep(LOG_INTERVAL_SEC);
    }

    return 0;
}

// Initialize pigpio and configure GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set up interrupt callback for rising edge detection
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick) {
    unsigned long current_time = gpioTick();
    if (level == 1) { // Rising edge
        if (current_time - last_pulse_time > DEBOUNCE_WINDOW_MS * 1000) { // Debounce
            pulse_count++;
            last_pulse_time = current_time;
        }
    }
}

// Calculate RPM based on pulse count
double calculate_rpm() {
    if (pulse_count == 0) {
        return 0.0;
    }

    double time_interval = 5.0; // seconds
    double pulses_per_second = (double)pulse_count / time_interval;
    double rpm = pulses_per_second * 60.0; // Convert to RPM

    return rpm;
}

// Log RPM to file
void log_rpm(double rpm) {
    if (!state.log_file_open) {
        fprintf(stderr, "Log file not open. Cannot log RPM.\n");
        return;
    }

    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    fprintf(log_file, "%s,%.2f\n", buf, rpm);
    fflush(log_file); // Ensure data is written to disk
}

// Print RPM to stdout
void print_rpm() {
    double rpm = calculate_rpm();
    if (rpm >= 0) {
        printf("RPM: %.2f\n", rpm);
    } else {
        fprintf(stderr, "Failed to calculate RPM.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Disable interrupt callback
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Release GPIO line
    gpioTerminate();

    // Close log file
    if (state.log_file_open) {
        fclose(log_file);
    }

    // Exit program
    exit(0);
}

