#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Configuration
#define RFID_SPI_CHANNEL 0
#define RFID_SPI_SPEED 100000 // 100kHz
#define RFID_READ_COMMAND 0x01 // Example command
#define RFID_READ_LENGTH 10
#define LOCK_1_GPIO 17
#define LOCK_2_GPIO 27
#define BUTTON_GPIO 22
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
int server_socket;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_read_rfid(unsigned char *tag);
int validate_tag(const unsigned char *tag);
void lock_and_unlock(int lock1_gpio, int lock2_gpio);
void log_event(const char *event_type);
void signal_handler(int signal);
int setup_spi();
int setup_socket();
int setup_logging();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    char server_ip[20];
    int server_port;
    char log_file[50];
} Config;

Config config = {"127.0.0.1", SERVER_PORT, LOG_FILE};

int main() {
    unsigned char rfid_tag[RFID_READ_LENGTH];
    int button_pressed = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Setup signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup logging
    if (setup_logging() != 0) {
        fprintf(stderr, "Logging setup failed\n");
        cleanup();
        return 1;
    }

    // Setup SPI
    if (setup_spi() != 0) {
        fprintf(stderr, "SPI setup failed\n");
        cleanup();
        return 1;
    }

    // Setup socket
    if (setup_socket() != 0) {
        fprintf(stderr, "Socket setup failed\n");
        cleanup();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read RFID tag
        if (spi_read_rfid(rfid_tag) == 0) {
            // Validate tag
            if (validate_tag(rfid_tag)) {
                // Button press
                if (gpioRead(BUTTON_GPIO) == 0) {
                    button_pressed = 1;
                } else {
                    button_pressed = 0;
                }

                // Check if button is pressed and tag is valid
                if (button_pressed && validate_tag(rfid_tag)) {
                    // Log event: Successful entry
                    log_event("Successful entry");
                    lock_and_unlock(LOCK_1_GPIO, LOCK_2_GPIO);
                } else {
                    // Log event: Invalid tag or button press
                    log_event("Invalid tag or button press");
                }
            } else {
                // Log event: No tag present
                log_event("No tag present");
            }
        } else {
            // Log event: RFID read failure
            log_event("RFID read failure");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Door access control system stopped.\n");
    return 0;
}

// Function to read RFID tag from SPI
int spi_read_rfid(unsigned char *tag) {
    char tx_buf[1] = {RFID_READ_COMMAND};
    char rx_buf[RFID_READ_LENGTH];

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, RFID_READ_LENGTH);

    if (result != RFID_READ_LENGTH) {
        fprintf(stderr, "SPI read failed: %d\n", result);
        return -1;
    }

    // Copy received data to the tag buffer
    memcpy(tag, rx_buf, RFID_READ_LENGTH);

    return 0;
}

// Function to validate RFID tag
int validate_tag(const unsigned char *tag) {
    // Example validation: Check if the tag is not all zeros
    for (int i = 0; i < RFID_READ_LENGTH; i++) {
        if (tag[i] == 0) {
            return 0; // Invalid tag
        }
    }
    return 1; // Valid tag
}

// Function to lock and unlock the electromagnetic locks
void lock_and_unlock(int lock1_gpio, int lock2_gpio) {
    gpioWrite(lock1_gpio, 0); // Lock 1
    gpioWrite(lock2_gpio, 0); // Lock 2
    gpioDelay(5000); // Wait 5 seconds
    gpioWrite(lock1_gpio, 1); // Unlock 1
    gpioWrite(lock2_gpio, 1); // Unlock 2
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received: %d. Terminating...\n", signal);
    terminate = 1;
}

// Function to setup SPI
int setup_spi() {
    spi_handle = spiOpen(RFID_SPI_CHANNEL, RFID_SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to setup socket
int setup_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Socket creation failed");
        return -1;
    }

    // Configure server address
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, config.server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(server_socket);
        return -1;
    }

    // Connect to server
    if (connect(server_socket, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Connection failed");
        close(server_socket);
        return -1;
    }

    printf("Connected to server: %s:%d\n", config.server_ip, SERVER_PORT);
    return 0;
}

// Function to setup logging
int setup_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI
    spiClose(spi_handle);

    // Close socket
    close(server_socket);

    // Close log file
    fclose(log_file);

    // Force locks to engaged state
    gpioWrite(LOCK_1_GPIO, 0);
    gpioWrite(LOCK_2_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

