// Motor 1 GPIO pins
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIO pins
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIO pins
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIO pins
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID parameters
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Target speed (RPM)
#define TARGET_SPEED 60.0

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000000 / 100.0 // 10 kHz / 100 ms = 100 Hz

// Global variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
volatile int encoder1_last_count = 0;
volatile int encoder2_last_count = 0;

// Mutexes
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// File pointer for logging
FILE *log_file = NULL;

// Function prototypes
void motor1_forward();
void motor1_backward();
void motor1_stop();
void motor2_forward();
void motor2_backward();
void motor2_stop();
void encoder1_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
void encoder2_interrupt_handler(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int count_diff);
double calculate_pid(double current_rpm, double target_rpm, double *integral, double *previous_error, double dt);
void log_data(double motor1_rpm, double motor1_integral, double motor1_derivative, double motor1_output, double motor2_rpm, double motor2_integral, double motor2_derivative, double motor2_output, double pid_output);
void signal_handler(int signal);

// Motor control functions
void motor1_forward() {
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
}

void motor1_backward() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 1);
}

void motor1_stop() {
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
}

void motor2_forward() {
    gpioWrite(MOTOR2_ENB, 1);
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);
}

void motor2_backward() {
    gpioWrite(MOTOR2_ENB, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 1);
}

void motor2_stop() {
    gpioWrite(MOTOR2_ENB, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);
}

// Interrupt handlers for encoder 1
void encoder1_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    pthread_mutex_lock(&encoder1_mutex);
    encoder1_count = (diff > 0) ? 1 : 0; // Count clockwise or counter-clockwise
    encoder1_last_count = encoder1_count;
    pthread_mutex_unlock(&encoder1_mutex);
    last_tick = tick;
}

// Interrupt handlers for encoder 2
void encoder2_interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    pthread_mutex_lock(&encoder2_mutex);
    encoder2_count = (diff > 0) ? 1 : 0; // Count clockwise or counter-clockwise
    encoder2_last_count = encoder2_count;
    pthread_mutex_unlock(&encoder2_mutex);
    last_tick = tick;
}

// Function to calculate RPM
double calculate_rpm(int count_diff) {
    return (double)count_diff * 60.0 / (double)PWM_FREQUENCY * 100.0; // Convert Hz to RPM
}

// Function to calculate PID output
double calculate_pid(double current_rpm, double target_rpm, double *integral, double *previous_error, double dt) {
    double error = target_rpm - current_rpm;
    *integral += error * dt;
    double derivative = (error - *previous_error) / dt;
    double output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to log data to file
void log_data(double motor1_rpm, double motor1_integral, double motor1_derivative, double motor1_output, double motor2_rpm, double motor2_integral, double motor2_derivative, double motor2_output, double pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor1_integral, motor1_derivative, motor1_output,
            motor2_rpm, motor2_integral, motor2_derivative, motor2_output, pid_output);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop motors
    motor1_stop();
    motor2_stop();

    // Release GPIO lines
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Close pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set edge detection for encoder 1
    gpioSetAlertFuncEx(ENCODER1_A, encoder1_interrupt_handler, NULL);
    gpioSetAlertFuncEx(ENCODER1_B, encoder1_interrupt_handler, NULL);

    // Set edge detection for encoder 2
    gpioSetAlertFuncEx(ENCODER2_A, encoder2_interrupt_handler, NULL);
    gpioSetAlertFuncEx(ENCODER2_B, encoder2_interrupt_handler, NULL);

    // Initialize mutexes
    pthread_mutex_init(&encoder1_mutex, NULL);
    pthread_mutex_init(&encoder2_mutex, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&encoder1_mutex);
        pthread_mutex_destroy(&encoder2_mutex);
        gpioTerminate();
        return 1;
    }

    // Write header row to log file
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor1_Integral,Motor1_Derivative,Motor1_Output,Motor2_RPM,Motor2_Integral,Motor2_Derivative,Motor2_Output,PID_Output\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables for PID control
    double integral = 0.0;
    double previous_error = 0.0;
    double dt = 0.1; // 100ms sample time

    // Main loop
    while (1) {
        // Calculate RPM
        double motor1_rpm = calculate_rpm(encoder1_count - encoder1_last_count);
        double motor2_rpm = calculate_rpm(encoder2_count - encoder2_last_count);

        // Calculate PID output
        double pid_output = calculate_pid(motor1_rpm, TARGET_SPEED, &integral, &previous_error, dt);

        // Calculate motor outputs
        double motor1_output = pid_output;
        double motor2_output = pid_output;

        // Convert PID output to PWM duty cycle (0-100%)
        int motor1_pwm = (int)(motor1_output * 10000.0 / 100.0); // Assuming 0-10000 for PWM
        int motor2_pwm = (int)(motor2_output * 10000.0 / 100.0);

        // Set motor directions and PWM duty cycles
        if (motor1_pwm > 0) {
            motor1_forward();
        } else if (motor1_pwm < 0) {
            motor1_backward();
        }
        gpioPWM(MOTOR1_ENA, motor1_pwm);

        if (motor2_pwm > 0) {
            motor2_forward();
        } else if (motor2_pwm < 0) {
            motor2_backward();
        }
        gpioPWM(MOTOR2_ENB, motor2_pwm);

        // Log data
        log_data(motor1_rpm, integral, motor1_output, motor1_pwm, motor2_rpm, integral, motor2_output, motor2_pwm, pid_output);

        // Sleep for 100ms
        gpioDelay(100000); // 100ms
    }

    return 0;
}

