#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_ECR 0x5E

// Relay GPIO pin
#define RELAY_PIN 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
int control_relay(int state);
int log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Initialize the MPR121 sensor
int mpr121_init() {
    int status;

    // Soft reset
    status = i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00); // ECR = 0x00 for soft reset
    if (status < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121 (ECR): %d\n", status);
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering parameters
    status = i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x01); // Filter threshold low byte
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write FILTERTH_L: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x01); // Filter threshold high byte
        if (status < 0) {
        fprintf(stderr, "Error: Failed to write FILTERTH_H: %d\n", status);
        return -1;
    }

    // Set baseline configuration
    status = i2cWriteByteData(i2c_handle, MPR121_BASELINE_L, 0x00); // Baseline threshold low byte
    if (status < 0) {
        fprintf(stderr, "Error: Failed to write BASELINE_L: %d\n", status);
        return -1;
    }
    status = i2cWriteByteData(i2c_handle, MPR121_BASELINE_H, 0x00); // Baseline threshold high byte
        if (status < 0) {
        fprintf(stderr, "Error: Failed to write BASELINE_H: %d\n", status);
        return -1;
    }

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        status = i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x10); // Touch threshold
        if (status < 0) {
            fprintf(stderr, "Error: Failed to write touch threshold %d: %d\n", i, status);
            return -1;
        }
        status = i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x0A); // Release threshold
        if (status < 0) {
            fprintf(stderr, "Error: Failed to write release threshold %d: %d\n", i, status);
            return -1;
        }
    }

    // Enable run mode
    status = i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0C); // Enable all electrodes
    if (status < 0) {
        fprintf(stderr, "Error: Failed to enable run mode: %d\n", status);
        return -1;
    }

    return 0;
}

// Read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    int status = i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2);
    if (status < 0) {
        fprintf(stderr, "Error: Failed to read touch status: %d\n", status);
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Control the relay
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Log the relay state to a file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s Relay state: %s\n", timestamp, state ? "HIGH" : "LOW");
    fflush(log_file); // Ensure data is written to the file immediately
    return 0;
}

