#define LOG_FILE "valve_log.txt"

// Define the schedule interval (in seconds)
#define SCHEDULE_INTERVAL 60

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void activate_valve(int gpio, int duration_ms);
void log_event(const char *event_message);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold the current schedule state
typedef struct {
    int valve1_active;
    int valve2_active;
    int valve1_duration_ms;
    int valve2_duration_ms;
} ScheduleState;

// Global schedule state
ScheduleState current_schedule = {0, 0, 0, 0};

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(VALVE1_GPIO, PI_OUTPUT);
    gpioSetMode(VALVE2_GPIO, PI_OUTPUT);

    // Ensure valves are initially closed (OFF)
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);

    return 0; // Indicate success
}

// Function to activate a valve for a specified duration
void activate_valve(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) != 0) {
        fprintf(stderr, "Error activating valve on GPIO %d\n", gpio);
        log_event("Error activating valve");
        return;
    }
    gpioDelay(duration_ms * 1000); // Delay in microseconds

    if (gpioWrite(gpio, 0) != 0) {
        fprintf(stderr, "Error deactivating valve on GPIO %d\n", gpio);
        log_event("Error deactivating valve");
        return;
    }
}

// Function to log an event to the log file
void log_event(const char *event_message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", tm);

    fprintf(fp, "%s: %s\n", timestamp, event_message);
    fclose(fp);
}

