void cleanup_gpio() {
    gpioWrite(VALVE1_GPIO, 0);
    gpioWrite(VALVE2_GPIO, 0);
    gpioTerminate();
    log_event("GPIO pins cleaned up");
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    log_event("Program started");

    // Main loop
    while (program_running) {
        // Activate Valve 1
        activate_valve(VALVE1_GPIO, current_schedule.valve1_duration_ms);
        current_schedule.valve1_active = 1;
        current_schedule.valve1_duration_ms = 500; // Set duration for the next cycle

        // Activate Valve 2
        activate_valve(VALVE2_GPIO, current_schedule.valve2_duration_ms);
        current_schedule.valve2_active = 1;
        current_schedule.valve2_duration_ms = 1000; // Set duration for the next cycle

        // Wait for the schedule interval
        gpioDelay(SCHEDULE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Clean up GPIO before exiting
    cleanup_gpio();

    log_event("Program finished");

    return 0;
}

