#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTER 0x5C
#define MPR121_ELECTRODECURRENT 0x5B

// Relay GPIO pin
#define RELAY_PIN 17

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int mpr121_set_thresholds();
int mpr121_set_filter_charge_time();
int mpr121_set_electrode_current();
int mpr121_enter_run_mode();
int mpr121_exit_run_mode();
int mpr121_read_touch_status();
void relay_toggle();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error writing to ECR register (Stop mode)\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Enter stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error writing to ECR register (Stop mode)\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Enter stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error writing to ECR register (Stop mode)\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error writing to ECR register (Stop mode)\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    return 0;
}

// Set touch and release thresholds for all electrodes
int mpr121_set_thresholds() {
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) {
            fprintf(stderr, "Error writing to touch threshold register %d\n", 2 * i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) {
            fprintf(stderr, "Error writing to release threshold register %d\n", 2 * i);
            return -1;
        }
    }
    return 0;
}

// Set filter and charge time
int mpr121_set_filter_charge_time() {
    if (i2cWriteByteData(i2c_handle, MPR121_FILTER, 0x01) < 0) {
        fprintf(stderr, "Error writing to filter register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECURRENT, 0x01) < 0) {
        fprintf(stderr, "Error writing to electrode current register\n");
        return -1;
    }
    return 0;
}

// Set electrode current
int mpr121_set_electrode_current() {
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECURRENT, 0x01) < 0) {
        fprintf(stderr, "Error writing to electrode current register\n");
        return -1;
    }
    return 0;
}

// Enter run mode
int mpr121_enter_run_mode() {
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x0C) < 0) {
        fprintf(stderr, "Error writing to ECR register (Run mode)\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// Exit run mode
int mpr121_exit_run_mode() {
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error writing to ECR register (Stop mode)\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay
    return 0;
}

// Read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_low, touch_status_high;

    touch_status_low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    if (touch_status_low < 0) {
        fprintf(stderr, "Error reading touch status low byte\n");
        return -1;
    }

    touch_status_high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);
    if (touch_status_high < 0) {
        fprintf(stderr, "Error reading touch status high byte\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Toggle the relay connected to GPIO17
void relay_toggle() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
    printf("Relay toggled to %d\n", !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set thresholds
    if (mpr121_set_thresholds() < 0) {
        fprintf(stderr, "MPR121 threshold setting failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set filter and charge time
    if (mpr121_set_filter_charge_time() < 0) {
        fprintf(stderr, "MPR121 filter/charge time setting failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Enter run mode
    if (mpr121_enter_run_mode() < 0) {
        fprintf(stderr, "MPR121 run mode entry failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        if (touch_status > 0) {
            relay_toggle();
        }

        gpioDelay(100000); // 100ms delay
    }

    // Exit run mode
    if (mpr121_exit_run_mode() < 0) {
        fprintf(stderr, "MPR121 run mode exit failed\n");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

