#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define UNLOCK_DURATION 500 // milliseconds
#define RATE_LIMIT_INTERVAL 2 // seconds
#define LOG_FILE "door_events.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int control_relay(int state);
int log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int pir_state;
    time_t last_motion_time;
} ProgramState;

ProgramState state = {0, 0};

int main() {
    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1) {
            // Motion detected
            time_t current_time = time(NULL);
            if (difftime(current_time, state.last_motion_time) >= RATE_LIMIT_INTERVAL) {
                // Unlock the door
                if (control_relay(1) == 0) {
                    log_event("Motion Detected");
                    state.last_motion_time = current_time;
                    last_unlock_time = current_time; // Update last unlock time
                } else {
                    fprintf(stderr, "Error controlling relay.\n");
                }
            } else {
                // Rate limiting
                log_event("Rate Limiting");
            }
        }

        gpioDelay(50); // 50ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Control relay state
int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error writing to relay pin.\n");
        return 1;
    }
    return 0;
}

// Log event to file
int log_event(const char *event_type) {
    time_t current_time = time(NULL);
    struct tm *time_info = localtime(&current_time);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

