#include <pigpio.h>

// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Define step duration range (50ms - 200ms)
#define MIN_STEP_DURATION 50
#define MAX_STEP_DURATION 200

// Define the number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Global flag to signal program termination
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, shutting down gracefully...\n");
        shutdown_flag = 1;
    }
}

// Function to generate a random duty cycle (0-255)
int generate_duty_cycle() {
    return rand() % PWM_RANGE;
}

// Function to generate a random step duration (50ms - 200ms)
int generate_step_duration() {
    return (rand() % (MAX_STEP_DURATION - MIN_STEP_DURATION + 1)) + MIN_STEP_DURATION;
}

// Function to generate a random pattern
int generate_pattern(int *duty_cycle1, int *duty_cycle2, int *step_duration) {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random duty cycle for Motor 1
    *duty_cycle1 = generate_duty_cycle();

    // Generate a random duty cycle for Motor 2
    *duty_cycle2 = generate_duty_cycle();

    // Generate a random step duration
    *step_duration = generate_step_duration();

    return 0; // Indicate success
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    if (gpioPWM(gpio, duty_cycle) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle for GPIO %d\n", gpio);
        return -1; // Indicate failure
    }
    return 0; // Indicate success
}

// Function to play a pattern
int play_pattern(int duty_cycle1, int duty_cycle2, int step_duration) {
    for (int i = 0; i < step_duration; i++) {
        if (set_pwm_duty_cycle(MOTOR1_GPIO, duty_cycle1) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for Motor 1\n");
            return -1;
        }
        if (set_pwm_duty_cycle(MOTOR2_GPIO, duty_cycle2) != 0) {
            fprintf(stderr, "Error setting PWM duty cycle for Motor 2\n");
            return -1;
        }
        gpioDelay(step_duration); // Delay for the specified step duration
    }
    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins to output mode
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set the PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Seed the random number generator
    srand(time(NULL));

    // Main loop to generate and play random patterns
    while (!shutdown_flag) {
        int duty_cycle1, duty_cycle2, step_duration;

        // Generate a random pattern
        if (generate_pattern(&duty_cycle1, &duty_cycle2, &step_duration) != 0) {
            fprintf(stderr, "Error generating pattern\n");
            continue; // Skip to the next iteration
        }

        // Play the generated pattern
        if (play_pattern(duty_cycle1, duty_cycle2, step_duration) != 0) {
            fprintf(stderr, "Error playing pattern\n");
        }

        // Delay to control the rate of pattern generation
        gpioDelay(100); // 100ms delay
    }

    // Stop the motors and terminate the pigpio library before exiting
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

