#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define READ_TIMEOUT_MS 500
#define ZERO_LOAD_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

// Global variables
static volatile int running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;
static FILE *log_file = NULL;

// Structure to hold calibration data
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
int read_hx711();
double calculate_weight(int raw_value);
void control_solenoid(double weight);
void log_data(double raw_value, double weight);
void calibrate_sensor();
void signal_handler(int signal);
void cleanup();
int load_calibration_data();
int save_calibration_data();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < READ_TIMEOUT_MS) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= READ_TIMEOUT_MS) {
        fprintf(stderr, "HX711 read timeout\n");
        return -1; // Indicate timeout
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1);
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight from raw value
double calculate_weight(int raw_value) {
    return (raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        gpioWrite(SOLENOID_PIN, 1); // Engage solenoid
        printf("Solenoid engaged\n");
    } else {
        gpioWrite(SOLENOID_PIN, 0); // Disengage solenoid
        printf("Solenoid disengaged\n");
    }
}

// Function to log data to file
void log_data(double raw_value, double weight) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Raw: %.2f, Weight: %.2f\n", timestamp, raw_value, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to calibrate the sensor
void calibrate_sensor() {
