// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioWrite(HX711_CLOCK_PIN, 0);

    // Wait for data line to go low
    int timeout_counter = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_counter < READ_TIMEOUT_MS) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= READ_TIMEOUT_MS) {
        fprintf(stderr, "HX711 read timeout\n");
        return -1; // Indicate timeout
