#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define RAIN_THRESHOLD 3
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define LOG_FILE "/var/log/window_control.log"
#define SENSOR_CHECK_INTERVAL_SEC 60
#define POST_CLOSING_WAIT_SEC 60

// Global variables
static volatile int running = 1;
static int sensor_count = 0;
static time_t last_sensor_check_time = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
void control_motor(int close_window);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold motor state
typedef struct {
    int in1_state;
    int in2_state;
    int pwm_enabled;
} MotorState;

MotorState motor_state = {0, 0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR_PWM_PIN, 255);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    int i;
    int low_count = 0;

    for (i = 0; i < 5; i++) {
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
        int reading = gpioRead(RAIN_SENSOR_PIN);
        if (reading < 0) {
            log_event("Error reading rain sensor");
            return -1; // Indicate error
        }
        if (reading == 0) { // Assuming 0 means rain
            low_count++;
        }
    }

    return low_count;
}

// Function to control the motor
void control_motor(int close_window) {
    if (close_window) {
        // Open window
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 1);
        gpioPWM(MOTOR_PWM_PIN, PWM_DUTY_CYCLE);
        log_event("Closing window");
        gpioDelay(5000000); // 5 seconds

        // Stop motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Stopping motor");
    } else {
        // Stop motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Stopping motor");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, stopping...");
}

// Cleanup function to release GPIO resources
void cleanup() {
    log_event("Cleaning up GPIO resources");
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    gpioTerminate();
    log_event("GPIO resources released");
    closelog();
    exit(0);
}

int main() {
    // Open syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (running) {
        // Check sensor every 60 seconds
        time_t current_time = time(NULL);
        if (difftime(current_time, last_sensor_check_time) >= SENSOR_CHECK_INTERVAL_SEC) {
            int rain_detected = (read_rain_sensor() >= RAIN_THRESHOLD);
            if (rain_detected) {
                log_event("Rain detected!");
                control_motor(1); // Close window
                sensor_count++;
                last_sensor_check_time = current_time;
            } else {
                sensor_count--;
                if (sensor_count < 0) {
                    sensor_count = 0; // Reset if below 0
                }
            }
        } else {
            // Wait until the next check
            gpioDelay(1000000); // 1 second
        }

        // Wait for 60 seconds before the next check
        gpioDelay(SENSOR_CHECK_INTERVAL_SEC * 1000000); // 60 seconds

        // Wait for POST_CLOSING_WAIT_SEC after closing the window
        gpioDelay(POST_CLOSING_WAIT_SEC * 1000000); // 60 seconds

        // Check if the sensor check interval has passed
        time_t current_time2 = time(NULL);
        if (difftime(current_time2, last_sensor_check_time) >= SENSOR_CHECK_INTERVAL_SEC) {
            // Check if the motor is still stopped
            if (motor_state.in1_state == 0 && motor_state.in2_state == 0 && motor_state.pwm_enabled == 0) {
                log_event("Motor stopped, cleaning up and exiting");
                cleanup();
            }
        }
    }

    return 0;
}

