    int data = 0;
    int i;

    gpioSetMode(DT_PIN, PI_INPUT);
    gpioSetMode(SCK_PIN, PI_OUTPUT);

    // Wait for DOUT to go low
    int timeout_counter = 0;
    while (gpioRead(DT_PIN) == 1 && timeout_counter < READ_TIMEOUT_MS) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout_counter++;
    }

    if (timeout_counter >= READ_TIMEOUT_MS) {
        log_event("ERROR", -1.0); // Indicate timeout
        return -1; // Indicate timeout
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(DT_PIN)) {
            data++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse to set the gain to 128
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

