#include <pigpio.h>
#include <errno.h>

#define GPIO_PIN 18
#define VALVE_ON 0
#define VALVE_OFF 1
#define MAX_DURATION 3600
#define CONFIG_FILE "watering.conf"
#define LOG_FILE "watering.log"

volatile sig_atomic_t program_running = 1;

// Function to log messages with timestamps
void log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename, int *duration) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening watering.conf");
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        return -1;
    }

    char *duration_str = strchr(line, '=');
    if (duration_str == NULL) {
        fclose(fp);
        return -1;
    }

    *duration = atoi(line_start(line));
    if (*duration <= 0 || *duration > MAX_DURATION) {
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_OFF); // Set pull-up/down to off
    gpioWrite(GPIO_PIN, VALVE_OFF); // Ensure valve is off initially

    return 0;
}

// Function to activate the valve
void activate_valve() {
    gpioWrite(GPIO_PIN, VALVE_ON);
    log_message("Valve activated");
}

// Function to deactivate the valve
void deactivate_valve() {
    gpioWrite(GPIO_PIN, VALVE_OFF);
    log_message("Valve deactivated");
}

// Function to handle the watering duration
void water_valve(int duration) {
    if (duration <= 0) {
        fprintf(stderr, "Invalid duration: %d\n", duration);
        return;
    }

    activate_valve();
    gpioDelay(duration * 1000000); // Delay in microseconds
    deactivate_valve();
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    log_message("Signal received, shutting down...");
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(GPIO_PIN, VALVE_OFF); // Ensure valve is off
    gpioTerminate();
    log_message("GPIO resources released");
}

int main() {
    int duration;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read the watering duration from the configuration file
    if (read_watering_duration(CONFIG_FILE, &duration) != 0) {
        fprintf(stderr, "Failed to read watering duration. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        water_valve(duration);
        gpioDelay(1000000); // Check every second
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    return 0;
}

