// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int bh1750_address;
    int gpio_relay;
    float lux_threshold;
    char log_file[64];
} config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
float read_lux() {
    char config_cmd[1] = {0x10}; // Continuous high-resolution mode
    char buffer[2];
    int result;

    result = i2cWriteDevice(i2c_handle, config_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1.0;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1.0;
    }

    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2; // Convert to lux

    return lux;
}

