#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo limits and debounce time
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define DEBOUNCE_DELAY 100 // milliseconds

// Global variable to track servo position
int servo_position = 0;

// Function prototypes
int initialize_gpio();
int read_lock_button();
int read_unlock_button();
int set_servo_pulse_width(int pulse_width);
void handle_lock_button();
void handle_unlock_button();
void handle_servo_pulse_width(int pulse_width);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Read lock button state
int read_lock_button() {
    return gpioRead(LOCK_BUTTON_PIN);
}

// Read unlock button state
int read_unlock_button() {
    return gpioRead(UNLOCK_BUTTON_PIN);
}

// Set servo pulse width
int set_servo_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Invalid pulse width: %d.  Must be between %d and %d us.\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return 1; // Indicate failure
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0; // Indicate success
}

// Handle lock button press
void handle_lock_button() {
    printf("Lock button pressed. Setting servo to 0°.\n");
    if (set_servo_pulse_width(1000) != 0) {
        fprintf(stderr, "Failed to set servo to 0°.\n");
    }
    servo_position = 0; // Update servo position
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

// Handle unlock button press
void handle_unlock_button() {
    printf("Unlock button pressed. Setting servo to 180°.\n");
    if (set_servo_pulse_width(2000) != 0) {
        fprintf(stderr, "Failed to set servo to 180°.\n");
    }
    servo_position = 1; // Update servo position
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
}

// Handle servo pulse width
void handle_servo_pulse_width(int pulse_width) {
    if (set_servo_pulse_width(pulse_width) != 0) {
        fprintf(stderr, "Failed to set servo pulse width.\n");
    }
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Main loop
    while (1) {
        // Read button states
        if (read_lock_button() == 0) {
            handle_lock_button();
        }
        if (read_unlock_button() == 0) {
            handle_unlock_button();
        }

        // Update servo position based on button press
        if (servo_position == 0) {
            handle_servo_pulse_width(1000);
        } else if (servo_position == 1) {
            handle_servo_pulse_width(2000);
        }

        gpioDelay(50000); // Delay to prevent excessive CPU usage
    }

    return 0;
}

