// Define GPIO pins for the vibration motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define the duration of the vibration pulses (in milliseconds)
#define PULSE_DURATION_MS 200
#define PULSE_DURATION_MS2 300

// Define the delay between pulses (in milliseconds)
#define DELAY_MS 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGINT, exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught SIGTERM, exiting gracefully...\n");
}

// Function to initialize the GPIO pins
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO17 as an output
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR1_GPIO);
        gpioTerminate();
        return -1;
    }

    // Set GPIO27 as an output
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) != 0)
    {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR2_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to stop the vibration motors
void stop_motors()
{
    gpioWrite(MOTOR1_GPIO, 0);
    gpioWrite(MOTOR2_GPIO, 0);
}

// Function to pulse the vibration motors
void pulse_motors()
{
    // Turn on motor 1
    gpioWrite(MOTOR1_GPIO, 1);
    gpioDelay(PULSE_DURATION_MS * 1000); // Convert ms to microseconds

    // Turn off motor 1
    gpioWrite(MOTOR1_GPIO, 0);
    gpioDelay(DELAY_MS * 1000); // Delay between motors

    // Turn on motor 2
    gpioWrite(MOTOR2_GPIO, 1);
    gpioDelay(PULSE_DURATION_MS2 * 1000); // Convert ms to microseconds

    // Turn off motor 2
    gpioWrite(MOTOR2_GPIO, 0);
    gpioDelay(DELAY_MS * 1000); // Delay between motors
}

int main()
{
    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running)
    {
        pulse_motors();
    }

    // Stop the motors before exiting
    stop_motors();

    // Terminate the pigpio library
    gpioTerminate();

    printf("Haptic feedback system stopped.\n");

    return 0;
}

