#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>
#include <errno.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define ZeroMQ message type
#define ZMQ_MESSAGE_TYPE "SOUND_ALERTS"

// Global variables
static volatile int running = 1;
static void *context = NULL;
static void *publisher = NULL;
static void *subscriber = NULL;

// Function prototypes
int gpio_init(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int gpio_write(int pin, int value);
int zmq_init(const char *endpoint);
int zmq_publish(void *socket, const char *topic, const char *message);
int zmq_subscribe(void *socket, const char *topic);
int zmq_receive(void *socket, char *buffer, size_t buffer_size);
void signal_handler(int signal);
void cleanup();

// GPIO initialization function
int gpio_init(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", pin);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// GPIO read function
int gpio_read(int pin) {
    return gpioRead(pin);
}

// GPIO write function
int gpio_write(int pin, int value) {
    return gpioWrite(pin, value);
}

// ZeroMQ initialization function
int zmq_init(const char *endpoint) {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context\n");
        return -1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket\n");
        zmq_ctx_destroy(context);
        return -1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket\n");
        zmq_close(publisher);
        zmq_ctx_destroy(context);
        return -1;
    }

    int rc = zmq_bind(subscriber, endpoint);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket: %s\n", zmq_strerror(errno));
        zmq_close(publisher);
        zmq_close(subscriber);
        zmq_ctx_destroy(context);
        return -1;
    }

    return 0;
}

// ZeroMQ publish function
int zmq_publish(void *socket, const char *topic, const char *message) {
    zmq_msg_t zmq_message;
    int rc = zmq_msg_init_size(&zmq_message, strlen(message));
    if (rc != 0) {
        fprintf(stderr, "Failed to initialize ZeroMQ message: %s\n", zmq_strerror(errno));
        zmq_msg_free(&zmq_message);
        return -1;
    }

    memcpy(zmq_msg_data(&zmq_message), message, strlen(message));

    rc = zmq_msg_send(&zmq_message, socket, 0);
    zmq_msg_free(&zmq_message);
    if (rc == -1) {
        fprintf(stderr, "Failed to send ZeroMQ message: %s\n", zmq_strerror(errno));
        return -1;
    }

    return 0;
}

// ZeroMQ subscribe function
int zmq_subscribe(void *socket, const char *topic) {
    int rc = zmq_socket(context, ZMQ_SUB);
    if (rc != 0) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket: %s\n", zmq_strerror(errno));
        return -1;
    }

    rc = zmq_connect(socket, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to connect ZeroMQ subscriber socket: %s\n", zmq_strerror(errno));
        zmq_close(socket);
        return -1;
    }

    rc = zmq_setsockopt(socket, ZMQ_SUBSCRIBE, topic, strlen(topic));
    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ subscriber topic: %s\n", zmq_strerror(errno));
        zmq_close(socket);
        return -1;
    }

    return 0;
}

// ZeroMQ receive function
int zmq_receive(void *socket, char *buffer, size_t buffer_size) {
    zmq_msg_t zmq_message;
    int rc = zmq_msg_recv(&zmq_message, socket, 0);
    if (rc == -1) {
        fprintf(stderr, "Failed to receive ZeroMQ message: %s\n", zmq_strerror(errno));
        return -1;
    }

    memcpy(buffer, zmq_msg_data(&zmq_message), zmq_msg_size(&zmq_message));
    zmq_msg_close(&zmq_message);

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("Signal received, exiting...\n");
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    if (subscriber) {
        zmq_close(subscriber);
    }
    if (publisher) {
        zmq_close(publisher);
    }
