#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define NUM_SENSORS 4
#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define SLEEP_MS 180

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x5C, 0x29, 0x28};

// Global variables
int i2c_fds[NUM_SENSORS];
int running = 1;

// Structure to hold sensor data
typedef struct {
    int sensor_id;
    float lux;
} sensor_data_t;

// Function prototypes
int init_i2c(int sensor_address);
float read_lux(int fd);
void broadcast_data(const sensor_data_t *data);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal, exiting gracefully.\n");
        running = 0;
    }
}

// Initialize I2C device
int init_i2c(int sensor_address) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, sensor_address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read lux value from BH1750FVI sensor
float read_lux(int fd) {
    uint8_t command[1] = {0x10}; // High resolution mode
    if (write(fd, command, 1) != 1) {
        perror("Error writing to I2C device");
        return NAN;
    }

    usleep(180000); // Wait 180ms

    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return NAN;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    return (float)raw_value / 1.2;
}

// Broadcast data via UDP multicast
void broadcast_data(const sensor_data_t *data) {
    int sockfd;
    struct sockaddr_in addr;
    char buffer[256];

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        perror("socket() failed");
        return;
    }

    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Format the data string
    snprintf(buffer, sizeof(buffer), "%d,%.2f", data->sensor_id, data->lux);

    // Send the data
    if (sendto(sockfd, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto() failed");
    }

    close(sockfd);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C devices
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = init_i2c(sensor_addresses[i]);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to initialize sensor %d at address 0x%02X\n", i + 1, sensor_addresses[i]);
            // Attempt to close any previously opened I2C devices
            for (int j = 0; j < i; j++) {
                close(i2c_fds[j]);
            }
            return 1;
        }
    }

    // Main loop
    while (running) {
        sensor_data_t sensor_data[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_data[i].sensor_id = i + 1;
            sensor_data[i].lux = read_lux(i2c_fds[i]);
            if (isnan(sensor_data[i].lux)) {
                fprintf(stderr, "Error reading sensor %d, using NaN value.\n", i + 1);
                sensor_data[i].lux = NAN; // Set to NaN
            }
        }

        broadcast_data(sensor_data);
        usleep(1000000); // Sleep for 1 second
    }

    // Close I2C devices
    for (int i = 0; i < NUM_SENSORS; i++) {
        close(i2c_fds[i]);
    }

    return 0;
}

