#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_REG 0x00
#define LOG_FILE "airflow_log.txt"

int i2c_fd = -1;
FILE *log_fp = NULL;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
    exit(0);
}

// Function to read data from the sensor with retry logic
int read_sensor_data(int i2c_fd, unsigned char *data, int count) {
    int retries = 0;
    int result;
    while (retries < 3) {
        result = i2cReadDevice(i2c_fd, (char *)data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(100000); // 100ms delay
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after multiple retries.\n");
    return -1; // Failure after retries
}

// Function to mask the 14-bit flow value from the first two bytes
int mask_flow_value(unsigned char high_byte, unsigned char low_byte) {
    return ((low_byte & 0x0FFF) << 8) | high_byte;
}

// Function to convert the raw flow value to SLPM
float convert_to_slpm(int raw_flow) {
    return (float)raw_flow / 100.0;
}

// Function to log the flow rate to a file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
    }

    fprintf(log_fp, "%s, %.2f\n", timestamp, flow_rate);
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, AWM7300V_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        unsigned char data[2];
        if (read_sensor_data(i2c_fd, data, 2) == 0) {
            int raw_flow = mask_flow_value(data[0], data[1]);
            float flow_rate = convert_to_slpm(raw_flow);

            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000); // 1 second delay
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_fd);
    gpioTerminate();
    return 0;
}

