#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Registers
#define AS7341_REG_IDENTIFICATION 0x80
#define AS7341_REG_POWER_CONTROL 0x81
#define AS7341_REG_CONFIG 0x82
#define AS7341_REG_SMUX 0x83
#define AS7341_REG_ENABLE 0x84
#define AS7341_REG_SP_EN 0x85
