#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Default values
#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1.0
#define DEFAULT_OUTPUT_FILENAME "seismic_data.csv"

// Sensor data structure
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Global variables
int i2c_handle;
FILE *csv_file = NULL;
FILE *error_file = NULL;
char *output_filename = NULL;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
int i2c_address = DEFAULT_I2C_ADDRESS;
int running = 1;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Convert raw data to g (example conversion, adjust as needed)
    data->x = (float)((buffer[0] << 8) | buffer[1]) / 1000.0; // Example: 1000 counts per g
    data->y = (float)((buffer[2] << 8) | buffer[3]) / 1000.0;
    data->z = (float)((buffer[4] << 8) | buffer[5]) / 1000.0;

    return 0;
}

// Function to log data to CSV file
int log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(csv_file); // Ensure data is written immediately

    return 0;
}

// Function to log errors to error log file
int log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to close files and I2C
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtof(optarg, NULL);
                break;
            case 'f':
                output_filename = strdup(optarg); // Duplicate the string
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f output_filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen(output_filename, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(output_filename, "a");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,x_g,y_g,z_g\n");
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            log_error("Failed to read sensor data, retrying...");
        }
        gpioDelay(sampling_interval * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

