// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return fd;
}

// Function to configure the BH1750 sensor
int configure_bh1750(int fd) {
    unsigned char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read the light intensity from the BH1750 sensor
int read_light_intensity(int fd, unsigned short *light_level) {
    unsigned char buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    *light_level = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert the raw light level to lux
float convert_to_lux(unsigned short raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    char buffer[32];
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }

    return 0;
}

