#define BAUD_RATE 921600

// Define magic word
#define MAGIC_WORD_SIZE 8
unsigned char magic_word[MAGIC_WORD_SIZE];

// Define CSV file name
#define CSV_FILE "radar_data.csv"

// Define TLV structure (example, adjust based on AWR1642 documentation)
typedef struct {
    unsigned short type;
    unsigned short length;
} tlv_header_t;

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart();
int read_magic_word();
int validate_magic_word();
int parse_tlv_payload(unsigned char *payload, int payload_length);
int extract_range_velocity(unsigned char *range_data, unsigned char *velocity_data);
