}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_PORT, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %d\n", uart_handle);
        return -1;
    }
    return 0;
}

// Read magic word from UART
int read_magic_word() {
    if (serRead(uart_handle, magic_word, MAGIC_WORD_SIZE) != MAGIC_WORD_SIZE) {
        fprintf(stderr, "Error reading magic word\n");
        return -1;
    }
    return 0;
}

// Validate magic word
int validate_magic_word() {
    // Example magic word (replace with the actual magic word from the AWR1642 documentation)
    unsigned char magic_word_expected[] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08};
    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (magic_word[i] != magic_word_expected[i]) {
            fprintf(stderr, "Error: Magic word mismatch at byte %d\n", i);
            return -1;
        }
    }
    return 0;
}

