    // Example TLV structure (replace with the actual TLV structure from the AWR1642 documentation)
    if (payload_length < 4) {
        fprintf(stderr, "Error: TLV payload too short\n");
        return -1;
    }

    // Extract range and velocity (example, adjust based on AWR1642 documentation)
    unsigned char range_data[2];
    unsigned char velocity_data[2];

    if (payload_length < 8) {
        fprintf(stderr, "Error: TLV payload too short for range/velocity\n");
        return -1;
    }

    memcpy(range_data, payload + 4, 2); // Assuming range data is 2 bytes after the type and length
    memcpy(velocity_data, payload + 6, 2); // Assuming velocity data is 2 bytes after the type and length

