            gpioDelay(100); // Wait before retrying
        } else {
            // No data received, sleep briefly to avoid busy-waiting
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    // Cleanup resources before exiting
    cleanup();

    return 0;
}

