#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/select.h>
#include <sys/time.h>

#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 0.5
#define SELECT_TIMEOUT_SEC 2

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Structure to hold UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
    }
}

// Function to initialize the UART
int init_uart(uart_config_t *config) {
    config->fd = open(UART_PORT, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", UART_PORT, strerror(errno));
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(config->fd);
        config->fd = -1;
        return -1;
    }

    // Configure UART: 115200 baud, 8 data bits, no parity, 1 stop bit
    config->tty.c_cflag = (config->tty.c_cflag & ~CSIZE) | 8;    // 8-bit chars
    config->tty.c_cflag &= ~(PARENB | PARODD);                  // No parity
    config->tty.c_cflag &= ~CSTOPB;                              // 1 stop bit
    config->tty.c_cflag |= CLOCAL | CREAD;                      // Enable receiver and set local mode

    config->tty.c_iflag &= ~(IXON | IXOFF | IXANY);             // Disable software flow control
    config->tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    config->tty.c_oflag &= ~OPOST;                              // Raw output
    config->tty.c_oflag &= ~ONLCR;                              // Convert CRLs to NULs

    config->tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);       // Non-canonical mode, disable echo, no echoing, no reporting of ctrl chars

    config->tty.c_cc[VMIN] = 0;  // Read doesn't block
    config->tty.c_cc[VTIME] = TIMEOUT_SEC; // Timeout of 0.5 seconds

    if (tcsetattr(config->fd, TCSANOW, &config->tty) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(config->fd);
        config->fd = -1;
        return -1;
    }

    return 0;
}

// Function to read data from the UART with timeout
int read_uart_data(int fd, char *buffer, int max_len) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = SELECT_TIMEOUT_SEC;
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
