#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    program_running = 0;
    printf("\nSIGINT received. Exiting gracefully...\n");
}

// Signal handler for SIGTERM (termination signal)
void sigterm_handler(int signal)
{
    program_running = 0;
    printf("\nSIGTERM received. Exiting gracefully...\n");
}

// Function to initialize the pigpio library
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set up the GPIO pins as inputs with pull-up resistors
int setup_gpio_pins()
{
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor values
int read_sensor_values()
{
    int left_value = gpioRead(LEFT_SENSOR_PIN);
    int middle_value = gpioRead(MIDDLE_SENSOR_PIN);
    int right_value = gpioRead(RIGHT_SENSOR_PIN);

    return (left_value == 0) ? 0 : 1;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to check for emergency stop condition
int check_emergency_stop(int left, int middle, int right)
{
    return (left == 0 && middle == 0 && right == 0) ? 1 : 0;
}

// Function to send a message over UART
int send_uart_message(const char *message)
{
    int uart_fd = open(UART_DEVICE, O_WRONLY);
    if (uart_fd < 0)
    {
        fprintf(stderr, "Error opening UART device: %s\n", UART_DEVICE);
        return -1;
    }

    if (tcgetattr(uart_fd, &tc_info) != 0)
    {
        fprintf(stderr, "Error getting UART attributes\n");
        close(uart_fd);
        return -1;
    }

    tcsetattr(uart_fd, TCSANOW, &tc_info);

    if (send(uart_fd, message, strlen(message), 0) < 0)
    {
        fprintf(stderr, "Error sending data to UART\n");
        close(uart_fd);
        return -1;
    }

    close(uart_fd);
    return 0;
}

int main()
{
    // Register signal handlers
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Setup GPIO pins
    if (setup_gpio_pins() != 0)
    {
        gpioTerminate();
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running)
    {
        int sensor_state = read_sensor_values();
        log_sensor_data(sensor_state, 0, 0);

        if (check_emergency_stop(sensor_state, 0, 0))
        {
            if (send_uart_message("EMERGENCY STOP!\n") != 0)
            {
                fprintf(stderr, "Error sending emergency stop message\n");
            }
        }

        gpioDelay(100000); // 100ms delay (10Hz)
    }

    // Cleanup
    gpioTerminate();
    printf("Program terminated.\n");
    return 0;
}

